BASE_DIR = Path(__file__).resolve().parent
PACKAGE_DIR = BASE_DIR.parent
LOCAL_DATA_DIR = BASE_DIR / "data"
LOCAL_DATA_DIR.mkdir(exist_ok=True)

# Persistent-data rule for all future patches:
# feature code lives inside each package folder, but classroom/story data must not be reset
# just because a new patch folder is unzipped.  The shared database lives outside the
# package directory by default, and every future package should use this same path.
def default_shared_db_path() -> Path:
    return Path.home() / "Documents" / "PhysicsStories" / "Physics_Assistant_AI_SHARED_DATA" / "stories.db"

DB_PATH = Path(os.environ.get("PHYSICS_AI_DB_PATH", str(default_shared_db_path()))).expanduser()
DB_PATH.parent.mkdir(parents=True, exist_ok=True)
DATA_MIGRATION_NOTES: List[str] = []

def _candidate_db_files() -> List[Path]:
    candidates: List[Path] = []
    local_db = LOCAL_DATA_DIR / "stories.db"
    if local_db.exists():
        candidates.append(local_db)
    # Search sibling package folders, for example QA_PATCH_04, QA_PATCH_03, etc.
    search_root = PACKAGE_DIR.parent
    if search_root.exists():
        for db in search_root.glob("Physics_Assistant_AI_*/backend/data/stories.db"):
            candidates.append(db)
    # Deduplicate and ignore the shared DB itself.
    unique: List[Path] = []
    seen = set()
    for db in candidates:
        try:
            key = db.resolve()
            if key == DB_PATH.resolve():
                continue
            if key in seen:
                continue
            if db.exists() and db.stat().st_size > 0:
                unique.append(db)
                seen.add(key)
        except OSError:
            continue
    return unique

def bootstrap_shared_database() -> None:
    if DB_PATH.exists() and DB_PATH.stat().st_size > 0:
        DATA_MIGRATION_NOTES.append(f"Using existing shared database: {DB_PATH}")
        return
    candidates = _candidate_db_files()
    if not candidates:
        DATA_MIGRATION_NOTES.append(f"No previous database found. A new shared database will be created at: {DB_PATH}")
        return
    # Use the newest non-empty database found in sibling/previous package folders.
    source = max(candidates, key=lambda p: p.stat().st_mtime)
    shutil.copy2(source, DB_PATH)
    DATA_MIGRATION_NOTES.append(f"Copied previous database from: {source}")
    DATA_MIGRATION_NOTES.append(f"Shared database now used at: {DB_PATH}")

bootstrap_shared_database()
DATA_DIR = DB_PATH.parent

