ALLOWED_STATUSES = {"draft", "submitted", "needs_revision", "approved", "archived"}
ALLOWED_LEVELS = {"basic", "intermediate", "advanced", "layered", "calculus", "other"}


def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def connect() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def ensure_column(conn: sqlite3.Connection, table: str, column: str, definition: str) -> None:
    existing = {row[1] for row in conn.execute(f"PRAGMA table_info({table})")}
    if column not in existing:
        conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")


def init_db() -> None:
    with connect() as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS stories (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                student_author TEXT DEFAULT '',
                physics_topic TEXT DEFAULT '',
                level TEXT DEFAULT 'basic',
                story_text TEXT NOT NULL,
                student_solution TEXT DEFAULT '',
                teacher_notes TEXT DEFAULT '',
                status TEXT DEFAULT 'submitted',
                submitted_at TEXT DEFAULT '',
                reviewed_at TEXT DEFAULT '',
                approved_at TEXT DEFAULT '',
                teacher_feedback TEXT DEFAULT '',
                revision_request TEXT DEFAULT '',
                student_response TEXT DEFAULT '',
                revision_count INTEGER DEFAULT 0,
                last_revision_at TEXT DEFAULT '',
                created_at TEXT DEFAULT '',
                updated_at TEXT DEFAULT ''
            )
            """
        )
        # Backward-compatible migration for earlier local databases.
        ensure_column(conn, "stories", "student_author", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "physics_topic", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "level", "TEXT DEFAULT 'basic'")
        ensure_column(conn, "stories", "story_text", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "student_solution", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "teacher_notes", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "status", "TEXT DEFAULT 'submitted'")
        ensure_column(conn, "stories", "submitted_at", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "reviewed_at", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "approved_at", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "teacher_feedback", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "revision_request", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "student_response", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "revision_count", "INTEGER DEFAULT 0")
        ensure_column(conn, "stories", "last_revision_at", "TEXT DEFAULT ''")
        conn.execute("""
            CREATE TABLE IF NOT EXISTS story_feedback_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                story_id INTEGER NOT NULL,
                event_type TEXT NOT NULL,
                status TEXT DEFAULT '',
                teacher_feedback TEXT DEFAULT '',
                revision_request TEXT DEFAULT '',
                student_response TEXT DEFAULT '',
                story_text_snapshot TEXT DEFAULT '',
                student_solution_snapshot TEXT DEFAULT '',
                created_at TEXT DEFAULT '',
                FOREIGN KEY(story_id) REFERENCES stories(id)
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS book_export_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                export_type TEXT DEFAULT '',
                story_count INTEGER DEFAULT 0,
                chapter_count INTEGER DEFAULT 0,
                created_at TEXT DEFAULT ''
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS story_scores (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                story_id INTEGER NOT NULL UNIQUE,
                physics_accuracy INTEGER DEFAULT 0,
                equation_use INTEGER DEFAULT 0,
                story_clarity INTEGER DEFAULT 0,
                context_quality INTEGER DEFAULT 0,
                solution_quality INTEGER DEFAULT 0,
                revision_quality INTEGER DEFAULT 0,
                book_readiness INTEGER DEFAULT 0,
                total_score INTEGER DEFAULT 0,
                readiness_label TEXT DEFAULT '',
                rubric_notes TEXT DEFAULT '',
                scored_at TEXT DEFAULT '',
                updated_at TEXT DEFAULT '',
                FOREIGN KEY(story_id) REFERENCES stories(id)
            )
        """)
        ensure_column(conn, "stories", "created_at", "TEXT DEFAULT ''")
        ensure_column(conn, "stories", "updated_at", "TEXT DEFAULT ''")
        conn.execute("""
            CREATE TABLE IF NOT EXISTS assignments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                physics_topic TEXT DEFAULT '',
                level TEXT DEFAULT 'basic',
                prompt_text TEXT NOT NULL,
                instructions TEXT DEFAULT '',
                due_date TEXT DEFAULT '',
                status TEXT DEFAULT 'active',
                created_at TEXT DEFAULT '',
                updated_at TEXT DEFAULT ''
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS assignment_submissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                assignment_id INTEGER NOT NULL,
                story_id INTEGER NOT NULL,
                student_author TEXT DEFAULT '',
                submitted_at TEXT DEFAULT '',
                FOREIGN KEY(assignment_id) REFERENCES assignments(id),
                FOREIGN KEY(story_id) REFERENCES stories(id)
            )
        """)
        # v11: student accounts and class sections.
        conn.execute("""
            CREATE TABLE IF NOT EXISTS class_sections (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                section_name TEXT NOT NULL,
                course_name TEXT DEFAULT '',
                term TEXT DEFAULT '',
                meeting_time TEXT DEFAULT '',
                teacher_name TEXT DEFAULT '',
                notes TEXT DEFAULT '',
                status TEXT DEFAULT 'active',
                created_at TEXT DEFAULT '',
                updated_at TEXT DEFAULT ''
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS student_accounts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_name TEXT NOT NULL,
                student_email TEXT DEFAULT '',
                section_id INTEGER DEFAULT NULL,
                display_name TEXT DEFAULT '',
                notes TEXT DEFAULT '',
                status TEXT DEFAULT 'active',
                created_at TEXT DEFAULT '',
                updated_at TEXT DEFAULT '',
                FOREIGN KEY(section_id) REFERENCES class_sections(id)
            )
        """)
        ensure_column(conn, "assignments", "section_id", "INTEGER DEFAULT NULL")
        ensure_column(conn, "assignment_submissions", "student_id", "INTEGER DEFAULT NULL")
        ensure_column(conn, "stories", "student_id", "INTEGER DEFAULT NULL")
        ensure_column(conn, "stories", "section_id", "INTEGER DEFAULT NULL")
        conn.commit()


