def slugify(value: Any) -> str:
    raw = "untitled" if value is None or str(value).strip() == "" else str(value).strip().lower()
    raw = re.sub(r"[^a-z0-9]+", "_", raw)
    raw = re.sub(r"_+", "_", raw).strip("_")
    return raw or "untitled"


def fetch_book_export_rows(include_strong_candidates: bool = True, approved_only: bool = True) -> List[Dict[str, Any]]:
    init_db()
    labels = ["ready_for_book_export"]
    if include_strong_candidates:
        labels.append("strong_candidate")
    with connect() as conn:
        rows = conn.execute(
            """
            SELECT
                stories.*,
                story_scores.total_score,
                story_scores.readiness_label,
                story_scores.book_readiness,
                story_scores.rubric_notes
            FROM stories
            LEFT JOIN story_scores ON story_scores.story_id = stories.id
            ORDER BY lower(COALESCE(stories.physics_topic, 'Unsorted')) ASC,
                     COALESCE(story_scores.total_score, -1) DESC,
                     stories.title ASC
            """
        ).fetchall()
    result = []
    for row in rows:
        item = row_to_dict(row)
        status_ok = (item.get("status") or "").lower() == "approved" if approved_only else True
        label = item.get("readiness_label") or ""
        score_ready = label in labels or int(item.get("book_readiness") or 0) >= 4
        if status_ok and score_ready:
            result.append(item)
    return result


def group_stories_by_topic(stories: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for story in stories:
        topic = (story.get("physics_topic") or "Unsorted Physics Stories").strip() or "Unsorted Physics Stories"
        grouped.setdefault(topic, []).append(story)
    return grouped


def build_book_manifest(stories: List[Dict[str, Any]]) -> Dict[str, Any]:
    grouped = group_stories_by_topic(stories)
    chapters = []
    for index, (topic, items) in enumerate(grouped.items(), start=1):
        chapters.append({
            "chapter_number": index,
            "physics_topic": topic,
            "slug": slugify(topic),
            "filename": f"ch{index:02d}_{slugify(topic)}.tex",
            "story_count": len(items),
            "story_ids": [item.get("id") for item in items],
            "titles": [item.get("title") for item in items],
        })
    return {
        "export_name": "Physics Assistant AI v18 Book Export Pipeline",
        "exported_at": utc_now(),
        "story_count": len(stories),
        "chapter_count": len(chapters),
        "selection_rule": "approved stories with readiness_label ready_for_book_export or strong_candidate, or book_readiness >= 4",
        "chapters": chapters,
    }


def build_story_latex_block(story: Dict[str, Any], number: int) -> str:
    title = latex_escape(story.get("title") or f"Story {number}")
    parts = [
        rf"\section{{Story {number}: {title}}}",
        r"\begin{approvedstorybox}",
        rf"\textbf{{Student Author:}} {latex_escape(story.get('student_author') or 'Not provided')}\\",
        rf"\textbf{{Physics Topic:}} {latex_escape(story.get('physics_topic') or 'Not provided')}\\",
        rf"\textbf{{Level:}} {latex_escape(story.get('level') or 'Not provided')}\\",
        rf"\textbf{{Rubric Score:}} {latex_escape(story.get('total_score') if story.get('total_score') is not None else 'Not scored')}/35\\",
        rf"\textbf{{Readiness:}} {latex_escape(story.get('readiness_label') or 'Not labeled')}",
        r"\end{approvedstorybox}",
        "",
        r"\subsection*{Story}",
        latex_escape(story.get("story_text") or ""),
        "",
    ]
    if story.get("student_solution"):
        parts.extend([r"\subsection*{Student Solution}", latex_escape(story.get("student_solution")), ""])
    if story.get("teacher_notes"):
        parts.extend([r"\subsection*{Teacher Notes}", latex_escape(story.get("teacher_notes")), ""])
    if story.get("rubric_notes"):
        parts.extend([r"\subsection*{Rubric Notes}", latex_escape(story.get("rubric_notes")), ""])
    return "\n".join(parts)


def build_book_chapter_latex(topic: str, stories: List[Dict[str, Any]], chapter_number: int) -> str:
    lines = [
        rf"% Auto-generated by Physics Assistant AI v18",
        rf"% Chapter {chapter_number}: {latex_escape(topic)}",
        rf"\chapter{{{latex_escape(topic)}}}",
        "",
        r"\begin{center}",
        rf"\textit{{Book-ready student stories exported from the local Physics Assistant AI database.}}\\",
        latex_escape(f"Exported: {utc_now()}"),
        r"\end{center}",
        "",
    ]
    for i, story in enumerate(stories, start=1):
        lines.append(build_story_latex_block(story, i))
        lines.append("")
    return "\n".join(lines)


def build_book_master_latex(manifest: Dict[str, Any]) -> str:
    lines = [
        r"% Auto-generated by Physics Assistant AI v18",
        r"\documentclass[11pt]{book}",
        r"\usepackage[margin=1in]{geometry}",
        r"\usepackage[T1]{fontenc}",
        r"\usepackage{lmodern}",
        r"\usepackage{xcolor}",
        r"\usepackage{tcolorbox}",
        r"\usepackage{hyperref}",
        r"\tcbset{colback=white,colframe=black!35,arc=2mm,boxrule=0.5pt}",
        r"\newenvironment{approvedstorybox}{\begin{tcolorbox}}{\end{tcolorbox}}",
        r"\begin{document}",
        r"\frontmatter",
        r"\title{Physics Stories: Approved Student Story Export}",
        r"\author{Physics Assistant AI Local Export}",
        r"\maketitle",
        r"\tableofcontents",
        r"\mainmatter",
    ]
    for chapter in manifest.get("chapters", []):
        lines.append(rf"\input{{chapters/{chapter['filename']}}}")
    lines.append(r"\end{document}")
    return "\n".join(lines)


def record_book_export(export_type: str, story_count: int, chapter_count: int) -> None:
    init_db()
    with connect() as conn:
        conn.execute(
            "INSERT INTO book_export_log (export_type, story_count, chapter_count, created_at) VALUES (?, ?, ?, ?)",
            (export_type, story_count, chapter_count, utc_now()),
        )
        conn.commit()


def book_export_zip_bytes(stories: List[Dict[str, Any]]) -> bytes:
    grouped = group_stories_by_topic(stories)
    manifest = build_book_manifest(stories)
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("manifest.json", json.dumps(manifest, indent=2))
        zf.writestr("main.tex", build_book_master_latex(manifest))
        zf.writestr("README_BOOK_EXPORT.md", "# Physics Assistant AI v18 Book Export\n\nCompile `main.tex` after placing the chapter files in the included `chapters/` directory.\n")
        for index, (topic, items) in enumerate(grouped.items(), start=1):
            filename = f"chapters/ch{index:02d}_{slugify(topic)}.tex"
            zf.writestr(filename, build_book_chapter_latex(topic, items, index))
    buffer.seek(0)
    return buffer.getvalue()


def h(value: Any) -> str:
    return escape("" if value is None else str(value), quote=True)


def latex_escape(text: Any) -> str:
    s = "" if text is None else str(text)
    replacements = {
        "\\": r"\textbackslash{}",
        "&": r"\&",
        "%": r"\%",
        "$": r"\$",
        "#": r"\#",
        "_": r"\_",
        "{": r"\{",
        "}": r"\}",
        "~": r"\textasciitilde{}",
        "^": r"\textasciicircum{}",
    }
    return "".join(replacements.get(ch, ch) for ch in s)


def markdown_escape(text: Any) -> str:
    return "" if text is None else str(text).strip()


def approved_filename(ext: str) -> str:
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    return f"approved_physics_stories_{stamp}.{ext}"


def build_markdown(stories: List[Dict[str, Any]]) -> str:
    lines = ["# Approved Physics Stories Export", "", f"Exported: {utc_now()}", "", f"Approved stories: {len(stories)}", ""]
    for i, story in enumerate(stories, start=1):
        lines.extend([
            f"## {i}. {markdown_escape(story.get('title'))}",
            "",
            f"- Student author: {markdown_escape(story.get('student_author')) or 'Not provided'}",
            f"- Physics topic: {markdown_escape(story.get('physics_topic')) or 'Not provided'}",
            f"- Level: {markdown_escape(story.get('level')) or 'Not provided'}",
            f"- Approved at: {markdown_escape(story.get('approved_at')) or markdown_escape(story.get('reviewed_at')) or 'Not recorded'}",
            "",
            "### Story",
            markdown_escape(story.get("story_text")),
            "",
        ])
        if story.get("student_solution"):
            lines.extend(["### Student solution", markdown_escape(story.get("student_solution")), ""])
        if story.get("teacher_notes"):
            lines.extend(["### Teacher notes", markdown_escape(story.get("teacher_notes")), ""])
        lines.append("---")
        lines.append("")
    return "\n".join(lines)


