V51_SHARED_PROBLEM_SCRIPT = '      <script>\n      // Shared Current Active Problem + Shared Reading and Comprehension State.\n      (function(){\n        const HELP = new Set([\'i_am_lost\',\'need_basics\',\'go_step_by_step\',\'need_hint\',\'show_full_solution\',\'check_my_work\',\'explain_equation\',\'explain_graph\',\'explain_fbd\']);\n        const PREFIX = \'phys_ai_v51_state:\';\n        function normProblem(txt){ return (txt||\'\').replace(/Selected reading and comprehension selections:[\\s\\S]*$/i,\'\').replace(/Student-selected reading and comprehension selections:[\\s\\S]*$/i,\'\').replace(/\\s+/g,\' \').trim(); }\n        function lowerProblem(txt){ return normProblem(txt).toLowerCase(); }\n        function hash(str){ let h=2166136261; for(let i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h,16777619); } return (h>>>0).toString(16); }\n        function getMode(){ const q=new URLSearchParams(window.location.search); return (q.get(\'mode_focus\') || q.get(\'learning_mode\') || \'ask_tutor\').trim(); }\n        function activeKeyFromText(txt){ const clean=lowerProblem(txt); return clean ? PREFIX + \'problem:\' + hash(clean) : PREFIX + \'current\'; }\n        function activeKey(form){ const ta=form.querySelector(\'textarea[name="message"], textarea#message, textarea\'); return activeKeyFromText(ta ? ta.value : \'\'); }\n        function rcBoxes(form){ return Array.from(form.querySelectorAll(\'input[type="checkbox"][name="problem_tags"]\')).filter(cb=>!HELP.has(cb.value)); }\n        function selectedRC(form){ return rcBoxes(form).filter(cb=>cb.checked).map(cb=>cb.value); }\n        function currentPayload(form){ const ta=form.querySelector(\'textarea[name="message"], textarea#message, textarea\'); const problem=ta?normProblem(ta.value):\'\'; return {problem:problem, problemLower:problem.toLowerCase(), tags:selectedRC(form), mode:getMode(), savedAt:new Date().toISOString()}; }\n        function save(form){ const payload=currentPayload(form); if(!payload.problem && !payload.tags.length) return; localStorage.setItem(PREFIX+\'last\', JSON.stringify(payload)); if(payload.problem){ localStorage.setItem(activeKeyFromText(payload.problem), JSON.stringify(payload)); } mark(form, \'Saved Current Active Problem and RC selections (\'+payload.tags.length+\' RC items).\'); }\n        function applyPayload(form, payload, applyProblem){ if(!payload) return false; const ta=form.querySelector(\'textarea[name="message"], textarea#message, textarea\'); if(applyProblem && ta && payload.problem && !ta.value.trim()){ ta.value = payload.problem; }\n          if(Array.isArray(payload.tags)){ const set=new Set(payload.tags); rcBoxes(form).forEach(cb=>{ cb.checked=set.has(cb.value); }); }\n          let hidden=form.querySelector(\'input[name="learning_mode"]\'); if(!hidden){ hidden=document.createElement(\'input\'); hidden.type=\'hidden\'; hidden.name=\'learning_mode\'; form.appendChild(hidden); } hidden.value=getMode();\n          return true;\n        }\n        function load(form, preferLast=false, applyProblem=true){ let raw=null; const key=activeKey(form); raw=localStorage.getItem(key); if(!raw && preferLast) raw=localStorage.getItem(PREFIX+\'last\'); if(!raw) return false; let payload; try{payload=JSON.parse(raw);}catch(e){return false;} const ok=applyPayload(form,payload,applyProblem); if(ok){ mark(form, \'Loaded Current Active Problem + RC selections across modes (\'+((payload.tags||[]).length)+\' RC items).\'); } return ok; }\n        function clear(form){ rcBoxes(form).forEach(cb=>cb.checked=false); const ta=form.querySelector(\'textarea[name="message"], textarea#message, textarea\'); if(ta) ta.value=\'\'; localStorage.removeItem(activeKey(form)); localStorage.removeItem(PREFIX+\'last\'); mark(form,\'Current Active Problem and RC selections reset.\'); }\n        function mark(form,msg){ let el=form.querySelector(\'.v51-state-banner\'); if(!el){ el=document.createElement(\'div\'); el.className=\'v51-state-banner\'; el.style.cssText=\'margin:0.55rem 0;padding:0.55rem 0.7rem;border:1px solid #9ec5fe;border-radius:10px;background:#eef6ff;font-size:0.95rem;\'; const details=Array.from(form.querySelectorAll(\'details\')).find(d=>(d.textContent||\'\').toLowerCase().includes(\'reading and comprehension\')); (details||form).insertAdjacentElement(details?\'beforebegin\':\'afterbegin\',el); } el.textContent=msg; }\n        function addControls(form){ if(form.dataset.v51Ready) return; form.dataset.v51Ready=\'1\'; const row=document.createElement(\'div\'); row.className=\'v51-state-controls\'; row.style.cssText=\'display:flex;gap:0.5rem;flex-wrap:wrap;margin:0.5rem 0;\'; row.innerHTML=\'<button type="button" class="secondary v51-use">Use saved problem + RC</button><button type="button" class="secondary v51-save">Save problem + RC for this problem</button><button type="button" class="secondary v51-reset">Reset problem + RC</button>\';\n          const details=Array.from(form.querySelectorAll(\'details\')).find(d=>(d.textContent||\'\').toLowerCase().includes(\'reading and comprehension\')); (details||form).insertAdjacentElement(details?\'beforebegin\':\'afterbegin\',row);\n          row.querySelector(\'.v51-use\').addEventListener(\'click\',()=>{ if(!load(form,true,true)) mark(form,\'No saved Current Active Problem yet. Paste problem, choose RC items, then save/send.\'); });\n          row.querySelector(\'.v51-save\').addEventListener(\'click\',()=>save(form));\n          row.querySelector(\'.v51-reset\').addEventListener(\'click\',()=>clear(form));\n          const ta=form.querySelector(\'textarea[name="message"], textarea#message, textarea\'); if(ta){ ta.addEventListener(\'input\',()=>load(form,false,false)); ta.addEventListener(\'blur\',()=>load(form,false,false)); }\n          form.addEventListener(\'submit\',()=>save(form));\n          load(form,true,true);\n        }\n        document.addEventListener(\'DOMContentLoaded\',()=>{ document.querySelectorAll(\'form\').forEach(f=>{ if(f.id===\'ask\') return; const ta=f.querySelector(\'textarea[name="message"], textarea#message, textarea\'); if(ta || f.querySelector(\'input[type="checkbox"][name="problem_tags"]\')) addControls(f); }); });\n      })();\n      </script>'

V56_GROUPED_RC_PULLDOWN_SCRIPT = '\n<script>\n// V56 grouped Reading & Comprehension pull-down menu.\n(function(){\n  const RC_ALIASES = {\n    speeding_up: \'speeding_up\', object_speeding_up: \'speeding_up\',\n    slowing_down: \'slowing_down\', object_slowing_down: \'slowing_down\',\n    pulley_system: \'pulley\', pulley: \'pulley\',\n    draw_fbd: \'draw_fbd\', fbd: \'draw_fbd\'\n  };\n  function canonical(v){ return RC_ALIASES[v] || v; }\n  function normalizeValues(form){\n    form.querySelectorAll(\'input[type="checkbox"][name="problem_tags"]\').forEach(cb=>{\n      const c=canonical(cb.value);\n      if(c!==cb.value){ cb.value=c; }\n      const lab=cb.closest(\'label\');\n      if(lab){ lab.style.display=\'block\'; lab.style.padding=\'0.15rem 0\'; }\n    });\n  }\n  function groupExistingRC(details){\n    if(!details || details.dataset.v56Grouped) return;\n    const summaryText=(details.querySelector(\'summary\')||{}).textContent||\'\';\n    if(!/Reading and Comprehension/i.test(summaryText)) return;\n    details.dataset.v56Grouped=\'1\';\n    details.classList.add(\'v56-rc-menu\');\n    const container=details.querySelector(\'div\');\n    if(!container) return;\n    container.style.maxHeight=\'none\';\n    container.style.overflow=\'visible\';\n    const h4s=Array.from(container.querySelectorAll(\'h4\'));\n    h4s.forEach((h4, idx)=>{\n      const title=(h4.textContent||\'\').replace(/^\\s*\\d+\\.\\s*/,\'\').trim();\n      const next=h4.nextElementSibling;\n      if(!next || !next.querySelector(\'input[name="problem_tags"]\')) return;\n      const d=document.createElement(\'details\');\n      d.className=\'v56-rc-kind\';\n      d.style.cssText=\'margin:0.45rem 0;border:1px solid #b6c2d2;border-radius:10px;background:#f8fbff;\';\n      if(idx<3) d.open=true;\n      const sum=document.createElement(\'summary\');\n      sum.textContent=title;\n      sum.style.cssText=\'cursor:pointer;padding:0.55rem 0.7rem;font-weight:700;\';\n      const body=document.createElement(\'div\');\n      body.style.cssText=\'padding:0 0.8rem 0.8rem 0.8rem;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:0.3rem 0.8rem;max-height:260px;overflow:auto;\';\n      // Move labels/inputs into nested pull-down body.\n      Array.from(next.children).forEach(ch=>body.appendChild(ch));\n      d.appendChild(sum); d.appendChild(body);\n      next.replaceWith(d);\n      h4.remove();\n    });\n    const note=document.createElement(\'p\');\n    note.className=\'muted\';\n    note.style.cssText=\'margin:0.35rem 0 0.6rem 0;font-size:0.92rem;\';\n    note.textContent=\'V56: RCs are grouped by kind/type. Open only the category you need: Situation, Motion Model, Given, Find, Surface/Resistance, Forces/Interactions, Coordinates/Representation, Equation Tool, Final Product, or Misconception/Conflict Checks.\';\n    const firstP=container.querySelector(\'p.muted\');\n    if(firstP) firstP.insertAdjacentElement(\'afterend\', note);\n  }\n  function init(){\n    document.querySelectorAll(\'form\').forEach(normalizeValues);\n    document.querySelectorAll(\'details.tag-menu\').forEach(groupExistingRC);\n  }\n  document.addEventListener(\'DOMContentLoaded\', init);\n})();\n</script>\n'



