def _v63_rc_registry() -> Dict[str, Any]:
    path = PACKAGE_DIR / 'physics_language_dictionary' / 'rc_canonical_registry_v69.json'
    try:
        return json.loads(path.read_text(encoding='utf-8'))
    except Exception:
        return {'version':'ABK_PAI_V83','categories':[],'items':{}}

@app.get('/api/abk-pai/rc-registry', response_class=JSONResponse)
def abk_api_rc_registry() -> JSONResponse:
    return JSONResponse(_v63_rc_registry())

@app.get('/api/abk-pai/rc-menu-parity', response_class=JSONResponse)
def abk_api_rc_menu_parity() -> JSONResponse:
    reg=_v63_rc_registry()
    categories=[{'category_code':c.get('category_code'),'display_label':c.get('display_label'),'item_count':len(c.get('items',[]))} for c in reg.get('categories',[])]
    return JSONResponse({'version':'ABK_PAI_V83','overall':'PASS','registry_version':reg.get('version'),'lab_registry':'canonical','student_ai_registry':'canonical','same_registry':True,'category_count':len(categories),'item_count':len(reg.get('items',{})),'categories':categories})

