EQUATION_LIBRARY: Dict[str, List[Dict[str, str]]] = {
    "Kinematics": [
        {"name": "Average velocity", "syntax": "v_avg = Delta x/Delta t", "display": "v<sub>avg</sub> = <span class=\"frac\"><span>Δx</span><span>Δt</span></span>", "use": "Use when total displacement and elapsed time are known."},
        {"name": "Constant-acceleration velocity", "syntax": "v_f = v_i + a*Delta t", "display": "v<sub>f</sub> = v<sub>i</sub> + aΔt", "use": "Use when acceleration is constant and time is known."},
        {"name": "Constant-acceleration displacement", "syntax": "Delta x = v_i*Delta t + 1/2*a*(Delta t)^2", "display": "Δx = v<sub>i</sub>Δt + <span class=\"frac\"><span>1</span><span>2</span></span>a(Δt)<sup>2</sup>", "use": "Use when displacement, time, and acceleration are involved."},
        {"name": "No-time equation", "syntax": "v_f^2 = v_i^2 + 2*a*Delta x", "display": "v<sub>f</sub><sup>2</sup> = v<sub>i</sub><sup>2</sup> + 2aΔx", "use": "Use when time is not needed or not given."},
    ],
    "Forces and Newton's Laws": [
        {"name": "Newton's second law", "syntax": "sum_F_x = m*a_x", "display": "ΣF<sub>x</sub> = ma<sub>x</sub>", "use": "Write separately for each direction after drawing the free-body diagram."},
        {"name": "Weight", "syntax": "F_g = m*g", "display": "F<sub>g</sub> = mg", "use": "Near Earth's surface."},
        {"name": "Level-road normal force", "syntax": "N = m*g", "display": "F_n = mg", "use": "Only when the surface is horizontal and no other vertical forces change N."},
    ],
    "Friction and Stopping Distance": [
        {"name": "Kinetic friction", "syntax": "f_k = mu_k*N", "display": "f<sub>k</sub> = μ<sub>k</sub>N", "use": "Use for sliding/skidding contact, or when kinetic friction is the model given."},
        {"name": "Braking force direction", "syntax": "sum_F_x = -f_k = m*a_x", "display": "ΣF<sub>x</sub> = −f<sub>k</sub> = ma<sub>x</sub>", "use": "Choose +x forward; friction points backward."},
        {"name": "Braking acceleration", "syntax": "a_x = -mu_k*g", "display": "a<sub>x</sub> = −μ<sub>k</sub>g", "use": "For a level road with kinetic friction as the only horizontal force. The minus sign means backward acceleration."},
        {"name": "Stopping-distance equation", "syntax": "Delta x_stop = v_i^2/(2*mu_k*g)", "display": "Δx<sub>stop</sub> = <span class=\"frac\"><span>v<sub>i</sub><sup>2</sup></span><span>2μ<sub>k</sub>g</span></span>", "use": "Use after setting v_f = 0 in the no-time kinematics equation."},
    ],
    "Energy": [
        {"name": "Gravitational potential energy", "syntax": "PE = m*g*h", "display": "PE = mgh", "use": "Use for height near Earth's surface."},
        {"name": "Kinetic energy", "syntax": "KE = 1/2*m*v^2", "display": "KE = <span class=\"frac\"><span>1</span><span>2</span></span>mv<sup>2</sup>", "use": "Energy of motion."},
        {"name": "Mechanical energy conservation", "syntax": "K_i + U_i = K_f + U_f", "display": "K<sub>i</sub> + U<sub>i</sub> = K<sub>f</sub> + U<sub>f</sub>", "use": "Use when nonconservative work/energy loss is negligible."},
        {"name": "Drop speed from height", "syntax": "v = sqrt(2*g*h)", "display": "v = √(2gh)", "use": "For simple fall from rest with no energy loss."},
    ],
    "Momentum and Impulse": [
        {"name": "Momentum", "syntax": "p = m*v", "display": "p = mv", "use": "Momentum of one object."},
        {"name": "Momentum conservation", "syntax": "p_i = p_f", "display": "p<sub>i</sub> = p<sub>f</sub>", "use": "Use for an isolated system or short interaction with small external impulse."},
        {"name": "Two-object conservation", "syntax": "m_1*v_1i + m_2*v_2i = m_1*v_1f + m_2*v_2f", "display": "m<sub>1</sub>v<sub>1i</sub> + m<sub>2</sub>v<sub>2i</sub> = m<sub>1</sub>v<sub>1f</sub> + m<sub>2</sub>v<sub>2f</sub>", "use": "Use for collision/recoil stories."},
        {"name": "Impulse-momentum theorem", "syntax": "J = F*Delta t = Delta p", "display": "J = FΔt = Δp", "use": "Use when force and interaction time matter."},
    ],
    "Waves": [
        {"name": "Wave speed", "syntax": "v = f*lambda", "display": "v = fλ", "use": "Relates speed, frequency, and wavelength."},
        {"name": "Period and frequency", "syntax": "T = 1/f", "display": "T = <span class=\"frac\"><span>1</span><span>f</span></span>", "use": "Use for repeating motion or waves."},
    ],
    "Electricity": [
        {"name": "Ohm's law", "syntax": "V = I*R", "display": "V = IR", "use": "Simple resistor/circuit stories."},
        {"name": "Electric force", "syntax": "F = q*E", "display": "F = qE", "use": "Force on a charge in an electric field."},
        {"name": "Electric power", "syntax": "P = I*V", "display": "P = IV", "use": "Power in simple circuits."},
    ],
}


def equation_library_cards(story_id: Optional[int] = None, interactive: bool = False) -> str:
    """Return textbook-style equation cards.

    Patch 09 makes this a student-facing equation picker: the displayed equation is
    book-style; the hidden syntax is only what the app sends to the tutor.
    """
    cards: List[str] = []
    for category, equations in EQUATION_LIBRARY.items():
        eq_html = []
        for eq in equations:
            syntax = eq["syntax"]
            rendered = eq.get("display") or physics_expr_to_html(syntax)
            action = ""
            if story_id:
                q = quote(syntax)
                action = f"""
                <div class="equation-actions">
                  <a class="button small use-equation" href="/stories/{story_id}/workspace?equation={q}#solution-equation-box">Use this equation in solution</a>
                  <a class="button small secondary" href="/equation-ai-chat?equation={q}">Ask AI about this equation</a>
                </div>
                """
            else:
                q = quote(syntax)
                action = f'<p class="actions"><a class="button small secondary" href="/equation-ai-chat?equation={q}">Ask AI about this equation</a></p><p class="muted">Open this library from a specific story to insert an equation into that story solution.</p>'
            eq_html.append(f"""
            <article class="equation-card" data-equation="{h(syntax)}">
              <h4>{h(eq['name'])}</h4>
              <div class="math-display textbook-equation">{rendered}</div>
              <p>{h(eq['use'])}</p>
              <details class="syntax-details"><summary>Show typed form</summary><code>{h(syntax)}</code></details>
              {action}
            </article>
            """)
        cards.append(f"""
        <section class="equation-category">
          <h3>{h(category)}</h3>
          <div class="equation-grid">{''.join(eq_html)}</div>
        </section>
        """)
    return "".join(cards)


