@app.post("/student-story-studio/submit", response_class=HTMLResponse)
def student_story_studio_submit(
    title: str = Form(...),
    student_author: str = Form(""),
    student_id: str = Form(""),
    discipline: str = Form("Everyday life"),
    situation: str = Form(...),
    physics_question: str = Form(...),
    known_information: str = Form(""),
    physics_ideas: str = Form(""),
    student_solution: str = Form(""),
    submission_action: str = Form("submitted"),
) -> HTMLResponse:
    status = "draft" if submission_action == "draft" else "submitted"
    story_parts = [
        f"Situation: {situation.strip()}",
        f"Physics question: {physics_question.strip()}",
    ]
    if known_information.strip():
        story_parts.append(f"Known or observable information: {known_information.strip()}")
    if physics_ideas.strip():
        story_parts.append(f"Student's initial physics ideas: {physics_ideas.strip()}")
    story = insert_story(StoryCreate(
        title=title.strip(),
        student_author=student_author.strip(),
        physics_topic=discipline.strip(),
        level="basic",
        story_text="\n\n".join(story_parts),
        student_solution=student_solution.strip(),
        teacher_notes="",
        status=status,
    ))
    sid = int(student_id) if str(student_id).strip().isdigit() else None
    if sid:
        with connect() as conn:
            stu = conn.execute("SELECT * FROM student_accounts WHERE id=?", (sid,)).fetchone()
            if stu:
                conn.execute(
                    "UPDATE stories SET student_id=?, section_id=?, student_author=? WHERE id=?",
                    (sid, stu["section_id"], stu["student_name"], story["id"]),
                )
    if status == "draft":
        return HTMLResponse(f'<meta http-equiv="refresh" content="0; url=/student-portfolio?story_id={story["id"]}">')
    return HTMLResponse(f'<meta http-equiv="refresh" content="0; url=/student-ai-chat/{story["id"]}?new_story=1&story_origin=student_studio">')


