def _legacy_tutor_reply(message: str, mode: str, step_count: int) -> Dict[str, Any]:
    text = (message or "").lower()
    mode = mode or "homework"
    final_answer_request = any(phrase in text for phrase in [
        "give me the answer", "final answer", "solve it for me", "do my homework", "just answer"
    ])
    if mode == "homework" and final_answer_request:
        return {
            "ok": True,
            "mode": mode,
            "concept_hint": "Homework Guidance Mode protects learning by giving hints instead of final answers.",
            "guiding_question": "What quantities are known, what is unknown, and which physics principle connects them?",
            "student_next_step": "Write the knowns, unknowns, and candidate equation. Then submit your setup for feedback.",
            "blocked_final_answer": True,
            "policy_reason": "blocked_final_answer_request",
            "teacher_note": None,
            "engine": "local_heuristic_legacy_compatibility",
        }
    if any(word in text for word in ["force", "newton", "acceleration", "mass"]):
        hint = "This looks like a Newton's-law situation: identify the net force, mass, and acceleration relationship."
        question = "Can you draw or describe the free-body diagram before choosing the equation?"
    elif any(word in text for word in ["momentum", "collision", "impulse", "recoil"]):
        hint = "This looks like a momentum/impulse situation: decide whether momentum is conserved or impulse changes momentum."
        question = "What is the system, and are external impulses negligible during the interaction?"
    elif any(word in text for word in ["energy", "work", "spring", "height", "speed"]):
        hint = "This may be an energy problem: compare initial and final forms of energy and any work done by nonconservative forces."
        question = "What energy terms exist at the beginning and at the end?"
    else:
        hint = "Start by translating the story into knowns, unknowns, assumptions, and the relevant physics principle."
        question = "Which physical quantity is changing, and what equation describes that change?"
    return {
        "ok": True,
        "mode": mode,
        "concept_hint": hint,
        "guiding_question": question,
        "student_next_step": "Write your setup in symbols first; then substitute numbers only after the structure is clear.",
        "blocked_final_answer": False,
        "policy_reason": "request_allowed",
        "teacher_note": "Legacy-compatible local tutor response. No external AI service is required.",
        "engine": "local_heuristic_legacy_compatibility",
    }


