@app.post("/api/stories/{story_id}/review")
def legacy_review_story_endpoint(story_id: int, review: LegacyStoryReview) -> Dict[str, Any]:
    legacy_status = (review.status or "submitted").strip()
    status_map = {
        "revision_requested": "needs_revision",
        "needs_revision": "needs_revision",
        "submitted": "submitted",
        "approved": "approved",
        "archived": "archived",
    }
    status = status_map.get(legacy_status, "submitted")
    comments = (review.teacher_comments or "").strip()
    reviewer = (review.reviewer or "Teacher").strip()
    combined = comments if not reviewer else f"{comments}\n\nReviewer: {reviewer}".strip()
    if status == "needs_revision":
        story = request_story_revision(story_id, TeacherFeedbackCreate(
            teacher_feedback=combined,
            revision_request=comments,
            status=status,
        ))
    else:
        story = update_story_status(story_id, StoryStatusUpdate(status=status, teacher_notes=combined))
    return {"ok": True, "story": story}


@app.post("/api/stories/form")
def create_story_form(
    title: str = Form(...),
    student_author: str = Form(""),
    student_id: str = Form(""),
    section_id: str = Form(""),
    physics_topic: str = Form(""),
    level: str = Form("basic"),
    story_text: str = Form(...),
    student_solution: str = Form(""),
    teacher_notes: str = Form(""),
    status: str = Form("submitted"),
) -> HTMLResponse:
    story = insert_story(StoryCreate(
        title=title,
        student_author=student_author,
        physics_topic=physics_topic,
        level=level,
        story_text=story_text,
        student_solution=student_solution,
        teacher_notes=teacher_notes,
        status=status,
    ))
    sid = int(student_id) if str(student_id).strip().isdigit() else None
    secid = int(section_id) if str(section_id).strip().isdigit() else None
    if sid or secid:
        with connect() as conn:
            if sid:
                stu = conn.execute("SELECT * FROM student_accounts WHERE id=?", (sid,)).fetchone()
                if stu:
                    conn.execute("UPDATE stories SET student_id=?, section_id=?, student_author=? WHERE id=?", (sid, secid or stu["section_id"], stu["student_name"], story["id"]))
            elif secid:
                conn.execute("UPDATE stories SET section_id=? WHERE id=?", (secid, story["id"]))
    # After a new story is submitted, go directly to chat for that exact story.
    return HTMLResponse(f'<meta http-equiv="refresh" content="0; url=/student-ai-chat/{story["id"]}?new_story=1">')


