# -----------------------------------------------------------------------------
# v11 student accounts and class-section workflow
# -----------------------------------------------------------------------------

def normalize_account_status(status: str) -> str:
    s = (status or "active").strip().lower()
    if s not in {"active", "inactive", "archived"}:
        raise HTTPException(status_code=400, detail="Status must be active, inactive, or archived")
    return s


def create_section(payload: ClassSectionCreate) -> Dict[str, Any]:
    init_db()
    now = utc_now()
    status = normalize_account_status(payload.status)
    with connect() as conn:
        cur = conn.execute(
            """
            INSERT INTO class_sections
            (section_name, course_name, term, meeting_time, teacher_name, notes, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (payload.section_name.strip(), payload.course_name.strip(), payload.term.strip(), payload.meeting_time.strip(), payload.teacher_name.strip(), payload.notes.strip(), status, now, now),
        )
        conn.commit()
        section_id = int(cur.lastrowid)
    return fetch_section(section_id)


def fetch_section(section_id: int) -> Dict[str, Any]:
    init_db()
    with connect() as conn:
        row = conn.execute("SELECT * FROM class_sections WHERE id=?", (section_id,)).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="Class section not found")
    return row_to_dict(row)


def fetch_sections(status: Optional[str] = None) -> List[Dict[str, Any]]:
    init_db()
    with connect() as conn:
        if status:
            rows = conn.execute("SELECT * FROM class_sections WHERE lower(status)=? ORDER BY term DESC, section_name ASC", (status.lower(),)).fetchall()
        else:
            rows = conn.execute("SELECT * FROM class_sections ORDER BY CASE status WHEN 'active' THEN 0 ELSE 1 END, term DESC, section_name ASC").fetchall()
    return [row_to_dict(r) for r in rows]


def create_student(payload: StudentAccountCreate) -> Dict[str, Any]:
    init_db()
    now = utc_now()
    status = normalize_account_status(payload.status)
    if payload.section_id:
        fetch_section(payload.section_id)
    display_name = payload.display_name.strip() or payload.student_name.strip()
    with connect() as conn:
        cur = conn.execute(
            """
            INSERT INTO student_accounts
            (student_name, student_email, section_id, display_name, notes, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (payload.student_name.strip(), payload.student_email.strip(), payload.section_id, display_name, payload.notes.strip(), status, now, now),
        )
        conn.commit()
        student_id = int(cur.lastrowid)
    return fetch_student(student_id)


def fetch_student(student_id: int) -> Dict[str, Any]:
    init_db()
    with connect() as conn:
        row = conn.execute(
            """
            SELECT student_accounts.*, class_sections.section_name, class_sections.course_name, class_sections.term
            FROM student_accounts
            LEFT JOIN class_sections ON class_sections.id = student_accounts.section_id
            WHERE student_accounts.id=?
            """,
            (student_id,),
        ).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="Student account not found")
    return row_to_dict(row)


def fetch_students(section_id: Optional[int] = None, status: Optional[str] = None) -> List[Dict[str, Any]]:
    init_db()
    clauses = []
    params: List[Any] = []
    if section_id:
        clauses.append("student_accounts.section_id=?")
        params.append(section_id)
    if status:
        clauses.append("lower(student_accounts.status)=?")
        params.append(status.lower())
    where = ("WHERE " + " AND ".join(clauses)) if clauses else ""
    with connect() as conn:
        rows = conn.execute(
            f"""
            SELECT student_accounts.*, class_sections.section_name, class_sections.course_name, class_sections.term
            FROM student_accounts
            LEFT JOIN class_sections ON class_sections.id = student_accounts.section_id
            {where}
            ORDER BY class_sections.section_name ASC, student_accounts.student_name ASC
            """,
            params,
        ).fetchall()
    return [row_to_dict(r) for r in rows]


def section_dashboard_rows() -> List[Dict[str, Any]]:
    sections = fetch_sections()
    students = fetch_students()
    classroom = classroom_progress_rows()
    # Map by exact student name because older stories may not yet have student_id.
    progress_by_name = {r.get("student_author"): r for r in classroom}
    result = []
    for section in sections:
        sid = int(section.get("id") or 0)
        section_students = [s for s in students if int(s.get("section_id") or 0) == sid]
        active_students = [s for s in section_students if (s.get("status") or "").lower() == "active"]
        total_stories = approved = needs_revision = book_ready = 0
        for stu in section_students:
            prog = progress_by_name.get(stu.get("student_name")) or progress_by_name.get(stu.get("display_name")) or {}
            total_stories += int(prog.get("total_stories") or 0)
            approved += int(prog.get("approved") or 0)
            needs_revision += int(prog.get("needs_revision") or 0)
            book_ready += int(prog.get("book_ready_stories") or 0)
        item = dict(section)
        item.update({
            "student_count": len(section_students),
            "active_student_count": len(active_students),
            "total_stories": total_stories,
            "approved_stories": approved,
            "needs_revision_stories": needs_revision,
            "book_ready_stories": book_ready,
        })
        result.append(item)
    return result


