def portfolio_story_rows(student_id: Optional[int] = None) -> List[Dict[str, Any]]:
    init_db()
    where = ""
    params: tuple[Any, ...] = ()
    if student_id is not None:
        where = "WHERE s.student_id=?"
        params = (student_id,)
    with connect() as conn:
        rows = conn.execute(f"""
            SELECT
                s.*,
                sc.total_score,
                sc.readiness_label,
                sc.rubric_notes,
                sc.scored_at,
                a.title AS assignment_title,
                a.due_date AS assignment_due_date,
                cs.section_name AS section_name,
                sa.student_name AS account_student_name,
                sa.student_email AS account_student_email
            FROM stories s
            LEFT JOIN story_scores sc ON sc.story_id = s.id
            LEFT JOIN assignment_submissions sub ON sub.story_id = s.id
            LEFT JOIN assignments a ON a.id = sub.assignment_id
            LEFT JOIN class_sections cs ON cs.id = s.section_id
            LEFT JOIN student_accounts sa ON sa.id = s.student_id
            {where}
            ORDER BY s.submitted_at DESC, s.updated_at DESC, s.id DESC
        """, params).fetchall()
    return [row_to_dict(r) for r in rows]


def portfolio_timeline_events(student_id: Optional[int] = None, story_id: Optional[int] = None) -> List[Dict[str, Any]]:
    init_db()
    events: List[Dict[str, Any]] = []
    story_params: List[Any] = []
    story_where: List[str] = []
    if student_id is not None:
        story_where.append("student_id=?")
        story_params.append(student_id)
    if story_id is not None:
        story_where.append("id=?")
        story_params.append(story_id)
    where_clause = "WHERE " + " AND ".join(story_where) if story_where else ""
    with connect() as conn:
        story_rows = conn.execute(f"SELECT * FROM stories {where_clause}", tuple(story_params)).fetchall()
        story_ids = [int(r["id"]) for r in story_rows]
        for s in story_rows:
            events.append({
                "event_time": s["submitted_at"] or s["created_at"] or s["updated_at"] or "",
                "event_type": "story_submitted",
                "story_id": s["id"],
                "story_title": s["title"],
                "status": s["status"],
                "description": f"Story submitted: {s['title']}",
            })
            if s["reviewed_at"]:
                events.append({
                    "event_time": s["reviewed_at"],
                    "event_type": "teacher_review",
                    "story_id": s["id"],
                    "story_title": s["title"],
                    "status": s["status"],
                    "description": (s["teacher_feedback"] or s["teacher_notes"] or "Teacher review recorded."),
                })
            if s["approved_at"]:
                events.append({
                    "event_time": s["approved_at"],
                    "event_type": "story_approved",
                    "story_id": s["id"],
                    "story_title": s["title"],
                    "status": "approved",
                    "description": "Story approved for classroom/book workflow.",
                })
            if s["last_revision_at"]:
                events.append({
                    "event_time": s["last_revision_at"],
                    "event_type": "student_revision",
                    "story_id": s["id"],
                    "story_title": s["title"],
                    "status": s["status"],
                    "description": s["student_response"] or "Student submitted a revision.",
                })
        if story_ids:
            placeholders = ",".join("?" for _ in story_ids)
            histories = conn.execute(f"""
                SELECT h.*, s.title AS story_title
                FROM story_feedback_history h
                JOIN stories s ON s.id = h.story_id
                WHERE h.story_id IN ({placeholders})
                ORDER BY h.created_at DESC, h.id DESC
            """, tuple(story_ids)).fetchall()
            for h in histories:
                events.append({
                    "event_time": h["created_at"] or "",
                    "event_type": h["event_type"],
                    "story_id": h["story_id"],
                    "story_title": h["story_title"],
                    "status": h["status"],
                    "description": h["student_response"] or h["revision_request"] or h["teacher_feedback"] or h["event_type"],
                })
            scores = conn.execute(f"""
                SELECT sc.*, s.title AS story_title
                FROM story_scores sc
                JOIN stories s ON s.id = sc.story_id
                WHERE sc.story_id IN ({placeholders})
                ORDER BY sc.updated_at DESC, sc.scored_at DESC
            """, tuple(story_ids)).fetchall()
            for sc in scores:
                events.append({
                    "event_time": sc["updated_at"] or sc["scored_at"] or "",
                    "event_type": "rubric_score",
                    "story_id": sc["story_id"],
                    "story_title": sc["story_title"],
                    "status": sc["readiness_label"],
                    "description": f"Rubric score {sc['total_score']}/35; label: {sc['readiness_label']}",
                })
    events.sort(key=lambda e: (e.get("event_time") or "", e.get("event_type") or ""), reverse=True)
    return events


def student_portfolio(student_id: int) -> Dict[str, Any]:
    student = fetch_student(student_id)
    stories = portfolio_story_rows(student_id)
    timeline = portfolio_timeline_events(student_id=student_id)
    total = len(stories)
    approved = len([s for s in stories if (s.get("status") or "").lower() == "approved"])
    needs_revision = len([s for s in stories if (s.get("status") or "").lower() == "needs_revision"])
    submitted = len([s for s in stories if (s.get("status") or "").lower() == "submitted"])
    scored = [s for s in stories if s.get("total_score") is not None]
    avg_score = round(sum(int(s.get("total_score") or 0) for s in scored) / len(scored), 2) if scored else 0
    book_ready = len([s for s in stories if s.get("readiness_label") in {"ready_for_book_export", "strong_candidate"}])
    topics = sorted({(s.get("physics_topic") or "Unspecified") for s in stories})
    return {
        "student": student,
        "summary": {
            "total_stories": total,
            "submitted_stories": submitted,
            "needs_revision": needs_revision,
            "approved_stories": approved,
            "scored_stories": len(scored),
            "average_score": avg_score,
            "book_ready_stories": book_ready,
            "physics_topics": topics,
        },
        "stories": stories,
        "timeline": timeline,
    }


def portfolio_cards() -> str:
    students = fetch_students()
    if not students:
        return "<p>No student accounts yet. Create students first on the Students page.</p>"
    cards = []
    for st in students:
        sid = int(st["id"])
        try:
            pf = student_portfolio(sid)
            summary = pf["summary"]
        except Exception:
            summary = {"total_stories": 0, "approved_stories": 0, "average_score": 0, "book_ready_stories": 0}
        section = st.get("section_name") or "No section"
        cards.append(f"""
        <div class="card">
          <h3>{escape(st.get('student_name') or '')}</h3>
          <p><strong>Section:</strong> {escape(section)}</p>
          <p><strong>Stories:</strong> {summary['total_stories']} &nbsp; <strong>Approved:</strong> {summary['approved_stories']} &nbsp; <strong>Average score:</strong> {summary['average_score']}</p>
          <p><strong>Book-ready:</strong> {summary['book_ready_stories']}</p>
          <p><a class="button" href="/student-portfolio/{sid}">Open Portfolio</a></p>
        </div>
        """)
    return "\n".join(cards)


