def teacher_analytics_data() -> Dict[str, Any]:
    init_db()
    stories = fetch_dashboard_rows()
    sections = fetch_sections()
    students = fetch_students()
    assignments = assignment_dashboard_rows()
    statuses = {key: 0 for key in sorted(ALLOWED_STATUSES)}
    topics: Dict[str, int] = {}
    readiness: Dict[str, int] = {}
    scored = []
    for story in stories:
        status = (story.get("status") or "draft").lower()
        if status in statuses:
            statuses[status] += 1
        topic = (story.get("physics_topic") or "Unspecified").strip() or "Unspecified"
        topics[topic] = topics.get(topic, 0) + 1
        label = (story.get("readiness_label") or "unscored").strip() or "unscored"
        readiness[label] = readiness.get(label, 0) + 1
        if story.get("total_score") is not None:
            scored.append(int(story.get("total_score") or 0))
    assignment_summary_data = assignment_summary(assignments)
    return {
        "version": "v18",
        "module": "Student AI Chat Branch 1 Clean Start QA Patch 33",
        "totals": {
            "sections": len(sections),
            "students": len(students),
            "assignments": len(assignments),
            "stories": len(stories),
            "submitted_stories": statuses.get("submitted", 0),
            "approved_stories": statuses.get("approved", 0),
            "needs_revision_stories": statuses.get("needs_revision", 0),
            "scored_stories": len(scored),
            "average_score": round(sum(scored) / len(scored), 2) if scored else 0,
            "book_ready_stories": readiness.get("ready_for_book_export", 0),
            "strong_candidate_stories": readiness.get("strong_candidate", 0),
            "assignment_submissions": assignment_summary_data.get("total_submissions", 0),
        },
        "status_counts": statuses,
        "readiness_counts": readiness,
        "topic_counts": dict(sorted(topics.items(), key=lambda kv: (-kv[1], kv[0]))),
        "assignment_summary": assignment_summary_data,
    }


def section_analytics_rows_v14() -> List[Dict[str, Any]]:
    init_db()
    with connect() as conn:
        rows = conn.execute("""
            SELECT
                cs.id AS section_id,
                cs.section_name,
                cs.course_name,
                cs.term,
                cs.teacher_name,
                COUNT(DISTINCT sa.id) AS student_count,
                COUNT(DISTINCT a.id) AS assignment_count,
                COUNT(DISTINCT s.id) AS story_count,
                SUM(CASE WHEN s.status='submitted' THEN 1 ELSE 0 END) AS submitted_count,
                SUM(CASE WHEN s.status='needs_revision' THEN 1 ELSE 0 END) AS needs_revision_count,
                SUM(CASE WHEN s.status='approved' THEN 1 ELSE 0 END) AS approved_count,
                SUM(CASE WHEN ss.readiness_label='ready_for_book_export' THEN 1 ELSE 0 END) AS book_ready_count,
                SUM(CASE WHEN ss.readiness_label='strong_candidate' THEN 1 ELSE 0 END) AS strong_candidate_count,
                COUNT(ss.total_score) AS scored_count,
                AVG(ss.total_score) AS average_score
            FROM class_sections cs
            LEFT JOIN student_accounts sa ON sa.section_id = cs.id
            LEFT JOIN assignments a ON a.section_id = cs.id
            LEFT JOIN stories s ON s.section_id = cs.id
            LEFT JOIN story_scores ss ON ss.story_id = s.id
            GROUP BY cs.id
            ORDER BY cs.section_name ASC, cs.id ASC
        """).fetchall()
    out: List[Dict[str, Any]] = []
    for row in rows:
        item = row_to_dict(row)
        item["average_score"] = round(float(item["average_score"] or 0), 2)
        for key in ["student_count", "assignment_count", "story_count", "submitted_count", "needs_revision_count", "approved_count", "book_ready_count", "strong_candidate_count", "scored_count"]:
            item[key] = int(item.get(key) or 0)
        out.append(item)
    return out


def section_analytics_summary(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    return {
        "section_count": len(rows),
        "student_count": sum(int(r.get("student_count") or 0) for r in rows),
        "assignment_count": sum(int(r.get("assignment_count") or 0) for r in rows),
        "story_count": sum(int(r.get("story_count") or 0) for r in rows),
        "approved_count": sum(int(r.get("approved_count") or 0) for r in rows),
        "needs_revision_count": sum(int(r.get("needs_revision_count") or 0) for r in rows),
        "book_ready_count": sum(int(r.get("book_ready_count") or 0) for r in rows),
    }


def csv_response(rows: List[Dict[str, Any]], fieldnames: List[str], filename: str) -> StreamingResponse:
    output = io.StringIO()
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    for row in rows:
        writer.writerow(row)
    output.seek(0)
    return StreamingResponse(iter([output.getvalue()]), media_type="text/csv", headers={"Content-Disposition": f'attachment; filename="{filename}"'})


