def chart_bar_rows(mapping: Dict[str, int], limit: int = 12) -> List[Dict[str, Any]]:
    items = sorted(mapping.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0])))[:limit]
    return [{"label": str(k), "value": int(v or 0)} for k, v in items]


def assignment_completion_chart_rows() -> List[Dict[str, Any]]:
    rows = assignment_dashboard_rows()
    section_rows = section_analytics_rows_v14()
    out = []
    for r in rows:
        section_student_count = 0
        section_name = r.get("section_name") or "Unassigned"
        title = r.get("title") or f"Assignment {r.get('id')}"
        sid = r.get("section_id")
        if sid:
            for s in section_rows:
                if int(s.get("section_id") or 0) == int(sid):
                    section_student_count = int(s.get("student_count") or 0)
                    break
        submitted = int(r.get("submission_count") or 0)
        denominator = section_student_count if section_student_count > 0 else max(submitted, 1)
        pct = round(100.0 * submitted / denominator, 1) if denominator else 0
        out.append({
            "assignment_id": r.get("id"),
            "label": title[:40],
            "section": section_name,
            "submitted": submitted,
            "expected": denominator,
            "completion_percent": pct,
            "approved": int(r.get("approved_count") or 0),
            "needs_revision": int(r.get("needs_revision_count") or 0),
            "book_ready": int(r.get("book_ready_count") or 0),
            "average_score": float(r.get("average_score") or 0),
        })
    return sorted(out, key=lambda x: (-x["completion_percent"], x["label"]))


def score_distribution_rows() -> List[Dict[str, Any]]:
    stories = fetch_dashboard_rows()
    bins = {"0-5": 0, "6-10": 0, "11-15": 0, "16-20": 0, "21-25": 0, "26-30": 0, "31-35": 0}
    for s in stories:
        if s.get("total_score") is None:
            continue
        score = int(s.get("total_score") or 0)
        if score <= 5:
            bins["0-5"] += 1
        elif score <= 10:
            bins["6-10"] += 1
        elif score <= 15:
            bins["11-15"] += 1
        elif score <= 20:
            bins["16-20"] += 1
        elif score <= 25:
            bins["21-25"] += 1
        elif score <= 30:
            bins["26-30"] += 1
        else:
            bins["31-35"] += 1
    return [{"label": k, "value": v} for k, v in bins.items()]


def v15_chart_overview_data() -> Dict[str, Any]:
    data = teacher_analytics_data()
    sections = section_analytics_rows_v14()
    submissions_by_section = [
        {
            "label": (r.get("section_name") or "Unnamed")[:40],
            "value": int(r.get("story_count") or 0),
            "students": int(r.get("student_count") or 0),
            "approved": int(r.get("approved_count") or 0),
            "book_ready": int(r.get("book_ready_count") or 0),
        }
        for r in sections
    ]
    submissions_by_section.sort(key=lambda x: (-x["value"], x["label"]))
    return {
        "version": "v18",
        "module": "Student AI Chat Branch 1 Clean Start QA Patch 33",
        "totals": data.get("totals", {}),
        "status_counts": chart_bar_rows(data.get("status_counts", {})),
        "readiness_counts": chart_bar_rows(data.get("readiness_counts", {})),
        "topic_counts": chart_bar_rows(data.get("topic_counts", {})),
        "submissions_by_section": submissions_by_section,
        "assignment_completion": assignment_completion_chart_rows(),
        "score_distribution": score_distribution_rows(),
    }


def simple_bar_chart_html(title: str, rows: List[Dict[str, Any]], value_key: str = "value", max_rows: int = 10, suffix: str = "") -> str:
    rows = rows[:max_rows]
    max_value = max([float(r.get(value_key) or 0) for r in rows] + [1.0])
    parts = [f'<div class="chart-card"><h3>{escape(title)}</h3><div class="bar-chart">']
    if not rows:
        parts.append('<p>No chart data yet.</p>')
    for r in rows:
        label = escape(str(r.get("label") or r.get("section_name") or "Item"))
        val = float(r.get(value_key) or 0)
        width = max(2, round((val / max_value) * 100, 1)) if max_value else 2
        shown = int(val) if val.is_integer() else val
        parts.append(f'<div class="bar-row"><div class="bar-label">{label}</div><div class="bar-track"><div class="bar-fill" style="width:{width}%"></div></div><div class="bar-value">{shown}{suffix}</div></div>')
    parts.append('</div></div>')
    return "".join(parts)


def status_tile_html(rows: List[Dict[str, Any]], title: str) -> str:
    parts = [f'<div class="chart-card"><h3>{escape(title)}</h3><div class="status-grid">']
    if not rows:
        parts.append('<p>No data.</p>')
    for r in rows:
        parts.append(f'<div class="status-tile"><strong>{escape(str(r.get("label") or ""))}</strong><span>{int(r.get("value") or 0)}</span></div>')
    parts.append('</div></div>')
    return "".join(parts)


def chart_styles() -> str:
    return """
    <style>
      .chart-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 1rem; margin-top: 1rem; }
      .chart-card { background: #fff; border: 1px solid #d9e2ef; border-radius: 14px; padding: 1rem; box-shadow: 0 1px 5px rgba(15, 23, 42, 0.06); }
      .bar-row { display: grid; grid-template-columns: 130px 1fr 58px; gap: .55rem; align-items: center; margin: .45rem 0; }
      .bar-label { font-size: .88rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
      .bar-track { height: 18px; background: #eef3f8; border-radius: 99px; overflow: hidden; border: 1px solid #d7e2ee; }
      .bar-fill { height: 100%; background: linear-gradient(90deg, #2b6cb0, #63b3ed); border-radius: 99px; }
      .bar-value { text-align: right; font-weight: 700; color: #263547; }
      .status-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: .65rem; }
      .status-tile { background: #f7fafc; border: 1px solid #dbe6f2; border-radius: 12px; padding: .7rem; }
      .status-tile span { display: block; font-size: 1.6rem; font-weight: 800; margin-top: .25rem; }
    </style>
    """


