def svg_bar_group(title: str, rows: List[Dict[str, Any]], x: int, y: int, width: int, value_key: str = "value") -> str:
    rows = rows[:7]
    max_value = max([float(r.get(value_key) or 0) for r in rows] + [1.0])
    out = [f'<text x="{x}" y="{y}" font-size="18" font-weight="700" fill="#14213d">{escape(title)}</text>']
    y0 = y + 24
    for i, r in enumerate(rows):
        yy = y0 + i * 28
        label = escape(str(r.get("label") or "Item")[:24])
        val = float(r.get(value_key) or 0)
        bar_w = int((val / max_value) * (width - 190)) if max_value else 0
        shown = int(val) if val.is_integer() else val
        out.append(f'<text x="{x}" y="{yy+15}" font-size="12" fill="#25344d">{label}</text>')
        out.append(f'<rect x="{x+130}" y="{yy}" width="{width-190}" height="18" rx="9" fill="#edf2f7" stroke="#d8e2ee"/>')
        out.append(f'<rect x="{x+130}" y="{yy}" width="{bar_w}" height="18" rx="9" fill="#2b6cb0"/>')
        out.append(f'<text x="{x+width-50}" y="{yy+14}" font-size="12" font-weight="700" fill="#25344d">{shown}</text>')
    if not rows:
        out.append(f'<text x="{x}" y="{y0+15}" font-size="12" fill="#25344d">No data yet.</text>')
    return "\n".join(out)


