@app.get("/api/ai-feedback/overview")
def api_ai_feedback_overview() -> Dict[str, Any]:
    stories = fetch_stories()
    suggestions = [ai_feedback_suggestion(s) for s in stories]
    counts: Dict[str, int] = {}
    for item in suggestions:
        key = str(item.get("recommendation") or "unknown")
        counts[key] = counts.get(key, 0) + 1
    return {
        "version": "v18",
        "module": "Student AI Chat Branch 1 Clean Start QA Patch 33",
        "total_stories": len(stories),
        "recommendation_counts": counts,
        "suggestions": suggestions,
    }


