# -----------------------------------------------------------------------------
# v17 Prompt Library and Assignment Template tools
# -----------------------------------------------------------------------------
class PromptCreate(BaseModel):
    title: str = Field(..., min_length=1)
    physics_topic: str = ""
    level: str = "basic"
    prompt_type: str = "story_starter"
    target_equation: str = ""
    prompt_text: str = Field(..., min_length=1)
    teacher_notes: str = ""
    status: str = "active"


def ensure_prompt_tables() -> None:
    init_db()
    with connect() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS prompt_library (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                physics_topic TEXT DEFAULT '',
                level TEXT DEFAULT 'basic',
                prompt_type TEXT DEFAULT 'story_starter',
                target_equation TEXT DEFAULT '',
                prompt_text TEXT NOT NULL,
                teacher_notes TEXT DEFAULT '',
                status TEXT DEFAULT 'active',
                created_at TEXT DEFAULT '',
                updated_at TEXT DEFAULT ''
            )
        """)
        count = conn.execute("SELECT COUNT(*) AS n FROM prompt_library").fetchone()["n"]
        if count == 0:
            now = utc_now()
            defaults = [
                ("Shopping Cart Momentum Story", "Momentum and Impulse", "basic", "story_starter", "p=mv", "Write a story about a shopping cart that is pushed, collides gently, or recoils. Identify the object, mass, velocity, momentum, impulse, and what changes during the interaction.", "Good starter for momentum/impulse assignments."),
                ("Soccer Ball Impulse Challenge", "Momentum and Impulse", "intermediate", "equation_targeted", "J=\\Delta p=F\\Delta t", "Write a story about kicking a soccer ball. Include contact time, change in velocity, impulse, average force, and a clear physical interpretation of the result.", "Targets impulse and force-time reasoning."),
                ("Rope Pulse Wave Story", "Waves", "basic", "story_starter", "v=f\\lambda", "Write a story about a pulse or wave moving along a rope. Include wave speed, frequency, wavelength, and how the medium motion differs from the wave motion.", "Useful for transverse wave misconceptions."),
                ("RC Circuit Switch Story", "Electricity and Magnetism", "advanced", "equation_targeted", "V_C(t)=V_0(1-e^{-t/RC})", "Write a story about a capacitor charging or discharging after a switch is closed. Identify R, C, the time constant, voltage behavior, and the physical meaning of exponential change.", "Advanced E&M prompt."),
                ("Energy Conservation Roller Coaster", "Energy", "intermediate", "assignment_template", "K_i+U_i=K_f+U_f", "Create a story in which a cart or skater moves between two heights. Use conservation of mechanical energy to connect speed and height, and discuss where nonconservative forces would enter.", "Can become a full assignment template."),
                ("Free Fall With Calculus Extension", "Kinematics", "calculus", "equation_targeted", "a=dv/dt, v=dx/dt", "Write a layered free-fall story. First solve using algebraic kinematics; then explain how the same motion can be represented with derivatives or integrals.", "Supports algebra-to-calculus bridge."),
            ]
            conn.executemany("""
                INSERT INTO prompt_library
                (title, physics_topic, level, prompt_type, target_equation, prompt_text, teacher_notes, status, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)
            """, [(a,b,c,d,e,f,g,now,now) for (a,b,c,d,e,f,g) in defaults])
        conn.commit()


def fetch_prompts(prompt_type: str = "", level: str = "", topic: str = "") -> List[Dict[str, Any]]:
    ensure_prompt_tables()
    clauses = []
    params: List[Any] = []
    if prompt_type:
        clauses.append("lower(prompt_type)=?")
        params.append(prompt_type.lower())
    if level:
        clauses.append("lower(level)=?")
        params.append(level.lower())
    if topic:
        clauses.append("lower(physics_topic) LIKE ?")
        params.append(f"%{topic.lower()}%")
    where = " WHERE " + " AND ".join(clauses) if clauses else ""
    with connect() as conn:
        rows = conn.execute(f"SELECT * FROM prompt_library{where} ORDER BY physics_topic, level, id", params).fetchall()
    return [row_to_dict(r) for r in rows]


def fetch_prompt(prompt_id: int) -> Dict[str, Any]:
    ensure_prompt_tables()
    with connect() as conn:
        row = conn.execute("SELECT * FROM prompt_library WHERE id=?", (prompt_id,)).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="Prompt not found")
    return row_to_dict(row)


def insert_prompt(data: PromptCreate) -> Dict[str, Any]:
    ensure_prompt_tables()
    now = utc_now()
    with connect() as conn:
        cur = conn.execute("""
            INSERT INTO prompt_library
            (title, physics_topic, level, prompt_type, target_equation, prompt_text, teacher_notes, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            data.title.strip(), data.physics_topic.strip(), normalize_level(data.level),
            (data.prompt_type or "story_starter").strip(), data.target_equation.strip(),
            data.prompt_text.strip(), data.teacher_notes.strip(), data.status.strip() or "active", now, now,
        ))
        conn.commit()
        prompt_id = int(cur.lastrowid)
    return fetch_prompt(prompt_id)


def prompt_card(prompt: Dict[str, Any]) -> str:
    target = f"<p><strong>Target equation:</strong> <code>{escape(prompt.get('target_equation') or '')}</code></p>" if prompt.get("target_equation") else ""
    return f"""
      <div class="card prompt-card">
        <h3>{escape(prompt.get('title') or '')}</h3>
        <p><strong>Topic:</strong> {escape(prompt.get('physics_topic') or '')} | <strong>Level:</strong> {escape(prompt.get('level') or '')} | <strong>Type:</strong> {escape(prompt.get('prompt_type') or '')}</p>
        {target}
        <p>{escape(prompt.get('prompt_text') or '')}</p>
        <p><em>{escape(prompt.get('teacher_notes') or '')}</em></p>
        <form method="post" action="/api/prompts/{prompt.get('id')}/create-assignment/form" class="story-form compact-form">
          <label>Assignment title <input name="title" value="{escape(prompt.get('title') or '')}"></label>
          <label>Due date <input name="due_date" placeholder="YYYY-MM-DD"></label>
          <label>Additional instructions <textarea name="instructions" rows="2">Use this prompt to write a physics story. Include the physical situation, knowns, unknowns, equations, and interpretation.</textarea></label>
          <button type="submit">Create Assignment from Prompt</button>
        </form>
      </div>
    """


