class CurriculumObjectiveCreate(BaseModel):
    objective_code: str = Field(..., min_length=1)
    title: str = Field(..., min_length=1)
    physics_topic: str = ""
    course_level: str = "freshman"
    standard_source: str = "Local Course Objective"
    description: str = ""
    status: str = "active"


def ensure_curriculum_tables() -> None:
    ensure_prompt_tables()
    with connect() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS curriculum_objectives (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                objective_code TEXT NOT NULL UNIQUE,
                title TEXT NOT NULL,
                physics_topic TEXT DEFAULT '',
                course_level TEXT DEFAULT 'freshman',
                standard_source TEXT DEFAULT 'Local Course Objective',
                description TEXT DEFAULT '',
                status TEXT DEFAULT 'active',
                created_at TEXT DEFAULT '',
                updated_at TEXT DEFAULT ''
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS curriculum_links (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                objective_id INTEGER NOT NULL,
                entity_type TEXT NOT NULL,
                entity_id INTEGER NOT NULL,
                link_note TEXT DEFAULT '',
                created_at TEXT DEFAULT '',
                FOREIGN KEY(objective_id) REFERENCES curriculum_objectives(id)
            )
        """)
        count = conn.execute("SELECT COUNT(*) AS n FROM curriculum_objectives").fetchone()["n"]
        if count == 0:
            now = utc_now()
            defaults = [
                ("KIN-01", "Represent motion with words, graphs, and equations", "Kinematics", "AP/Freshman", "Course Objective", "Students identify knowns, unknowns, coordinate choices, and kinematic relationships."),
                ("FOR-01", "Apply Newton's laws to physical interactions", "Forces", "AP/Freshman", "Course Objective", "Students draw force diagrams and connect net force to acceleration."),
                ("MOM-01", "Use momentum and impulse in collisions and recoil", "Momentum and Impulse", "AP/Freshman", "Course Objective", "Students use p=mv and impulse-momentum reasoning in story contexts."),
                ("ENE-01", "Use conservation of energy and work-energy reasoning", "Energy", "AP/Freshman", "Course Objective", "Students distinguish kinetic, potential, work, thermal, and nonconservative effects."),
                ("WAV-01", "Connect wave speed, frequency, wavelength, and medium motion", "Waves", "AP/Freshman", "Course Objective", "Students interpret transverse/longitudinal wave stories and avoid medium-motion misconceptions."),
                ("EM-01", "Analyze electric circuits and fields using appropriate models", "Electricity and Magnetism", "AP/Freshman", "Course Objective", "Students connect circuit stories to current, voltage, resistance, capacitance, and energy."),
                ("MOD-01", "Interpret modern-physics stories using quantum or atomic models", "Modern Physics", "Freshman", "Course Objective", "Students connect photons, spectra, atoms, or nuclear processes to appropriate equations."),
                ("LAB-01", "Use data, uncertainty, and model checking in physics stories", "Lab and Data Skills", "AP/Freshman", "Course Objective", "Students describe measurement, uncertainty, plots, and model limits."),
            ]
            conn.executemany("""
                INSERT INTO curriculum_objectives
                (objective_code, title, physics_topic, course_level, standard_source, description, status, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, 'active', ?, ?)
            """, [(a,b,c,d,e,f,now,now) for (a,b,c,d,e,f) in defaults])
        conn.commit()


def fetch_curriculum_objectives(topic: str = "", level: str = "") -> List[Dict[str, Any]]:
    ensure_curriculum_tables()
    clauses = []
    params: List[Any] = []
    if topic:
        clauses.append("lower(physics_topic) LIKE ?")
        params.append(f"%{topic.lower()}%")
    if level:
        clauses.append("lower(course_level) LIKE ?")
        params.append(f"%{level.lower()}%")
    where = " WHERE " + " AND ".join(clauses) if clauses else ""
    with connect() as conn:
        rows = conn.execute(f"SELECT * FROM curriculum_objectives{where} ORDER BY physics_topic, objective_code", params).fetchall()
    return [row_to_dict(r) for r in rows]


def insert_curriculum_objective(data: CurriculumObjectiveCreate) -> Dict[str, Any]:
    ensure_curriculum_tables()
    now = utc_now()
    with connect() as conn:
        cur = conn.execute("""
            INSERT OR REPLACE INTO curriculum_objectives
            (objective_code, title, physics_topic, course_level, standard_source, description, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, COALESCE((SELECT created_at FROM curriculum_objectives WHERE objective_code=?), ?), ?)
        """, (
            data.objective_code.strip(), data.title.strip(), data.physics_topic.strip(),
            data.course_level.strip() or "freshman", data.standard_source.strip() or "Local Course Objective",
            data.description.strip(), data.status.strip() or "active", data.objective_code.strip(), now, now,
        ))
        conn.commit()
        objective_id = int(cur.lastrowid) if cur.lastrowid else conn.execute("SELECT id FROM curriculum_objectives WHERE objective_code=?", (data.objective_code.strip(),)).fetchone()["id"]
    with connect() as conn:
        row = conn.execute("SELECT * FROM curriculum_objectives WHERE id=?", (objective_id,)).fetchone()
    return row_to_dict(row)


def curriculum_coverage() -> Dict[str, Any]:
    ensure_curriculum_tables()
    objectives = fetch_curriculum_objectives()
    prompts = fetch_prompts()
    assignments = fetch_assignments()
    stories = fetch_stories()
    rows = []
    for obj in objectives:
        topic = (obj.get("physics_topic") or "").strip().lower()
        def match(item: Dict[str, Any], key: str = "physics_topic") -> bool:
            value = (item.get(key) or "").strip().lower()
            return bool(topic and (topic in value or value in topic))
        prompt_count = sum(1 for p in prompts if match(p))
        assignment_count = sum(1 for a in assignments if match(a))
        story_count = sum(1 for st in stories if match(st))
        approved_count = sum(1 for st in stories if match(st) and (st.get("status") or "").lower() == "approved")
        practiced_count = assignment_count + story_count
        coverage_label = "covered" if practiced_count >= 3 else "started" if practiced_count > 0 else "not_started"
        rows.append({
            **obj,
            "prompt_count": prompt_count,
            "assignment_count": assignment_count,
            "story_count": story_count,
            "approved_story_count": approved_count,
            "practiced_count": practiced_count,
            "coverage_label": coverage_label,
        })
    topic_summary: Dict[str, Dict[str, Any]] = {}
    for row in rows:
        topic = row.get("physics_topic") or "General"
        entry = topic_summary.setdefault(topic, {"physics_topic": topic, "objective_count": 0, "covered": 0, "started": 0, "not_started": 0, "stories": 0, "assignments": 0, "prompts": 0})
        entry["objective_count"] += 1
        entry[row["coverage_label"]] += 1
        entry["stories"] += row["story_count"]
        entry["assignments"] += row["assignment_count"]
        entry["prompts"] += row["prompt_count"]
    return {"objectives": rows, "topics": list(topic_summary.values()), "counts": {"objectives": len(rows), "topics": len(topic_summary)}}


