def solution_workspace_prefill(solution: str, equation: str = "") -> Dict[str, str]:
    """Create a simple four-step workspace without forcing students to know syntax.

    The existing saved solution is preserved in Step 1 so no student work is lost.
    """
    solution = str(solution or "").strip()
    return {
        "given": solution if solution else "Step 1: Given quantities\n",
        "equation": f"Step 2: Equation to use\n{equation}" if equation else "Step 2: Equation to use\n",
        "substitution": "Step 3: Substitute values and do the algebra\n",
        "answer": "Step 4: Final answer with units\n",
    }


