def _graph_from_request(text: str = "", record: Optional[Dict[str, str]] = None) -> str:
    low = (text or '').lower()
    name = (record or {}).get('name', '').lower()
    syntax = (record or {}).get('syntax', '').lower()
    combined = ' '.join([low, name, syntax])

    # Patch 24/28: choose the graph from the physics model, not just the variable names.
    # Patch 28: y=x2 is ambiguous and must not be silently treated as y=x^2.
    if _looks_like_ambiguous_y_equals_x2(combined):
        return _ambiguous_x2_reply()
    if _looks_like_y_equals_2x(combined):
        return _graph_y_equals_2x()
    if _looks_like_y_equals_x_squared(combined):
        return _graph_y_equals_x_squared()
    # Position/displacement vs time is linear only for constant velocity.  For free fall
    # or constant acceleration it is quadratic.  This rule must run before the
    # average-velocity/constant-velocity fallback.
    freefall_words = ['free fall', 'freefall', 'freely falling', 'falling object', 'dropped', 'drop from rest', 'fall off', 'gravity', 'gravitational']
    position_time = (('position' in combined or 'displacement' in combined or 'height' in combined or 'distance fallen' in combined or 'vertical position' in combined) and 'time' in combined)
    if position_time and any(w in combined for w in freefall_words):
        if 'distance fallen' in combined or 'downward distance' in combined:
            return _graph_freefall_distance_fallen_time()
        return _graph_freefall_position_time()
    if ('free fall' in combined or 'freefall' in combined or 'freely falling' in combined) and ('graph' in combined or 'plot' in combined):
        return _graph_freefall_position_time()
    if position_time and ('acceleration' in combined or 'constant acceleration' in combined or '1/2*a' in combined):
        return _graph_displacement_time_constant_acceleration()
    if 'quadratic' in combined and not any(k in combined for k in ['kinetic', 'displacement', 'energy', 'free fall']):
        return _graph_quadratic_example()
    if ('velocity' in combined and 'time' in combined and ('acceleration' in combined or 'constant acceleration' in combined)) or 'v = v_i' in combined:
        return _graph_velocity_time_constant_acceleration()
    if ('displacement' in combined and 'time' in combined and 'acceleration' in combined) or '1/2*a' in combined:
        return _graph_displacement_time_constant_acceleration()
    if 'kinetic energy' in combined or 'ke' in combined or 'v^2' in combined:
        return _graph_ke_vs_speed()
    if "ohm" in combined or 'v = i' in combined or ('voltage' in combined and 'current' in combined):
        return _graph_ohms_law()
    if 'momentum' in combined or 'p = m' in combined:
        return _graph_momentum_vs_velocity()
    if 'friction' in combined or 'mu_k' in combined or 'μ_k' in combined:
        return _graph_friction_vs_normal()
    if 'wave' in combined or 'lambda' in combined or 'frequency' in combined:
        return _graph_wave_speed_vs_frequency()
    if ('average velocity' in combined or 'average speed' in combined or 'v_avg' in combined or (('displacement' in combined or 'position' in combined) and 'time' in combined)):
        return _graph_displacement_time_constant_velocity()
    return _plot_svg_card(
        "Physics relationship example",
        "choose a physics model before graphing",
        "independent variable",
        "dependent variable",
        [(0, 0), (1, 1), (2, 4), (3, 9), (4, 16), (5, 25)],
        "This is only a placeholder. Ask for a specific physics model, such as free fall position versus time, velocity versus time for constant acceleration, or kinetic energy versus speed.",
        "Model needed"
    )

def _equation_graph_svg(record: Dict[str, str], request: str = "") -> str:
    return _graph_from_request(request, record)


def physics_ai_graph_svg(kind: str = 'linear', request: str = '') -> str:
    low = (request or kind or '').lower()
    if _looks_like_y_equals_x_squared(low):
        return _graph_y_equals_x_squared()
    if any(w in low for w in ['free fall', 'freefall', 'freely falling', 'falling object', 'dropped', 'gravity']) and any(w in low for w in ['position', 'displacement', 'height', 'distance', 'time', 'plot', 'graph']):
        if 'distance fallen' in low or 'downward distance' in low:
            return _graph_freefall_distance_fallen_time()
        return _graph_freefall_position_time()
    if 'velocity' in low and 'time' in low and 'acceleration' in low:
        return _graph_velocity_time_constant_acceleration()
    if (('position' in low or 'displacement' in low) and 'time' in low and 'acceleration' in low):
        return _graph_displacement_time_constant_acceleration()
    if 'kinetic' in low or 'ke' in low or kind == 'quadratic':
        return _graph_ke_vs_speed()
    if 'ohm' in low or 'voltage' in low or 'current' in low:
        return _graph_ohms_law()
    if 'momentum' in low:
        return _graph_momentum_vs_velocity()
    if 'friction' in low:
        return _graph_friction_vs_normal()
    if 'wave' in low:
        return _graph_wave_speed_vs_frequency()
    if 'acceleration' in low and ('displacement' in low or 'position' in low):
        return _graph_displacement_time_constant_acceleration()
    return _graph_displacement_time_constant_velocity()


