def ensure_independent_physics_chat_table() -> None:
    init_db()
    with connect() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS independent_physics_ai_chat_messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                role TEXT NOT NULL,
                message TEXT NOT NULL,
                created_at TEXT DEFAULT ''
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS independent_physics_ai_chat_archive (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                conversation_hash TEXT DEFAULT '',
                problem_text TEXT DEFAULT '',
                role TEXT NOT NULL,
                message TEXT NOT NULL,
                created_at TEXT DEFAULT '',
                archived_at TEXT DEFAULT ''
            )
        """)
        conn.commit()


def fetch_independent_physics_chat(limit: int = 100) -> List[Dict[str, Any]]:
    ensure_independent_physics_chat_table()
    with connect() as conn:
        rows = conn.execute(
            "SELECT * FROM independent_physics_ai_chat_messages ORDER BY id ASC LIMIT ?",
            (limit,),
        ).fetchall()
    return [row_to_dict(r) for r in rows]

def fetch_independent_physics_chat_archive(limit: int = 300) -> List[Dict[str, Any]]:
    ensure_independent_physics_chat_table()
    with connect() as conn:
        rows = conn.execute(
            "SELECT * FROM independent_physics_ai_chat_archive ORDER BY id DESC LIMIT ?",
            (limit,),
        ).fetchall()
    return [row_to_dict(r) for r in reversed(rows)]

def _v78_archive_and_clear_student_chat(previous_state: Dict[str, Any] | None = None) -> int:
    """Move the visible conversation to Chat History before a new Lab problem becomes active."""
    ensure_independent_physics_chat_table()
    previous_state = previous_state or {}
    conversation_hash = str(previous_state.get('canonical_hash') or '')
    problem_text = str(previous_state.get('problem_text') or '')
    with connect() as conn:
        rows = conn.execute(
            "SELECT role, message, created_at FROM independent_physics_ai_chat_messages ORDER BY id ASC"
        ).fetchall()
        for row in rows:
            conn.execute(
                "INSERT INTO independent_physics_ai_chat_archive (conversation_hash, problem_text, role, message, created_at, archived_at) VALUES (?, ?, ?, ?, ?, ?)",
                (conversation_hash, problem_text, row['role'], row['message'], row['created_at'], utc_now()),
            )
        if rows:
            conn.execute('DELETE FROM independent_physics_ai_chat_messages')
        conn.commit()
    return len(rows)


def save_independent_physics_chat(role: str, message: str) -> None:
    ensure_independent_physics_chat_table()
    with connect() as conn:
        conn.execute(
            "INSERT INTO independent_physics_ai_chat_messages (role, message, created_at) VALUES (?, ?, ?)",
            (role, str(message or '').strip(), utc_now()),
        )
        conn.commit()





# Compatibility alias added in v47 fixed baseline.
# The inherited stable chat-storage function is save_independent_physics_chat.
# v47 route code used add_independent_physics_chat, causing a NameError on POST.
def add_independent_physics_chat(role: str, message: str) -> None:
    return save_independent_physics_chat(role, message)

def _recent_assistant_context(limit: int = 6) -> str:
    """Return recent independent-chat text so follow-up questions can refer to the prior example/problem."""
    try:
        msgs = fetch_independent_physics_chat(limit=limit)
    except Exception:
        return ""
    parts = []
    for m in msgs[-limit:]:
        role = str(m.get('role') or '')
        text = str(m.get('message') or '').strip()
        if text:
            parts.append(f"{role}: {text}")
    return "\n".join(parts)


def _followup_solution_from_recent_context(message: str, recent: str) -> str:
    low = (message or '').lower()
    ctx = (recent or '').lower()
    wants_solution = any(k in low for k in ['complete solution', 'proceed to provide', 'solution of the example', 'solve the example', 'what is the solution', 'provide a complete solution'])
    if not wants_solution:
        return ''
    # The common example generated by the tutor: v_avg = 10 m/s for 10 s.
    if ('average speed' in ctx or 'average velocity' in ctx or 'v_avg' in ctx) and ('10 m/s' in ctx or '10 s' in ctx):
        return (
            "Complete solution for the example story:\n\n"
            "Story: A car travels in one direction with an average speed of 10 m/s for 10 s. Find how far it travels.\n\n"
            "Step 1: Known quantities and unknown\n"
            "v_avg = 10 m/s\n"
            "Δt = 10 s\n"
            "Unknown: Δx\n\n"
            "Step 2: Equation\n"
            "v_avg = Δx/Δt\n\n"
            "Step 3: Solve algebraically\n"
            "Δx = v_avg Δt\n\n"
            "Step 4: Substitute values\n"
            "Δx = (10 m/s)(10 s) = 100 m\n\n"
            "Final answer: The car travels 100 m. Because the car moves in one direction, the distance traveled is also the magnitude of the displacement."
        )
    if 'apple' in ctx and ('mechanical energy' in ctx or 'k_i' in ctx or 'mgh' in ctx):
        return (
            "Complete solution for the apple story:\n\n"
            "Step 1: Known quantities and unknown\n"
            "The apple starts from rest at height h. The unknown is the speed v just before reaching the ground.\n\n"
            "Step 2: Equation\n"
            "K_i + U_i = K_f + U_f\n\n"
            "Step 3: Substitute the energy terms\n"
            "0 + mgh = 1/2 mv² + 0\n\n"
            "Step 4: Solve\n"
            "mgh = 1/2 mv², so v = sqrt(2gh).\n\n"
            "Final answer: Ignoring air resistance, the apple's final speed depends on the drop height h and gravity g."
        )
    return (
        "I can solve the example, but I need the example values from the previous message. "
        "Please include the known quantities, or ask: 'solve using v_avg = 10 m/s and Δt = 10 s.'"
    )



