def _split_graph_requests(message: str) -> List[str]:
    """Return one or more graph requests from a student message.

    Patch 32: split repeated Plot/Graph/Show requests robustly so an
    ambiguous request such as y=x2 does not get merged with a valid request
    such as y=x^2.  Each request should be routed independently.
    """
    text = str(message or '').strip()
    if not text:
        return []
    low = text.lower()
    if 'graph' not in low and 'plot' not in low:
        return []
    # Reading/analyzing an existing graph is not a graph-generation request.
    if any(k in low for k in ['what do i do', 'how do i', 'how can i', 'from a graph', 'from the graph', 'for a plot', 'for a position versus time graph']) and any(k in low for k in ['average velocity', 'slope']):
        return []
    # First respect line breaks.
    lines = [ln.strip(' -•\t') for ln in re.split(r'[\r\n]+', text) if ln.strip()]
    graph_lines = [ln for ln in lines if any(k in ln.lower() for k in ['graph', 'plot'])]
    if len(graph_lines) >= 2:
        return graph_lines
    # Then split repeated commands on one line: "Plot y=x2 Plot y=x^2".
    matches = list(re.finditer(r'(?i)\b(?:plot|graph|show\s+me\s+(?:a\s+)?(?:plot|graph)(?:\s+for)?)\b', text))
    if len(matches) >= 2:
        parts = []
        for idx, m in enumerate(matches):
            a = m.start()
            b = matches[idx+1].start() if idx+1 < len(matches) else len(text)
            part = text[a:b].strip(' .;\n\t')
            if part:
                parts.append(part)
        return parts
    return [text]

def _graph_explanation_for_request(request: str) -> str:
    low = (request or '').lower()
    if _looks_like_y_equals_x_squared(low):
        return (
            "The requested function y = x² is quadratic, not linear. Its graph is a parabola opening upward. The slope changes from negative to zero to positive as x passes through 0."
        )
    if any(w in low for w in ['free fall', 'freefall', 'freely falling', 'falling object', 'dropped', 'gravity']) and any(w in low for w in ['position', 'displacement', 'height', 'distance', 'time', 'plot', 'graph']):
        return (
            "For free fall, position versus time is quadratic, not linear. "
            "Using upward as positive, y = y_0 + v_0*t - 1/2*g*t^2. The curve bends because gravity gives constant acceleration, so the slope of the position-time graph changes with time."
        )
    if 'velocity' in low and 'time' in low and 'acceleration' in low:
        return (
            "For constant acceleration, the velocity-time graph is a straight line. "
            "The equation is v = v_i + a*t. The slope is the acceleration a, and the vertical intercept is the initial velocity v_i."
        )
    if ('kinetic' in low or 'ke' in low) and ('speed' in low or 'velocity' in low):
        return (
            "Kinetic energy depends on the square of speed: KE = 1/2*m*v^2. "
            "The graph of KE versus speed is curved upward, not linear."
        )
    if 'quadratic' in low and not any(k in low for k in ['kinetic', 'displacement']):
        return (
            "A quadratic graph curves because the dependent variable changes with the square of the independent variable. "
            "It is not linear: the slope is not constant, and the curve becomes steeper as the independent variable increases."
        )
    if 'voltage' in low and 'current' in low:
        return (
            "For an ohmic resistor, voltage is proportional to current: V = I*R. "
            "The voltage-current graph is a straight line whose slope is the resistance R."
        )
    if 'momentum' in low and ('velocity' in low or 'speed' in low):
        return (
            "Momentum is proportional to velocity for a fixed mass: p = m*v. "
            "The momentum-velocity graph is a straight line whose slope is the mass m."
        )
    if (('displacement' in low or 'position' in low) and 'time' in low and 'acceleration' in low):
        return (
            "For constant acceleration, position or displacement has a quadratic dependence on time: Δx = v_i*t + 1/2*a*t^2. "
            "The graph curves because the slope is velocity, and velocity changes with time."
        )
    if ('position' in low or 'x versus time' in low or 'position versus time' in low) and ('average velocity' in low or 'velocity' in low):
        return (
            "To get average velocity from a position-time graph, choose two points on the graph and calculate the slope of the secant line: v_avg = Δx/Δt = (x_f - x_i)/(t_f - t_i). "
            "The sign of the slope gives the direction of the average velocity."
        )
    if ('distance' in low or 'displacement' in low) and 'time' in low:
        return (
            "For constant average velocity, displacement changes linearly with time: Δx = v_avg*Δt. "
            "On a displacement-time graph, the slope is the average velocity."
        )
    if 'friction' in low:
        return (
            "Kinetic friction is proportional to the normal force: f_k = μ_k*N. "
            "The friction-normal-force graph is a straight line whose slope is μ_k."
        )
    return (
        "I will treat this as a physics graph request. The key is to identify the independent variable, dependent variable, and the equation that connects them."
    )


def _graph_response_for_requests(message: str) -> str:
    # Patch 26/28: plain algebra/function plot requests must be caught before
    # broad physics graph routing. Patch 28 treats y=x2 as ambiguous instead
    # of silently assuming a parabola.
    if _looks_like_ambiguous_y_equals_x2(message) and not _looks_like_y_equals_x_squared(message):
        return _ambiguous_x2_reply()
    preliminary_requests = _split_graph_requests(message)
    # For a single function request, handle directly. For multiple lines, handle
    # each request inside the loop below so no graph is lost.
    if len(preliminary_requests) <= 1:
        custom_physics_reply = _custom_physics_graph_reply(message)
        if custom_physics_reply:
            return custom_physics_reply
        general_function_reply = _general_function_graph_reply(message)
        if general_function_reply:
            return general_function_reply
    if len(preliminary_requests) <= 1 and _looks_like_y_equals_2x(message):
        return (
            "Graph: y = 2x\n"
            "This is an algebraic function plot. It is linear, not quadratic.\n"
            + _graph_y_equals_2x()
        )
    if len(preliminary_requests) <= 1 and _looks_like_y_equals_x_squared(message):
        return (
            "Graph: y = x²\n"
            "This is an algebraic function plot. It is quadratic, not linear.\n"
            + _graph_y_equals_x_squared()
        )
    requests = preliminary_requests
    if not requests:
        return ''
    blocks = []
    if len(requests) > 1:
        blocks.append(f"You asked for {len(requests)} graphs. I will treat each line as a separate graph request.\n")
    for i, req in enumerate(requests, start=1):
        # Patch 27/28: catch function syntax again inside each split graph request.
        # y=x2 is ambiguous; y=x^2 is explicit quadratic; y=2x is explicit linear.
        if _looks_like_ambiguous_y_equals_x2(req) and not _looks_like_y_equals_x_squared(req):
            blocks.append(f"Graph {i}: ambiguous input y=x2" if len(requests) > 1 else "Graph: ambiguous input y=x2")
            blocks.append(_ambiguous_x2_reply())
            continue
        custom_req_reply = _custom_physics_graph_reply(req)
        if custom_req_reply:
            blocks.append(custom_req_reply)
            continue
        general_req_reply = _general_function_graph_reply(req)
        if general_req_reply:
            blocks.append(general_req_reply)
            continue
        if _looks_like_y_equals_2x(req):
            blocks.append(f"Graph {i}: y = 2x" if len(requests) > 1 else "Graph: y = 2x")
            blocks.append("This is an algebraic function plot. It is linear, not quadratic. The slope is 2 and the intercept is 0.")
            blocks.append(_graph_y_equals_2x())
            continue
        if _looks_like_y_equals_x_squared(req):
            blocks.append(f"Graph {i}: y = x²" if len(requests) > 1 else "Graph: y = x²")
            blocks.append("This is an algebraic function plot. It is quadratic, not linear. The graph is a parabola opening upward, and the slope is not constant.")
            blocks.append(_graph_y_equals_x_squared())
            continue
        title = f"Graph {i}: {req}" if len(requests) > 1 else f"Graph: {req}"
        blocks.append(title)
        blocks.append(_graph_explanation_for_request(req))
        blocks.append(_graph_from_request(req, None))
    return "\n\n".join(blocks)


