def _module_name_from_message(message: str) -> str:
    low = str(message or '').lower()
    # Use bounded matching so short aliases like "ke" do not accidentally match
    # words such as "mistakes".  Explicit topic words still win over generic cues.
    priority = ['newton', 'energy', 'momentum', 'kinematics', 'graphing']
    for name in priority:
        mod = TUTOR_CONCEPT_MODULES.get(name, {})
        tokens = [name] + list(mod.get('aliases', []))
        for token in tokens:
            tok = str(token).lower().strip()
            if not tok:
                continue
            if len(tok) <= 3 or re.match(r'^[a-z0-9_]+$', tok):
                if re.search(r'(?<![a-z0-9_])' + re.escape(tok) + r'(?![a-z0-9_])', low):
                    return name
            elif tok in low:
                return name
    return ''


def _requested_response_level(message: str) -> str:
    low = str(message or '').lower()
    if 'advanced' in low or 'derivation' in low or 'calculus' in low or 'vector' in low:
        return 'advanced'
    if 'intermediate' in low or 'algebra' in low or 'step-by-step' in low or 'step by step' in low:
        return 'intermediate'
    if 'basic' in low or 'simple' in low or 'short' in low:
        return 'basic'
    return 'intermediate'


def _concept_module_reply(message: str) -> Optional[str]:
    low = str(message or '').lower()
    topic = _module_name_from_message(message)
    if not topic:
        return None
    # Trigger only when the user is asking to learn, explain, make notes, list steps, use module, or compare concepts.
    trigger_phrases = [
        'explain', 'notes', 'module', 'concept', 'basic', 'intermediate', 'advanced',
        'when to use', 'common mistake', 'mistakes', 'steps', 'how do i choose', 'how to choose',
        'difference', 'compare', 'summary', 'review', 'learn'
    ]
    # v29: do not let the substring 'teach' inside 'teacher' trigger a module dump.
    # Only explicit tutor requests like 'teach me kinematics' or 'teach kinematics' should trigger.
    explicit_teach = bool(re.search(r'(?<![a-z])teach( me)?(?![a-z])', low))
    if not (explicit_teach or any(t in low for t in trigger_phrases)):
        return None
    if 'teacher asked' in low or 'my teacher' in low or 'asked me to study' in low:
        # This is a student planning prompt, not a request for the whole concept module.
        return None
    mod = TUTOR_CONCEPT_MODULES[topic]
    level = _requested_response_level(message)
    eqs = mod.get('equations', [])
    mistakes = mod.get('common_mistakes', [])
    steps = mod.get('reasoning_steps', [])
    variables = mod.get('variables', {})
    do_not = mod.get('do_not_use_when', [])
    lines = [
        f"Concept module: {topic.title()}",
        f"Response level: {level}",
        "",
        "Core idea:",
        str(mod.get('core_idea','')),
        "",
        "Student explanation:",
        str(mod.get('student_explanation','')),
        "",
        f"{level.title()} explanation:",
        str(mod.get(level, mod.get('student_explanation',''))),
    ]
    if eqs:
        lines += ["", "Key equations:"] + [f"- {eq}" for eq in eqs]
    if mod.get('when_to_use'):
        lines += ["", "When to use:", str(mod.get('when_to_use'))]
    if do_not:
        lines += ["", "Do not use when:"] + [f"- {x}" for x in do_not]
    if variables:
        lines += ["", "Important variables:"] + [f"- {k}: {v}" for k, v in variables.items()]
    if steps:
        lines += ["", "Required reasoning steps:"] + [f"{i+1}. {step}" for i, step in enumerate(steps)]
    if mistakes:
        lines += ["", "Common mistakes:"] + [f"- {m}" for m in mistakes]
    # Add a short next-action prompt appropriate for a local tutor.
    lines += ["", "Next action:", f"Give me a {topic} story, graph, or calculation, and I will classify the situation before choosing an equation."]
    return "\n".join(lines)


def _compare_energy_momentum_reply(message: str) -> Optional[str]:
    low = str(message or '').lower()
    if not (('energy' in low and 'momentum' in low) and any(k in low for k in ['difference', 'compare', 'distinguish', 'versus', 'vs'])):
        return None
    return (
        "Concept comparison: Energy vs Momentum\n\n"
        "Momentum uses p = mv. It is a vector, so direction matters. Use it for one-object momentum, impulse, collisions, recoil, and system interactions.\n\n"
        "Kinetic energy uses K = 1/2mv^2. It is a scalar, so it has no direction. Use it when the question asks about energy of motion, work, height-to-speed conversion, or energy transfer.\n\n"
        "Model-choice rule:\n"
        "1. If the question asks for momentum or direction of motion after an interaction, start with momentum.\n"
        "2. If the question asks for kinetic energy, work, speed from height, or joules, start with energy.\n"
        "3. If both appear, define the physical situation first; do not choose only because the symbols m and v appear.\n\n"
        "Common mistake: mass and speed appear in both equations, but the models are different."
    )

def _classify_tutor_request(message: str) -> Dict[str, Any]:
    """Small local classifier for tutor-style routing.

    This is deliberately transparent and rule-based for now.  It is the first
    baseline for the future tutor reasoning engine; later it can be backed by a
    richer concept-module database or external model.
    """
    msg = str(message or '').strip()
    low = msg.lower()
    request_type = 'conceptual explanation'
    if any(k in low for k in ['graph', 'plot']):
        request_type = 'graph'
    if any(k in low for k in ['calculate', 'compute', 'solve', 'find', 'what is', 'how much', 'determine']):
        request_type = 'calculation/solution'
    if any(k in low for k in ['rewrite', 'correct spelling', 'grammar', 'own words', 'make it clear']):
        request_type = 'rewrite/language edit'
    if any(k in low for k in ['practice problem', 'practice', 'quiz']):
        request_type = 'practice problem'
    if any(k in low for k in ['write a story', 'story about', 'turn into story', 'make a story']):
        request_type = 'story generation'

    model = 'general physics'
    graph_type = None
    if any(k in low for k in ['graph', 'plot']):
        if re.search(r'\by\s*=|\bf\s*\(|x\^|x\*\*|sqrt\(|1\s*/\s*x', low):
            model = 'mathematical function graph'
            graph_type = 'mathematical function'
        elif any(k in low for k in ['csv', 'table', 'data points', 'data table']):
            model = 'data visualization'
            graph_type = 'data/table'
        else:
            model = 'physics graph'
            graph_type = 'physics model'
    elif any(k in low for k in ['kinetic energy', 'potential energy', 'energy', 'mgh', 'ke', 'pe']):
        # v21: explicit energy language wins over generic mass/speed cues.
        model = 'energy'
    elif any(k in low for k in ['momentum', 'collision', 'impulse']) or ((('mass' in low) or ('kg' in low)) and (('velocity' in low) or ('speed' in low) or ('m/s' in low)) and ('momentum' in low)):
        model = 'momentum'
    elif any(k in low for k in ['free fall', 'freely falling', 'dropped', 'kinematics', 'velocity', 'acceleration', 'position', 'displacement']):
        model = 'kinematics'
    elif any(k in low for k in ['force', 'newton', 'friction', 'normal force', 'fbd']):
        model = 'newton'
    return {'request_type': request_type, 'model': model, 'graph_type': graph_type}


def _extract_named_parameters(message: str) -> Dict[str, float]:
    params: Dict[str, float] = {}
    text = str(message or '')
    patterns = {
        'mass': r'\b(?:mass|m)\s*(?:=|is|of)?\s*(-?\d+(?:\.\d+)?)\s*(?:kg)?\b',
        'velocity': r'\b(?:velocity|speed|v)\s*(?:=|is|of)?\s*(-?\d+(?:\.\d+)?)\s*(?:m/s)?\b',
        'time': r'\b(?:time|t)\s*(?:=|is|of)?\s*(-?\d+(?:\.\d+)?)\s*(?:s|sec|seconds)?\b',
        'acceleration': r'\b(?:acceleration|a)\s*(?:=|is|of)?\s*(-?\d+(?:\.\d+)?)\s*(?:m/s\^?2)?\b',
        'distance': r'\b(?:distance|displacement|delta x|dx|x)\s*(?:=|is|of)?\s*(-?\d+(?:\.\d+)?)\s*(?:m|meter|meters)?\b',
    }
    for name, pat in patterns.items():
        m = re.search(pat, text, flags=re.I)
        if m:
            try: params[name] = float(m.group(1))
            except Exception: pass
    return params


def _reasoning_summary(message: str, equation: str = '', why: str = '', knowns: Optional[List[str]] = None, unknown: str = '') -> str:
    c = _classify_tutor_request(message)
    lines = [
        "Tutor reasoning",
        f"Problem type: {c['request_type']}",
        f"Model: {c['model']}",
    ]
    if knowns:
        lines.append("Knowns: " + "; ".join(knowns))
    if unknown:
        lines.append("Unknown: " + unknown)
    if equation:
        lines.append("Equation: " + equation)
    if why:
        lines.append("Why this applies: " + why)
    return "\n".join(lines)


def _momentum_reasoning_reply(message: str) -> Optional[str]:
    low = (message or '').lower()
    nums = _extract_numbers(message)
    if 'momentum' not in low and not ('mass' in low and ('velocity' in low or 'speed' in low)):
        return None
    if any(k in low for k in ['calculate', 'compute', 'find', 'what do i do', 'what is']) and len(nums) >= 2 and ('kg' in low or 'mass' in low) and ('m/s' in low or 'velocity' in low or 'speed' in low):
        m, v = nums[0], nums[1]
        direction = ''
        for d in ['east','west','north','south','upward','downward','left','right']:
            if d in low:
                direction = ' ' + d
                break
        return (
            _reasoning_summary(
                message,
                equation='p = mv',
                why='Momentum of a single object is mass times velocity, and velocity carries direction.',
                knowns=[f"m = {_fmt_num(m)} kg", f"v = {_fmt_num(v)} m/s{direction}"],
                unknown='p'
            ) +
            "\n\nStep 1: Identify the object and direction.\n"
            "The object has mass and velocity, so this is single-object momentum, not momentum conservation.\n\n"
            "Step 2: Substitute into p = mv.\n"
            f"p = ({_fmt_num(m)} kg)({_fmt_num(v)} m/s) = {_fmt_num(m*v)} kg·m/s{direction}\n\n"
            f"Final answer: p = {_fmt_num(m*v)} kg·m/s{direction}.\n"
            "Common mistake: do not use conservation of momentum unless there is a defined interacting system such as a collision or recoil."
        )
    if any(k in low for k in ['practice','problem']):
        return (
            _reasoning_summary(message, equation='Σp_initial = Σp_final', why='For a collision system, total momentum is conserved only when external impulse is negligible.') +
            "\n\nPractice problem: A 2 kg cart moving east at 3 m/s collides and sticks to a 1 kg cart initially at rest. Find the final velocity of the combined carts.\n"
            "Start by defining the system as both carts, choosing east as positive, and writing m1 v1i + m2 v2i = (m1+m2)vf."
        )
    if any(k in low for k in ['story','situation','example']):
        return (
            _reasoning_summary(message, equation='p = mv or Σp_initial = Σp_final', why='The correct equation depends on whether the question is one-object momentum or system momentum conservation.') +
            "\n\nExample situation: A cart rolls east on a low-friction track and collides with a second cart. During the short collision, if external horizontal impulse is small, the two-cart system can be analyzed using conservation of momentum."
        )
    return None


def _kinematics_reasoning_reply(message: str) -> Optional[str]:
    low = (message or '').lower()
    nums = _extract_numbers(message)
    if not any(k in low for k in ['average velocity', 'velocity', 'speed', 'acceleration', 'position', 'displacement', 'free fall', 'kinematics', 'slowed', 'slowed down', 'sped up', 'brake', 'braked']):
        return None

    # v26: acceleration/deceleration from change in velocity has high priority.
    # Example: slowed from 20 m/s to 10 m/s in 2 s -> a = (vf-vi)/Δt.
    accel_intent = any(k in low for k in ['acceleration', 'accelerate', 'deceleration', 'decelerate', 'slowed', 'slowed down', 'brake', 'braked', 'sped up'])
    if accel_intent and len(nums) >= 3 and any(k in low for k in ['m/s', 'second', 'seconds', ' sec', ' s']):
        vi, vf, dt = nums[0], nums[1], nums[2]
        if dt != 0:
            a = (vf - vi) / dt
            sign_word = 'negative' if a < 0 else ('positive' if a > 0 else 'zero')
            direction_note = (
                'If we choose the original direction of motion as positive, the acceleration is negative because the final velocity is smaller than the initial velocity.'
                if a < 0 else
                'If we choose the original direction of motion as positive, the acceleration is positive because the final velocity is larger than the initial velocity.'
                if a > 0 else
                'The acceleration is zero because the velocity did not change.'
            )
            return (
                "Tutor reasoning\n"
                "Problem type: calculation/solution\n"
                "Model: kinematics\n"
                f"Knowns: v_i = {_fmt_num(vi)} m/s; v_f = {_fmt_num(vf)} m/s; Δt = {_fmt_num(dt)} s\n"
                "Unknown: a\n"
                "Equation: a = (v_f - v_i)/Δt\n"
                "Why this applies: Acceleration is the rate of change of velocity. The question gives an initial velocity, final velocity, and elapsed time." +
                "\n\nStep 1: Choose the positive direction.\n"
                "Let the original direction of motion be positive.\n\n"
                "Step 2: Use the acceleration equation.\n"
                "a = (v_f - v_i)/Δt\n\n"
                f"Step 3: Substitute the values.\na = ({_fmt_num(vf)} - {_fmt_num(vi)})/{_fmt_num(dt)} = {_fmt_num(a)} m/s².\n\n"
                f"Final answer: a = {_fmt_num(a)} m/s², so the acceleration is **{sign_word}**.\n"
                f"Why: {direction_note} The object can still be moving forward while accelerating backward.\n"
                "Common mistake: negative acceleration does not always mean moving backward; it means acceleration points in the negative direction."
            )

    if any(k in low for k in ['average velocity', 'v_avg']) and any(k in low for k in ['position versus time', 'position-time', 'position vs time', 'x versus time', 'x vs time', 'from a plot', 'from a graph']):
        return (
            _reasoning_summary(
                message,
                equation='v_avg = Δx/Δt = (x_f - x_i)/(t_f - t_i)',
                why='Average velocity is the slope of the secant line between two points on a position-time graph.',
                knowns=['two points on the position-time graph'],
                unknown='average velocity'
            ) +
            "\n\nStep 1: Choose two points on the graph, preferably clear grid points.\n"
            "Step 2: Read their coordinates: (t_i, x_i) and (t_f, x_f).\n"
            "Step 3: Compute the slope: v_avg = (x_f - x_i)/(t_f - t_i).\n"
            "Step 4: Include the sign and units. Positive slope means motion in +x; negative slope means motion in -x.\n"
            "Common mistake: average speed uses total distance/time, but average velocity uses displacement/time."
        )
    if any(k in low for k in ['calculate','compute','solve','find']) and len(nums) >= 2 and any(k in low for k in ['average velocity','average speed','v_avg']):
        a, b = nums[0], nums[1]
        # Interpret as velocity*time if speed and time are present; otherwise be transparent.
        if ('m/s' in low or 'speed' in low or 'velocity' in low) and ('s' in low or 'sec' in low or 'time' in low):
            return (
                _reasoning_summary(message, equation='Δx = v_avg Δt', why='For constant average velocity over a time interval, displacement equals average velocity times elapsed time.', knowns=[f"v_avg = {_fmt_num(a)} m/s", f"Δt = {_fmt_num(b)} s"], unknown='Δx') +
                f"\n\nSubstitute: Δx = ({_fmt_num(a)} m/s)({_fmt_num(b)} s) = {_fmt_num(a*b)} m.\n"
                f"Final answer: Δx = {_fmt_num(a*b)} m, assuming the direction is unchanged."
            )
    return None


def _energy_reasoning_reply(message: str) -> Optional[str]:
    low = (message or '').lower()
    if not any(k in low for k in ['energy', 'kinetic', 'potential', 'mgh', 'ke', 'pe', 'apple', 'falling']):
        return None
    if any(k in low for k in ['story','write','example']) and 'apple' in low:
        return (
            _reasoning_summary(message, equation='K_i + U_i = K_f + U_f', why='If air resistance is neglected, gravitational potential energy becomes kinetic energy during the fall.') +
            "\n\nStory: An apple hangs from a branch near the top of a tall tree. At first it is at rest, so its kinetic energy is nearly zero, but it has gravitational potential energy because it is high above the ground. When the apple falls, gravity pulls it downward and its potential energy is converted into kinetic energy.\n\n"
            "Physics connection: if losses are negligible, K_i + U_i = K_f + U_f. For a drop from rest, this often becomes mgh = 1/2 mv^2."
        )
    if any(k in low for k in ['kinetic energy','ke']) and len(_extract_numbers(message)) >= 2 and any(k in low for k in ['calculate','compute','find','solve','what is','how much','determine']):
        nums = _extract_numbers(message)
        m, v = nums[0], nums[1]
        ke = 0.5*m*v*v
        return (
            _reasoning_summary(message, equation='K = 1/2 mv^2', why='The question asks for kinetic energy, so use the energy of motion model. Kinetic energy depends on mass and the square of speed.', knowns=[f"m = {_fmt_num(m)} kg", f"v = {_fmt_num(v)} m/s"], unknown='K') +
            "\n\nStep 1: Identify the model.\nThis is a kinetic-energy calculation, not a momentum calculation, because the question asks for energy.\n\n"
            "Step 2: Choose the equation.\nK = 1/2 mv^2\n\n"
            f"Step 3: Substitute the values.\nK = 1/2({_fmt_num(m)} kg)({_fmt_num(v)} m/s)^2 = {_fmt_student_num(ke)} J.\n\n"
            "Step 4: Check units.\nkg·(m/s)^2 = kg·m^2/s^2 = joule (J).\n\n"
            f"Final answer: K = {_fmt_student_num(ke)} J.\n"
            "Common mistake: do not use p = mv here. Momentum uses mass times velocity; kinetic energy uses one-half mass times speed squared."
        )
    return None


def independent_physics_ai_reply(message: str) -> str:
    msg = str(message or '').strip()
    low = msg.lower()
    recent = _recent_assistant_context()
    if not msg:
        return "Ask me any physics question, equation question, calculation, graph request, or ask me to turn an equation idea into a physics story."

    projectile_any_route = _projectile_motion_guidance_reply(msg)
    if projectile_any_route:
        return projectile_any_route

    # v30: absolute early guard for pursuit/story-planning prompts in any chat route.
    # Some Branch 2 navigation paths can pass broad story questions through the
    # independent tutor fallback.  A cheetah/deer chase question must still be
    # answered as pursuit guidance or solved as a pursuit problem, not as the
    # generic help prompt.
    projectile_any_route = _projectile_motion_guidance_reply(msg)
    if projectile_any_route:
        return projectile_any_route
    pursuit_any_route = _branch2_story_guidance_reply(msg)
    if pursuit_any_route:
        return pursuit_any_route
    pursuit_direct_any_route = _pursuit_setup_or_solve_reply(msg)
    if pursuit_direct_any_route:
        return pursuit_direct_any_route

    followup = _followup_solution_from_recent_context(msg, recent)
    if followup:
        return followup

    # Step 1: Classify graph/data/function requests before physics fallbacks.
    # If the student asks for graphing notes/explanation, use the concept module;
    # if they ask to plot/graph a relationship, draw or interpret the graph.
    if any(k in low for k in ['graph', 'plot']):
        if any(k in low for k in ['notes', 'explain', 'concept', 'module', 'common mistake', 'how to', 'teach', 'review']) and not any(k in low for k in ['plot y', 'plot ', 'show me a graph', 'draw', 'sketch']):
            module_reply = _concept_module_reply(msg)
            if module_reply:
                return module_reply
        # Reading an existing graph is a reasoning task, not necessarily a draw-new-graph task.
        if any(k in low for k in ['average velocity', 'v_avg']) and any(k in low for k in ['position versus time', 'position-time', 'position vs time', 'x versus time', 'x vs time', 'from a plot', 'from a graph']):
            return _kinematics_reasoning_reply(msg) or _graph_response_for_requests(msg)
        return _graph_response_for_requests(msg)

    # Step 2: Story/language requests should generate or rewrite text before solving.
    if any(k in low for k in ['rewrite','write this story','write the story','own words','correct spelling','spelling','grammar','make it clear','cohesive','clean up','edit the story','fix the story']):
        return _rewrite_student_story(msg)

    if any(k in low for k in ['turn into story','make a story','write a story','help me write a story','story about']):
        rec = {'name': 'Physics story', 'syntax': '', 'use': 'Use the physics principle that matches the situation.'}
        if 'apple' in low and ('tree' in low or 'branch' in low or 'fall' in low):
            return _energy_reasoning_reply(msg) or _write_story_for_selected_equation({'name':'Mechanical energy conservation','syntax':'K_i + U_i = K_f + U_f','use':'Use when mechanical energy is conserved and losses are negligible.'}, msg)
        elif 'car' in low and ('speed' in low or 'velocity' in low or 'time' in low):
            rec = {'name': 'Average velocity', 'syntax': 'v_avg = Delta x/Delta t', 'use': 'Use when displacement and elapsed time are related by average velocity.'}
        elif 'momentum' in low or 'collision' in low or ('bird' in low and 'snack' in low):
            rec = {'name': 'Momentum', 'syntax': 'p = mv or Σp_initial = Σp_final', 'use': 'Use p=mv for one object; use conservation only for a defined system with negligible external impulse.'}
        return _write_story_for_selected_equation(rec, msg)

    # Step 3: Structured concept-module and comparison requests.
    cmp_reply = _compare_energy_momentum_reply(msg)
    if cmp_reply:
        return cmp_reply
    module_reply = _concept_module_reply(msg)
    if module_reply:
        return module_reply

    # Step 4: Tutor reasoning replies for major starter concepts.
    for handler in (_energy_reasoning_reply, _momentum_reasoning_reply, _kinematics_reasoning_reply):
        reply = handler(msg)
        if reply:
            return reply

    # Step 5: General equation-choice notes and common tutoring modes.
    if any(k in low for k in ['notes', 'how to choose an equation', 'choose an equation', 'model']):
        return (
            _reasoning_summary(msg, why='Equation choice should follow the physical model, not symbol matching.') +
            "\n\nHow to choose an equation:\n"
            "1. Identify the physical situation.\n"
            "2. List knowns and unknowns.\n"
            "3. Decide the model: constant velocity, constant acceleration, force/net force, energy, or momentum.\n"
            "4. Choose an equation whose conditions match the model.\n"
            "5. Solve and interpret units and signs.\n"
            "Common mistake: choosing an equation only because it contains the variable you want."
        )

    if 'friction' in low or 'brake' in low or 'stopping' in low:
        return (
            _reasoning_summary(msg, equation='ΣF_x = -f_k = ma_x; f_k = μ_k N; F_n = mg', why='On a level surface with kinetic friction, friction acts opposite motion and causes negative acceleration if +x is forward.') +
            "\n\nChoose +x in the direction of motion. Friction points backward, so ΣF_x = -f_k = ma_x. With f_k = μ_kN and F_n = mg, a_x = -μ_k g. Then use v_f² = v_i² + 2a_xΔx if stopping distance is needed."
        )

    if any(k in low for k in ['force', 'newton', 'fbd', 'free body']):
        return (
            _reasoning_summary(msg, equation='ΣF = ma', why='Newton’s second law applies when net force causes acceleration.', unknown='net force or acceleration') +
            "\n\nRequired reasoning steps:\n"
            "1. Identify one object.\n"
            "2. Draw only forces acting on that object.\n"
            "3. Choose axes.\n"
            "4. Write ΣF = ma along each needed axis.\n"
            "5. Solve and interpret the sign of acceleration.\n"
            "Common mistake: action-reaction forces act on different objects and do not belong on the same free-body diagram."
        )

    if any(k in low for k in ['practice problem', 'practice']):
        return "Practice problem: A car starts from rest and accelerates uniformly at 2 m/s² for 5 s. Find its final velocity and displacement. First classify the model, then choose equations."

    if any(k in low for k in ['basic', 'intermediate', 'advanced']):
        return (
            "Response levels are available.\n\n"
            "Basic: conceptual explanation with minimal math.\n"
            "Intermediate: algebraic solution with standard equations.\n"
            "Advanced: vectors, calculus, derivation, or limiting cases.\n\n"
            "Tell me the topic and level, for example: 'Explain projectile motion at the intermediate level.'"
        )

    return (
        "I can help as a physics tutor. I will try to classify the situation first, then choose the model, equation, solution, and interpretation.\n\n"
        "Useful prompts:\n"
        "- Calculate momentum for m = 10 kg and v = 10 m/s east.\n"
        "- Get average velocity from a position-time graph.\n"
        "- Plot y=x^2 from x=-5 to x=5.\n"
        "- Write a story about an apple falling from a tree.\n"
        "- Give me a Newton’s second law practice problem."
    )

def chat_messages_html(messages: List[Dict[str, Any]]) -> str:
    if not messages:
        return '<p class="muted">No chat messages yet. Start by asking a physics or equation question.</p>'
    out = []
    for m in messages:
        role = str(m.get('role') or '')
        label = 'Student' if role == 'student' else 'AI Tutor'
        cls = 'student' if role == 'student' else 'assistant'
        out.append(f'<div class="card wide chat-card {cls}"><strong>{label}</strong><p>{format_chat_text(str(m.get("message") or ""))}</p><small>{h(m.get("created_at") or "")}</small></div>')
    return ''.join(out)



