# -----------------------------------------------------------------------------
# QA Patch 19: intent routing for equation chat
# -----------------------------------------------------------------------------
def _wants_rewrite_or_language_edit(message: str) -> bool:
    low = (message or "").lower()
    return any(k in low for k in [
        "rewrite", "write this story", "write the story", "own words",
        "correct spelling", "spelling", "grammar", "make it clear",
        "cohesive", "clean up", "edit the story", "fix the story"
    ])


def _extract_story_for_rewrite(message: str) -> str:
    """Extract the student story from a free equation-chat message.

    Students often write a rough story and then add a command such as
    "rewrite this story in correct spelling and grammar".  The tutor should
    edit the story, not fall back to the selected equation template.
    """
    text = (message or "").strip()
    # Remove the explicit edit instruction from the end or beginning while
    # preserving the actual student situation.
    patterns = [
        r"(?i)\s*[-–—:]*\s*rewrite this story.*$",
        r"(?i)\s*[-–—:]*\s*write this story in your own words.*$",
        r"(?i)\s*[-–—:]*\s*correct spelling and grammar.*$",
        r"(?i)^\s*(please\s+)?(rewrite|edit|correct|clean up).*?:\s*",
    ]
    for pat in patterns:
        text = re.sub(pat, "", text).strip()
    # Keep useful physics framing, but remove meta-commentary if it is just a label.
    text = re.sub(r"(?i)^this is (a|an)?\s*", "", text).strip()
    return text or (message or "").strip()


def _rewrite_student_story_briefly(message: str, equation: str = "") -> str:
    rough = _extract_story_for_rewrite(message)
    low = rough.lower()
    # A few classroom-safe, deterministic rewrites for common student patterns.
    if "bird" in low and "snack" in low:
        rewritten = (
            "While I was eating a snack on the beach, a bird flew by and snatched the snack from my hand. "
            "The bird was moving at about 10 m/s as it carried the snack away. "
            "I want to understand how the momentum of the snack changes during this interaction and whether momentum is conserved for the system I choose."
        )
        note = (
            "Physics focus: this can become a momentum story, but the system must be defined carefully. "
            "The snack alone does not have conserved momentum because the bird exerts a force on it. "
            "A better question is whether the momentum of the bird-and-snack system is conserved during a short interaction when external impulse is small."
        )
    elif any(k in low for k in ["car", "speed", "velocity", "distance", "time"]):
        rewritten = (
            "A car travels with an average speed of 10 m/s for 10 s. "
            "The question is how far the car travels during that time."
        ) if "10" in low else (
            "A car moves for a measured amount of time with a known average speed or average velocity. "
            "The question is to determine the distance traveled or displacement during the trip."
        )
        note = "Physics focus: average speed or average velocity, using v_avg = Δx/Δt or distance/time as appropriate."
    elif any(k in low for k in ["height", "fall", "dropped", "raised", "log"]):
        rewritten = (
            "An object is raised to a height h above the ground. When it is released, its gravitational potential energy changes into kinetic energy as it falls. "
            "The question is to find its speed just before it reaches the ground, assuming energy losses are negligible."
        )
        note = "Physics focus: conservation of mechanical energy, PE = mgh and KE = 1/2mv²."
    else:
        # General light cleanup without inventing extra physics details.
        cleaned = rough[0].upper() + rough[1:] if rough else ""
        cleaned = re.sub(r"\s+", " ", cleaned).strip()
        if cleaned and not cleaned.endswith(('.', '?', '!')):
            cleaned += "."
        rewritten = cleaned or "Please provide the rough story text you want edited."
        note = "Physics focus: after the story is clear, identify the system, known quantities, unknown quantity, and the equation that matches the situation."
    return (
        "Rewritten story:\n"
        f"{rewritten}\n\n"
        f"{note}\n\n"
        "I kept the wording concise and did not add a full solution."
    )


# -----------------------------------------------------------------------------
# QA Patch 19: stronger tutor-training rules
# -----------------------------------------------------------------------------
def _student_asks_for_story_generation(message: str) -> bool:
    low = (message or "").lower()
    return any(k in low for k in [
        "help me write a story", "write a story", "make a story", "create a story",
        "story about", "turn this equation into a story", "turn it into a story"
    ])


def _student_asks_for_practice_problem(message: str) -> bool:
    low = (message or "").lower()
    return any(k in low for k in ["practice problem", "give me a problem", "quiz me", "problem for me", "try one"])


def _student_asks_for_notes(message: str) -> bool:
    low = (message or "").lower()
    return any(k in low for k in ["write notes", "make notes", "notes for", "summary notes", "student notes"])


def _student_asks_for_story_from_equation(message: str) -> bool:
    low = (message or "").lower()
    return any(k in low for k in ["situation", "example", "application", "where is", "where do", "use this equation"])


def _story_subject_hint(message: str) -> str:
    low = (message or "").lower()
    if "apple" in low and ("tree" in low or "branch" in low or "fall" in low):
        return "apple_falling"
    if "car" in low and any(k in low for k in ["speed", "velocity", "time", "distance"]):
        return "car_average_motion"
    if "bird" in low and "snack" in low:
        return "bird_snack_momentum"
    if "cart" in low and any(k in low for k in ["collision", "recoil", "momentum"]):
        return "cart_momentum"
    return "general"


def _write_story_for_selected_equation(record: Dict[str, str], message: str) -> str:
    """Produce an actual short student-facing story first, then connect it to the equation.

    Training rule: when a student asks for a story, do not merely give a template.
    Write a plausible story in cohesive language, then identify the physics and equation.
    """
    name = record.get("name", "Selected equation")
    syntax = record.get("syntax", "")
    hint = _story_subject_hint(message)
    if hint == "apple_falling" or name in ["Mechanical energy conservation", "Gravitational potential energy", "Kinetic energy", "Drop speed from height"]:
        return (
            "Here is a clear physics story:\n\n"
            "An apple hangs from a branch near the top of a tall tree. At first, the apple is at rest, so its kinetic energy is zero. "
            "Because the apple is high above the ground, it has gravitational potential energy. When the stem breaks, gravity pulls the apple downward. "
            "As the apple falls, its height decreases and its speed increases. If air resistance is ignored, the apple's gravitational potential energy changes into kinetic energy.\n\n"
            "Physics idea: conservation of mechanical energy.\n\n"
            "Useful equation: K_i + U_i = K_f + U_f.\n\n"
            "For this story, K_i = 0, U_i = mgh, U_f = 0, and K_f = 1/2 mv^2. Therefore, mgh = 1/2 mv^2, so v = sqrt(2gh)."
        )
    if hint == "car_average_motion" or name == "Average velocity":
        return (
            "Here is a clear physics story:\n\n"
            "A car travels along a straight road with an average velocity of 10 m/s. The car continues moving in the same direction for 10 s. "
            "The question is how far the car moves during that time.\n\n"
            "Physics idea: average velocity connects displacement and elapsed time.\n\n"
            "Useful equation: v_avg = Δx / Δt.\n\n"
            "For this story, v_avg = 10 m/s and Δt = 10 s. Solving for displacement gives Δx = v_avg Δt = (10 m/s)(10 s) = 100 m."
        )
    if hint == "bird_snack_momentum" or name in ["Momentum", "Momentum conservation", "Two-object conservation", "Impulse-momentum theorem"]:
        return (
            "Here is a clear physics story:\n\n"
            "While a student is eating a snack on the beach, a bird flies by and snatches the snack from the student's hand. "
            "The bird is moving as it carries the snack away, so the snack's momentum changes during the interaction. "
            "The question is how to choose the system and whether momentum is conserved for that system during the short interaction.\n\n"
            "Physics idea: momentum changes when a force or impulse acts. Momentum is conserved only for a properly chosen system when the external impulse is small.\n\n"
            "Useful equation: m_1 v_1i + m_2 v_2i = m_1 v_1f + m_2 v_2f, if the bird-and-snack interaction can be treated as an isolated short-time system."
        )
    if name == "Kinetic friction" or name == "Stopping-distance equation" or name == "Braking acceleration":
        return (
            "Here is a clear physics story:\n\n"
            "A driver is moving along a foggy road when a stop sign suddenly becomes visible. The driver applies the brakes, and the tires skid on the road. "
            "The question is whether the car can stop before reaching the stop sign.\n\n"
            "Physics idea: kinetic friction provides the backward force that slows the car.\n\n"
            "Useful equations: f_k = μ_k N, F_n = mg on a level road, a_x = -μ_k g if +x is forward, and v_f^2 = v_i^2 + 2a_x Δx."
        )
    return (
        "Here is a clear physics story:\n\n"
        f"A student observes a situation where the quantities in the equation {syntax} can be measured. The student lists the known quantities, identifies the unknown, and asks whether the equation can predict the missing quantity.\n\n"
        f"Physics idea: {name}.\n\n"
        f"Useful equation: {syntax}.\n\n"
        "Next step: list the knowns, choose a sign convention if directions matter, and solve for the unknown before substituting numbers."
    )


def _practice_problem_for_equation(record: Dict[str, str]) -> str:
    name = record.get("name", "Selected equation")
    if name == "Mechanical energy conservation":
        return (
            "Practice problem:\n"
            "An apple falls from rest from a branch 3.0 m above the ground. Ignore air resistance. Find the speed of the apple just before it reaches the ground.\n\n"
            "Try first: use K_i + U_i = K_f + U_f. Then ask me to check your work."
        )
    if name == "Average velocity":
        return (
            "Practice problem:\n"
            "A bicycle travels with an average velocity of 6.0 m/s for 12 s in a straight line. What is the displacement?\n\n"
            "Try first: solve v_avg = Δx/Δt for Δx."
        )
    if name in ["Two-object conservation", "Momentum conservation"]:
        return (
            "Practice problem:\n"
            "A 2.0 kg cart moving at 3.0 m/s collides with a 1.0 kg cart initially at rest. The carts stick together. Find their final velocity.\n\n"
            "Try first: write the momentum before and after the collision."
        )
    if name in ["Kinetic friction", "Stopping-distance equation", "Braking acceleration"]:
        return (
            "Practice problem:\n"
            "A car is moving at 20 m/s on a level road. The coefficient of kinetic friction is 0.25. Estimate the stopping distance if the wheels skid.\n\n"
            "Try first: find a_x = -μ_k g, then use v_f^2 = v_i^2 + 2a_xΔx."
        )
    return _equation_example(record) + "\n\nNow try writing your own knowns and unknown."


def _student_notes_for_equation(record: Dict[str, str]) -> str:
    return (
        "Student notes:\n"
        f"1. Equation: {record.get('syntax','')}\n"
        f"2. Name: {record.get('name','Selected equation')}\n"
        f"3. Meaning: {record.get('use','Use this equation when the physical assumptions match the situation.')}\n"
        "4. Before using it, list the known quantities, unknown quantity, units, and assumptions.\n"
        "5. Rearrange symbolically first. Substitute numbers only after the algebra is clear.\n"
        "6. Interpret the answer in words, including direction or sign when relevant."
    )

def equation_ai_tutor_reply(equation: str, message: str = "") -> str:
    """Equation tutor with intent-first routing.

    Patch 18 training principle:
    The selected equation is context, not a cage. The tutor must answer the
    student's actual request first: write a story, rewrite text, explain symbols,
    give an example, give a practice problem, calculate, graph, or solve step by step.
    """
    eq = str(equation or "").strip()
    msg = str(message or "").strip()
    low = msg.lower()
    record = find_equation_record(eq)
    name = record.get("name", "Selected equation")
    use = record.get("use", "Use this equation when the physics assumptions match the situation.")

    def intro() -> str:
        return f"Selected equation: {eq}\nEquation: {name}\n\n"

    if not msg:
        return (
            intro()
            + "Ask me anything about this equation. I can write a story, rewrite your rough story, explain symbols, give examples, make a practice problem, calculate with values, show a graph, or guide a step-by-step solution."
        )

    # 1. Writing and editing requests must produce writing first, not a template.
    if _wants_rewrite_or_language_edit(msg):
        return _rewrite_student_story_briefly(msg, eq)
    if _student_asks_for_story_generation(msg):
        return _write_story_for_selected_equation(record, msg)

    # 2. Study-note and practice-problem requests.
    if _student_asks_for_notes(msg):
        return _student_notes_for_equation(record)
    if _student_asks_for_practice_problem(msg):
        return _practice_problem_for_equation(record)

    # 3. Specific equation-learning intents.
    wants_example = any(w in low for w in ["example", "situation", "where", "applied", "application", "use this", "requires"])
    wants_symbols = any(w in low for w in ["symbol", "mean", "each term", "variables", "what is", "units"])
    wants_check = any(w in low for w in ["check", "correct", "wrong", "valid", "fits", "appropriate"])
    wants_steps = any(w in low for w in ["step", "explain", "derive", "how do", "how can", "show me how"])
    wants_calc = any(w in low for w in ["calculate", "compute", "solve", "find", "substitute", "answer"])
    wants_graph = any(w in low for w in ["graph", "plot", "curve", "show relationship", "versus", "vs"])

    if wants_graph:
        return intro() + "Here is a physics graph for the selected equation or requested relationship. The axes are labeled with the physical quantities and units.\n\n" + _equation_graph_svg(record, msg)
    if wants_calc:
        return intro() + _equation_calculation(record, msg)
    if wants_symbols:
        return intro() + _equation_symbols(record)
    if wants_example or _student_asks_for_story_from_equation(msg):
        return intro() + _equation_example(record)
    if wants_check:
        return intro() + f"This equation is appropriate when: {use}\n\nNow check your story: does it have the right system, known quantities, unknown quantity, units, and assumptions? If yes, the equation is a good candidate."
    if wants_steps:
        return (
            intro()
            + "Step 1: Read the physical situation and identify the system.\n"
            + "Step 2: List known quantities with units.\n"
            + "Step 3: Identify the unknown quantity.\n"
            + f"Step 4: Check the condition for this equation: {use}\n"
            + "Step 5: Rearrange the equation symbolically before substituting numbers.\n"
            + "Step 6: Substitute values with units.\n"
            + "Step 7: Interpret the answer in words."
        )

    # 4. If no narrow intent is detected, use the broader tutor but keep the selected equation visible.
    return intro() + independent_physics_ai_reply(msg)


