@app.post("/api/stories/{story_id}/edit/form")
def save_story_edit_form(
    story_id: int,
    title: str = Form(...),
    physics_topic: str = Form(""),
    level: str = Form("basic"),
    story_text: str = Form(...),
    student_solution: str = Form(""),
) -> HTMLResponse:
    now = utc_now()
    with connect() as conn:
        current = conn.execute("SELECT * FROM stories WHERE id=?", (story_id,)).fetchone()
        if current is None:
            raise HTTPException(status_code=404, detail="Story not found")
        conn.execute(
            """
            UPDATE stories
            SET title=?, physics_topic=?, level=?, story_text=?, student_solution=?, updated_at=?
            WHERE id=?
            """,
            (title.strip(), physics_topic.strip(), level.strip(), story_text.strip(), student_solution.strip(), now, story_id),
        )
        conn.execute(
            """
            INSERT INTO story_feedback_history
            (story_id, event_type, status, teacher_feedback, revision_request, student_response, story_text_snapshot, student_solution_snapshot, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (story_id, "student_story_edit", current["status"] or "submitted", "", "", "Student edited story/solution with equation library support.", story_text.strip(), student_solution.strip(), now),
        )
        conn.commit()
    return HTMLResponse(f'<meta http-equiv="refresh" content="0; url=/stories/{story_id}">')

