# -----------------------------------------------------------------------------
# v35: Projectile Graph Active Route Fix
# -----------------------------------------------------------------------------
# v33 and v34 were rejected.  v35 is a correction candidate based on the last
# safe rollback baseline (v32).  The exact generic graph fallback route is
# bypassed for projectile graph requests such as "Plot the vertical and
# horizontal motion of the dog."  The convention is explicit: +x is forward,
# +y is upward, and the gravitational acceleration vector is a_y = -g.

try:
    _v35_old_graph_response_for_requests = _graph_response_for_requests
except Exception:
    _v35_old_graph_response_for_requests = None
try:
    _v35_old_student_ai_chat_reply = student_ai_chat_reply
except Exception:
    _v35_old_student_ai_chat_reply = None
try:
    _v35_old_independent_physics_ai_reply = independent_physics_ai_reply
except Exception:
    _v35_old_independent_physics_ai_reply = None
try:
    _v35_old_format_chat_text = format_chat_text
except Exception:
    _v35_old_format_chat_text = None


def _v35_projectile_terms(text: str) -> bool:
    low = str(text or '').lower()
    return any(w in low for w in [
        'dog', 'dock', 'horizontal launch', 'projectile', 'water surface', 'above the water',
        'jumps off', 'jumped off', 'leaves the dock', 'off a dock', 'cliff', 'ledge'
    ])


def _v35_projectile_graph_request(text: str) -> bool:
    low = str(text or '').lower()
    graph_intent = any(w in low for w in ['plot', 'graph', 'show plot', 'show graph', 'draw', 'sketch'])
    if not graph_intent:
        return False
    if _v35_projectile_terms(low):
        return True
    if ('vertical' in low and 'horizontal' in low and 'motion' in low):
        return True
    if any(w in low for w in ['x versus time', 'x vs time', 'horizontal position', 'horizontal motion', 'x(t)']):
        return True
    if any(w in low for w in ['y versus time', 'y vs time', 'vertical height', 'vertical position', 'vertical motion', 'y(t)']):
        return True
    if any(w in low for w in ['trajectory', 'y versus x', 'y vs x', 'path']):
        return True
    if any(w in low for w in ['velocity graphs', 'v_x', 'vx(t)', 'v_y', 'vy(t)']):
        return True
    return False


def _v35_projectile_story_request(text: str) -> bool:
    low = str(text or '').lower()
    if not _v35_projectile_terms(low):
        return False
    return any(w in low for w in ['describe', 'what happens', 'motion', 'jumps', 'jumped', 'leaves', 'horizontal speed'])


def _v35_get_projectile_values(text: str, context_text: str = '') -> tuple:
    combined = (str(text or '') + '\n' + str(context_text or '')).strip()
    vx, hgt = _projectile_values_from_text(combined)
    vx_source = 'student/context supplied' if vx is not None else 'sample default'
    h_source = 'student/context supplied' if hgt is not None else 'sample default'
    if vx is None:
        vx = 10.0
    if hgt is None:
        hgt = 1.2
    return float(vx), float(abs(hgt)), vx_source, h_source


def _v35_projectile_action_buttons(story_id: Any = None) -> str:
    if story_id is None or str(story_id) == '':
        return (
            '<div class="projectile-action-panel"><strong>Projectile graph actions</strong>'
            '<p>Ask: show horizontal position x versus time, show vertical height y versus time, show trajectory y versus x, or show all projectile graphs.</p></div>'
        )
    sid = str(story_id)
    items = [
        ('Show x(t): horizontal position vs time', 'show horizontal position x versus time t for the dog'),
        ('Show y(t): vertical height vs time', 'show vertical height y versus time t for the dog'),
        ('Show trajectory y(x)', 'show trajectory y versus x for the dog'),
        ('Show velocity graphs', 'show velocity graphs v_x(t) and v_y(t) for the dog'),
        ('Show all projectile graphs', 'plot the vertical and horizontal motion of the dog'),
    ]
    links = []
    for label, cmd in items:
        links.append(f'<a class="button small secondary" href="/student-ai-chat/{h(sid)}/quick?message={quote(cmd)}">{h(label)}</a>')
    return '<div class="projectile-action-panel" style="border:1px solid #d0d7de;border-radius:12px;padding:10px;margin:10px 0;background:#f6f8fa;"><strong>Projectile graph actions</strong><p>Click a graph to generate it from the current dog/dock model.</p><p class="actions">' + ' '.join(links) + '</p></div>'


def _v35_projectile_description_reply(message: str, story_id: Any = None) -> str:
    vx, hgt, vx_source, h_source = _v35_get_projectile_values(message)
    g = 9.8
    tf = (2.0*hgt/g)**0.5 if hgt >= 0 else 0.0
    rng = vx*tf
    reply = (
        "This is a **projectile-motion situation with a horizontal launch**.\n\n"
        "Coordinate convention:\n"
        "+x is forward from the dock.\n"
        "+y is upward, away from the water.\n"
        "Gravity is a vector quantity: a_y = -g = -9.8 m/s².\n\n"
        "Horizontal motion: x(t) = v_x t, because a_x = 0 when air resistance is ignored.\n"
        "Vertical motion: y(t) = y_0 - (1/2)gt², because the dog starts with no vertical velocity and accelerates downward.\n\n"
        f"Using the values available: v_x = {_fmt_num(vx)} m/s ({vx_source}); y_0 = {_fmt_num(hgt)} m ({h_source}).\n"
        f"Time to hit the water: t = sqrt(2y_0/g) = {tf:.2f} s.\n"
        f"Horizontal range: x = v_x t = {rng:.2f} m.\n\n"
        "Physical interpretation: the dog moves forward at constant horizontal speed while its vertical velocity becomes more negative. "
        "The height-versus-time graph is concave downward under the +y upward convention."
    )
    reply += "\n\n" + _v35_projectile_action_buttons(story_id)
    return reply


def _v35_projectile_graphs_reply(message: str, context_text: str = '', story_id: Any = None) -> Optional[str]:
    if not _v35_projectile_graph_request(message):
        return None
    vx, hgt, vx_source, h_source = _v35_get_projectile_values(message, context_text)
    g = 9.8
    tf = (2.0*hgt/g)**0.5 if hgt >= 0 else 0.0
    if tf <= 0:
        tf = 0.5
    rng = vx*tf
    ts = _sample_values_from_range(0.0, tf, 181)
    x_pts = [(t, vx*t) for t in ts]
    y_pts = [(t, hgt - 0.5*g*t*t) for t in ts]
    traj_pts = [(vx*t, hgt - 0.5*g*t*t) for t in ts]
    vx_pts = [(t, vx) for t in ts]
    vy_pts = [(t, -g*t) for t in ts]
    low = str(message or '').lower()
    wants_x = any(k in low for k in ['horizontal position', 'x versus time', 'x vs time', 'x(t)', 'horizontal motion'])
    wants_y = any(k in low for k in ['vertical height', 'vertical position', 'y versus time', 'y vs time', 'y(t)', 'vertical motion'])
    wants_traj = any(k in low for k in ['trajectory', 'y versus x', 'y vs x', 'path'])
    wants_vel = any(k in low for k in ['velocity graphs', 'v_x', 'vx', 'v_y', 'vy'])
    wants_both = ('vertical' in low and 'horizontal' in low and 'motion' in low) or 'all projectile graphs' in low or 'show all' in low
    # If the student asks vaguely for the dog motion, show the three motion graphs.
    if not any([wants_x, wants_y, wants_traj, wants_vel]) or wants_both:
        wants_x = wants_y = wants_traj = True
    intro = (
        "Projectile graph model: horizontal launch from a dock.\n\n"
        "Coordinate convention: +x forward, +y upward. Gravity is a vector: a_y = -g = -9.8 m/s².\n"
        f"Values used: v_x = {_fmt_num(vx)} m/s ({vx_source}); y_0 = {_fmt_num(hgt)} m ({h_source}); time of flight ≈ {tf:.2f} s; range ≈ {rng:.2f} m.\n\n"
        "These are generated model curves, not experimental data and not a fit.\n"
    )
    blocks = [intro]
    if wants_x:
        blocks.append(_plot_svg_card(
            "Horizontal position x versus time t", "x = v_x t", "time t (s)", "horizontal position x (m)", x_pts,
            "x(t) is a straight line increasing with time because horizontal velocity is constant and a_x = 0.", "Linear horizontal motion"
        ))
    if wants_y:
        blocks.append(_plot_svg_card(
            "Vertical height y versus time t", "y = y_0 - 1/2*g*t^2", "time t (s)", "height y above water (m)", y_pts,
            "With +y upward, gravity is negative. The height decreases and the curve is concave downward because a_y = -g.", "Concave-down free fall"
        ))
    if wants_traj:
        blocks.append(_plot_svg_card(
            "Projectile trajectory y versus x", "y = y_0 - (g/(2*v_x^2))*x^2", "horizontal position x (m)", "height y above water (m)", traj_pts,
            "The trajectory is a downward-opening parabola: the dog moves forward while falling downward.", "Downward-opening parabola"
        ))
    if wants_vel:
        blocks.append(_plot_svg_card(
            "Horizontal velocity v_x versus time", "v_x = constant", "time t (s)", "horizontal velocity v_x (m/s)", vx_pts,
            "v_x is constant when air resistance is ignored.", "Constant velocity"
        ))
        blocks.append(_plot_svg_card(
            "Vertical velocity v_y versus time", "v_y = -g*t", "time t (s)", "vertical velocity v_y (m/s)", vy_pts,
            "v_y becomes more negative with time because gravity points downward.", "Linear decreasing velocity"
        ))
    blocks.append(_v35_projectile_action_buttons(story_id))
    return "\n".join(blocks)


def _graph_response_for_requests(message: str) -> str:
    # v35 active-route guard: projectile graph requests must bypass the generic
    # "choose a physics model before graphing" fallback.
    projectile = _v35_projectile_graphs_reply(message, _recent_assistant_context() if 'fetch_independent_physics_chat' in globals() else '')
    if projectile:
        return projectile
    if _v35_old_graph_response_for_requests:
        return _v35_old_graph_response_for_requests(message)
    return "I need a specific graph model."


def student_ai_chat_reply(story: Dict[str, Any], student_message: str) -> str:
    # v35: exact active Branch 2 route guard.  This runs before the general graph
    # fallback and before generic story classification.
    recent_context = _recent_branch2_context_text(story.get('id') or '', limit=12)
    if _v35_projectile_graph_request(student_message):
        reply = _v35_projectile_graphs_reply(student_message, recent_context + '\n' + str(story.get('story_text') or ''), story.get('id') or '')
        if reply:
            return reply
    if _v35_projectile_story_request(student_message):
        return _v35_projectile_description_reply(student_message, story.get('id') or '')
    if _v35_old_student_ai_chat_reply:
        return _v35_old_student_ai_chat_reply(story, student_message)
    return "I can help classify the physics situation first, then choose a model and equation."


def independent_physics_ai_reply(message: str) -> str:
    recent = _recent_assistant_context() if 'fetch_independent_physics_chat' in globals() else ''
    if _v35_projectile_graph_request(message):
        reply = _v35_projectile_graphs_reply(message, recent, None)
        if reply:
            return reply
    if _v35_projectile_story_request(message):
        return _v35_projectile_description_reply(message, None)
    if _v35_old_independent_physics_ai_reply:
        return _v35_old_independent_physics_ai_reply(message)
    return "Ask me any physics question."


def format_chat_text(text: str) -> str:
    """v35: preserve trusted graph cards and projectile action buttons."""
    raw = unescape(text or "")
    blocks: List[str] = []
    def stash(match: re.Match) -> str:
        blocks.append(match.group(0))
        return f"@@TRUSTED_BLOCK_{len(blocks)-1}@@"
    raw = re.sub(r'<div class=\\?"(?:equation-graph-card|equation-graph|projectile-action-panel|v47-fbd-figure)\\?"[\s\S]*?</div>', stash, raw)
    safe = h(raw)
    safe = re.sub(r"\*\*(.*?)\*\*", r"<strong>\1</strong>", safe)
    lines = safe.split("\n")
    out = []
    for line in lines:
        for i, block in enumerate(blocks):
            marker = f"@@TRUSTED_BLOCK_{i}@@"
            if marker in line:
                line = line.replace(marker, block.replace('\\"', '"'))
        plain_line = re.sub(r"<[^>]+>", "", line).strip()
        if any(cls in line for cls in ["equation-graph-card", "equation-graph", "projectile-action-panel", "v47-fbd-figure"]):
            out.append(line)
        elif looks_like_equation_line(plain_line):
            equation_source = re.sub(r'^[-•]\s+', '', plain_line).strip()
            normalized = normalize_equation_input(equation_source)
            rendered = physics_expr_to_html(normalized)
            notes = equation_writing_diagnostics(equation_source)
            warning = ""
            if notes and any("ambiguous" in n.lower() for n in notes):
                warning = '<div class="equation-warning">' + h(notes[0]) + '</div>'
            out.append(f'<div class="equation-line"><span class="math-display">{rendered}</span>{warning}</div>')
        else:
            out.append(line)
    return "<br>".join(out)


@app.get('/student-ai-chat/{story_id}/quick', response_class=HTMLResponse)
def student_ai_chat_quick_action(story_id: int, message: str = Query(...)) -> HTMLResponse:
    """Clickable Branch 2 action buttons that execute a fixed tutor command."""
    story = get_story(story_id)
    save_student_chat_message(story_id, str(story.get('student_author') or ''), 'student', message)
    reply = student_ai_chat_reply(story, message)
    save_student_chat_message(story_id, str(story.get('student_author') or ''), 'assistant', reply)
    return HTMLResponse(f'<meta http-equiv="refresh" content="0; url=/student-ai-chat/{story_id}">')


