@app.get('/branch2-new-story-chat/export.txt', response_class=PlainTextResponse)
def v39_export_branch2_txt() -> PlainTextResponse:
    lines = [f'Physics Assistant AI {V39_VERSION} — Branch 2B Chat Export', '']
    for role, msg in BRANCH2_FRESH_MESSAGES:
        label = 'Student' if role == 'student' else 'AI Tutor'
        clean = re.sub(r'<[^>]+>', '', unescape(str(msg or '')))
        clean = re.sub(r'\n{3,}', '\n\n', clean).strip()
        lines.append(f'{label}:')
        lines.append(clean)
        lines.append('')
    return PlainTextResponse('\n'.join(lines), media_type='text/plain')

@app.get('/branch2-new-story-chat/export.html', response_class=HTMLResponse)
def v39_export_branch2_html() -> HTMLResponse:
    blocks = []
    for role, msg in BRANCH2_FRESH_MESSAGES:
        label = 'Student' if role == 'student' else 'AI Tutor'
        if role == 'assistant':
            block_body = _v38_format_response_html(str(msg or ''))
        else:
            block_body = '<p>' + escape(str(msg or '')) + '</p>'
        blocks.append(f'<section class="card"><h3>{label}</h3>{block_body}</section>')
    content = ''.join(blocks) or '<p>No Branch 2B chat messages yet.</p>'
    return page('Branch 2B Chat Export', '<section class="hero"><h2>Branch 2B Chat Export</h2><p class="actions"><a class="button" href="/branch2-new-story-chat">Back to Branch 2B</a></p></section>' + content)

