# ============================================================
# v42: Constant Acceleration Active Tutor Fix
# Connects the v41 constant-acceleration test pack to the active
# tutor response routes. This section intentionally wraps the existing
# v41 tutor rather than replacing projectile/UI features.
# ============================================================

V42_VERSION = "v42_CONSTANT_ACCELERATION_ACTIVE_TUTOR_FIX"


def _v42_first_number(text: str, default: Optional[float] = None) -> Optional[float]:
    vals = _extract_numbers(text or "")
    return vals[0] if vals else default


def _v42_constant_acceleration_reply(message: str) -> Optional[str]:
    """Freshman-level constant-acceleration tutor router.

    Handles the active response cases that v41 only listed in the test pack:
    upward throw, free fall, starts-from-rest acceleration, stopping/slowing,
    sign convention, and basic graph interpretation.
    """
    msg = str(message or "").strip()
    low = msg.lower()
    nums = _extract_numbers(msg)
    g = 9.8

    # Explicit sign convention question.
    if ('upward' in low and 'positive' in low and any(w in low for w in ['gravity', 'free fall', 'freely falling', 'acceleration'])):
        return (
            "This is a sign-convention question for vertical constant-acceleration motion.\n\n"
            "If +y is upward, gravity points downward, so the acceleration is negative:\n\n"
            "a_y = -g = -9.8 m/s².\n\n"
            "Interpretation: the object may be moving upward or downward, but the acceleration due to gravity still points downward near Earth's surface."
        )

    # Upward throw / time to top / maximum height route.
    upward_throw = any(w in low for w in ['thrown upward', 'thrown up', 'tossed upward', 'tossed up', 'launched upward', 'shot upward'])
    top_request = any(w in low for w in ['top', 'highest point', 'maximum height', 'max height', 'peak'])
    if upward_throw and top_request and nums:
        vi = abs(nums[0])
        t_top = vi / g
        h = vi * vi / (2*g)
        return (
            "This is 1D vertical motion with constant acceleration.\n\n"
            "Choose the sign convention: +y is upward. The object is thrown upward, so v_i is positive, but gravity points downward, so a_y = -g = -9.8 m/s².\n\n"
            "At the top of the motion, the vertical velocity is momentarily zero: v_f = 0.\n\n"
            "Use the constant-acceleration velocity equation:\n"
            "v_f = v_i + a t\n\n"
            f"Substitute: 0 = {vi:g} + (-9.8)t.\n"
            f"So t = {vi:g}/9.8 = {t_top:.2f} s.\n\n"
            f"Final answer: the object reaches the top after about {t_top:.2f} s.\n\n"
            f"Extra check: the maximum height above the launch point would be Δy = v_i²/(2g) ≈ {h:.2f} m, if air resistance is neglected.\n"
            "Common mistake: do not use +9.8 m/s² when +y is upward. Gravity is a vector acceleration and points downward."
        )

    # Free fall from rest from a height.
    free_fall = any(w in low for w in ['dropped', 'free fall', 'falls from rest', 'falling from rest'])
    if free_fall and any(w in low for w in ['height', 'ground', 'reach the ground', 'hit the ground', 'water']) and nums:
        # Prefer a number near a height if possible; first number is acceptable for test pack.
        hgt = abs(nums[0])
        t = (2*hgt/g)**0.5
        vf = -g*t
        return (
            "This is vertical motion with constant acceleration.\n\n"
            "Choose +y upward. The object is dropped from rest, so v_i = 0, and gravity gives a_y = -g = -9.8 m/s².\n\n"
            "For a drop from height h to the ground, use:\n"
            "0 = h - 1/2 g t²\n\n"
            f"Solve: t = sqrt(2h/g) = sqrt(2({hgt:g})/9.8) = {t:.2f} s.\n\n"
            f"Final answer: the object reaches the ground after about {t:.2f} s.\n"
            f"Its vertical velocity just before impact is v_y = -gt ≈ {vf:.2f} m/s with +y upward."
        )

    # Starts from rest and accelerates for a time.
    if any(w in low for w in ['starts from rest', 'start from rest', 'from rest']) and 'accelerat' in low and len(nums) >= 2:
        # Choose acceleration and time. In prompts like "accelerates at 3 m/s^2 for 5 s", nums = [3,2,5] if exponent 2 is caught.
        vals = [x for x in nums if abs(x) != 2] if len(nums) > 2 else nums
        if len(vals) >= 2:
            a = vals[0]; t = vals[1]
        else:
            a = nums[0]; t = nums[-1]
        vf = a*t
        dx = 0.5*a*t*t
        if any(w in low for w in ['how far', 'distance', 'displacement', 'travel']):
            return (
                "This is 1D constant-acceleration motion starting from rest.\n\n"
                "Knowns: v_i = 0, a = %.3g m/s², t = %.3g s.\n\n" % (a, t) +
                "Use the position equation:\nΔx = v_i t + 1/2 a t².\n\n"
                f"Since v_i = 0, Δx = 1/2({a:g})({t:g})² = {dx:.2f} m.\n\n"
                f"Final answer: the object travels about {dx:.2f} m."
            )
        return (
            "This is 1D constant-acceleration motion starting from rest.\n\n"
            f"v_i = 0, a = {a:g} m/s², t = {t:g} s.\n\n"
            "Use v_f = v_i + at and Δx = v_i t + 1/2 a t².\n\n"
            f"v_f = 0 + ({a:g})({t:g}) = {vf:.2f} m/s.\n"
            f"Δx = 1/2({a:g})({t:g})² = {dx:.2f} m."
        )

    # Stopping / no-time equation selection. Example: car moving 20 m/s stops with acceleration -4 m/s^2.
    if any(w in low for w in ['stop', 'stopping', 'comes to rest', 'brakes']) and len(nums) >= 2:
        # Interpret first number as initial speed; second useful signed number as acceleration if acceleration word present.
        vi = abs(nums[0])
        # Remove exponent 2 if m/s^2 extracted as 2; choose a negative if present else second non-2.
        candidates = [x for x in nums[1:] if abs(x) != 2]
        acc = None
        for x in candidates:
            if x < 0:
                acc = x; break
        if acc is None and candidates:
            acc = -abs(candidates[0]) if any(w in low for w in ['brake', 'stop', 'slowing']) else candidates[0]
        if acc:
            dx = (0 - vi*vi)/(2*acc)
            return (
                "This is constant-acceleration stopping motion.\n\n"
                "Because time is not needed, choose the no-time kinematics equation:\n"
                "v_f² = v_i² + 2aΔx.\n\n"
                f"Here v_i = {vi:g} m/s, v_f = 0, and a = {acc:g} m/s².\n"
                f"0 = ({vi:g})² + 2({acc:g})Δx, so Δx = {dx:.2f} m.\n\n"
                f"Final answer: the stopping distance is about {dx:.2f} m."
            )

    # Generic thrown upward maximum-height route without time wording.
    if upward_throw and nums:
        vi = abs(nums[0])
        t_top = vi/g
        h = vi*vi/(2*g)
        return (
            "This is vertical constant-acceleration motion with +y upward and a_y = -g.\n\n"
            f"For v_i = {vi:g} m/s upward, the object reaches the top when v_f = 0.\n"
            f"Time to top: t = v_i/g = {vi:g}/9.8 = {t_top:.2f} s.\n"
            f"Maximum height above launch point: Δy = v_i²/(2g) = {h:.2f} m."
        )

    # Graph interpretation prompts for constant acceleration.
    if any(w in low for w in ['position-time graph', 'position versus time', 'x-t graph', 'x versus t']) and any(w in low for w in ['constant acceleration', 'acceleration']):
        return (
            "For constant acceleration, a position-time graph is generally curved, not a straight line.\n\n"
            "The slope of x(t) is velocity. If acceleration is constant and nonzero, the slope changes steadily with time.\n"
            "Concave upward means positive acceleration in the chosen positive direction; concave downward means negative acceleration."
        )
    if any(w in low for w in ['velocity-time graph', 'velocity versus time', 'v-t graph', 'v versus t']) and any(w in low for w in ['constant acceleration', 'acceleration']):
        return (
            "For constant acceleration, a velocity-time graph is a straight line.\n\n"
            "The slope of the v(t) graph is acceleration. A positive slope means positive acceleration; a negative slope means negative acceleration."
        )
    if any(w in low for w in ['acceleration-time graph', 'acceleration versus time', 'a-t graph', 'a versus t']) and any(w in low for w in ['constant acceleration', 'acceleration']):
        return (
            "For constant acceleration, an acceleration-time graph is a horizontal line.\n\n"
            "If the line is above zero, acceleration is positive. If it is below zero, acceleration is negative. For free fall with +y upward, the line is at -9.8 m/s²."
        )

    return None


