# v43: Constant-acceleration graph context fix + persistent navigation
# -----------------------------------------------------------------------------
V43_VERSION = "v43_CONSTANT_ACCELERATION_GRAPH_CONTEXT_FIX"

def _v43_nav() -> str:
    return """
    <div class='quick-chat' style='margin:0 0 1rem 0;'>
      <strong>Navigation:</strong>
      <a class='button small secondary' href='/student-ai-chat-v43'>Branch Selector</a>
      <a class='button small secondary' href='/physics-ai-chat-v43'>Branch 1: Dynamics Training Chat</a>
      <a class='button small secondary' href='/student-ai-chat'>Branch 2A</a>
      <a class='button small secondary' href='/branch2-new-story-chat-v43'>Branch 2B</a>
      <a class='button small secondary' href='/constant-acceleration-test-pack-v43'>Constant Acceleration Tests</a>
      <a class='button small secondary' href='/test-checklist-v43'>v43 Checklist</a>
    </div>
    """

def _v43_first_float(patterns, text: str, default=None):
    raw = str(text or '')
    for pat in patterns:
        m = re.search(pat, raw, flags=re.I)
        if m:
            try:
                return float(m.group(1))
            except Exception:
                pass
    return default

def _v43_recent_independent_context(limit: int = 12) -> str:
    try:
        msgs = fetch_independent_physics_chat(limit=limit)
        return "\n".join(str(m.get('message') or '') for m in msgs[-limit:])
    except Exception:
        return ""

def _v43_detect_constant_accel_context(text: str) -> Optional[Dict[str, Any]]:
    raw = str(text or '')
    low = raw.lower()
    g = 9.8
    if any(s in low for s in ['thrown upward', 'thrown up', 'reaches the top', 'reach the top', 'maximum height', 'at the top']):
        vi = _v43_first_float([
            r'(?:thrown\s+upward|thrown\s+up|launched\s+upward|upward\s+at)[^0-9\-]*(-?\d+(?:\.\d+)?)\s*(?:m/s|meters per second|meter/s)',
            r'(-?\d+(?:\.\d+)?)\s*(?:m/s|meters per second|meter/s)[^\n\.]{0,60}(?:upward|up)'
        ], raw, 20.0)
        vi = abs(vi or 20.0)
        return {'model':'upward_throw_top','vi':vi,'g':g,'tmax':vi/g,'ymax':vi*vi/(2*g)}
    if any(s in low for s in ['dropped from rest', 'ball is dropped', 'object is dropped', 'free fall from rest']):
        hgt = _v43_first_float([
            r'(?:height|from)\s+(?:of\s+)?(-?\d+(?:\.\d+)?)\s*(?:m|meters|meter)\b(?!\s*/)',
            r'(-?\d+(?:\.\d+)?)\s*(?:m|meters|meter)\b(?!\s*/)[^\n\.]{0,80}(?:height|high|above)'
        ], raw, 20.0)
        hgt = abs(hgt or 20.0)
        return {'model':'drop_from_rest','h':hgt,'g':g,'tmax':(2*hgt/g)**0.5}
    if 'starts from rest' in low and 'accelerat' in low:
        a = _v43_first_float([r'accelerat(?:es|ing|ion)?[^0-9\-]*(-?\d+(?:\.\d+)?)\s*(?:m/s\^?2|m/s²|meters per second squared|m per s2)'], raw, 3.0)
        t = _v43_first_float([r'(?:for|in|during)\s+(-?\d+(?:\.\d+)?)\s*(?:s|sec|seconds)\b'], raw, 5.0)
        return {'model':'starts_from_rest','a':a if a is not None else 3.0,'tmax':abs(t or 5.0)}
    return None

def _v43_constacc_action_forms() -> str:
    actions = [
        ('Show position versus time', 'V43_GRAPH_POSITION'),
        ('Show velocity versus time', 'V43_GRAPH_VELOCITY'),
        ('Show acceleration versus time', 'V43_GRAPH_ACCELERATION'),
        ('Show all motion graphs', 'V43_GRAPH_ALL'),
    ]
    forms = []
    for label, msg in actions:
        forms.append(f'''<form method="post" action="/physics-ai-chat-v43/form" style="display:inline-block;margin:0.2rem;"><input type="hidden" name="message" value="{h(msg)}"><button type="submit" class="secondary">{h(label)}</button></form>''')
    return "<div class='quick-chat'><p><strong>Constant-acceleration graph actions:</strong></p>" + ''.join(forms) + "</div>"

def _v43_visible_prompt_label(message: str) -> str:
    labels = {
        'V43_GRAPH_POSITION': 'Show position versus time',
        'V43_GRAPH_VELOCITY': 'Show velocity versus time',
        'V43_GRAPH_ACCELERATION': 'Show acceleration versus time',
        'V43_GRAPH_ALL': 'Show all motion graphs',
    }
    return labels.get(str(message or '').strip(), str(message or ''))

def _v43_constant_accel_graph_html(model: Dict[str, Any], kind: str = 'all') -> str:
    g = float(model.get('g', 9.8)); m = model.get('model'); kind = (kind or 'all').lower(); n = 181
    if m == 'upward_throw_top':
        vi = float(model.get('vi', 20.0)); tmax = float(model.get('tmax', vi/g)); ymax=float(model.get('ymax', vi*vi/(2*g)))
        ts = [i*tmax/(n-1) for i in range(n)]; y = [vi*t - 0.5*g*t*t for t in ts]; v = [vi - g*t for t in ts]; a = [-g for _ in ts]
        intro = "<div class='feedback-box'><strong>Constant-acceleration graph convention:</strong> +y is upward. The object is thrown upward with positive initial velocity, while gravity is the vector acceleration a_y = -g = -9.8 m/s². The graphs run from launch to the top, where v_y = 0.</div>"
        pos = _v36_points_to_svg(list(zip(ts,y)), 'Vertical position y versus time t', 'y(t) = v_i t - 1/2 g t²', 'time t (s)', 'vertical position y (m)', 'The position graph is concave downward because the acceleration is negative. The slope becomes zero at the top.', xmin=0, xmax=tmax, ymin=0, ymax=max(ymax,1e-6))
        vel = _v36_points_to_svg(list(zip(ts,v)), 'Vertical velocity v_y versus time t', 'v_y(t) = v_i - gt', 'time t (s)', 'vertical velocity v_y (m/s)', 'The velocity decreases linearly from +v_i to 0 at the top because gravity is constant and downward.', xmin=0, xmax=tmax, ymin=0, ymax=vi)
        acc = _v36_points_to_svg(list(zip(ts,a)), 'Vertical acceleration a_y versus time t', 'a_y(t) = -g', 'time t (s)', 'vertical acceleration a_y (m/s²)', 'The acceleration is constant and negative for the entire upward motion.', xmin=0, xmax=tmax, ymin=-1.2*g, ymax=0)
    elif m == 'drop_from_rest':
        hgt=float(model.get('h',20.0)); tmax=float(model.get('tmax',(2*hgt/g)**0.5)); ts=[i*tmax/(n-1) for i in range(n)]
        y=[hgt-0.5*g*t*t for t in ts]; v=[-g*t for t in ts]; a=[-g for _ in ts]
        intro = "<div class='feedback-box'><strong>Constant-acceleration graph convention:</strong> +y is upward. The ball is dropped from rest, so v_y0 = 0, and gravity gives a_y = -g = -9.8 m/s².</div>"
        pos=_v36_points_to_svg(list(zip(ts,y)), 'Vertical height y versus time t', 'y(t) = h - 1/2 g t²', 'time t (s)', 'height y (m)', 'Height decreases and the graph is concave downward in the +y-up coordinate system.', xmin=0, xmax=tmax, ymin=0, ymax=hgt)
        vel=_v36_points_to_svg(list(zip(ts,v)), 'Vertical velocity v_y versus time t', 'v_y(t) = -gt', 'time t (s)', 'vertical velocity v_y (m/s)', 'Velocity starts at 0 and becomes more negative as the ball falls.', xmin=0, xmax=tmax, ymin=min(v), ymax=0)
        acc=_v36_points_to_svg(list(zip(ts,a)), 'Vertical acceleration a_y versus time t', 'a_y(t) = -g', 'time t (s)', 'vertical acceleration a_y (m/s²)', 'Acceleration is a constant negative value because gravity points downward.', xmin=0, xmax=tmax, ymin=-1.2*g, ymax=0)
    elif m == 'starts_from_rest':
        aa=float(model.get('a',3.0)); tmax=float(model.get('tmax',5.0)); ts=[i*tmax/(n-1) for i in range(n)]
        x=[0.5*aa*t*t for t in ts]; v=[aa*t for t in ts]; a=[aa for _ in ts]
        intro = "<div class='feedback-box'><strong>Constant-acceleration graph convention:</strong> The object starts from rest, so v_i = 0. The acceleration is constant, so position is quadratic, velocity is linear, and acceleration is horizontal.</div>"
        pos=_v36_points_to_svg(list(zip(ts,x)), 'Position x versus time t', 'x(t) = 1/2 a t²', 'time t (s)', 'position x (m)', 'Position curves upward for positive acceleration because displacement grows as t².', xmin=0, xmax=tmax, ymin=0, ymax=max(x) if x else 1)
        vel=_v36_points_to_svg(list(zip(ts,v)), 'Velocity v versus time t', 'v(t) = at', 'time t (s)', 'velocity v (m/s)', 'Velocity increases linearly because acceleration is constant.', xmin=0, xmax=tmax, ymin=0, ymax=max(v) if v else 1)
        acc=_v36_points_to_svg(list(zip(ts,a)), 'Acceleration a versus time t', 'a(t) = constant', 'time t (s)', 'acceleration a (m/s²)', 'Acceleration is constant, so the graph is a horizontal line.', xmin=0, xmax=tmax, ymin=min(0,aa*1.2), ymax=max(0,aa*1.2))
    else:
        return ""
    if 'position' in kind or 'displacement' in kind:
        body = pos
    elif 'velocity' in kind:
        body = vel
    elif 'acceleration' in kind:
        body = acc
    else:
        body = pos + vel + acc
    return intro + body + _v43_constacc_action_forms()

def _v43_is_graph_followup(msg: str) -> bool:
    low = str(msg or '').strip().lower()
    if low in ['plot', 'graph', 'draw', 'show graph', 'show plot']:
        return True
    return any(w in low for w in ['plot', 'graph', 'draw']) and any(w in low for w in ['position', 'velocity', 'acceleration', 'motion', 'versus time', 'vs time'])

def _v43_kind_from_graph_message(msg: str) -> str:
    s = str(msg or ''); low = s.lower()
    if 'V43_GRAPH_POSITION' in s: return 'position'
    if 'V43_GRAPH_VELOCITY' in s: return 'velocity'
    if 'V43_GRAPH_ACCELERATION' in s: return 'acceleration'
    if 'V43_GRAPH_ALL' in s: return 'all'
    if 'position' in low or 'displacement' in low or 'height' in low: return 'position'
    if 'velocity' in low or 'speed' in low: return 'velocity'
    if 'acceleration' in low: return 'acceleration'
    return 'all'

try:
    _v43_old_independent_physics_ai_reply = independent_physics_ai_reply
except NameError:
    _v43_old_independent_physics_ai_reply = None

def independent_physics_ai_reply(message: str) -> str:
    msg = str(message or '').strip(); context = _v43_recent_independent_context(12)
    if msg in {'V43_GRAPH_POSITION','V43_GRAPH_VELOCITY','V43_GRAPH_ACCELERATION','V43_GRAPH_ALL'} or _v43_is_graph_followup(msg):
        model = _v43_detect_constant_accel_context(context)
        if model:
            return _v43_constant_accel_graph_html(model, _v43_kind_from_graph_message(msg))
    if _v43_is_graph_followup(msg):
        model = _v43_detect_constant_accel_context(msg)
        if model:
            return _v43_constant_accel_graph_html(model, _v43_kind_from_graph_message(msg))
    reply = _v43_old_independent_physics_ai_reply(message) if _v43_old_independent_physics_ai_reply else "I can help with physics."
    if _v43_detect_constant_accel_context(msg):
        reply += "\n\n" + _v43_constacc_action_forms()
    return reply

def _v43_chat_messages_html(messages: List[Dict[str, Any]]) -> str:
    if not messages:
        return '<p class="muted">No chat messages yet. Start by asking a physics or equation question.</p>'
    out = []
    for m in messages:
        role = str(m.get('role') or ''); label = 'Student' if role == 'student' else 'AI Tutor'; cls = 'student' if role == 'student' else 'assistant'
        raw = str(m.get('message') or '')
        body = _v38_format_response_html(raw) if role == 'assistant' and '_v38_format_response_html' in globals() else format_chat_text(raw)
        out.append(f'<div class="card wide chat-card {cls}"><strong>{label}</strong><div>{body}</div><small>{h(m.get("created_at") or "")}</small></div>')
    return ''.join(out)

