V45_VERSION = "v45_CHAT_HISTORY_ACTIVE_WORKSPACE_FIX"

def _v45_nav() -> str:
    return """
    <div class='quick-chat' style='margin:0 0 1rem 0;'>
      <strong>Navigation:</strong>
      <a class='button small secondary' href='/student-ai-chat-v45'>Branch Selector</a>
      <a class='button small secondary' href='/physics-ai-chat-v45'>Branch 1: Dynamics Training Chat</a>
      <a class='button small secondary' href='/student-ai-chat'>Branch 2A</a>
      <a class='button small secondary' href='/branch2-new-story-chat'>Branch 2B</a>
      <a class='button small secondary' href='/constant-acceleration-test-pack-v45'>Constant Acceleration Tests</a>
      <a class='button small secondary' href='/test-checklist-v45'>v45 Checklist</a>
    </div>
    """

def _v45_constacc_action_forms() -> str:
    actions = [
        ('Show position versus time', 'V45_GRAPH_POSITION'),
        ('Show velocity versus time', 'V45_GRAPH_VELOCITY'),
        ('Show acceleration versus time', 'V45_GRAPH_ACCELERATION'),
        ('Show all motion graphs', 'V45_GRAPH_ALL'),
    ]
    forms = []
    for label, msg in actions:
        forms.append(f'''<form method="post" action="/physics-ai-chat-v45/form" style="display:inline-block;margin:0.2rem;"><input type="hidden" name="message" value="{h(msg)}"><button type="submit" class="secondary">{h(label)}</button></form>''')
    return "<div class='quick-chat'><p><strong>Constant-acceleration graph actions:</strong></p>" + ''.join(forms) + "</div>"

def _v45_convert_v43_graph_html(html: str) -> str:
    return (str(html or '')
            .replace('/physics-ai-chat-v43/form', '/physics-ai-chat-v45/form')
            .replace('V43_GRAPH_POSITION', 'V45_GRAPH_POSITION')
            .replace('V43_GRAPH_VELOCITY', 'V45_GRAPH_VELOCITY')
            .replace('V43_GRAPH_ACCELERATION', 'V45_GRAPH_ACCELERATION')
            .replace('V43_GRAPH_ALL', 'V45_GRAPH_ALL'))

def _v45_visible_prompt_label(message: str) -> str:
    labels = {
        'V45_GRAPH_POSITION': 'Show position versus time',
        'V45_GRAPH_VELOCITY': 'Show velocity versus time',
        'V45_GRAPH_ACCELERATION': 'Show acceleration versus time',
        'V45_GRAPH_ALL': 'Show all motion graphs',
    }
    return labels.get(str(message or '').strip(), str(message or ''))

def _v45_kind_from_graph_message(message: str) -> str:
    s = str(message or '')
    if 'V45_GRAPH_POSITION' in s: return 'position'
    if 'V45_GRAPH_VELOCITY' in s: return 'velocity'
    if 'V45_GRAPH_ACCELERATION' in s: return 'acceleration'
    if 'V45_GRAPH_ALL' in s: return 'all'
    return _v43_kind_from_graph_message(message)

def _v45_is_graph_followup(message: str) -> bool:
    s = str(message or '')
    return s in {'V45_GRAPH_POSITION','V45_GRAPH_VELOCITY','V45_GRAPH_ACCELERATION','V45_GRAPH_ALL'} or _v43_is_graph_followup(s)

def _v45_reply(message: str) -> str:
    msg = str(message or '').strip()
    context = _v43_recent_independent_context(16)
    if _v45_is_graph_followup(msg):
        model = _v43_detect_constant_accel_context(context)
        if model:
            return _v45_convert_v43_graph_html(_v43_constant_accel_graph_html(model, _v45_kind_from_graph_message(msg)))
    reply = independent_physics_ai_reply(msg)
    reply = _v45_convert_v43_graph_html(reply)
    if _v43_detect_constant_accel_context(msg) and 'Constant-acceleration graph actions' not in reply:
        reply += "\n\n" + _v45_constacc_action_forms()
    return reply

def _v45_pair_exchanges(messages: List[Dict[str, Any]]) -> List[List[Dict[str, Any]]]:
    pairs = []
    i = 0
    while i < len(messages):
        cur = messages[i]
        if str(cur.get('role')) == 'student':
            pair = [cur]
            if i + 1 < len(messages) and str(messages[i+1].get('role')) == 'assistant':
                pair.append(messages[i+1])
                i += 2
            else:
                i += 1
            pairs.append(pair)
        else:
            pairs.append([cur])
            i += 1
    return pairs

def _v45_render_messages(messages: List[Dict[str, Any]]) -> str:
    if not messages:
        return '<p class="muted">No messages in this view.</p>'
    return _v43_chat_messages_html(messages)

def _v45_select_messages(messages: List[Dict[str, Any]], view: str = 'current', exchange: str = '') -> List[Dict[str, Any]]:
    view = str(view or 'current')
    pairs = _v45_pair_exchanges(messages)
    if view == 'hide':
        return []
    if view == 'all':
        return messages
    if view == 'recent3':
        selected = []
        for pair in pairs[-3:]:
            selected.extend(pair)
        return selected
    if view == 'students':
        return [m for m in messages if str(m.get('role')) == 'student']
    if view == 'ai':
        return [m for m in messages if str(m.get('role')) == 'assistant']
    if view == 'selected':
        try:
            idx = int(exchange)
            if 0 <= idx < len(pairs):
                return pairs[idx]
        except Exception:
            pass
        return []
    selected = []
    if pairs:
        selected.extend(pairs[-1])
    return selected

def _v45_history_controls(messages: List[Dict[str, Any]], view: str = 'current', exchange: str = '') -> str:
    pairs = _v45_pair_exchanges(messages)
    options = []
    for i, pair in enumerate(pairs):
        prompt = ''
        for m in pair:
            if str(m.get('role')) == 'student':
                prompt = str(m.get('message') or '')[:72]
                break
        selected = ' selected' if str(exchange) == str(i) and view == 'selected' else ''
        options.append(f'<option value="{i}"{selected}>Exchange {i+1}: {h(prompt)}</option>')
    view_options = [
        ('current','Current exchange only'),
        ('recent3','Most recent 3 exchanges'),
        ('all','Display all exchanges'),
        ('hide','Hide history'),
        ('students','Student prompts only'),
        ('ai','AI replies only'),
        ('selected','Select previous exchange'),
    ]
    view_html = ''.join(f'<option value="{v}" {"selected" if view==v else ""}>{h(label)}</option>' for v,label in view_options)
    exchange_options = ''.join(options)
    return f'''
    <div class="card wide" style="margin:0.75rem 0;">
      <form method="get" action="/physics-ai-chat-v45" style="display:flex;gap:0.5rem;align-items:end;flex-wrap:wrap;">
        <label><strong>Chat History</strong><br><select name="view">{view_html}</select></label>
        <label><strong>Previous exchange</strong><br><select name="exchange">{exchange_options}</select></label>
        <button class="secondary" type="submit">Apply</button>
        <a class="button secondary" href="/physics-ai-chat-v45?view=current">Clear view to current</a>
      </form>
      <p class="muted">Older exchanges are stored here. Hiding history does not erase the active physics context for follow-up graph prompts.</p>
    </div>
    '''

