def _v47_format_chat_text_no_equation_corruption(text: str) -> str:
    """Render v47 tutor text without sending HTML/SVG through the old equation formatter.

    The legacy formatter is useful for short equation answers, but it corrupts
    trusted SVG/HTML graph blocks by rewriting attributes such as text-anchor
    and by treating units like m/s^2 as fractions.  v47 uses this renderer for
    Branch 1 so FBDs and plots remain real figures rather than transcript
    gibberish.
    """
    raw = unescape(text or "")
    blocks = []
    def stash(match: re.Match) -> str:
        blocks.append(match.group(0))
        return f"@@V47_TRUSTED_BLOCK_{len(blocks)-1}@@"
    raw = re.sub(r'<div class=["\'][^"\']*(?:v47-fbd-figure|equation-graph-card|v47-graph-menu|v49-tutor-card|v49-solution-card|v49-pulley-fbd)[^"\']*["\'][\s\S]*?</div>', stash, raw)
    safe = h(raw)
    safe = safe.replace("\n", "<br>")
    for i, block in enumerate(blocks):
        safe = safe.replace(f"@@V47_TRUSTED_BLOCK_{i}@@", block)
    return safe


def chat_messages_html_v47(messages: List[Dict[str, Any]]) -> str:
    if not messages:
        return '<p class="muted">No chat messages yet. Start by asking a physics or equation question.</p>'
    out = []
    for m in messages:
        role = str(m.get('role') or '')
        label = 'Student' if role == 'student' else 'AI Tutor'
        cls = 'student' if role == 'student' else 'assistant'
        raw = str(m.get('message') or '')
        content = h(raw).replace('\n', '<br>') if role == 'student' else _v47_format_chat_text_no_equation_corruption(raw)
        out.append(f'<div class="card wide chat-card {cls}"><strong>{label}</strong><div>{content}</div><small>{h(m.get("created_at") or "")}</small></div>')
    return ''.join(out)

