@app.post('/physics-ai-chat-v47/form', response_class=HTMLResponse)
def independent_physics_ai_chat_form_v47(message: str = Form(...)) -> HTMLResponse:
    last_assistant = _v47_last_assistant_message()
    add_independent_physics_chat('student', message)
    reply = _v47_followup_reply(message, last_assistant) or _v47_reply(message)
    add_independent_physics_chat('assistant', reply)
    return HTMLResponse('<meta http-equiv="refresh" content="0; url=/physics-ai-chat-v47?view=current#latest">')


@app.post('/physics-ai-chat-v47/clear', response_class=HTMLResponse)
def independent_physics_ai_chat_clear_v47() -> HTMLResponse:
    ensure_independent_physics_chat_table()
    with connect() as conn:
        conn.execute('DELETE FROM independent_physics_ai_chat_messages')
        conn.commit()
    return HTMLResponse('<meta http-equiv="refresh" content="0; url=/physics-ai-chat-v47?view=current">')


