# Keep the previous dynamics tutor, but append a Branch 1 graph menu whenever it
# computes an acceleration. This makes graph access part of dynamics, not only
# part of the Constant Acceleration Tests page.
_v47_dynamics_training_reply_previous = _v47_dynamics_training_reply

def _v47_dynamics_training_reply(message: str) -> str:
    reply = _v47_dynamics_training_reply_previous(message)
    if not reply:
        return reply
    text = str(reply)
    low_msg = str(message or '').lower()
    already_has_menu = 'Graph menu for this motion model' in text or 'V47_GRAPH_CONTEXT' in text
    # Extract a numerical acceleration from standard v47 dynamics answers.
    match = re.search(r'a\s*=\s*[^=\n]*=\s*([-+]?\d+(?:\.\d+)?)\s*m/s²', text)
    if not match:
        match = re.search(r'a\s*=\s*[^=\n]*=\s*([-+]?\d+(?:\.\d+)?)\s*m/s\^2', text)
    if match and not already_has_menu:
        a = float(match.group(1))
        tmax = 5.0
        t_match = re.search(r'(?:for|after|from\s+0\s+to)\s+([-+]?\d+(?:\.\d+)?)\s*s', low_msg)
        if t_match:
            tmax = float(t_match.group(1))
        graph_intro = (
            "\n\nMotion graph connection inside dynamics:\n"
            "Now that dynamics has determined acceleration, the same Branch 1 chat can plot motion using constant-acceleration kinematics. "
            "Assuming x_i = 0 and v_i = 0 unless the student gives different initial conditions, choose a graph below.\n"
        )
        return text + graph_intro + _v47_graph_choice_menu(a, tmax, 0.0, 0.0)
    return reply


# Improve the generic combined force-motion case so a request for all graphs
# shows all three immediately, not only the first graph.
_v47_combined_kinematics_dynamics_reply_previous = _v47_combined_kinematics_dynamics_reply

def _v47_combined_kinematics_dynamics_reply(message: str) -> str:
    low = str(message or '').lower()
    reply = _v47_combined_kinematics_dynamics_reply_previous(message)
    if not reply:
        return reply
    if any(k in low for k in ['all three', 'position, velocity, and acceleration', 'position velocity and acceleration']):
        # Try to extract acceleration and time from the reply or prompt.
        a_match = re.search(r'a\s*=\s*([-+]?\d+(?:\.\d+)?)\s*m/s²', reply) or re.search(r'acceleration\s+of\s+([-+]?\d+(?:\.\d+)?)\s*m/s', low)
        t_match = re.search(r'(?:from\s+0\s+to|for|after)\s+([-+]?\d+(?:\.\d+)?)\s*s', low)
        if a_match:
            a = float(a_match.group(1))
            tmax = float(t_match.group(1)) if t_match else 5.0
            return reply + "\n\nBecause you asked for all three graphs, here they are inside Branch 1:\n" + _v47_graph_context_reply(f"V47_GRAPH_CONTEXT kind=all a={a} tmax={tmax} xi=0 vi=0")
    return reply


