def _v48_working_prompt_buttons(compact: bool = True) -> str:
    prompts = [
        ("Horizontal dynamics + graph", "A 12 kg crate is pulled across a horizontal floor by a rope with tension T = 60 N at 30 degrees above the horizontal. The coefficient of kinetic friction is mu_k = 0.20. The crate starts from rest at x = 0. Draw the FBD, find acceleration, find v(5 s) and x(5 s), and plot position versus time from 0 to 5 seconds."),
        ("Multiple horizontal forces", "A 20 kg cart is pulled by T = 90 N at 25 degrees above horizontal. A second horizontal force of 18 N pushes backward. mu_k = 0.15. It starts from rest. Draw the FBD, find acceleration, v(8 s), x(8 s), and plot x(t)."),
        ("Inclined plane", "A 6 kg block slides down a 30 degree incline with coefficient of kinetic friction mu_k = 0.10. Start from Newton's laws, draw the FBD with axes along the ramp, find acceleration down the incline, then find velocity and displacement after 4 s from rest."),
        ("Elevator apparent weight", "A 70 kg student stands on a scale in an elevator accelerating upward at 1.5 m/s^2. Draw the FBD and find the scale reading. Then explain what changes if the elevator accelerates downward."),
        ("Pulley two-body", "A 4 kg cart on a frictionless table is connected by a light string over a pulley to a hanging 2 kg mass. Draw separate FBDs, write Newton's law for each object, solve for acceleration and tension, then find speed after 3 s from rest."),
        ("Equilibrium sign", "A 20 kg sign hangs at rest from two ropes that make angles of 35 degrees and 55 degrees with the horizontal. Draw the FBD and set up Sigma Fx = 0 and Sigma Fy = 0 to solve the two tensions."),
        ("Kinematics regression", "A car starts from rest and accelerates at 2 m/s^2 for 5 seconds. Find the final velocity and plot position versus time."),
        ("Force from acceleration", "An object of mass 10 kg experiences a 2 m/s^2 horizontal acceleration. What is the net force? Then plot position versus time from 0 to 5 seconds assuming it starts from rest.")
    ]
    buttons = ''.join(_v48_prompt_button(label, prompt) for label, prompt in prompts)
    return f'''<details open><summary><strong>Current guided-tutor prompt library</strong></summary><p>These prompts test template families, not isolated examples.</p>{buttons}</details>'''



def _v48_svg_arrow(x1: float, y1: float, x2: float, y2: float, label: str, label_dx: float = 0, label_dy: float = 0, dashed: bool = False) -> str:
    dash = ' stroke-dasharray="7 5"' if dashed else ''
    mx = (x1 + x2) / 2 + label_dx
    my = (y1 + y2) / 2 + label_dy
    return f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="currentColor" stroke-width="2.8" marker-end="url(#arrow)"{dash}/><text x="{mx:.1f}" y="{my:.1f}" font-size="15" font-weight="700">{h(label)}</text>'


def _v48_incline_fbd_svg(object_label: str, theta: float, m: float, mg: float, fn: float, fk: float, mgsin: float, mgcos: float, tension: float = 0.0, motion_up: bool = False) -> str:
    import math
    th = math.radians(theta)
    cx, cy = 390.0, 238.0
    ux, uy = math.cos(th), -math.sin(th)
    dx, dy = -ux, -uy
    nx, ny = -math.sin(th), -math.cos(th)
    ix, iy = -nx, -ny
    sx, sy = (ux, uy) if motion_up else (dx, dy)
    s_label = '+s up ramp' if motion_up else '+s down ramp'
    frx, fry = (dx, dy) if motion_up else (ux, uy)
    friction_label = 'f_k down ramp' if motion_up else 'f_k up ramp'
    tension_arrow = ''
    if tension and tension > 0:
        tension_arrow = _v48_svg_arrow(cx, cy, cx + ux*105, cy + uy*105, f'T = {tension:.1f} N', 18, -10)
    return f"""
<div class="v47-fbd-figure" style="max-width:860px;border:1px solid #d0d7de;border-radius:12px;padding:12px;margin:0.75rem 0;background:#fff;">
  <h3 style="margin:0 0 0.4rem 0;">Inclined-plane free-body diagram</h3>
  <svg viewBox="0 0 820 470" width="100%" role="img" aria-label="Inclined plane free-body diagram with axes and components">
    <defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth"><path d="M0,0 L0,6 L9,3 z" fill="currentColor"/></marker></defs>
    <rect x="0" y="0" width="820" height="470" rx="10" fill="#ffffff"/>
    <line x1="115" y1="360" x2="695" y2="149" stroke="currentColor" stroke-width="4"/>
    <line x1="115" y1="360" x2="695" y2="360" stroke="currentColor" stroke-width="1.4" opacity="0.45"/>
    <path d="M 155 360 A 58 58 0 0 0 209 339" fill="none" stroke="currentColor" stroke-width="1.5"/>
    <text x="180" y="352" font-size="15">theta = {theta:.1f} deg</text>
    <g transform="translate({cx:.1f},{cy:.1f}) rotate({-theta:.1f})">
      <rect x="-45" y="-24" width="90" height="48" rx="6" fill="#eef2ff" stroke="currentColor" stroke-width="2"/>
      <text x="0" y="5" text-anchor="middle" font-size="14" font-weight="700">{h(object_label)}</text>
    </g>
    {_v48_svg_arrow(cx, cy, cx + sx*118, cy + sy*118, s_label, 8, -10)}
    {_v48_svg_arrow(cx, cy, cx + nx*105, cy + ny*105, '+n', -30, -12)}
    {_v48_svg_arrow(cx, cy, cx, cy + 115, f'mg = {mg:.1f} N', 14, 8)}
    {_v48_svg_arrow(cx, cy, cx + nx*max(55, min(105, fn*0.75)), cy + ny*max(55, min(105, fn*0.75)), f'F_n = {fn:.1f} N', -52, -18)}
    {tension_arrow}
    {_v48_svg_arrow(cx, cy, cx + frx*75, cy + fry*75, f'{friction_label} = {fk:.1f} N', -84, 22)}
    {_v48_svg_arrow(cx+18, cy+18, cx+18 + dx*92, cy+18 + dy*92, f'mg sinθ = {mgsin:.1f} N', -100, 12, dashed=True)}
    {_v48_svg_arrow(cx-18, cy+18, cx-18 + ix*82, cy+18 + iy*82, f'mg cosθ = {mgcos:.1f} N', 12, 28, dashed=True)}
  </svg>
  <p><strong>FBD rule:</strong> choose axes parallel and perpendicular to the plane. The real force is <em>mg</em> downward; <em>mg sinθ</em> and <em>mg cosθ</em> are components of weight, not extra forces.</p>
  <p><strong>Sign convention:</strong> {'positive s is up the incline because the rope pulls the block up the incline.' if motion_up else 'positive s is down the incline because the block slides down the incline.'}</p>
</div>
"""

def _v48_reasoning_engine_reply(message: str) -> str:
    low = str(message or '').lower()
    import math, re
    if any(w in low for w in ['incline','inclined plane','ramp']) and ('friction' in low or 'mu' in low or 'μ' in low):
        m = _v47_find_number(r'(\d+(?:\.\d+)?)\s*kg', message, 6.0)
        theta = _v47_find_number(r'(\d+(?:\.\d+)?)\s*(?:°|deg|degree|degrees)', message, None)
        if theta is None:
            theta = _v47_find_number(r'(?:theta|θ)\s*(?:=|is)?\s*(\d+(?:\.\d+)?)', message, None)
        if theta is None:
            theta = 30.0
        mu = _v47_find_number(r'(?:mu_k|μ_k|coefficient\s+of\s+kinetic\s+friction)\s*(?:=|is)?\s*(\d+(?:\.\d+)?)', message, 0.10)
        T = _v47_find_number(r'(?:rope\s+tension\s+(?:is|=)|tension\s+(?:is|of|=)|tension\s*T\s*=|T\s*=)\s*(\d+(?:\.\d+)?)\s*N', message, None)
        if T is None:
            # No tension was stated; leave it at zero only for genuine no-rope incline cases.
            T = 0.0
        times = [float(x) for x in re.findall(r'(\d+(?:\.\d+)?)\s*(?:s|seconds?)\b', message, re.I)]
        tmax = times[-1] if times else 4.0
        g = 9.8
        mg = m*g
        mgsin = mg*math.sin(math.radians(theta))
        mgcos = mg*math.cos(math.radians(theta))
        Fn = mgcos
        fk = mu*Fn
        motion_up = any(k in low for k in ['up the incline', 'up incline', 'up the ramp', 'up ramp', 'pulls the block up', 'pulled up'])
        object_label = 'block'
        for candidate in ['sled','cart','crate','box','block','object']:
            if candidate in low:
                object_label = candidate
                break
        if motion_up or T > 0:
            Fnet = T - mgsin - fk
            direction_text = 'up the ramp' if Fnet >= 0 else 'down the ramp'
            eq_parallel = 'Sigma F_s = T - mg sin(theta) - f_k = ma'
            positive_axis = 'up the incline'
        else:
            Fnet = mgsin - fk
            direction_text = 'down the ramp' if Fnet >= 0 else 'up the ramp'
            eq_parallel = 'Sigma F_s = mg sin(theta) - f_k = ma'
            positive_axis = 'down the incline'
        a = Fnet/m
        v = a*tmax
        x = 0.5*a*tmax*tmax
        fbd = _v48_incline_fbd_svg(object_label, theta, m, mg, Fn, fk, mgsin, mgcos, T, motion_up or T > 0)
        if motion_up or T > 0:
            parallel_line = f"Sigma F_s = T - mg sin(theta) - f_k = {T:.1f} N - {mgsin:.1f} N - {fk:.1f} N = {Fnet:.1f} N."
            tension_line = f"\nT = {T:.1f} N acts up the incline."
        else:
            parallel_line = f"Sigma F_s = mg sin(theta) - f_k = {mgsin:.1f} N - {fk:.1f} N = {Fnet:.1f} N."
            tension_line = ''
        return (_v47_clean_header('template-family dynamics', 'inclined plane with friction', 'F_n, f_k, a, v(t), x(t)', f'F_n = mg cos(theta); f_k = mu_k F_n; {eq_parallel}', 'Choosing axes along and perpendicular to the ramp turns the force problem into one-dimensional dynamics along the ramp.')
            + f"\n\nCurrent problem values extracted: m = {m:.1f} kg, theta = {theta:.1f} deg, T = {T:.1f} N, mu_k = {mu:.2f}, t = {tmax:.1f} s, v_i = 0.0 m/s. These values come from the current written prompt; no template values or previous-problem values are used. Positive s is {positive_axis}."
            + tension_line
            + fbd
            + f"\nPerpendicular equation: F_n - mg cos(theta) = 0, so F_n = mg cos(theta) = ({mg:.1f} N)cos({theta:.1f} deg) = {Fn:.1f} N."
            + f"\nKinetic friction: f_k = mu_k F_n = ({mu:.2f})({Fn:.1f} N) = {fk:.1f} N."
            + f"\nParallel equation: {parallel_line}"
            + f"\na = Sigma F_s/m = {Fnet:.1f} N/{m:.1f} kg = {a:.3f} m/s^2. The acceleration is {direction_text} relative to the chosen axis."
            + f"\nv({tmax:.1f} s) = {v:.2f} m/s; s({tmax:.1f} s) = {x:.2f} m along the incline, using the chosen sign convention."
            + _v47_graph_choice_menu(a, tmax, 0.0, 0.0)
            + _v47_followup_question('Which force would change if the incline angle were increased: F_n, mg sin(theta), friction, or all three?'))
    if 'elevator' in low or 'scale reading' in low or 'apparent weight' in low:
        m = _v47_find_number(r'(\d+(?:\.\d+)?)\s*kg', message, 70.0)
        a = _v47_find_number(r'(\d+(?:\.\d+)?)\s*m\s*/?\s*s\^?2', message, 1.5)
        upward = 'downward' not in low
        g = 9.8
        Fn = m*(g + a) if upward else m*(g - a)
        sign_eq = 'F_n - mg = ma' if upward else 'mg - F_n = ma'
        direction = 'upward' if upward else 'downward'
        return (_v47_clean_header('template-family dynamics', 'elevator apparent weight', 'scale reading F_n', sign_eq, 'The scale reads the normal force, not the weight directly.')
            + f"\n\nFree-body diagram:\n```text\n      F_n upward\n       ↑\n   [ student ]   acceleration {direction}\n       ↓\n      mg downward\n```"
            + f"\nFor {direction} acceleration a = {a:.2f} m/s² and m = {m:.1f} kg:"
            + (f"\nF_n = m(g+a) = {m:.1f}(9.8+{a:.2f}) = {Fn:.1f} N." if upward else f"\nF_n = m(g-a) = {m:.1f}(9.8-{a:.2f}) = {Fn:.1f} N.")
            + _v47_followup_question('Would the scale reading be larger, smaller, or equal to mg in this case?'))
    if ('pulley' in low or 'hanging' in low or 'string over' in low) and ('cart' in low or 'mass' in low):
        # v49 corrective inheritance: the active engine must solve the two-body
        # pulley template directly, including cart friction, instead of falling
        # back to the older frictionless v48 shortcut.
        def find_before_word(word: str, default: float) -> float:
            m = re.search(r'(\d+(?:\.\d+)?)\s*kg\s+' + word, message, re.I)
            if m:
                return float(m.group(1))
            m = re.search(word + r'[\s\S]{0,45}?(\d+(?:\.\d+)?)\s*kg', message, re.I)
            return float(m.group(1)) if m else default
        m_cart = find_before_word(r'(?:cart|block|crate|box)', 8.0)
        m_hang = find_before_word(r'(?:hanging\s+mass|hanger|mass)', 5.0)
        # Avoid using the cart mass for the hanging mass when the phrase says "mass is connected ... to cart".
        m_h = re.search(r'(\d+(?:\.\d+)?)\s*kg\s+hanging\s+mass', message, re.I)
        if m_h:
            m_hang = float(m_h.group(1))
        m_c = re.search(r'(\d+(?:\.\d+)?)\s*kg\s+cart', message, re.I)
        if m_c:
            m_cart = float(m_c.group(1))
        nums = [float(x) for x in re.findall(r'(\d+(?:\.\d+)?)\s*kg', message, re.I)]
        if len(nums) >= 2 and not (m_h and m_c):
            # If the text says hanging mass first and cart second, preserve that semantic order.
            if 'hanging mass' in low and 'cart' in low and low.find('hanging mass') < low.find('cart'):
                m_hang, m_cart = nums[0], nums[1]
            else:
                m_cart, m_hang = nums[0], nums[1]
        mu = _v47_find_number(r'(?:mu_k|μ_k|coefficient\s+of\s+kinetic\s+friction|friction\s+coefficient)[^0-9]{0,30}(\d+(?:\.\d+)?)', message, 0.0)
        times = [float(x) for x in re.findall(r'(\d+(?:\.\d+)?)\s*(?:s|seconds?)\b', message, re.I)]
        tmax = times[-1] if times else 3.0
        g = 9.8
        fk = mu*m_cart*g
        drive = m_hang*g - fk
        a = drive/(m_cart+m_hang)
        T = m_cart*a + fk
        v = a*tmax
        x = 0.5*a*tmax*tmax
        direction_note = 'hanging mass downward and cart to the right' if a >= 0 else 'opposite the assumed direction because friction is too large for this assumed motion'
        return (_v47_clean_header('template-family dynamics', 'two-body pulley system with shared acceleration', 'a, T, v(t), x(t)', 'cart: T - f_k = m_cart a; hanging mass: m_h g - T = m_h a', 'The string constraint makes the cart and hanging mass have the same acceleration magnitude. Friction on the cart must be included before solving the coupled equations.')
            + f"\n\nGiven: m_cart = {m_cart:.1f} kg, m_hanging = {m_hang:.1f} kg, mu_k = {mu:.2f}, t = {tmax:.1f} s. Choose positive directions as cart to the right and hanging mass downward."
            + "\n\nFree-body diagrams:\n```text\nCart on rough table:                    Hanging mass:\n       F_n ↑                                T ↑\n           │                                │\n f_k ←  [ cart ]  → T                    [ m_h ]\n           │                                │\n       m_cart g ↓                         m_h g ↓\n\n+x for cart: right                  +y for hanging mass: downward\n```"
            + f"\nCart normal force: F_n = m_cart g = ({m_cart:.1f})(9.8) = {m_cart*g:.1f} N."
            + f"\nKinetic friction on cart: f_k = mu_k F_n = ({mu:.2f})({m_cart*g:.1f}) = {fk:.1f} N."
            + f"\nCart equation: T - f_k = m_cart a."
            + f"\nHanging-mass equation: m_h g - T = m_h a."
            + f"\nAdd the equations: m_h g - f_k = (m_cart + m_h)a."
            + f"\na = ({m_hang:.1f}*9.8 - {fk:.1f})/({m_cart:.1f}+{m_hang:.1f}) = {a:.2f} m/s^2. Motion is {direction_note}."
            + f"\nT = m_cart a + f_k = ({m_cart:.1f})({a:.2f}) + {fk:.1f} = {T:.1f} N."
            + f"\nFrom rest: v({tmax:.1f} s) = a t = {v:.2f} m/s."
            + f"\nFrom rest: x({tmax:.1f} s) = 1/2 a t^2 = {x:.2f} m."
            + _v47_graph_choice_menu(a, tmax, 0.0, 0.0)
            + _v47_followup_question('Why does adding the two Newton-law equations eliminate the tension?'))
    if ('equilibrium' in low or 'at rest' in low or 'hangs' in low or 'sign' in low) and ('rope' in low or 'tension' in low):
        return (_v47_clean_header('template-family dynamics', 'translational equilibrium', 'unknown tensions', 'ΣF_x = 0 and ΣF_y = 0', 'At rest means acceleration is zero, so the vector sum of forces is zero.')
            + "\n\nFree-body diagram setup:\n```text\n          T1 ↖      ↗ T2\n              \\    /\n               [ sign ]\n                  ↓\n                 mg\n+x right, +y upward\n```"
            + "\nWrite components of each tension, then set horizontal and vertical sums equal to zero."
            + "\nHorizontal: T2 cos(theta2) - T1 cos(theta1) = 0."
            + "\nVertical: T1 sin(theta1) + T2 sin(theta2) - mg = 0."
            + _v47_followup_question('What are the two rope angles and the mass of the sign?'))
    return None

def _v48_reply(message: str) -> str:
    engine = _v48_reasoning_engine_reply(message)
    if engine:
        return engine
    return _v47_reply(message)



# v49 Guided Tutoring helpers --------------------------------------------------
def _v49_classify(message: str) -> str:
    low = str(message or '').lower()
    if 'pulley' in low or 'hanging mass' in low or 'string over' in low:
        return 'pulley'
    if 'incline' in low or 'ramp' in low or 'inclined plane' in low:
        return 'incline'
    if 'elevator' in low or 'scale' in low or 'apparent weight' in low:
        return 'elevator'
    if 'equilibrium' in low or 'sign hangs' in low or ('at rest' in low and 'rope' in low):
        return 'equilibrium'
    if any(w in low for w in ['friction','tension','force','push','pull','crate','cart','sled','box','block']):
        return 'horizontal_dynamics'
    if any(w in low for w in ['accelerat','velocity','position','kinematics','plot']):
        return 'kinematics'
    return 'general'

def _v49_guided_intro(message: str) -> str:
    family = _v49_classify(message)
    names = {'pulley':'two-body pulley dynamics','incline':'inclined-plane dynamics','elevator':'elevator / apparent-weight dynamics','equilibrium':'translational equilibrium','horizontal_dynamics':'horizontal dynamics with forces and motion','kinematics':'constant-acceleration kinematics','general':'physics reasoning'}
    data = {
        'pulley': ('This is a beautiful Newton-law problem because one string constraint makes two separate bodies move together.', 'Which objects need their own free-body diagrams: the cart, the hanging mass, or both?', ['Identify the two objects.','Choose positive directions consistent with the string constraint.','Draw one FBD for each object.','Write Newton’s second law for each object.','Solve the coupled equations for acceleration and tension.','Use kinematics after acceleration is known.']),
        'incline': ('The incline becomes much simpler when the axes follow the surface; the geometry does the work for us.', 'Which coordinate axes should we choose: ordinary horizontal/vertical axes, or axes parallel and perpendicular to the incline?', ['Choose rotated axes.','Draw the real forces first.','Resolve weight into mg sinθ and mg cosθ.','Write perpendicular and parallel force equations.','Solve acceleration with a clear sign convention.','Use kinematics along the ramp.']),
        'elevator': ('The scale does not measure mass directly; it measures the normal force required by the acceleration.', 'What are the two forces acting on the person: weight, normal force, tension, or friction?', ['Draw the person’s FBD.','Choose upward or downward as positive.','Write ΣF_y = ma.','Identify that the scale reads F_n.','Compare F_n with mg.']),
        'equilibrium': ('Equilibrium is not “no forces”; it is balanced forces.', 'Since the object is at rest, what should ΣF_x and ΣF_y equal?', ['Draw all forces on the object.','Resolve angled tensions into components.','Set ΣF_x = 0.','Set ΣF_y = 0.','Solve unknown tensions.']),
        'horizontal_dynamics': ('This is the central bridge in mechanics: forces determine acceleration, then acceleration determines motion.', 'Before calculating, which forces act on the object: weight, normal force, applied force or tension, friction, or all of these?', ['Draw the FBD.','Resolve angled forces.','Find the normal force.','Find friction if present.','Find net horizontal force.','Use a = ΣF/m.','Use kinematics and graphs.']),
        'kinematics': ('Kinematics is a language for motion; the equation choice follows the knowns and unknowns.', 'What are the known quantities and what is the unknown: final velocity, position, acceleration, or time?', ['List knowns.','Choose positive direction.','Pick the matching kinematics equation.','Solve with units.','Interpret the graph shape.']),
        'general': ('Good physics starts by naming the model, not by hunting for a formula.', 'What physical model do you think this problem belongs to: kinematics, forces, energy, momentum, or equilibrium?', ['Classify the problem.','Identify the system.','Choose a model.','Write equations.','Interpret the answer.'])}
    inspire, question, checkpoints = data[family]
    steps = ''.join(f'<li>{h(s0)}</li>' for s0 in checkpoints)
    return f'''<div class="v49-tutor-card" style="border:1px solid #d0d7de;border-radius:12px;padding:14px;margin:0.75rem 0;background:#fff;">
<h3>Guided Tutor Mode: {h(names[family])}</h3>
<p>{h(inspire)}</p>
<p><strong>We will not dump the full solution yet.</strong> We will build it in checkpoints.</p>
<ol>{steps}</ol>
<p><strong>Checkpoint 1 question:</strong> {h(question)}</p>
<p>Reply with your answer, even if it is only a guess. I will check it and then open the next step.</p>
<div style="display:flex;gap:0.5rem;flex-wrap:wrap;margin-top:0.75rem;">
  <form method="post" action="/physics-ai-chat-v49/form" style="display:inline-block;"><input type="hidden" name="mode" value="full"><input type="hidden" name="message" value="Full solution for the current problem"><button type="submit" class="secondary">Show Full Solution</button></form>
  <form method="post" action="/physics-ai-chat-v49/form" style="display:inline-block;"><input type="hidden" name="mode" value="hint"><input type="hidden" name="message" value="Give me one hint for the current problem"><button type="submit" class="secondary">Give One Hint</button></form>
</div>
</div>'''

def _v49_guided_followup(message: str, last_assistant: str) -> str:
    low = str(message or '').lower(); last = str(last_assistant or '').lower(); praise = 'Good — that is the right kind of reasoning move. '
    if 'which objects need their own free-body diagrams' in last:
        lead = praise if ('both' in low or ('cart' in low and ('hanging' in low or 'mass' in low))) else 'Close. In a coupled system, each object gets its own FBD. '
        return lead + 'For the pulley problem, draw two FBDs: one for the cart and one for the hanging mass. Next checkpoint: choose positive directions. A consistent choice is cart to the right as positive and hanging mass downward as positive. Why do these two directions share the same acceleration magnitude?'
    if 'which coordinate axes should we choose' in last:
        lead = praise if any(w in low for w in ['parallel','perpendicular','rotated','along']) else 'The best choice is rotated axes. '
        return lead + 'Use +s along the incline and +n perpendicular to the incline. Now draw the real forces first: mg downward, F_n perpendicular to the surface, friction opposite motion, and tension along the rope if present. Next checkpoint: which part of the weight goes along the incline: mg sin(theta) or mg cos(theta)?'
    if 'what are the two forces acting on the person' in last:
        lead = praise if ('normal' in low and ('weight' in low or 'mg' in low)) else 'Almost. The person has two main forces: normal force upward and weight downward. '
        return lead + 'Now write Newton’s second law in the vertical direction. If upward is positive and the elevator accelerates upward, the equation is F_n - mg = ma. What does the scale read: mass, weight mg, or normal force F_n?'
    if 'what should σf_x and σf_y equal' in last or 'what should sig' in last:
        return praise + 'For equilibrium, ΣF_x = 0 and ΣF_y = 0. Next checkpoint: resolve each angled tension into x and y components, then balance horizontal and vertical components separately.'
    if 'which forces act on the object' in last:
        return praise + 'Now turn that force list into an FBD. Put mg downward, F_n upward, any applied/tension force in its actual direction, and friction opposite motion. Next checkpoint: if the rope pulls upward at an angle, does the normal force become larger than mg, equal to mg, or smaller than mg?'
    if 'what are the known quantities' in last:
        return praise + 'Now choose the kinematics equation that contains your knowns and your target unknown. If acceleration is known and the object starts from rest, v = at and x = 1/2 at² are usually the clean path.'
    return 'Good. Let us continue one step at a time. Identify the forces or known quantities, then I will help you write the equation before solving.'

def _v49_hint_reply(message: str) -> str:
    family = _v49_classify(message)
    hints = {'pulley':'Hint: draw two FBDs and write two Newton-law equations. The cart and hanging mass have the same acceleration magnitude because the string length is fixed.','incline':'Hint: rotate your axes. Use +s along the ramp and +n perpendicular to it. Weight is still downward; mg sinθ and mg cosθ are components.','elevator':'Hint: the scale reads F_n. Use F_n - mg = ma if upward is positive and acceleration is upward.','equilibrium':'Hint: at rest means ΣF_x = 0 and ΣF_y = 0. Resolve each angled tension into components.','horizontal_dynamics':'Hint: find the normal force before friction. If a rope pulls upward at an angle, F_n is less than mg.','kinematics':'Hint: list knowns and unknowns first. If starting from rest with constant acceleration, v = at and x = 1/2 at².'}
    return '<strong>Hint only:</strong> ' + h(hints.get(family, 'Start by identifying the physical model, the system, and the unknown.'))

def _v49_check_reply(message: str, last_assistant: str = '') -> str:
    low = str(message or '').lower()
    if any(x in low for x in ['i think','my answer','=', 'n', 'm/s', 'kg']):
        return '<strong>Check My Work:</strong> I see an attempted quantitative or equation answer. I will check structure first: (1) clear FBD, (2) sign convention, (3) Newton-law equation, and (4) units. Paste your equations and numbers, and I will mark the first incorrect step instead of simply giving the answer.'
    return '<strong>Check My Work:</strong> Paste your attempted FBD description, equations, or numerical answer. I will check one step at a time and explain the first place where the reasoning needs correction.'


def _v49_last_student_problem() -> str:
    try:
        ensure_independent_physics_chat_table()
        with connect() as conn:
            row = conn.execute("SELECT message FROM independent_physics_ai_chat_messages WHERE role='student' AND message NOT LIKE 'Full solution for the current problem%' AND message NOT LIKE 'Give me one hint for the current problem%' ORDER BY id DESC LIMIT 1").fetchone()
        return row[0] if row else ''
    except Exception:
        return ''



def _v49_prompt_requests_complete_workflow(message: str) -> bool:
    """Return True when a student has asked for a complete worked workflow.

    Guided Tutor Mode is still useful for exploratory questions, but an explicit
    classroom-style command such as "draw FBDs, write equations, solve, then plot"
    should not stop at checkpoint 1.  It should produce the full reasoning chain
    and then invite the student to discuss any step.
    """
    low = str(message or '').lower()
    required_action = any(x in low for x in [
        'solve for', 'find the acceleration', 'find acceleration', 'find the speed',
        'find the velocity', 'find the distance', 'find the position', 'find the tension',
        'write the force equation', 'write the equation', 'use the two equations'
    ])
    requested_visual_or_plot = any(x in low for x in [
        'plot', 'graph', 'draw two separate free-body diagrams', 'draw the free-body diagram', 'draw a free-body diagram', 'draw fbd'
    ])
    multi_step_phrasing = any(x in low for x in [
        'then use kinematics', 'finally', 'start from newton', 'start from newton’s laws',
        'start from newton\'s laws', 'use newton', 'free-body diagrams'
    ])
    return required_action and (requested_visual_or_plot or multi_step_phrasing)

def _v49_tutor_reply(message: str, mode: str, last_assistant: str = '') -> str:
    low = str(message or '').lower()
    current_problem = _v49_last_student_problem() if ('current problem' in low or mode == 'full') else ''
    problem_text = current_problem or message
    if 'full solution' in low or mode == 'full' or (mode == 'guided' and _v49_prompt_requests_complete_workflow(problem_text)):
        card_title = 'Full Solution Mode' if (mode == 'full' or 'full solution' in low) else 'Guided Tutor Mode: complete workflow requested'
        card_note = 'This prompt explicitly asks for FBDs, Newton-law equations, solution, kinematics, and plots, so the tutor will complete the workflow and then invite step-by-step discussion.' if mode == 'guided' else 'This mode gives the complete worked solution. Use Guided Tutor Mode when the student should answer checkpoints first.'
        return f'<div class="v49-solution-card" style="border:1px solid #d0d7de;border-radius:12px;padding:14px;margin:0.75rem 0;background:#fff;"><h3>{card_title}</h3><p>{card_note}</p></div>' + _v48_reply(problem_text)
    if mode == 'hint':
        return _v49_hint_reply(problem_text)
    if mode == 'check':
        return _v49_check_reply(message, last_assistant)
    if 'checkpoint 1 question' in str(last_assistant or '').lower() or 'next checkpoint' in str(last_assistant or '').lower():
        return _v49_guided_followup(message, last_assistant)
    return _v49_guided_intro(message)

