# -----------------------------------------------------------------------------
# v49 student workflow hardening: dedicated student ask route + direct pulley path
# -----------------------------------------------------------------------------
def _v49_is_pulley_cart_hanging_problem(message: str) -> bool:
    low = str(message or '').lower()
    return (('pulley' in low or 'hanging mass' in low or 'string over' in low or 'connected by a light string' in low)
            and ('cart' in low or 'table' in low)
            and ('tension' in low or 'string' in low))

def _v49_direct_pulley_full_solution(message: str) -> str:
    """Clean classroom-style solution for cart + hanging-mass pulley problems.

    This replaces the earlier debug-style output. The student should see a
    readable solution with sections, not internal tutor metadata or raw HTML
    tables.
    """
    import re
    text = str(message or '')
    low = text.lower()

    nums = [float(x) for x in re.findall(r'(\d+(?:\.\d+)?)\s*kg', text, re.I)]
    m_hang, m_cart = 5.0, 8.0
    mh = re.search(r'(\d+(?:\.\d+)?)\s*kg\s+hanging\s+mass', text, re.I)
    mc = re.search(r'(\d+(?:\.\d+)?)\s*kg\s+cart', text, re.I)
    if mh:
        m_hang = float(mh.group(1))
    if mc:
        m_cart = float(mc.group(1))
    if len(nums) >= 2 and not (mh and mc):
        if 'hanging mass' in low and 'cart' in low and low.find('hanging mass') < low.find('cart'):
            m_hang, m_cart = nums[0], nums[1]
        else:
            m_cart, m_hang = nums[0], nums[1]

    mu = _v47_find_number(r'(?:mu_k|μ_k|coefficient\s+of\s+kinetic\s+friction|friction\s+coefficient)[^0-9]{0,30}(\d+(?:\.\d+)?)', text, 0.0)
    times = [float(x) for x in re.findall(r'(\d+(?:\.\d+)?)\s*(?:s|seconds?)\b', text, re.I)]
    tmax = times[-1] if times else 3.5
    g = 9.8

    fn = m_cart * g
    fk = mu * fn
    drive = m_hang * g
    net_system = drive - fk
    a = net_system / (m_cart + m_hang)
    T = m_cart * a + fk
    v = a * tmax
    x = 0.5 * a * tmax * tmax

    fbd = f"""
<div class="v49-pulley-fbd" style="max-width:900px;border:1px solid #d0d7de;border-radius:12px;padding:12px;margin:0.75rem 0;background:#fff;">
  <h3 style="margin:0 0 0.4rem 0;">Free-body diagrams</h3>
  <pre style="white-space:pre-wrap;font-family:Consolas,monospace;font-size:15px;line-height:1.35;">
Cart on rough table, +x to the right        Hanging mass, +y downward

          F_n ↑                                      T ↑
              |                                      |
 f_k ←   [ cart ]   → T                         [ m_h ]
              |                                      |
        m_cart g ↓                                m_h g ↓

F_n = {fn:.1f} N       f_k = {fk:.1f} N       m_h g = {drive:.1f} N
  </pre>
  <p><strong>Constraint:</strong> the string does not stretch, so both objects have the same acceleration magnitude.</p>
</div>
"""

    rows = []
    for i in range(0, 6):
        tt = tmax * i / 5.0
        rows.append((tt, 0.5 * a * tt * tt, a * tt))
    plot_lines = ['t (s)     x (m)     v (m/s)']
    for tt, xx, vv in rows:
        plot_lines.append(f'{tt:4.2f}    {xx:6.2f}    {vv:7.2f}')
    plot_text = '\n'.join(plot_lines)

    title = '<div class="v49-solution-card" style="border:1px solid #d0d7de;border-radius:12px;padding:14px;margin:0.75rem 0;background:#fff;"><h3>Full workflow: cart + hanging mass pulley system</h3><p>We solve this from Newton’s laws first, then use the acceleration in the kinematics.</p></div>'

    return (title
            + f"\n\n**Given**\n"
            + f"m_cart = {m_cart:.1f} kg, m_hanging = {m_hang:.1f} kg, μ_k = {mu:.2f}, t = {tmax:.1f} s, g = 9.8 m/s².\n"
            + "Choose cart to the right as positive and the hanging mass downward as positive. These directions are consistent with the expected motion.\n"
            + fbd
            + "\n**Newton’s second law equations**\n"
            + "Cart, vertical: F_n - m_cart g = 0.\n"
            + f"F_n = ({m_cart:.1f})(9.8) = {fn:.1f} N.\n\n"
            + f"Kinetic friction: f_k = μ_k F_n = ({mu:.2f})({fn:.1f}) = {fk:.1f} N.\n\n"
            + "Cart, horizontal: T - f_k = m_cart a.\n"
            + "Hanging mass: m_h g - T = m_h a.\n\n"
            + "Add the two equations. The tension cancels because it is internal to the two-object system:\n"
            + "m_h g - f_k = (m_cart + m_h)a.\n\n"
            + f"a = ({drive:.1f} - {fk:.1f})/({m_cart:.1f} + {m_hang:.1f}) = {a:.2f} m/s².\n"
            + f"T = m_cart a + f_k = ({m_cart:.1f})({a:.2f}) + {fk:.1f} = {T:.1f} N.\n"
            + "\n**Kinematics from rest**\n"
            + f"v({tmax:.1f} s) = at = ({a:.2f})({tmax:.1f}) = {v:.2f} m/s.\n"
            + f"x({tmax:.1f} s) = 1/2 at² = 0.5({a:.2f})({tmax:.1f})² = {x:.2f} m.\n"
            + "\n**Motion functions**\n"
            + f"x(t) = {0.5*a:.3f} t²,    v(t) = {a:.3f} t,    0 ≤ t ≤ {tmax:.1f} s.\n"
            + "\n**Plot data**\n"
            + f"```text\n{plot_text}\n```\n"
            + _v47_graph_choice_menu(a, tmax, 0.0, 0.0)
            + _v47_followup_question('Why is the tension smaller than the weight of the hanging mass?'))

_v49_tutor_reply_previous = _v49_tutor_reply

def _v49_tutor_reply(message: str, mode: str, last_assistant: str = '') -> str:
    low = str(message or '').lower()
    current_problem = _v49_last_student_problem() if ('current problem' in low or str(mode or '').lower() == 'full') else ''
    problem_text = current_problem or message
    if _v49_is_pulley_cart_hanging_problem(problem_text) and (_v49_prompt_requests_complete_workflow(problem_text) or str(mode or '').lower() == 'full'):
        return _v49_direct_pulley_full_solution(problem_text)
    return _v49_tutor_reply_previous(message, mode, last_assistant)

