_v49_tutor_reply_before_state_machine = _v49_tutor_reply

def _v49_tutor_reply(message: str, mode: str, last_assistant: str = '') -> str:
    raw = str(message or '')
    low = raw.lower().strip()
    # Graph action route: generate the requested graph, but do not replace the current physics problem.
    if low.startswith('v48_graph_context') or low.startswith('v47_graph_context'):
        graph_cmd = raw.replace('V48_GRAPH_CONTEXT', 'V47_GRAPH_CONTEXT').replace('v48_graph_context', 'V47_GRAPH_CONTEXT')
        reply = _v47_graph_context_reply(graph_cmd)
        if reply:
            return str(reply).replace('/physics-ai-chat-v47/form','/v49-student-ask/form').replace('/physics-ai-chat-v49/form','/v49-student-ask/form').replace('V47_GRAPH_CONTEXT','GRAPH_CONTEXT')
    # Full/hint/check current-problem requests must point back to the last real problem.
    if 'current problem' in low or str(mode or '').lower() in {'full', 'hint'}:
        current_problem = _v49_last_student_problem()
        if current_problem:
            if str(mode or '').lower() == 'full' or low.startswith('full solution'):
                if _v49_is_pulley_cart_hanging_problem(current_problem):
                    return _v49_direct_pulley_full_solution(current_problem)
                return _v48_reply(current_problem)
            if str(mode or '').lower() == 'hint' or low.startswith('give me one hint'):
                return _v49_hint_reply(current_problem)
    return _v49_tutor_reply_before_state_machine(raw, mode, last_assistant)




