def _v47_graph_choice_menu(a: float, tmax: float, xi: float = 0.0, vi: float = 0.0) -> str:
    def hidden(kind: str) -> str:
        return f'GRAPH_CONTEXT kind={kind} a={a:.6g} tmax={tmax:.6g} xi={xi:.6g} vi={vi:.6g}'
    items = [
        ('position', 'Show position versus time'),
        ('velocity', 'Show velocity versus time'),
        ('acceleration', 'Show acceleration versus time'),
        ('all', 'Show all motion graphs'),
    ]
    forms = []
    for kind, label in items:
        forms.append(
            '<form method="post" action="/v49-student-ask/form" style="display:inline-block;margin:0.25rem;">'
            f'<input type="hidden" name="message" value="{h(hidden(kind))}">'
            f'<button type="submit" class="secondary">{h(label)}</button>'
            '</form>'
        )
    return (
        '\n<div class="v49-graph-menu" style="max-width:780px;border:1px solid #d0d7de;border-radius:12px;padding:12px;margin:0.75rem 0;background:#f6f8fa;">'
        '<strong>Graph menu for this motion model</strong>'
        '<p style="margin:0.35rem 0;">Choose a graph. This stays inside the active Student View.</p>'
        + ''.join(forms) +
        '</div>\n'
    )

_v49_tutor_reply_before_transcript_cleanup = _v49_tutor_reply

def _v49_tutor_reply(message: str, mode: str, last_assistant: str = '') -> str:
    raw = str(message or '')
    low = raw.lower().strip()
    # Graph action route: graph commands are UI actions, not physics problems.
    if low.startswith('graph_context') or low.startswith('v48_graph_context') or low.startswith('v47_graph_context'):
        graph_cmd = (raw
            .replace('GRAPH_CONTEXT', 'V47_GRAPH_CONTEXT')
            .replace('graph_context', 'V47_GRAPH_CONTEXT')
            .replace('V48_GRAPH_CONTEXT', 'V47_GRAPH_CONTEXT')
            .replace('v48_graph_context', 'V47_GRAPH_CONTEXT'))
        reply = _v47_graph_context_reply(graph_cmd)
        if reply:
            return str(reply).replace('/physics-ai-chat-v47/form','/v49-student-ask/form').replace('/physics-ai-chat-v49/form','/v49-student-ask/form').replace('V47_GRAPH_CONTEXT','GRAPH_CONTEXT').replace('V48_GRAPH_CONTEXT','GRAPH_CONTEXT')
    if 'current problem' in low or str(mode or '').lower() in {'full', 'hint'}:
        current_problem = _v49_last_student_problem()
        if current_problem:
            if str(mode or '').lower() == 'full' or low.startswith('full solution'):
                if _v49_is_pulley_cart_hanging_problem(current_problem):
                    return _v49_direct_pulley_full_solution(current_problem)
                return _v48_reply(current_problem)
            if str(mode or '').lower() == 'hint' or low.startswith('give me one hint'):
                return _v49_hint_reply(current_problem)
    reply = _v49_tutor_reply_before_transcript_cleanup(raw, mode, last_assistant)
    return str(reply).replace('V47_GRAPH_CONTEXT','GRAPH_CONTEXT').replace('V48_GRAPH_CONTEXT','GRAPH_CONTEXT')


# -----------------------------------------------------------------------------
# v49 expanded student-selection menu + clean inclined-plane FBD patch.
# This patch keeps the selections as learning-diagnostic data and separates
# inclined-plane visuals into a force FBD and a weight-component diagram.
# -----------------------------------------------------------------------------
def _v49_tag_triage_card(message: str, tags: Any) -> str:
    keys = _v49_normalize_tags(tags)
    if not keys:
        return ''
    labels = _v49_tag_labels()
    summary = ', '.join(labels[k] for k in keys)
    text = str(message or '')
    low = text.lower()

    correct = []
    incorrect = []
    conflicts = []
    support = []
    diagnostic = []

    support_keys = {'i_am_lost', 'need_basics', 'go_step_by_step', 'need_hint', 'check_my_work', 'show_full_solution'}
    for k in keys:
        if k in support_keys:
            support.append(labels[k])

    incline_problem = any(w in low for w in ['incline', 'inclined plane', 'ramp'])
    has_mu = ('μ' in text or 'mu' in low or 'coefficient of kinetic friction' in low or 'coefficient of static friction' in low)
    has_motion_from_rest = ('starts from rest' in low or 'released from rest' in low)
    has_tension = ('tension' in low or 'rope' in low or 'string' in low)
    has_pulley_text = 'pulley' in low
    has_two_body_text = any(w in low for w in ['two-body', 'two body', 'hanging mass', 'connected by'])
    has_circle_text = any(w in low for w in ['circle', 'circular', 'centripetal', 'orbit'])
    has_projectile_text = any(w in low for w in ['projectile', 'launched', 'thrown', 'horizontal range'])

    def add_correct(key, reason):
        if key in keys:
            correct.append(f'{labels[key]} — {reason}')
    def add_incorrect(key, reason):
        if key in keys:
            incorrect.append(f'{labels[key]} — {reason}')

    if incline_problem:
        add_correct('inclined_plane', 'the object is on an incline/ramp.')
        add_correct('rotated_axes', 'the natural axes are along and perpendicular to the ramp.')
        add_correct('constant_acceleration', 'the force model gives a constant acceleration along the ramp.')
        add_correct('fbd', 'the problem explicitly asks for a free-body diagram.')
        add_correct('find_acceleration', 'the problem asks for acceleration.')
        add_correct('find_velocity', 'the problem asks for velocity.')
        add_correct('find_position', 'the problem asks for displacement/position.')
        add_correct('graph', 'the problem asks for graphs.')
        add_correct('find_normal_force', 'normal force is needed on an incline.')
        if has_mu:
            add_correct('friction', 'the problem gives a friction coefficient.')
            add_correct('kinetic_friction', 'the problem gives kinetic friction, μ_k.')
            add_correct('find_friction', 'friction must be found from μ_k F_n.')
        if has_tension:
            add_correct('find_tension', 'tension is given or part of the force model.')

        add_incorrect('constant_velocity', 'No — this is accelerated motion. The speed is changing because the net force along the incline is not zero.')
        add_incorrect('no_friction', 'No — the problem gives a friction coefficient, so friction is present.')
        add_incorrect('horizontal_surface', 'No — the surface is inclined, not horizontal.')
        add_incorrect('pulley', 'No — there is a rope, but no pulley system is described.')
        add_incorrect('two_body_system', 'No — this is one object on an incline, not two connected bodies.')
        add_incorrect('equilibrium', 'No — the object moves with acceleration; equilibrium would require net force zero.')
        add_incorrect('circular_motion', 'No — the path is along a ramp, not circular.')
        add_incorrect('momentum', 'Not the main guide here — this problem asks for Newton’s laws, FBD, and kinematics, not impulse/momentum.')
        add_incorrect('work_energy', 'Not the primary guide for this prompt — it asks for force equations and acceleration. Work-energy could be a check, but not the requested pathway.')
        add_incorrect('spring_force', 'No spring is described.')
        add_incorrect('torque', 'No rotation or lever arm is described.')
        add_incorrect('projectile_motion', 'No — the object stays on the incline, not in projectile flight.')

    # General conflict detection that applies to any problem family.
    if 'friction' in keys and 'no_friction' in keys:
        conflicts.append('You selected both friction and no friction. Those cannot both describe the same contact surface in one model.')
    if 'constant_velocity' in keys and 'constant_acceleration' in keys:
        conflicts.append('You selected both constant velocity and constant acceleration. Constant velocity means acceleration is zero; constant acceleration may be nonzero.')
    if 'no_friction' in keys and has_mu:
        conflicts.append('You selected no friction, but the written problem gives a friction coefficient. I will use the written problem and include friction.')
    if 'horizontal_surface' in keys and 'inclined_plane' in keys:
        conflicts.append('You selected both horizontal surface and inclined plane. I will use the geometry stated in the problem.')

    if support:
        if any(k in keys for k in ['i_am_lost', 'need_basics']):
            diagnostic.append('You asked for basic support. I will slow down and begin with objects, forces, axes, and the meaning of acceleration before solving.')
        if 'go_step_by_step' in keys:
            diagnostic.append('You asked to go step by step. I will use checkpoints instead of jumping directly to the answer.')
        if 'need_hint' in keys:
            diagnostic.append('You asked for a hint. I will give the smallest useful next step first.')

    if any(k in keys for k in ['normal_equals_weight_misconception','tension_is_net_force_misconception']):
        diagnostic.append('You selected a possible misconception. I will explicitly address that idea instead of silently correcting it.')

    details = ''
    if support:
        details += '<p><strong>Support request:</strong></p><ul>' + ''.join(f'<li>{h(x)}</li>' for x in support) + '</ul>'
    if correct:
        details += '<p><strong>Correct/useful guides:</strong></p><ul>' + ''.join(f'<li>{h(x)}</li>' for x in correct) + '</ul>'
    if incorrect:
        details += '<p><strong>Incorrect or non-matching guides:</strong></p><ul>' + ''.join(f'<li>{h(x)}</li>' for x in incorrect) + '</ul>'
    if conflicts:
        details += '<p><strong>Conflicting guides:</strong></p><ul>' + ''.join(f'<li>{h(c)}</li>' for c in conflicts) + '</ul>'
    if diagnostic:
        details += '<p><strong>Tutoring response:</strong></p><ul>' + ''.join(f'<li>{h(d)}</li>' for d in diagnostic) + '</ul>'

    return (
        '<div class="v49-tag-card" style="border:1px solid #d0d7de;border-radius:12px;padding:12px;margin:0.75rem 0;background:#f6f8fa;">'
        '<h3 style="margin:0 0 0.35rem 0;">Reading and comprehension check</h3>'
        f'<p><strong>Student selected:</strong> {h(summary)}</p>'
        '<p>I will use these selections as diagnostic data about your first understanding of the problem. The written problem has priority when a selected item does not match the text.</p>'
        + details +
        '</div>'
    )

def _v49_selected_tags_comment(tags: Any) -> str:
    keys = _v49_normalize_tags(tags)
    if not keys:
        return ''
    return 'Selected reading and comprehension selections: ' + _v49_tag_summary(keys) + '.'

def _v48_incline_fbd_svg(object_label: str, theta: float, m: float, mg: float, fn: float, fk: float, mgsin: float, mgcos: float, tension: float = 0.0, motion_up: bool = False) -> str:
    import math
    th = math.radians(theta)
    cx, cy = 360.0, 250.0
    ux, uy = math.cos(th), -math.sin(th)          # up ramp
    dx, dy = -ux, -uy                             # down ramp
    nx, ny = -math.sin(th), -math.cos(th)         # outward normal
    ix, iy = -nx, -ny                             # into surface
    sx, sy = (ux, uy) if motion_up else (dx, dy)
    frx, fry = (dx, dy) if motion_up else (ux, uy)
    friction_label = 'f_k down ramp' if motion_up else 'f_k up ramp'
    tension_arrow = ''
    if tension and tension > 0:
        tension_arrow = _v48_svg_arrow(cx, cy, cx + ux*105, cy + uy*105, 'T', 16, -10)
    return f"""
<div class="v47-fbd-figure" style="max-width:900px;border:1px solid #d0d7de;border-radius:12px;padding:12px;margin:0.75rem 0;background:#fff;">
  <h3 style="margin:0 0 0.4rem 0;">Inclined plane: clean force diagram and component diagram</h3>
  <p style="margin:0 0 0.6rem 0;"><strong>Teaching layout:</strong> the first figure shows only real forces; the second figure shows the components of weight. This avoids crowding.</p>
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:12px;align-items:start;">
    <svg viewBox="0 0 520 360" width="100%" role="img" aria-label="Clean inclined plane free-body diagram with real forces only">
      <defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth"><path d="M0,0 L0,6 L9,3 z" fill="currentColor"/></marker></defs>
      <rect x="0" y="0" width="520" height="360" rx="10" fill="#ffffff"/>
      <text x="20" y="28" font-size="16" font-weight="700">1. Real forces on the {h(object_label)}</text>
      <line x1="70" y1="295" x2="470" y2="150" stroke="currentColor" stroke-width="4"/>
      <line x1="70" y1="295" x2="470" y2="295" stroke="currentColor" stroke-width="1.2" opacity="0.45"/>
      <path d="M 100 295 A 45 45 0 0 0 142 278" fill="none" stroke="currentColor" stroke-width="1.4"/>
      <text x="112" y="286" font-size="13">θ = {theta:.1f}°</text>
      <g transform="translate({cx:.1f},{cy:.1f}) rotate({-theta:.1f})">
        <rect x="-42" y="-22" width="84" height="44" rx="6" fill="#eef2ff" stroke="currentColor" stroke-width="2"/>
        <text x="0" y="5" text-anchor="middle" font-size="13" font-weight="700">{h(object_label)}</text>
      </g>
      {_v48_svg_arrow(cx, cy, cx + sx*95, cy + sy*95, '+s', 8, -10)}
      {_v48_svg_arrow(cx, cy, cx + nx*85, cy + ny*85, '+n', -24, -8)}
      {_v48_svg_arrow(cx, cy, cx, cy + 95, 'mg', 12, 6)}
      {_v48_svg_arrow(cx, cy, cx + nx*92, cy + ny*92, 'F_n', -44, -16)}
      {tension_arrow}
      {_v48_svg_arrow(cx, cy, cx + frx*78, cy + fry*78, friction_label, -70, 20)}
    </svg>
    <svg viewBox="0 0 520 360" width="100%" role="img" aria-label="Weight component diagram for an inclined plane">
      <defs><marker id="arrow2" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth"><path d="M0,0 L0,6 L9,3 z" fill="currentColor"/></marker></defs>
      <rect x="0" y="0" width="520" height="360" rx="10" fill="#ffffff"/>
      <text x="20" y="28" font-size="16" font-weight="700">2. Components of weight</text>
      <line x1="70" y1="295" x2="470" y2="150" stroke="currentColor" stroke-width="4"/>
      <g transform="translate({cx:.1f},{cy:.1f}) rotate({-theta:.1f})">
        <rect x="-42" y="-22" width="84" height="44" rx="6" fill="#fff7ed" stroke="currentColor" stroke-width="2"/>
      </g>
      {_v48_svg_arrow(cx, cy, cx, cy + 105, 'mg', 10, 8)}
      {_v48_svg_arrow(cx, cy, cx + dx*102, cy + dy*102, 'mg sinθ', -82, 18, dashed=True)}
      {_v48_svg_arrow(cx, cy, cx + ix*92, cy + iy*92, 'mg cosθ', 12, 25, dashed=True)}
      {_v48_svg_arrow(cx+120, cy-70, cx+120 + ux*68, cy-70 + uy*68, '+s', 8, -5)}
      {_v48_svg_arrow(cx+120, cy-70, cx+120 + nx*68, cy-70 + ny*68, '+n', -24, -7)}
    </svg>
  </div>
  <p><strong>FBD rule:</strong> <em>mg</em>, <em>F_n</em>, <em>T</em>, and <em>f_k</em> are forces. <em>mg sinθ</em> and <em>mg cosθ</em> are components of <em>mg</em>, not additional forces.</p>
  <p><strong>Numerical values:</strong> mg = {mg:.1f} N, F_n = {fn:.1f} N, f_k = {fk:.1f} N, mg sinθ = {mgsin:.1f} N, mg cosθ = {mgcos:.1f} N. Values are listed here instead of crowding the arrows.</p>
  <p><strong>Sign convention:</strong> {'positive s is up the incline because the rope pulls the object up the incline.' if motion_up else 'positive s is down the incline because the object slides down the incline.'}</p>
</div>
"""

# -----------------------------------------------------------------------------
# v49 replacement patch: explicit guide-by-guide diagnostics + force-to-a fix.
# Directory name remains Physics_Assistant_AI_v49_TUTORING_MODE_ENGINE.
# -----------------------------------------------------------------------------
def _v49_problem_features_for_guides(message: str) -> Dict[str, bool]:
    text = str(message or '')
    low = text.lower()
    frictionless = any(w in low for w in ['frictionless', 'no friction', 'without friction'])
    has_mu_k = ('μ_k' in text or 'μk' in text or 'mu_k' in low or 'coefficient of kinetic friction' in low)
    has_mu_s = ('μ_s' in text or 'μs' in text or 'mu_s' in low or 'coefficient of static friction' in low)
    horizontal = any(w in low for w in ['horizontal floor', 'horizontal surface', 'level floor', 'level surface', 'table']) and not any(w in low for w in ['incline', 'inclined', 'ramp'])
    incline = any(w in low for w in ['incline', 'inclined plane', 'ramp'])
    constant_force = 'constant force' in low or 'pushed' in low or 'pull' in low or 'tension' in low or 'force of' in low
    starts_rest = 'starts from rest' in low or 'released from rest' in low
    graph = any(w in low for w in ['plot', 'graph', 'versus time'])
    asks_accel = 'acceleration' in low or 'accelerate' in low
    asks_velocity = 'velocity' in low or 'speed' in low
    asks_position = 'position' in low or 'displacement' in low or 'distance' in low
    pulley = 'pulley' in low
    two_body = any(w in low for w in ['two-body', 'two body', 'hanging mass', 'connected by'])
    circular = any(w in low for w in ['circular', 'circle', 'centripetal', 'orbit'])
    projectile = any(w in low for w in ['projectile', 'launched', 'thrown', 'range'])
    equilibrium = any(w in low for w in ['equilibrium', 'constant velocity', 'at rest']) and not constant_force
    net_force_nonzero = constant_force and not equilibrium
    constant_accel = (constant_force or incline or has_mu_k or frictionless) and (asks_accel or asks_velocity or asks_position or graph or starts_rest)
    constant_velocity = False
    kinetic_friction = has_mu_k and not frictionless
    no_friction = frictionless
    return {
        'frictionless': frictionless, 'has_mu_k': has_mu_k, 'has_mu_s': has_mu_s,
        'horizontal': horizontal, 'incline': incline, 'constant_force': constant_force,
        'starts_rest': starts_rest, 'graph': graph, 'asks_accel': asks_accel,
        'asks_velocity': asks_velocity, 'asks_position': asks_position, 'pulley': pulley,
        'two_body': two_body, 'circular': circular, 'projectile': projectile,
        'equilibrium': equilibrium, 'net_force_nonzero': net_force_nonzero,
        'constant_accel': constant_accel, 'constant_velocity': constant_velocity,
        'kinetic_friction': kinetic_friction, 'no_friction': no_friction,
        'friction_present': (has_mu_k or has_mu_s) and not frictionless,
    }


def _v49_tag_triage_card(message: str, tags: Any) -> str:
    keys = _v49_normalize_tags(tags)
    if not keys:
        return ''
    labels = _v49_tag_labels()
    summary = ', '.join(labels[k] for k in keys)
    f = _v49_problem_features_for_guides(message)
    support_keys = {'i_am_lost', 'need_basics', 'go_step_by_step', 'need_hint', 'check_my_work', 'show_full_solution'}

    yes_no = []
    support = []
    missing = []

    def yn(key: str, ok: bool, reason: str):
        if key in keys:
            verdict = 'YES' if ok else 'NO'
            yes_no.append(f'{labels[key]}: {verdict}. {reason}')

    for k in keys:
        if k in support_keys:
            support.append(f'{labels[k]}: SUPPORT REQUEST. I will adjust the tutoring pace rather than treating this as a physics model.')

    yn('constant_velocity', f['constant_velocity'], 'The velocity would have to stay unchanged. In this problem the force model makes the velocity change.' if not f['constant_velocity'] else 'The net force is zero, so acceleration is zero and velocity is constant.')
    yn('constant_acceleration', f['constant_accel'], 'The applied force, mass, and contact model are constant, so the net force and acceleration are constant.' if f['constant_accel'] else 'The problem statement does not establish one constant acceleration model.')
    yn('kinetic_friction', f['kinetic_friction'], 'The problem gives μ_k, so sliding/kinetic friction is part of the model.' if f['kinetic_friction'] else 'The problem says the surface is frictionless or gives no kinetic-friction coefficient, so kinetic friction is not present.')
    yn('no_friction', f['no_friction'], 'The problem says the surface is frictionless.' if f['no_friction'] else 'The problem includes friction information, so no-friction is not the correct model.')
    yn('friction', f['friction_present'], 'A friction coefficient or friction force is described.' if f['friction_present'] else 'The problem says frictionless or gives no friction information.')
    yn('horizontal_surface', f['horizontal'], 'The object moves on a horizontal/level surface.' if f['horizontal'] else 'The geometry is not horizontal, or it is an incline/ramp.')
    yn('inclined_plane', f['incline'], 'The object is on a ramp/incline.' if f['incline'] else 'No inclined plane or ramp is described.')
    yn('rotated_axes', f['incline'], 'Rotated axes are useful because one axis should lie along the incline.' if f['incline'] else 'Rotated axes are not needed for a simple horizontal-surface problem.')
    yn('pulley', f['pulley'], 'A pulley is explicitly described.' if f['pulley'] else 'No pulley is described.')
    yn('two_body_system', f['two_body'], 'Two connected bodies are described.' if f['two_body'] else 'Only one moving object is described.')
    yn('equilibrium', f['equilibrium'], 'The problem states rest/constant velocity with zero net force.' if f['equilibrium'] else 'The problem asks for acceleration or motion from a nonzero force, so net force is not zero.')
    yn('circular_motion', f['circular'], 'The path is circular/centripetal.' if f['circular'] else 'No circular path is described.')
    yn('projectile_motion', f['projectile'], 'The object is launched/thrown and moves through the air.' if f['projectile'] else 'The object remains on a surface; it is not projectile motion.')
    yn('fbd', any([f['constant_force'], f['incline'], f['friction_present'], f['pulley']]), 'Forces must be identified before applying Newton’s second law.' if any([f['constant_force'], f['incline'], f['friction_present'], f['pulley']]) else 'The prompt does not require a force diagram.')
    yn('graph', f['graph'], 'The problem asks for a plot/graph.' if f['graph'] else 'The problem does not ask for a graph.')
    yn('find_acceleration', f['asks_accel'] or f['constant_force'], 'Acceleration follows from a = F_net/m.' if (f['asks_accel'] or f['constant_force']) else 'Acceleration is not requested or needed.')
    yn('find_velocity', f['asks_velocity'], 'Velocity is requested.' if f['asks_velocity'] else 'Velocity is not requested.')
    yn('find_position', f['asks_position'], 'Position/displacement is requested.' if f['asks_position'] else 'Position/displacement is not requested.')
    yn('find_friction', f['friction_present'], 'Friction must be calculated from the friction model.' if f['friction_present'] else 'There is no friction force to calculate.')
    yn('find_normal_force', f['incline'] or f['friction_present'], 'Normal force is needed for contact-force analysis.' if (f['incline'] or f['friction_present']) else 'For this simple frictionless horizontal problem, normal force is not needed to find the requested motion.')

    if 'constant_velocity' in keys and 'constant_acceleration' in keys:
        missing.append('You selected two incompatible motion descriptions. I graded each one separately above: constant velocity is NO when speed changes; constant acceleration is YES when acceleration is steady.')
    if 'kinetic_friction' in keys and f['frictionless']:
        missing.append('Important correction: frictionless means f_k = 0. Do not include kinetic friction in the force equation.')
    if 'constant_acceleration' in keys and f['constant_accel']:
        missing.append('Use clear language: acceleration is constant here, not “may be nonzero.” The velocity changes at a steady rate.')

    details = ''
    if support:
        details += '<p><strong>Support request:</strong></p><ul>' + ''.join(f'<li>{h(x)}</li>' for x in support) + '</ul>'
    if yes_no:
        details += '<p><strong>Reading-comprehension check:</strong></p><ul>' + ''.join(f'<li>{h(x)}</li>' for x in yes_no) + '</ul>'
    if missing:
        details += '<p><strong>Diagnostic teaching note:</strong></p><ul>' + ''.join(f'<li>{h(x)}</li>' for x in missing) + '</ul>'

    return (
        '<div class="v49-tag-card" style="border:1px solid #d0d7de;border-radius:12px;padding:12px;margin:0.75rem 0;background:#f6f8fa;">'
        '<h3 style="margin:0 0 0.35rem 0;">Reading and comprehension check</h3>'
        f'<p><strong>Student selected:</strong> {h(summary)}</p>'
        '<p>These selections record what the student thinks the problem contains. I now grade each selected item against the written problem. The written problem has priority.</p>'
        + details +
        '</div>'
    )


_v47_combined_kinematics_dynamics_reply_before_forcefix = _v47_combined_kinematics_dynamics_reply

def _v49_parse_first_number_before_unit(text: str, unit_pattern: str):
    m = re.search(r'([-+]?\d*\.?\d+)\s*' + unit_pattern, str(text or ''), re.I)
    return float(m.group(1)) if m else None


def _v47_combined_kinematics_dynamics_reply(message: str) -> str:
    """Replacement guard for simple horizontal force problems.

    This prevents the tutor from treating a given force in N as an acceleration
    in m/s^2.  If mass and applied/net force are given, acceleration is computed
    from a = F_net/m.
    """
    text = str(message or '')
    low = text.lower()
    simple_horizontal_force = (
        any(w in low for w in ['frictionless horizontal', 'frictionless floor', 'frictionless horizontal floor', 'horizontal floor'])
        and ('force' in low or 'pushed' in low or 'pull' in low)
        and ('kg' in low)
        and (' n' in low or 'newton' in low)
        and any(w in low for w in ['position', 'velocity', 'plot', 'graph', 'acceleration'])
    )
    if simple_horizontal_force:
        m = _v49_parse_first_number_before_unit(text, r'kg')
        # Prefer a number attached to N/newton as the force.
        F = _v49_parse_first_number_before_unit(text, r'(?:N|newtons?|newton)\b')
        tmatches = re.findall(r'after\s+([-+]?\d*\.?\d+)\s*s|from\s+0\s+to\s+([-+]?\d*\.?\d+)\s*s', text, re.I)
        tvals = [float(a or b) for a, b in tmatches if (a or b)]
        tmax = tvals[0] if tvals else 3.0
        if m and F is not None:
            a = F / m
            vf = a * tmax
            xf = 0.5 * a * tmax * tmax
            return (_v47_clean_header('combined calculation/graph', 'Newton second law + constant-acceleration kinematics', 'acceleration, v(t), and x(t)', 'a = F_net/m; v(t)=v_i+at; x(t)=x_i+v_i t+1/2 a t²', 'The problem gives force, not acceleration. Newton’s second law first gives acceleration; then kinematics predicts the motion.') +
                f"\n\nStep 1 - identify the force model:\nThe surface is frictionless, so f_k = 0. The net horizontal force is F_net = {_fmt_student_num(F)} N.\n" +
                f"\nStep 2 - dynamics:\na = F_net/m = ({_fmt_student_num(F)} N)/({_fmt_num(m)} kg) = {_fmt_num(a)} m/s².\n" +
                f"\nStep 3 - kinematics from rest:\nv(t) = at = {_fmt_num(a)}t.\n" +
                f"x(t) = 1/2 at² = {_fmt_num(0.5*a)}t².\n" +
                f"\nAt t = {_fmt_num(tmax)} s:\nv = {_fmt_num(vf)} m/s.\nx = {_fmt_num(xf)} m.\n" +
                _v47_position_time_svg(a, tmax, 0.0, 0.0) +
                _v47_graph_choice_menu(a, tmax, 0.0, 0.0) +
                _v47_followup_question('Why is the acceleration 3.0 m/s² rather than 12 m/s² in this problem?'))
    return _v47_combined_kinematics_dynamics_reply_before_forcefix(message)

# -----------------------------------------------------------------------------
# v49 replacement patch 2026-07-02: Branch 1 guide tags must be diagnostic only.
# Directory name remains Physics_Assistant_AI_v49_TUTORING_MODE_ENGINE.
# Fixes:
#   1) selected wrong tags no longer reclassify the written problem as pulley/etc.
#   2) current-problem full solution strips visible Selected reading and comprehension selections lines.
#   3) frictionless horizontal FBD suppresses friction and static/kinetic friction.
#   4) every selected reading-comprehension item is graded individually where possible.
# -----------------------------------------------------------------------------
def _v49_strip_diagnostic_hint_lines(text: str) -> str:
    raw = str(text or '')
    cleaned = []
    for line in raw.splitlines():
        s = line.strip().lower()
        if s.startswith('selected reading and comprehension selections:'):
            continue
        if s.startswith('student-selected reading and comprehension selections:'):
            continue
        cleaned.append(line)
    return '\n'.join(cleaned).strip()


def _v49_augment_problem_with_tags(message: str, tags: Any) -> str:
    """Do not append guide tags to the solving/classification prompt.

    Tags are diagnostic student data. They belong in the triage card and visible
    transcript only.  They must not alter the physics family selected from the
    written problem; otherwise a wrong selected tag such as pulley can route a
    frictionless one-box problem into the pulley solver.
    """
    return _v49_strip_diagnostic_hint_lines(message)


def _v49_last_student_problem() -> str:
    try:
        ensure_independent_physics_chat_table()
        with connect() as conn:
            row = conn.execute("SELECT message FROM independent_physics_ai_chat_messages WHERE role='student' AND message NOT LIKE 'Full solution for the current problem%' AND message NOT LIKE 'Give me one hint for the current problem%' ORDER BY id DESC LIMIT 1").fetchone()
        return _v49_strip_diagnostic_hint_lines(row[0]) if row else ''
    except Exception:
        return ''


def _v49_is_simple_frictionless_horizontal_force_problem(message: str) -> bool:
    text = str(message or '')
    low = text.lower()
    return (
        ('frictionless' in low or 'no friction' in low or 'without friction' in low)
        and ('horizontal' in low or 'floor' in low or 'surface' in low)
        and ('force' in low or 'pushed' in low or 'push' in low or 'pull' in low)
        and ('kg' in low)
        and (' n' in low or 'newton' in low)
    )


