def _v49_full_solution_simple_frictionless_horizontal(message: str) -> str:
    text = _v49_strip_diagnostic_hint_lines(message)
    m = _v49_parse_first_number_before_unit(text, r'kg')
    F = _v49_parse_first_number_before_unit(text, r'(?:N|newtons?|newton)\b')
    tmatches = re.findall(r'after\s+([-+]?\d*\.?\d+)\s*s|from\s+0\s+to\s+([-+]?\d*\.?\d+)\s*s', text, re.I)
    tvals = [float(a or b) for a, b in tmatches if (a or b)]
    tmax = tvals[0] if tvals else 3.0
    if not m or F is None:
        return _v48_reply(text)
    a = F / m
    vf = a * tmax
    xf = 0.5 * a * tmax * tmax
    return (_v47_clean_header('combined calculation/graph', 'frictionless horizontal Newton-law motion', 'a, v(t), x(t)', 'a = F_net/m; v(t)=v_i+at; x(t)=x_i+v_i t+1/2 a t²', 'The written problem says frictionless, so friction is absent. The applied force is the horizontal net force.') +
        _v49_horizontal_frictionless_fbd_svg() +
        f"\nGuide correction built into the model: frictionless surface means f_k = 0 and f_s = 0 for this calculation. Do not include a friction arrow.\n" +
        f"\nStep 1 - force model:\nF_net = F_push = {_fmt_student_num(F)} N.\n" +
        f"\nStep 2 - Newton's second law:\na = F_net/m = ({_fmt_student_num(F)} N)/({_fmt_num(m)} kg) = {_fmt_num(a)} m/s².\n" +
        f"\nStep 3 - constant-acceleration kinematics from rest:\nv(t) = at = {_fmt_num(a)}t.\n" +
        f"x(t) = 1/2 at² = {_fmt_num(0.5*a)}t².\n" +
        f"\nAt t = {_fmt_num(tmax)} s:\nv = {_fmt_num(vf)} m/s.\nx = {_fmt_num(xf)} m.\n" +
        _v47_position_time_svg(a, tmax, 0.0, 0.0) +
        _v47_graph_choice_menu(a, tmax, 0.0, 0.0) +
        _v47_followup_question('Which force is responsible for the acceleration if the surface is frictionless?'))


# Preserve the previous final tutor dispatcher, then put a stronger guard on top.
_v49_tutor_reply_before_branch1_tag_isolation = _v49_tutor_reply

def _v49_tutor_reply(message: str, mode: str, last_assistant: str = '') -> str:
    raw = _v49_strip_diagnostic_hint_lines(message)
    low = raw.lower().strip()
    mode_low = str(mode or '').lower()

    # Current-problem controls must solve the last real written problem, not the
    # student's reading-comprehension selection sentence.
    if 'current problem' in low or mode_low in {'full', 'hint'}:
        current_problem = _v49_last_student_problem()
        if current_problem:
            if mode_low == 'full' or low.startswith('full solution'):
                if _v49_is_simple_frictionless_horizontal_force_problem(current_problem):
                    return _v49_full_solution_simple_frictionless_horizontal(current_problem)
                if _v49_is_pulley_cart_hanging_problem(current_problem):
                    return _v49_direct_pulley_full_solution(current_problem)
                return _v48_reply(current_problem)
            if mode_low == 'hint' or low.startswith('give me one hint'):
                return _v49_hint_reply(current_problem)

    # Explicit complete-workflow or Full Solution on a simple frictionless push.
    if _v49_is_simple_frictionless_horizontal_force_problem(raw) and (mode_low == 'full' or _v49_prompt_requests_complete_workflow(raw) or any(w in low for w in ['find the acceleration', 'velocity after', 'position after', 'plot'])):
        return _v49_full_solution_simple_frictionless_horizontal(raw)

    # For guided mode, classify from the written problem only; never from tags.
    return _v49_tutor_reply_before_branch1_tag_isolation(raw, mode, last_assistant)



# v49 replacement patch 2026-07-02: parsed-model-first guide diagnostics.
# Rule: the written problem is parsed into an internal model first. Student-selected
# optional guides are then compared against that model one by one. Student-facing
# tutor output should only grade guides the student actually selected; it should
# not list every possible NO category such as torque/circular/projectile unless
# the student selected those guides. Developer diagnostics may be more complete.

# Strengthen final guide card so common wrong selections are always marked.
_v49_tag_triage_card_before_branch1_tag_isolation = _v49_tag_triage_card

def _v49_tag_triage_card(message: str, tags: Any) -> str:
    keys = _v49_normalize_tags(tags)
    if not keys:
        return ''
    labels = _v49_tag_labels()
    f = _v49_problem_features_for_guides(message)
    # Use the already improved card as base, but this replacement explicitly
    # grades static friction, spring force, and starts-from-rest because those
    # appeared in Branch 1 testing.
    base = _v49_tag_triage_card_before_branch1_tag_isolation(message, tags)
    extra = []
    def extra_yn(key: str, ok: bool, reason_yes: str, reason_no: str):
        if key in keys:
            extra.append(f'{labels[key]}: {"YES" if ok else "NO"}. {reason_yes if ok else reason_no}')
    extra_yn('static_friction', f['has_mu_s'] and not f['frictionless'], 'The problem gives a static-friction coefficient or asks about impending motion.', 'The written problem says frictionless or does not give static friction; static friction is not part of this model.')
    extra_yn('spring_force', 'spring' in str(message or '').lower(), 'A spring is explicitly described.', 'No spring is described in the written problem.')
    extra_yn('starts_from_rest', f['starts_rest'], 'The problem states that the object starts from rest.', 'The written problem does not state starts from rest.')
    if not extra:
        return base
    insert = '<p><strong>Additional reading-comprehension checks:</strong></p><ul>' + ''.join(f'<li>{h(x)}</li>' for x in extra) + '</ul>'
    return base.replace('</div>', insert + '</div>', 1)


