def _v57_active_problem_banner(source_channel: str = 'Student AI Chat') -> str:
    source = h(str(source_channel or 'Student AI Chat'))
    return ('<div class="v57-active-banner" style="border:2px solid #198754;border-radius:12px;padding:10px;margin:0.75rem 0;background:#effaf3;">'
            f'<strong>Current Active Problem updated from {source}.</strong><br>'
            'Show Full Solution, Plot, RC grading, and all learning modes will now use this exact problem.</div>')

def _v57_active_problem_using_banner(source_channel: str = '') -> str:
    source = h(str(source_channel or _v57_load_active_problem().get('source_channel') or 'the saved training channel'))
    return ('<div class="v57-active-banner" style="border:2px solid #198754;border-radius:12px;padding:10px;margin:0.75rem 0;background:#effaf3;">'
            f'<strong>Using Current Active Problem from {source}.</strong><br>'
            'Show Full Solution, Plot, RC grading, and all learning modes are using this exact problem.</div>')

def _v57_save_or_use_active_problem(problem_text: str, source_channel: str = 'Student AI Chat', tags: Any = None, learning_mode: str = 'ask_tutor') -> str:
    clean = _v49_current_problem_text_only(str(problem_text or '')).strip()
    active = _v57_load_active_problem()
    active_text = str(active.get('problem_text') or '').strip()
    if active_text and clean and active_text == clean:
        return _v57_active_problem_using_banner(str(active.get('source_channel') or source_channel))
    _v57_save_active_problem(problem_text, source_channel=source_channel, tags=tags, learning_mode=learning_mode)
    return _v57_active_problem_banner(source_channel)


def _v57_visible_command(message: str, mode: str = '') -> str:
    low = str(message or '').strip().lower()
    mode_low = str(mode or '').strip().lower()
    if mode_low == 'full' or 'full solution' in low:
        return 'Student selected: Show Full Solution for the Current Active Problem.'
    if mode_low in {'plot','graph'} or low.startswith('plot') or low.startswith('graph') or low in {'plot','graph'}:
        return 'Student requested: plot the Current Active Problem.'
    if mode_low == 'hint' or 'hint' in low:
        return 'Student selected: Give One Hint for the Current Active Problem.'
    return str(message or 'Current Active Problem command')

def _v57_full_solution_html(problem_text: str) -> str:
    clean = _v49_current_problem_text_only(problem_text)
    data = _v55_parse_direct_kinematics(clean)
    if not data.get('complete'):
        return _v55_mode_card('Show Full Solution', 'Use the Current Active Problem only.', '<p>The current active problem is not yet complete in the dictionary. Train it with the correct RCs and solution.</p>')
    vi, vf, t, a = data['vi'], data['vf'], data['t'], data['a']
    body = (
        f'<p><strong>Current Active Problem:</strong> {h(clean)}</p>'
        '<p><strong>Given:</strong></p>'
        f'<ul><li>v<sub>i</sub> = {_fmt_num(vi)} m/s</li><li>v<sub>f</sub> = {_fmt_num(vf)} m/s</li><li>Δt = {_fmt_num(t)} s</li></ul>'
        '<p><strong>Equation:</strong> a = (v<sub>f</sub> - v<sub>i</sub>)/Δt</p>'
        f'<p><strong>Solution:</strong> a = ({_fmt_num(vf)} - {_fmt_num(vi)})/{_fmt_num(t)} = <strong>{_fmt_num(a)} m/s²</strong></p>'
        f'<p><strong>Answer:</strong> a = <strong>{_fmt_num(a)} m/s²</strong></p>'
    )
    return _v55_mode_card('Show Full Solution — Current Active Problem', 'Full solution for this exact problem only.', body)

def _v57_plot_html(problem_text: str) -> str:
    clean = _v49_current_problem_text_only(problem_text)
    data = _v55_parse_direct_kinematics(clean)
    if not data.get('complete'):
        return _v55_mode_card('Plot — Current Active Problem', 'Plot this exact problem only.', '<p>The current active problem is not yet complete enough to plot.</p>')
    vi, t, a = data['vi'], data['t'], data['a']
    vexpr = _v55_velocity_expr(vi, a)
    # Simple inline SVG velocity-time plot.
    W,H=520,260; L,B,R,T=55,210,490,30
    vf=vi+a*t
    ymin=min(0,vi,vf); ymax=max(0,vi,vf)
    if abs(ymax-ymin)<1e-9: ymax=ymin+1
    def sx(x): return L + (R-L)*(x/max(t,1e-9))
    def sy(y): return B - (B-T)*((y-ymin)/(ymax-ymin))
    x0,y0=sx(0),sy(vi); x1,y1=sx(t),sy(vf)
    svg=(f'<svg width="{W}" height="{H}" viewBox="0 0 {W} {H}" style="max-width:100%;background:#fff;border:1px solid #ddd;border-radius:10px;">'
         f'<line x1="{L}" y1="{B}" x2="{R}" y2="{B}" stroke="#333"/><line x1="{L}" y1="{T}" x2="{L}" y2="{B}" stroke="#333"/>'
         f'<text x="{R-40}" y="{B+30}" font-size="13">t (s)</text><text x="8" y="{T+10}" font-size="13">v (m/s)</text>'
         f'<line x1="{x0:.1f}" y1="{y0:.1f}" x2="{x1:.1f}" y2="{y1:.1f}" stroke="#0d6efd" stroke-width="4"/>'
         f'<circle cx="{x0:.1f}" cy="{y0:.1f}" r="5" fill="#0d6efd"/><circle cx="{x1:.1f}" cy="{y1:.1f}" r="5" fill="#0d6efd"/>'
         f'<text x="{x0+6:.1f}" y="{y0-8:.1f}" font-size="12">(0, {_fmt_num(vi)})</text><text x="{max(L,x1-95):.1f}" y="{y1-8:.1f}" font-size="12">({_fmt_num(t)}, {_fmt_num(vf)})</text>'
         '</svg>')
    body=(f'<p><strong>Current Active Problem:</strong> {h(clean)}</p>'
          f'<p><strong>Velocity-time equation:</strong> v(t) = <strong>{h(vexpr)}</strong>, for 0 ≤ t ≤ {_fmt_num(t)} s.</p>'
          f'{svg}')
    return _v55_mode_card('Plot — Current Active Problem', 'Plot this exact problem only.', body)

def _v57_reply_for_active_problem_command(message: str, mode: str = '', learning_mode: str = 'ask_tutor', tags: Any = None) -> str:
    active = _v57_active_problem_text()
    if not active:
        return _v55_mode_card('Current Active Problem', 'No active problem has been trained yet.', '<p>Enter a physics problem in Student AI Chat first. Then Show Full Solution and Plot will use that exact problem.</p>')
    low = str(message or '').strip().lower()
    mode_low = str(mode or '').strip().lower()
    if mode_low == 'full' or 'full solution' in low:
        return _v57_full_solution_html(active)
    if mode_low in {'plot','graph'} or low.startswith('plot') or low.startswith('graph') or low in {'plot','graph'}:
        return _v57_plot_html(active)
    if mode_low == 'hint' or 'hint' in low:
        return _v55_mode_card('Hint — Current Active Problem', 'Hint for this exact problem only.', '<p>Use the change in velocity over the time interval: compare v<sub>f</sub> and v<sub>i</sub>, then divide by Δt.</p>')
    return _v51_mode_mission_reply(learning_mode, active, str(mode or 'guided'), '')

# V57 active problem aware override for full/hint/plot requests that pass through the tutor reply layer.
_v57_tutor_reply_before_active_problem = _v49_tutor_reply

def _v49_tutor_reply(message: str, mode: str, last_assistant: str = '') -> str:
    if _v57_is_active_problem_command(message, mode):
        return _v57_reply_for_active_problem_command(message, mode, 'ask_tutor', [])
    return _v57_tutor_reply_before_active_problem(message, mode, last_assistant)


# -----------------------------------------------------------------------------
# V57 FORCES/FBD TRAINING CASE EXTENSION
# -----------------------------------------------------------------------------
# Adds the first non-kinematics book-training case:
# "A 10 kg box is pushed horizontally with a 50 N force on a frictionless surface.
# Find the acceleration."
# The student-facing logic remains dictionary-first: problem -> clues -> RCs ->
# tool/mode -> solve or redirect.

try:
    _V56_RC_ALIAS_TO_ID.update({
        'newton’s laws': 'newtons_laws',
        "newton's laws": 'newtons_laws',
        'newtons laws': 'newtons_laws',
        'newton laws': 'newtons_laws',
        'newton’s second law': 'newtons_laws',
        "newton's second law": 'newtons_laws',
        'frictionless surface': 'frictionless_surface',
        'horizontal surface': 'horizontal_surface',
        'draw fbd': 'draw_fbd',
        'draw_fbd': 'draw_fbd',
        'applied force': 'applied_force',
    })
except Exception:
    pass

def _v57_first_match(patterns, text):
    for p in patterns:
        m = re.search(p, str(text or ''), flags=re.I)
        if m:
            return m
    return None

def _v57_parse_forces_fbd_acceleration(message: str) -> dict:
    text = _v49_current_problem_text_only(str(message or ''))
    low = text.lower()
    clues = []
    m = None
    F = None

    mm = _v57_first_match([
        r'\b(\d+(?:\.\d+)?)\s*kg\s+(?:box|crate|cart|block|object)\b',
        r'\b(?:mass\s*(?:is|=|of)?\s*)(\d+(?:\.\d+)?)\s*kg\b',
        r'\b(?:box|crate|cart|block|object)\s+(?:of\s+mass\s+|with\s+mass\s+)(\d+(?:\.\d+)?)\s*kg\b',
    ], text)
    if mm:
        try:
            m = float(mm.group(1))
            clues.append(f'“{mm.group(0).strip()}” → mass m = {_fmt_num(m)} kg')
        except Exception:
            pass

    fm = _v57_first_match([
        r'\b(?:pushed|pulled|acted\s+on)\s+horizontally\s+with\s+(?:a\s+)?(\d+(?:\.\d+)?)\s*N\s+force\b',
        r'\b(?:pushed|pulled|acted\s+on)\s+with\s+(?:a\s+)?(\d+(?:\.\d+)?)\s*N\s+force\b',
        r'\b(?:force\s+of|applied\s+force\s+of|horizontal\s+force\s+of)\s*(\d+(?:\.\d+)?)\s*N\b',
        r'\b(\d+(?:\.\d+)?)\s*N\s+(?:force|horizontal\s+force|applied\s+force)\b',
    ], text)
    if fm:
        try:
            F = float(fm.group(1))
            clues.append(f'“{fm.group(0).strip()}” → applied horizontal force F = {_fmt_num(F)} N')
        except Exception:
            pass

    horizontal = bool(re.search(r'\bhorizontal(?:ly)?\b|\bhorizontal\s+surface\b', low))
    if horizontal:
        clues.append('“horizontally / horizontal surface” → choose +x along the horizontal motion')

    frictionless = bool(re.search(r'\bfrictionless\b|\bno\s+friction\b|\bneglect\s+friction\b|\bsmooth\s+surface\b', low))
    if frictionless:
        clues.append('“frictionless surface” → friction force f = 0 N')

    asks_a = bool(re.search(r'\b(find|calculate|determine|compute|what\s+is)\b[^.?!\n]*\bacceleration\b|\bacceleration\s*\??\s*$', low))
    if asks_a:
        am = re.search(r'((?:find|calculate|determine|compute|what\s+is)[^.?!\n]*\bacceleration\b\??|\bacceleration\s*\??\s*$)', text, flags=re.I)
        clues.append(f'“{am.group(1).strip() if am else "Find the acceleration"}” → requested unknown a')

    complete = (m not in (None, 0) and F is not None and frictionless and asks_a)
    a = F / m if complete else None
    relevant = []
    if horizontal:
        relevant.extend(['horizontal_surface', 'one_dimensional_motion'])
    if frictionless:
        relevant.append('frictionless_surface')
    if m is not None:
        relevant.append('mass_given')
    if F is not None:
        relevant.extend(['force_given', 'applied_force'])
    if asks_a:
        relevant.append('find_acceleration')
    if complete:
        relevant.extend(['newtons_laws', 'draw_fbd'])
    # Keep a compact relevant set while preserving order.
    seen = set()
    relevant = [x for x in relevant if not (x in seen or seen.add(x))]
    irrelevant = ['kinematics_equations', 'initial_velocity_given', 'final_velocity_given', 'time_given',
                  'inclined_plane', 'pulley', 'equilibrium', 'constant_velocity', 'two_dimensional_motion']
    return {
        'kind': 'forces_fbd_acceleration',
        'topic': 'Forces/FBD / Newton’s second law on a frictionless horizontal surface',
        'mode': 'Forces and FBDs Mode',
        'm': m, 'F': F, 'a': a,
        'horizontal': horizontal, 'frictionless': frictionless, 'asks_a': asks_a,
        'complete': complete,
        'clues': clues,
        'relevant': relevant,
        'irrelevant': irrelevant,
    }

def _v57_is_forces_fbd_acceleration(message: str) -> bool:
    return bool(_v57_parse_forces_fbd_acceleration(message).get('complete'))

def _v57_grade_forces_fbd_key(key: str, label: str, message: str) -> tuple:
    k = _v56_canonical_rc(key)
    data = _v57_parse_forces_fbd_acceleration(message)
    m, F, a = data.get('m'), data.get('F'), data.get('a')
    if k == 'horizontal_surface':
        return ('YES', 'The phrase “pushed horizontally” and the surface description support a horizontal-surface model.') if data.get('horizontal') else ('NO', 'No horizontal surface is described.')
    if k == 'frictionless_surface':
        return ('YES', 'The phrase “frictionless surface” means friction is zero.') if data.get('frictionless') else ('NO', 'The problem does not state a frictionless surface.')
    if k in {'no_friction','neglect_friction'}:
        return ('YES', 'The frictionless surface means friction is neglected in the horizontal force balance.') if data.get('frictionless') else ('NO', 'The problem does not say friction is neglected.')
    if k == 'one_dimensional_motion':
        return ('YES', 'The acceleration is along one horizontal axis.')
    if k == 'mass_given':
        return ('YES', f'The dictionary gives m = {_fmt_num(m)} kg.') if m is not None else ('NO', 'No mass is given.')
    if k == 'force_given':
        return ('YES', f'The dictionary gives an applied force F = {_fmt_num(F)} N.') if F is not None else ('NO', 'No numerical force is given.')
    if k == 'applied_force':
        return ('YES', f'The push is the applied horizontal force, F = {_fmt_num(F)} N.') if F is not None else ('NO', 'No applied force is identified.')
    if k == 'find_acceleration':
        return ('YES', 'The written problem asks to find the acceleration.') if data.get('asks_a') else ('NO', 'Acceleration is not requested.')
    if k in {'newtons_laws','write_newton_equations'}:
        return ('YES', 'The force and mass clues match Newton’s second law: ΣF = ma.') if data.get('complete') else ('PARTLY', 'Newton’s law may apply, but the force/mass clue set is incomplete.')
    if k in {'draw_fbd','fbd'}:
        return ('YES', 'A free-body diagram is appropriate: weight downward, normal upward, applied force horizontally, and no friction.')
    if k == 'normal_force':
        return ('PARTLY', 'A normal force exists for the box on the surface and belongs on the FBD, but it is not needed for the horizontal acceleration calculation.')
    if k == 'weight_gravity':
        return ('PARTLY', 'Weight acts downward and belongs on the FBD, but it cancels with the normal force vertically for this horizontal acceleration calculation.')
    if k == 'friction':
        return ('NO', 'The surface is frictionless, so friction is zero.')
    if k in {'kinetic_friction','static_friction','mu_k_given','mu_s_given'}:
        return ('NO', 'No friction coefficient is given; the surface is frictionless.')
    if k == 'kinematics_equations':
        return ('NO', 'No initial velocity, final velocity, or time interval is given; the acceleration comes from Newton’s second law.')
    if k == 'initial_velocity_given':
        return ('NO', 'No initial velocity is given.')
    if k == 'final_velocity_given':
        return ('NO', 'No final velocity is given.')
    if k == 'time_given':
        return ('NO', 'No time interval is given.')
    if k == 'constant_velocity':
        return ('NO', 'A net horizontal force produces acceleration, so the motion is not constant velocity.')
    if k == 'constant_acceleration':
        return ('PARTLY', 'If the applied force stays constant, Newton’s second law gives a constant acceleration.')
    if k == 'inclined_plane':
        return ('NO', 'No ramp or incline is described.')
    if k in {'pulley','pulley_system'}:
        return ('NO', 'No pulley or connected-body constraint is described.')
    if k in {'equilibrium','static_equilibrium'}:
        return ('NO', 'The horizontal net force is nonzero, so this is not equilibrium.')
    return ('NO', 'This RC is not supported by the dictionary clues in the written problem.')

_v57_rc_card_before_forces_extension = _v55_rc_card

def _v55_rc_card(message: str, tags: Any) -> str:
    fdata = _v57_parse_forces_fbd_acceleration(message)
    if fdata.get('complete'):
        keys = _v49_normalize_tags(tags)
        labels = _v49_tag_labels()
        selected_lines = []
        for k in keys:
            status, reason = _v57_grade_forces_fbd_key(k, labels.get(k, k), message)
            selected_lines.append(f'<li><strong>{h(labels.get(k,k))}:</strong> {h(status)}. {h(reason)}</li>')
        relevant_lines = []
        for k in fdata.get('relevant', []):
            status, reason = _v57_grade_forces_fbd_key(k, labels.get(k, k), message)
            relevant_lines.append(f'<li><strong>{h(labels.get(k,k))}:</strong> {h(status)}. {h(reason)}</li>')
        missing = [k for k in fdata.get('relevant', []) if k not in keys]
        wrong = []
        for k in keys:
            status, _ = _v57_grade_forces_fbd_key(k, labels.get(k, k), message)
            if status == 'NO':
                wrong.append(k)
        clue_html = '<ul>' + ''.join(f'<li>{h(c)}</li>' for c in fdata.get('clues', [])) + '</ul>'
        selected_html = '<ul>' + ''.join(selected_lines) + '</ul>' if selected_lines else '<p>No student RC selections were submitted.</p>'
        relevant_html = '<ul>' + ''.join(relevant_lines) + '</ul>'
        missing_html = '<p><strong>Important RCs not selected:</strong> ' + (', '.join(h(labels.get(k,k)) for k in missing) if missing else 'None.') + '</p>'
        wrong_html = '<p><strong>Selected RCs that do not match this problem:</strong> ' + (', '.join(h(labels.get(k,k)) for k in wrong) if wrong else 'None.') + '</p>'
        summary = _v49_tag_summary(keys)
        return (
            '<div class="v56-rc-card" style="border:2px solid #8250df;border-radius:12px;padding:12px;margin:0.75rem 0;background:#fbf7ff;">'
            '<h3 style="margin:0 0 0.35rem 0;">Book-Training Dictionary RC Check</h3>'
            f'<p><strong>Student selected:</strong> {h(summary) if summary else "None"}</p>'
            f'<p><strong>Dictionary topic:</strong> {h(fdata.get("topic", ""))}</p>'
            f'<p><strong>Recommended tool:</strong> {h(fdata.get("mode", ""))}</p>'
            '<p><strong>Physics phrases detected:</strong></p>' + clue_html +
            '<p><strong>Relevant RCs inferred by the dictionary:</strong></p>' + relevant_html +
            '<p><strong>Student-selected RC grading:</strong></p>' + selected_html +
            missing_html + wrong_html +
            '<p><strong>Rule:</strong> the problem text and book-trained dictionary are the source of truth; student RC selections are diagnostic feedback.</p>'
            '</div>'
        )
    return _v57_rc_card_before_forces_extension(message, tags)

def _v49_tag_triage_card(message: str, tags: Any) -> str:
    return _v55_rc_card(message, tags)

_v57_direct_kinematics_mode_reply_before_forces_extension = _v55_direct_kinematics_mode_reply

def _v57_forces_mode_reply(learning_mode: str, message: str) -> str:
    data = _v57_parse_forces_fbd_acceleration(message)
    if not data.get('complete'):
        return ''
    key = _v55_mode_key(learning_mode)
    m, F, a = data['m'], data['F'], data['a']
    clue_html = '<br>'.join(h(c) for c in data.get('clues', []))
    givens = (f'<p><strong>Physics phrases detected:</strong><br>{clue_html}</p>'
              f'<p><strong>Given quantities:</strong> m = {_fmt_num(m)} kg, F = {_fmt_num(F)} N, friction force f = 0 N.</p>')
    solution = (
        '<p><strong>Free-body diagram:</strong> weight F<sub>g</sub> downward, normal force F<sub>N</sub> upward, applied force F horizontally, and no friction.</p>'
        '<p><strong>Horizontal force equation:</strong> ΣF<sub>x</sub> = ma.</p>'
        f'<p><strong>Net horizontal force:</strong> ΣF<sub>x</sub> = {_fmt_num(F)} N.</p>'
        f'<p><strong>Solution:</strong> a = ΣF<sub>x</sub>/m = {_fmt_num(F)}/{_fmt_num(m)} = <strong>{_fmt_num(a)} m/s²</strong>.</p>'
        '<p><strong>Physical meaning:</strong> The acceleration is in the direction of the applied horizontal force.</p>'
    )
    if key in {'ask_tutor', 'forces_fbd'}:
        title = 'Ask Physics Tutor Mode' if key == 'ask_tutor' else 'Forces and FBDs Mode'
        mission = 'Read the problem with the book-trained dictionary, infer relevant RCs, select the equation tool, and solve when the clue set is complete.' if key == 'ask_tutor' else 'Use real forces, free-body diagrams, and Newton’s second law to find acceleration.'
        return _v55_mode_card(title, mission, givens + '<p><strong>Mode fit:</strong> YES. This is a complete Newton’s second-law force problem.</p>' + solution)
    if key == 'dynamics_kinematics':
        body = givens + '<p><strong>Mode fit:</strong> YES for the dynamics step. The problem gives force and mass, so acceleration comes from Newton’s second law. No time information is given for later velocity/displacement kinematics.</p>' + solution
        return _v55_mode_card('Dynamics + Kinematics Mode', 'Connect force information to acceleration, then use kinematics only if time or motion data are given.', body)
    if key == 'kinematics':
        body = givens + '<p><strong>Mode fit:</strong> NO for direct kinematics. Initial velocity, final velocity, and time are not given. The correct tool is Forces and FBDs Mode or Dynamics + Kinematics Mode.</p><p><strong>Redirect:</strong> use Forces and FBDs Mode.</p>'
        return _v55_mode_card('Kinematics Mode', 'Use motion variables when v_i, v_f, Δt, displacement, or motion graphs are given.', body)
    if key == 'inclined_plane':
        body = givens + '<p><strong>Mode fit:</strong> NO. No incline angle, ramp, rotated-axis, or weight-component clue appears.</p><p><strong>Redirect:</strong> use Forces and FBDs Mode.</p>'
        return _v55_mode_card('Inclined Plane Mode', 'Use ramp geometry and rotated axes only when an incline is described.', body)
    if key == 'pulleys':
        body = givens + '<p><strong>Mode fit:</strong> NO. No pulley, connected-body constraint, hanging mass, or unknown tension appears.</p><p><strong>Redirect:</strong> use Forces and FBDs Mode.</p>'
        return _v55_mode_card('Pulleys Mode', 'Use pulley constraints only when a pulley system is described.', body)
    if key == 'equilibrium':
        body = givens + f'<p><strong>Mode fit:</strong> NO. The net horizontal force is {_fmt_num(F)} N, so acceleration is not zero. Equilibrium requires ΣF = 0.</p><p><strong>Redirect:</strong> use Forces and FBDs Mode.</p>'
        return _v55_mode_card('Equilibrium Mode', 'Test whether net force or net torque is zero.', body)
    return _v55_mode_card('Book-Training Dictionary Tutor', 'Use the book-trained dictionary to identify the correct physics tool.', givens + solution)

def _v55_direct_kinematics_mode_reply(learning_mode: str, message: str) -> str:
    force_reply = _v57_forces_mode_reply(learning_mode, message)
    if force_reply:
        return force_reply
    return _v57_direct_kinematics_mode_reply_before_forces_extension(learning_mode, message)

def _v52_pure_kinematics_mode_reply(learning_mode: str, message: str) -> str:
    clean = _v49_current_problem_text_only(str(message or ''))
    return _v55_direct_kinematics_mode_reply(learning_mode, clean)

def _v51_mode_mission_reply(learning_mode: str, message: str, tutor_mode: str, last_assistant: str='') -> str:
    clean = _v49_current_problem_text_only(str(message or ''))
    return _v55_direct_kinematics_mode_reply(learning_mode, clean)

_v57_full_solution_html_before_forces_extension = _v57_full_solution_html

def _v57_full_solution_html(problem_text: str) -> str:
    clean = _v49_current_problem_text_only(problem_text)
    data = _v57_parse_forces_fbd_acceleration(clean)
    if data.get('complete'):
        m, F, a = data['m'], data['F'], data['a']
        body = (
            f'<p><strong>Current Active Problem:</strong> {h(clean)}</p>'
            '<p><strong>Given:</strong></p>'
            f'<ul><li>m = {_fmt_num(m)} kg</li><li>F = {_fmt_num(F)} N</li><li>frictionless surface → f = 0 N</li></ul>'
            '<p><strong>Free-body diagram:</strong> F<sub>g</sub> downward, F<sub>N</sub> upward, applied force horizontally, no friction.</p>'
            '<p><strong>Equation:</strong> ΣF<sub>x</sub> = ma</p>'
            f'<p><strong>Solution:</strong> a = ΣF<sub>x</sub>/m = {_fmt_num(F)}/{_fmt_num(m)} = <strong>{_fmt_num(a)} m/s²</strong></p>'
            f'<p><strong>Answer:</strong> a = <strong>{_fmt_num(a)} m/s²</strong></p>'
        )
        return _v55_mode_card('Show Full Solution — Current Active Problem', 'Full solution for this exact problem only.', body)
    return _v57_full_solution_html_before_forces_extension(problem_text)

_v57_plot_html_before_forces_extension = _v57_plot_html

def _v57_plot_html(problem_text: str) -> str:
    clean = _v49_current_problem_text_only(problem_text)
    data = _v57_parse_forces_fbd_acceleration(clean)
    if data.get('complete'):
        a = data['a']
        body = (f'<p><strong>Current Active Problem:</strong> {h(clean)}</p>'
                f'<p><strong>Acceleration from Newton’s second law:</strong> a = <strong>{_fmt_num(a)} m/s²</strong>.</p>'
                '<p>No time interval is given, so a velocity-time or position-time graph cannot be determined from this problem alone. A simple acceleration value can be plotted once a time window is supplied.</p>')
        return _v55_mode_card('Plot — Current Active Problem', 'Plot this exact problem only.', body)
    return _v57_plot_html_before_forces_extension(problem_text)


