def _v65_evaluate_other_entries(problem: str, other_rc: str) -> List[Dict[str, str]]:
    entries=[x.strip() for x in str(other_rc or '').split(',') if x.strip()]
    reg=_v63_rc_registry(); items=reg.get('items',{})
    lookup={}
    for code,m in items.items():
        lookup[str(m.get('display_label','')).lower()]=code
        for a in m.get('aliases',[]) or []: lookup[str(a).lower()]=code
    out=[]; pl=problem.lower()
    for text in entries:
        key=text.lower(); code=lookup.get(key)
        if code: out.append({'entry':text,'status':'MATCHES EXISTING RC','detail':items[code].get('display_label',code)}); continue
        if 'stopping distance' in key and ('stop' in pl or 'rest' in pl): out.append({'entry':text,'status':'VALID PHYSICS IDEA','detail':'Stopping distance is not determined by the stated information.'}); continue
        if any(w in key for w in ['friction','braking','drag','collision','tension']): out.append({'entry':text,'status':'UNSUPPORTED BY THE PROBLEM','detail':'Possible interaction, but not identified by the written problem.'}); continue
        if 'heat' in key or 'thermal' in key: out.append({'entry':text,'status':'CONDITIONAL','detail':'Thermal-energy generation depends on the stopping mechanism.'}); continue
        out.append({'entry':text,'status':'STUDENT COMMENT ONLY','detail':'Saved for teacher review and possible promotion into the canonical RC dictionary.'})
    return out

@app.get('/abk-pai/expression-lab', response_class=HTMLResponse)
def abk_expression_lab(q: str = Query(default=''), rc: List[str] = Query(default=[]), learning_mode: str = Query(default='auto_mode'), other_rc: str = Query(default='')) -> HTMLResponse:
    if not str(q or '').strip() and not rc and learning_mode == 'auto_mode' and not str(other_rc or '').strip():
        q = _V73_RELEASE_PROMPT
        rc = list(_V73_RELEASE_RC)
        learning_mode = _V73_RELEASE_MODE
    active = _v57_load_active_problem()
    clean_q = _v49_current_problem_text_only(str(q or '')).strip()
    active_q = _v49_current_problem_text_only(str(active.get('problem_text') or '')).strip()
    normalized_rc = _v49_normalize_tags(rc)
    if clean_q and clean_q == active_q and normalized_rc == list(active.get('selected_rc_ids') or []) and isinstance(active.get('canonical_analysis'), dict):
        inference = dict(active.get('canonical_analysis') or {})
        learning_mode = str(active.get('learning_mode') or learning_mode)
        other_rc = str(active.get('other_entries_text') or '')
    else:
        other_rc = _v70_clean_other_rc(other_rc)
        learning_mode = _v70_resolve_learning_mode(q, learning_mode, rc)
        inference = abk_lab_canonical_analysis(q, rc, learning_mode, other_rc) if q.strip() else None
    rc_path = PACKAGE_DIR / 'physics_language_dictionary' / 'rc_canonical_registry_v69.json'
    try:
        rc_registry = json.loads(rc_path.read_text(encoding='utf-8'))
    except Exception:
        rc_registry = {'categories': [], 'items': {}}
    rc_selected = set(rc or [])
    rc_groups=[]
    for idx, category in enumerate(rc_registry.get('categories', [])):
        item_html=[]
        for code in category.get('items', []):
            meta=rc_registry.get('items',{}).get(code,{})
            label=meta.get('display_label') or code.replace('_',' ')
            checked=' checked' if code in rc_selected else ''
            item_html.append(f"<label class='v61-rc-item'><input type='checkbox' name='rc' value='{h(code)}'{checked}> <span>{h(label)}</span></label>")
        rc_groups.append(f"<details class='v61-rc-kind'{' open' if idx < 3 else ''}><summary>{h(category.get('display_label',''))} <span class='v61-category-count' data-category='{idx}'>0 selected</span></summary><div class='v61-rc-grid' data-category-grid='{idx}'>{''.join(item_html)}</div></details>")
    result_html=''
    other_eval=(inference or {}).get('other_entry_evaluation', [])
    if inference:
        extracted=''.join(f'<li>{h(x)}</li>' for x in inference.get('extracted_statements',[])) or '<li>No quantities extracted.</li>'
        activated=''.join(f'<li>{h(x)}</li>' for x in inference.get('physics_connections',[])) or '<li>No seeded connection matched.</li>'
        conditional_physics=''.join(f'<li>{h(x)}</li>' for x in inference.get('conditional_physics_connections',[])) or '<li>No additional conditional physics connection was identified.</li>'
        graded=''.join(f"<li><strong>{h(x['label'])}:</strong> {h(x['status'])}. {h(x['reason'])}</li>" for x in inference.get('selected_rc_grading',[])) or '<li>No RC items selected.</li>'
        requested=''.join(f'<li>{h(x)}</li>' for x in inference.get('explicitly_requested',[])) or '<li>No unknown is explicitly requested by the wording.</li>'
        inferable=''.join(f'<li>{h(x)}</li>' for x in inference.get('inferable_quantities',[])) or '<li>No additional quantity is currently inferable.</li>'
        conditional=''.join(f'<li>{h(x)}</li>' for x in inference.get('conditional_results',[])) or '<li>No conditional model result is displayed.</li>'
        prompts=''.join(f'<li>{h(x)}</li>' for x in inference.get('prompts',[]))
        cautions=''.join(f'<li>{h(x)}</li>' for x in inference.get('cautions',[]))
        other_html=(''.join(f"<li><strong>{h(x['entry'])}:</strong> {h(x['status'])}. {h(x['detail'])}</li>" for x in other_eval) or '<li>No Other entries submitted.</li>')
        equations=''.join(f'<li><code>{h(x)}</code></li>' for x in inference.get('governing_equations',[])) or '<li>No equation selected.</li>'
        steps=''.join(f'<li>{h(x)}</li>' for x in inference.get('solution_steps',[])) or '<li>No numerical solution generated for this statement.</li>'
        final_answer=h(inference.get('final_answer','')) or 'No final answer is explicitly required.'
        result_html=f'''<section class="card"><h2>Physics interpretation</h2><h3>Information extracted from the language</h3><ul>{extracted}</ul><h3>Physics activated by the statement</h3><ul>{activated}</ul><h3>Conditional physics possibilities</h3><ul>{conditional_physics}</ul><h3>Explicitly requested unknown</h3><ul>{requested}</ul><h3>Inferable quantities</h3><ul>{inferable}</ul><h3>Conditional model results</h3><ul>{conditional}</ul><h3>Governing equations</h3><ul>{equations}</ul><h3>Canonical solution steps</h3><ol>{steps}</ol><p><strong>Final answer:</strong> {final_answer}</p><h3>Student-selected RC grading</h3><ul>{graded}</ul><h3>Other entry evaluation</h3><ul>{other_html}</ul><h3>Reading and comprehension prompts</h3><ul>{prompts}</ul><h3>Cautions and missing information</h3><ul>{cautions}</ul><details><summary><strong>Technical diagnostic data</strong></summary><pre>{h(json.dumps(inference,indent=2))}</pre></details></section>'''
    body=f'''
    <style>.v61-status{{margin:.65rem 0;padding:.65rem .8rem;border:1px solid #9ec5fe;border-radius:10px;background:#eef6ff}}.v61-status.warn{{border-color:#e6b800;background:#fff8d8}}.v61-controls{{display:flex;gap:.5rem;flex-wrap:wrap;margin:.65rem 0}}.v61-controls button:disabled,.v61-submit:disabled{{opacity:.48;cursor:not-allowed}}.v61-rc-kind{{margin:.45rem 0;border:1px solid #b6c2d2;border-radius:10px;background:#f8fbff}}.v61-rc-kind summary{{cursor:pointer;padding:.6rem .75rem;font-weight:700;display:flex;justify-content:space-between;gap:1rem}}.v61-category-count{{font-weight:400;font-size:.88rem;color:#425466}}.v61-rc-grid{{padding:0 .8rem .8rem;display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:.3rem .9rem;max-height:280px;overflow:auto}}.v61-rc-item{{display:flex;align-items:flex-start;gap:.35rem;padding:.22rem 0}}.v61-rc-item input{{margin-top:.2rem}}</style>
    <section class="card"><h1>Expression Sources and Reading Comprehension</h1><p>Enter a physics problem, then select the physics you believe is contained in the language. The Lab and Student AI use the same canonical ABK_PAI inference engine. Use the parity page to verify field-by-field identity.</p><form method="get" id="v61-rc-form" data-v51-ready="1"><label for="v61-problem"><strong>Current physics problem</strong></label><textarea id="v61-problem" name="q" rows="5" style="width:100%">{h(q)}</textarea><label><strong>Learning mode</strong><select name="learning_mode">{_v73_mode_options_html(learning_mode)}</select></label><div id="v61-status" class="v61-status" role="status">Enter a problem and select at least one RC item.</div><details class="tag-menu" open><summary><strong>Reading and Comprehension Selection Menu</strong></summary><p class="muted">Average acceleration and the constant-acceleration assumption are separate RC decisions.</p>{''.join(rc_groups)}</details><fieldset style="margin:.7rem 0;border:1px dashed #8ca3bf;border-radius:10px;padding:.75rem"><legend><strong>Other (optional)</strong></legend><label for="v71-other">Additional physics keywords or short phrases separated by commas</label><textarea id="v71-other" name="other_rc" rows="2" style="width:100%">{h(other_rc)}</textarea></fieldset><div class="v61-controls"><button type="button" class="button secondary" id="v61-use">Use saved problem + RC</button><button type="button" class="button secondary" id="v61-save">Save problem + RC for this problem</button><button type="button" class="button secondary" id="v61-reset">Reset problem + RC</button></div><p><button class="button v61-submit" id="v61-submit" type="submit">Interpret Problem + Apply RC</button> <button class="button" id="v80-load-student" type="button">Load into Student-AI Chat</button> <a class="button secondary" href="/abk-pai">ABK_PAI Home</a></p></form></section>{result_html}
    <script>(function(){{const KEY='abk_pai_v62_current_problem_rc',form=document.getElementById('v61-rc-form'),ta=document.getElementById('v61-problem'),getBoxes=()=>Array.from(form.querySelectorAll('input[name="rc"]')),status=document.getElementById('v61-status'),useBtn=document.getElementById('v61-use'),saveBtn=document.getElementById('v61-save'),resetBtn=document.getElementById('v61-reset'),submitBtn=document.getElementById('v61-submit'),studentBtn=document.getElementById('v80-load-student');function selected(){{return getBoxes().filter(b=>b.checked).map(b=>b.value)}}function saved(){{try{{return JSON.parse(localStorage.getItem(KEY)||'null')}}catch(e){{return null}}}}function counts(){{form.querySelectorAll('[data-category-grid]').forEach(g=>{{const n=g.querySelectorAll('input:checked').length,b=form.querySelector('[data-category="'+g.dataset.categoryGrid+'"]');if(b)b.textContent=n+' selected'}})}}function update(msg){{const p=ta.value.trim(),n=selected().length,sv=!!saved();saveBtn.disabled=!(p&&n);submitBtn.disabled=!(p&&n);if(studentBtn)studentBtn.disabled=!(p&&n);useBtn.disabled=!sv;resetBtn.disabled=!(p||n||sv);status.classList.toggle('warn',!(p&&n));status.textContent=msg||(p?(n?n+' RC item'+(n===1?'':'s')+' selected. Ready to save or interpret.':'Problem entered. Select at least one Reading and Comprehension item.'):'Enter a problem and select at least one RC item.');counts()}}ta.addEventListener('input',()=>update());form.addEventListener('change',()=>update());saveBtn.addEventListener('click',async()=>{{const other=(form.querySelector('textarea[name="other_rc"]')||{{}}).value||'';const mode=(form.querySelector('select[name="learning_mode"]')||{{}}).value||'auto_mode';const x={{problem:ta.value.trim(),rc:selected(),learning_mode:mode,other_rc:other,savedAt:new Date().toISOString()}};if(!x.problem||!x.rc.length){{update('A problem and at least one RC selection are required before saving.');return}}localStorage.setItem(KEY,JSON.stringify(x));const body=new URLSearchParams();body.set('problem',x.problem);x.rc.forEach(v=>body.append('rc',v));body.set('learning_mode',mode);body.set('other_rc',other);body.set('source_channel','Expression Sources Lab');try{{const r=await fetch('/api/abk-pai/active-state',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:body.toString()}});const j=await r.json();if(!r.ok)throw new Error(j.detail||'save failed');update('Saved to shared active state: '+j.selected_rc_count+' RC items. Refreshing the Lab from the authoritative canonical record.');const qs=new URLSearchParams();qs.set('q',x.problem);x.rc.forEach(v=>qs.append('rc',v));qs.set('learning_mode',mode);qs.set('other_rc',other);window.location='/abk-pai/expression-lab?'+qs.toString()}}catch(e){{update('Shared save failed: '+e.message)}}}});useBtn.addEventListener('click',()=>{{const x=saved();if(!x){{update('No saved problem and RC selections are available.');return}}ta.value=x.problem||'';const s=new Set(x.rc||[]);getBoxes().forEach(b=>b.checked=s.has(b.value));const mode=form.querySelector('select[name="learning_mode"]');if(mode&&x.learning_mode)mode.value=x.learning_mode;const other=form.querySelector('textarea[name="other_rc"]');if(other)other.value=x.other_rc||'';update('Saved problem, RC selections, mode, and Other entries loaded.')}});resetBtn.addEventListener('click',()=>{{ta.value='';getBoxes().forEach(b=>b.checked=false);localStorage.removeItem(KEY);update('Problem and RC selections reset.')}});if(studentBtn)studentBtn.addEventListener('click',async()=>{{const problem=ta.value.trim(),rcs=selected(),other=(form.querySelector('textarea[name="other_rc"]')||{{}}).value||'',mode=(form.querySelector('select[name="learning_mode"]')||{{}}).value||'auto_mode';if(!problem||!rcs.length){{update('A problem and at least one RC selection are required before loading Student-AI.');return}}const body=new URLSearchParams();body.set('problem',problem);rcs.forEach(v=>body.append('rc',v));body.set('learning_mode',mode);body.set('other_rc',other);body.set('source_channel','Expression Sources Lab');body.set('force_clean_workspace','true');try{{const r=await fetch('/api/abk-pai/load-student-ai',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:body.toString()}});const j=await r.json();if(!r.ok)throw new Error(j.detail||'transfer failed');window.location='/v49-student-ask?view=current&mode_focus='+encodeURIComponent(j.learning_mode||mode)}}catch(e){{update('Student-AI transfer failed: '+e.message)}}}});form.addEventListener('submit',e=>{{e.preventDefault();if(!ta.value.trim()||!selected().length){{update('Select at least one RC item before interpreting this problem.');return}}saveBtn.click();}});update()}})();</script>'''
    return page('ABK_PAI Volume 89 - Expression Sources and RC', body)

