_v61_original_parse_direct_kinematics = _v55_parse_direct_kinematics
_v61_original_grade_rc_key = _v55_grade_rc_key

def _v55_parse_direct_kinematics(message: str) -> dict:
    data = _v61_original_parse_direct_kinematics(message)
    if not data.get('complete'):
        return data
    shared = abk_infer_rc(message, [])
    kin = shared.get('kinematics', {})
    data['average_acceleration'] = kin.get('average_acceleration')
    data['nonzero_acceleration'] = bool(kin.get('average_acceleration') is not None and abs(kin.get('average_acceleration')) > 1e-12)
    data['constant_acceleration_explicit'] = bool(kin.get('constant_acceleration_explicit'))
    data['explicit_requested'] = shared.get('explicitly_requested', [])
    data['inferable'] = shared.get('inferable_quantities', [])
    rel = ['one_dimensional_motion']
    vi, vf = data.get('vi'), data.get('vf')
    if vi is not None and vf is not None:
        rel.append('slowing_down' if abs(vf) < abs(vi) else ('speeding_up' if abs(vf) > abs(vi) else 'constant_velocity'))
    rel += ['initial_speed_stated','initial_velocity_given','final_velocity_implied_zero','time_given','average_acceleration','nonzero_acceleration','kinematics_equations','constant_acceleration_assumption']
    if data.get('asks_a'):
        rel.append('find_acceleration')
    data['relevant'] = list(dict.fromkeys(rel))
    return data

def _v55_grade_rc_key(key: str, label: str, message: str) -> tuple:
    code = _v56_canonical_rc(key)
    shared = abk_infer_rc(message, [code])
    rows = shared.get('selected_rc_grading', [])
    if rows:
        row = rows[0]
        if row.get('status') != 'NO' or code in {'average_acceleration','nonzero_acceleration','constant_acceleration','constant_acceleration_assumption','find_acceleration','kinematics_equations'}:
            return (row.get('status','NO'), row.get('reason',''))
    return _v61_original_grade_rc_key(key, label, message)

def _v55_direct_kinematics_mode_reply(learning_mode: str, message: str) -> str:
    data = _v55_parse_direct_kinematics(message)
    if not data.get('complete'):
        return None
    key = _v55_mode_key(learning_mode)
    vi, vf, t = data['vi'], data['vf'], data['t']
    a = data.get('average_acceleration')
    clues = '<br>'.join(h(c) for c in data.get('clues', []))
    if data.get('asks_a'):
        request_text = 'Acceleration is explicitly requested by the problem.'
    else:
        request_text = 'No unknown is explicitly requested; average acceleration is inferable from the stated information.'
    body = (
        f'<p><strong>Physics phrases detected:</strong><br>{clues}</p>'
        f'<p><strong>Language interpretation:</strong> The initial speed is {_fmt_num(abs(vi))} m/s. Choosing the original direction as positive gives v<sub>i</sub> = +{_fmt_num(abs(vi))} m/s. The stopping phrase implies v<sub>f</sub> = {_fmt_num(vf)} m/s. The elapsed time is Δt = {_fmt_num(t)} s.</p>'
        f'<p><strong>Explicitly requested versus inferable:</strong> {h(request_text)}</p>'
        f'<p><strong>Average acceleration:</strong> a<sub>avg</sub> = (v<sub>f</sub>-v<sub>i</sub>)/Δt = ({_fmt_num(vf)}-{_fmt_num(vi)})/{_fmt_num(t)} = <strong>{_fmt_num(a)} m/s²</strong>.</p>'
    )
    if data.get('constant_acceleration_explicit'):
        body += f'<p><strong>Constant-acceleration model:</strong> v(t) = <strong>{h(_v55_velocity_expr(vi, a))}</strong>, for 0 ≤ t ≤ {_fmt_num(t)} s.</p>'
    else:
        body += '<p><strong>Model caution:</strong> The data determine average acceleration, but not the complete function v(t). A velocity-time equation is displayed only when constant acceleration is stated or explicitly adopted as an assumption.</p>'
    title = _V55_MODE_TITLES.get(key, 'Ask Physics Tutor Mode')
    return _v55_mode_card(title, 'Use the shared ABK_PAI inference engine to distinguish stated, implied, inferable, and assumed physics.', body)

