def _v62_student_canonical_card(problem: str, rc: List[str], learning_mode: str, other_rc: str = '') -> str:
    active = _v57_load_active_problem()
    clean = _v49_current_problem_text_only(str(problem or '')).strip()
    active_clean = _v49_current_problem_text_only(str(active.get('problem_text') or '')).strip()
    if clean and clean == active_clean and _v49_normalize_tags(rc) == list(active.get('selected_rc_ids') or []) and isinstance(active.get('canonical_analysis'), dict):
        c = dict(active.get('canonical_analysis') or {})
    else:
        c = abk_student_canonical_analysis(problem, rc, learning_mode, _v70_clean_other_rc(other_rc))
    extracted=''.join(f'<li>{h(x)}</li>' for x in c.get('extracted_statements',[])) or '<li>None.</li>'
    graded=''.join(f"<li><strong>{h(x.get('label',''))}:</strong> {h(x.get('status',''))}. {h(x.get('reason',''))}</li>" for x in c.get('selected_rc_grading',[])) or '<li>No RC items selected.</li>'
    inferable=''.join(f'<li>{h(x)}</li>' for x in c.get('inferable_quantities',[])) or '<li>None.</li>'
    conditional=''.join(f'<li>{h(x)}</li>' for x in c.get('conditional_results',[])) or '<li>None.</li>'
    other=''.join(f"<li><strong>{h(x.get('entry',''))}:</strong> {h(x.get('status',''))}. {h(x.get('detail',''))}</li>" for x in c.get('other_entry_evaluation',[])) or '<li>No Other entries submitted.</li>'
    equations=''.join(f'<li><code>{h(x)}</code></li>' for x in c.get('governing_equations',[])) or '<li>No equation selected.</li>'
    steps=''.join(f'<li>{h(x)}</li>' for x in c.get('solution_steps',[])) or '<li>No numerical solution generated for this statement.</li>'
    final=h(c.get('final_answer','')) or 'No final answer is explicitly required.'
    return f'''<section class="mode-card" data-canonical-hash="{h(c.get('canonical_hash',''))}">
      <h3>ABK_PAI Canonical Physics Record</h3>
      <p><strong>Shared record:</strong> This is the same canonical physics content used by the Expression Sources Lab.</p>
      <p><strong>Learning mode:</strong> {h(c.get('learning_mode',''))}<br><strong>Canonical hash:</strong> <code>{h(c.get('canonical_hash',''))}</code></p>
      <h4>Information extracted</h4><ul>{extracted}</ul>
      <h4>Inferable quantities</h4><ul>{inferable}</ul>
      <h4>Conditional model results</h4><ul>{conditional}</ul>
      <h4>Governing equations</h4><ul>{equations}</ul>
      <h4>Canonical solution steps</h4><ol>{steps}</ol>
      <p><strong>Final answer:</strong> {final}</p>
      <h4>Selected RC grading</h4><ul>{graded}</ul>
      <h4>Other entry evaluation</h4><ul>{other}</ul>
    </section>'''

