@app.get('/abk-pai/parity-test', response_class=HTMLResponse)
def abk_parity_test(q: str = Query(default='An object traveling at 20 m/s came to a stop in 5 seconds.'), rc: List[str] = Query(default=[]), learning_mode: str = Query(default='auto_mode')) -> HTMLResponse:
    defaults=['slowing_down','one_dimensional_motion','average_acceleration','constant_acceleration_assumption','initial_speed_stated','final_velocity_implied_zero','kinematics_equations']
    selected=rc or defaults
    report=abk_parity_report(q, selected, learning_mode) if q.strip() else None
    rc_path=PACKAGE_DIR/'physics_language_dictionary'/'rc_canonical_registry_v69.json'
    try: registry=json.loads(rc_path.read_text(encoding='utf-8'))
    except Exception: registry={'items':{}}
    checks=[]
    for code in defaults:
        label=registry.get('items',{}).get(code,{}).get('display_label') or code.replace('_',' ')
        checked=' checked' if code in selected else ''
        checks.append(f"<label style='display:block'><input type='checkbox' name='rc' value='{h(code)}'{checked}> {h(label)}</label>")
    result=''
    if report:
        rows=''.join(f"<tr><td>{h(x['field'])}</td><td><strong>{h(x['status'])}</strong></td></tr>" for x in report['comparisons'])
        cls='pass' if report['overall']=='PASS' else 'fail'
        result=f'''<section class="card"><h2>Parity result: <span class="{cls}">{h(report['overall'])}</span></h2>
        <p><strong>Lab canonical hash:</strong> <code>{h(report['lab_hash'])}</code><br><strong>Student-AI canonical hash:</strong> <code>{h(report['student_ai_hash'])}</code></p>
        <table><thead><tr><th>Canonical field</th><th>Status</th></tr></thead><tbody>{rows}</tbody></table>
        <details><summary><strong>Full parity diagnostic</strong></summary><pre>{h(json.dumps(report,indent=2))}</pre></details></section>'''
    body=f'''<style>.pass{{color:#087830}}.fail{{color:#b42318}}</style><section class="card"><h1>Lab–Student AI Canonical Parity Test</h1>
    <p>Submit the same prompt, RC selections, and learning mode to both adapters. PASS means the canonical physics content is identical; interface wording may differ.</p>
    <form method="get"><label><strong>Physics prompt</strong></label><textarea name="q" rows="4" style="width:100%">{h(q)}</textarea>
    <label><strong>Learning mode</strong><select name="learning_mode">{_v73_mode_options_html(learning_mode, include_auto=True)}</select></label>
    <fieldset><legend><strong>RC selections</strong></legend>{''.join(checks)}</fieldset><p><button type="submit">Run parity test</button> <a class="button secondary" href="/abk-pai/expression-lab">Expression Sources Lab</a> <a class="button secondary" href="/v49-student-ask">Student AI</a></p></form></section>{result}'''
    return page('ABK_PAI Volume 89 - Canonical Parity Test',body)

# V62 final RC normalization: preserve every canonical registry item so the
# Student-AI receives exactly the same RC list submitted to the Lab.
def _v62_rc_registry_labels() -> Dict[str, str]:
    path = PACKAGE_DIR / 'physics_language_dictionary' / 'rc_canonical_registry_v69.json'
    try:
        reg = json.loads(path.read_text(encoding='utf-8'))
    except Exception:
        reg = {'items': {}}
    labels = dict(_v49_tag_labels())
    for code, meta in reg.get('items', {}).items():
        labels[str(code)] = str(meta.get('display_label') or str(code).replace('_', ' '))
    return labels

_V69_LEGACY_TO_REGISTRY_RC = {
    'slowing_down': 'object_slowing_down',
    'average_acceleration': 'average_acceleration_available',
    'constant_acceleration_assumption': 'constant_acceleration_assumed',
    'initial_velocity_given': 'initial_velocity_assigned_sign',
}

def _v49_normalize_tags(tags: Any) -> List[str]:
    """Preserve the canonical UI registry codes used by both Lab and Student-AI."""
    if tags is None:
        return []
    if isinstance(tags, str):
        tags = [tags]
    labels = _v62_rc_registry_labels()
    registry = _v63_rc_registry().get('items', {})
    out=[]
    for item in list(tags):
        raw=str(item or '').strip()
        if not raw:
            continue
        if raw in registry:
            code=raw
        else:
            legacy=_v56_canonical_rc(raw)
            code=_V69_LEGACY_TO_REGISTRY_RC.get(legacy, legacy)
        if code in labels and code not in out:
            out.append(code)
    return out

def _v49_tag_summary(tags: Any) -> str:
    labels=_v62_rc_registry_labels()
    return ', '.join(labels.get(k,k.replace('_',' ')) for k in _v49_normalize_tags(tags))


