@app.get('/api/abk-pai/integrity')
def abk_pai_integrity():
    from backend.abk_pai_core import summary as core_summary, canonical_analysis
    batch=_v77_batch() if '_v77_batch' in globals() else {'cases':[],'version':'missing'}
    core=core_summary()
    prompt='A student holds a dumbbell so that the forearm is horizontal. The dumbbell exerts a downward force of 90.0 N at a distance of 0.32 m from the elbow joint. The weight of the forearm and hand is modeled as a downward force of 18.0 N acting 0.16 m from the elbow. F_1 &= 90.0 N, & r_1 &= 0.32 m, & F_2 &= 18.0 N, & r_2 &= 0.16 m. Find the total clockwise torque about the elbow due to the dumbbell and the forearm-hand weight. . F_1 &= 90.0 N, & r_1 &= 0.32 m, & F_2 &= 18.0 N, & r_2 &= 0.16 m.'
    rc=['rotational_motion','weight_gravity','applied_force','torque','torque_equation','force_is_given','distance_is_given','find_torque','solve_symbolically_first','solve_numerically','check_units']
    result=canonical_analysis(prompt,rc,'rotation_mode','')
    versions={'app':'ABK_PAI_V83','batch':batch.get('version'),'core':core.get('version'),'solver':result.get('version')}
    same=len(set(versions.values()))==1
    answer_ok='31.7' in str(result.get('final_answer',''))
    match_ok=result.get('base_analysis',{}).get('matched_entry_count',0)>0
    return JSONResponse({'version':'ABK_PAI_V83','overall':'PASS' if same and answer_ok and match_ok else 'FAIL','versions':versions,'same_version':same,'indexed_problem_count':len(batch.get('cases',[])),'usable_prompt_count':sum(1 for c in batch.get('cases',[]) if str(c.get('prompt','')).strip()),'source_prompt_gap_count':sum(1 for c in batch.get('cases',[]) if not str(c.get('prompt','')).strip()),'forearm_self_test':{'matched':match_ok,'answer_ok':answer_ok,'final_answer':result.get('final_answer'),'canonical_hash':result.get('canonical_hash')}})

