_V77_BATCH_PATH = PACKAGE_DIR / 'abk_pai' / 'book_batch_trainer_v77.json'
_V77_LAB_DEV_PATH = PACKAGE_DIR / 'abk_pai' / 'expression_lab_development_v77.json'


def _v77_batch() -> Dict[str, Any]:
    try:
        return json.loads(_V77_BATCH_PATH.read_text(encoding='utf-8'))
    except Exception:
        return {'version':'ABK_PAI_V83','summary':{},'source_catalog':[],'families':{},'cases':[]}


def _v76_save_batch(data: Dict[str, Any]) -> None:
    _V77_BATCH_PATH.write_text(json.dumps(data, indent=2), encoding='utf-8')


