@app.post('/api/abk-pai/batch-trainer/status', response_class=JSONResponse)
def abk_batch_status(case_id: str = Form(...), action: str = Form(...), note: str = Form(default='')) -> JSONResponse:
    allowed={'approve','edit','merge','reject','send_to_lab','mark_validated','needs_review'}
    if action not in allowed: raise HTTPException(status_code=400, detail='Unsupported review action')
    data=_v77_batch(); case=next((x for x in data.get('cases',[]) if x.get('id')==case_id),None)
    if not case: raise HTTPException(status_code=404, detail='Problem not found')
    mapping={'approve':'approved','edit':'teacher_edit','merge':'merge_review','reject':'rejected','send_to_lab':'teacher_review','mark_validated':'approved','needs_review':'teacher_review'}
    case['review_status']=mapping[action]
    if action=='mark_validated': case['validation_status']='validated'
    case.setdefault('review_history',[]).append({'action':action,'note':note.strip(),'timestamp':utc_now()})
    _v76_save_batch(data)
    return JSONResponse({'version':'ABK_PAI_V83','saved':True,'case_id':case_id,'review_status':case['review_status'],'validation_status':case.get('validation_status')})


