@app.get('/api/abk-pai/rc-transfer-audit', response_class=JSONResponse)
def abk_rc_transfer_audit() -> JSONResponse:
    results=[]
    for case in _v77_batch().get('cases',[]):
        source=list(case.get('expected_rc',[]) or [])
        loaded=_v49_normalize_tags(source)
        missing=[x for x in source if x not in loaded]
        results.append({'id':case.get('id'),'source_rc_count':len(source),'loaded_rc_count':len(loaded),
                        'status':'PASS' if source==loaded else 'FAIL','missing_rc':missing,
                        'source_rc':source,'loaded_rc':loaded})
    overall='PASS' if results and all(x['status']=='PASS' for x in results) else 'FAIL'
    return JSONResponse({'version':'ABK_PAI_V83','overall':overall,'case_count':len(results),
                         'passed':sum(1 for x in results if x['status']=='PASS'),'results':results})

@app.get('/abk-pai/batch-trainer/load/{case_id}', response_class=HTMLResponse)
def abk_batch_load_case(case_id: str) -> HTMLResponse:
    """Use one server-side transfer path for filtered and full-list selections."""
    case = next((x for x in _v77_batch().get('cases', []) if x.get('id') == case_id), None)
    if not case:
        raise HTTPException(status_code=404, detail='Problem not found')
    prompt = str(case.get('prompt') or '').strip()
    if not prompt:
        prompt = f"{case.get('source_location','')}: {case.get('title','')}".strip(': ')
    source_rc = list(case.get('expected_rc', []) or [])
    loaded_rc = _v49_normalize_tags(source_rc)
    if source_rc != loaded_rc:
        missing = [x for x in source_rc if x not in loaded_rc]
        raise HTTPException(status_code=500, detail='RC transfer integrity failure: ' + ', '.join(missing))
    params = [('q', prompt), ('learning_mode', case.get('mode', 'auto_mode'))]
    params += [('rc', x) for x in loaded_rc]
    params += [('case_id', case_id), ('source_location', case.get('source_location', ''))]
    target = '/abk-pai/expression-lab?' + urllib.parse.urlencode(params)
    return HTMLResponse(f'<meta http-equiv="refresh" content="0; url={h(target)}">')


