_V69_DOMAIN_PACK_PATH = PACKAGE_DIR / 'abk_pai' / 'broad_domain_training_v69.json'

def _v69_domain_pack() -> Dict[str, Any]:
    try:
        return json.loads(_V69_DOMAIN_PACK_PATH.read_text(encoding='utf-8'))
    except Exception:
        return {'version':'ABK_PAI_V83','cases':[]}

@app.get('/api/abk-pai/domain-tests', response_class=JSONResponse)
def abk_api_domain_tests() -> JSONResponse:
    pack=_v69_domain_pack(); results=[]
    for case in pack.get('cases',[]):
        lab=abk_lab_canonical_analysis(case['prompt'],case.get('expected_rc',[]),case.get('mode','ask_tutor'),'')
        student=abk_student_canonical_analysis(case['prompt'],case.get('expected_rc',[]),case.get('mode','ask_tutor'),'')
        answer_ok=str(case.get('final_answer',''))==str(lab.get('final_answer',''))
        parity=lab.get('canonical_hash')==student.get('canonical_hash')
        results.append({'id':case['id'],'domain':case['domain'],'mode':case['mode'],'answer':lab.get('final_answer'),
                        'expected_answer':case.get('final_answer'),'answer_status':'PASS' if answer_ok else 'FAIL',
                        'parity_status':'PASS' if parity else 'FAIL','canonical_hash':lab.get('canonical_hash')})
    overall='PASS' if results and all(x['answer_status']=='PASS' and x['parity_status']=='PASS' for x in results) else 'FAIL'
    return JSONResponse({'version':'ABK_PAI_V83','overall':overall,'case_count':len(results),'results':results})

@app.get('/abk-pai/domain-tests', response_class=HTMLResponse)
def abk_domain_tests() -> HTMLResponse:
    pack=_v69_domain_pack(); cards=[]; pass_count=0
    for case in pack.get('cases',[]):
        record=abk_lab_canonical_analysis(case['prompt'],case.get('expected_rc',[]),case.get('mode','ask_tutor'),'')
        parity=abk_parity_report(case['prompt'],case.get('expected_rc',[]),case.get('mode','ask_tutor'),'')
        ok=record.get('final_answer')==case.get('final_answer') and parity.get('overall')=='PASS'
        pass_count += int(ok)
        eq=''.join(f'<li><code>{h(x)}</code></li>' for x in record.get('governing_equations',[]))
        steps=''.join(f'<li>{h(x)}</li>' for x in record.get('solution_steps',[]))
        cards.append(f'''<article class="card"><h3>{h(case['domain'].replace('_',' ').title())}: {h(case['id'])}</h3>
        <p>{h(case['prompt'])}</p><p><strong>Mode:</strong> {h(case['mode'])}</p>
        <p><strong>Status:</strong> {'PASS' if ok else 'FAIL'} &nbsp; <strong>Hash:</strong> <code>{h(record.get('canonical_hash',''))}</code></p>
        <h4>Equations</h4><ul>{eq}</ul><h4>Solution</h4><ol>{steps}</ol>
        <p><strong>Answer:</strong> {h(record.get('final_answer',''))}</p></article>''')
    body=f'''<section class="hero"><h2>ABK_PAI Volume 89 Broad-Domain Regression Tests</h2>
    <p>The stopping problem remains a frozen regression case. These cases verify that the shared dictionary now recognizes and solves representative problems across multiple domains.</p>
    <div class="cards"><div class="card"><strong>{pass_count}</strong><span>cases passed</span></div><div class="card"><strong>{len(pack.get('cases',[]))}</strong><span>total cases</span></div></div>
    <p class="actions"><a class="button" href="/abk-pai/expression-lab">Train in Lab</a><a class="button" href="/v49-student-ask">Test in Student-AI</a><a class="button secondary" href="/api/abk-pai/domain-tests">JSON results</a></p></section>
    <section class="grid">{''.join(cards)}</section>'''
    return page('ABK_PAI Volume 89 Broad-Domain Tests',body)


@app.get('/api/abk-pai/v80/transfer-parity', response_class=JSONResponse)
def abk_v80_transfer_parity() -> JSONResponse:
    state = _v57_load_active_problem()
    problem = str(state.get('problem_text') or '')
    rc = list(state.get('selected_rc_ids') or [])
    mode = str(state.get('learning_mode') or 'ask_tutor')
    other = str(state.get('other_entries_text') or '')
    recomputed = abk_canonical_analysis(problem, rc, mode, other) if problem else {}
    stored_hash = str(state.get('canonical_hash') or '')
    computed_hash = str(recomputed.get('canonical_hash') or '')
    return JSONResponse({
        'version':'ABK_PAI_V83',
        'overall':'PASS' if problem and stored_hash == computed_hash else 'FAIL',
        'problem_match': bool(problem),
        'mode':mode,
        'rc_count':len(rc),
        'stored_hash':stored_hash,
        'recomputed_hash':computed_hash,
        'chat_reset_policy':'archive_previous_visible_chat_on_new_active_problem',
    })

