def _v84_make_challenge(case: Dict[str, Any], difficulty: str) -> Dict[str, str]:
    solved = _v84_average_speed_solution(case.get('story_text', ''), case.get('physics_question', ''), case.get('givens', ''), case.get('student_attempt', ''))
    if solved:
        if difficulty == 'harder':
            return {'title': 'Two-stage travel challenge', 'prompt': 'A student bicycles 4.0 km in 12 min, rests for 6 min, then bicycles 3.0 km in 10 min. Find the average speed for the entire trip in km/h and m/s.', 'answer': '15.0 km/h = 4.17 m/s'}
        if difficulty == 'transfer':
            major = case.get('major') or 'General Physics'
            return {'title': f'{major} average-speed transfer challenge', 'prompt': 'A field researcher walks 1.8 km along a survey path in 27 min. Find the average speed in km/h and m/s.', 'answer': '4.00 km/h = 1.11 m/s'}
        return {'title': 'Related average-speed challenge', 'prompt': 'A student walks 3.6 km in 45 min. Find the average speed in km/h and m/s.', 'answer': '4.80 km/h = 1.33 m/s'}
    return {'title': 'Related physics challenge', 'prompt': f"Create a clear diagram and identify the givens, unknown, and governing equation for this related context: {case.get('story_text','')}", 'answer': 'Teacher-reviewed response'}

