V85_VERSION = "ABK_PAI_V85"
V85_CANONICAL_PATH = PACKAGE_DIR / "abk_pai" / "canonical_problem_registry_v85.json"
V85_INGEST_PATH = PACKAGE_DIR / "abk_pai" / "problem_ingestion_staging_v85.json"

def _v85_json(path: Path, default: Dict[str, Any]) -> Dict[str, Any]:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default

def _v85_save(path: Path, data: Dict[str, Any]) -> None:
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")

@app.get('/abk-pai/canonical-problems', response_class=HTMLResponse)
def v85_canonical_problems(q: str = Query(''), chapter: str = Query('All'), family: str = Query('All')) -> HTMLResponse:
    data = _v85_json(V85_CANONICAL_PATH, {'records': []})
    records = list(data.get('records', []))
    chapters = sorted({str(x.get('chapter','')) for x in records if x.get('chapter')})
    families = sorted({str(x.get('problem_family','')) for x in records if x.get('problem_family')})
    filtered=[]
    for x in records:
        blob=' '.join(str(x.get(k,'')) for k in ('title','prompt','chapter','problem_family','domain','source_location')).lower()
        if q and q.lower() not in blob: continue
        if chapter!='All' and x.get('chapter')!=chapter: continue
        if family!='All' and x.get('problem_family')!=family: continue
        filtered.append(x)
    cards=[]
    for x in filtered:
        rc=', '.join(x.get('expected_rc') or [])
        cards.append(f"""<section class='panel'><h3>{h(x.get('source_location',''))}: {h(x.get('title',''))}</h3>
        <p>{h(x.get('prompt',''))}</p><p><strong>Domain:</strong> {h(x.get('domain',''))} | <strong>Family:</strong> {h(x.get('problem_family',''))} | <strong>Mode:</strong> {h(x.get('mode',''))}</p>
        <p><strong>RCs:</strong> {h(rc)} | <strong>Status:</strong> {h(x.get('canonical_status',''))} / {h(x.get('approval_status',''))}</p>
        <details><summary>Canonical solution and provenance</summary><pre style='white-space:pre-wrap'>{h(chr(10).join(x.get('solution') or []))}\n\nFinal answer: {h(x.get('final_answer',''))}\n\nHash: {h(x.get('canonical_hash',''))}</pre></details>
        <p class='actions'><a class='button' href='/abk-pai/expression-lab?case_id={quote(str(x.get('id','')))}'>Load into Operational Lab</a><a class='button secondary' href='/abk-pai/lab-development?case_id={quote(str(x.get('id','')))}'>Develop in Lab Workspace</a></p></section>""")
    chapter_opts=''.join(f"<option{' selected' if chapter==v else ''}>{h(v)}</option>" for v in ['All']+chapters)
    family_opts=''.join(f"<option{' selected' if family==v else ''}>{h(v)}</option>" for v in ['All']+families)
    body=f"""<section class='hero'><h1>Canonical Textbook Problem Registry</h1><p>The controlled expert set that tracks the textbook. Every record preserves source, chapter, family, mode, RCs, equations, solution, and canonical hash.</p><p><strong>{len(records)}</strong> canonical seed records; <strong>{len(filtered)}</strong> shown.</p></section>
    <section class='panel'><form method='get'><label>Search<input name='q' value='{h(q)}'></label><label>Chapter<select name='chapter'>{chapter_opts}</select></label><label>Problem family<select name='family'>{family_opts}</select></label><button type='submit'>Apply Filters</button></form><p class='actions'><a class='button secondary' href='/abk-pai/ingestion-staging'>Stage New Problems</a><a class='button secondary' href='/training-tools'>AI Training Tools</a></p></section>{''.join(cards)}"""
    return page('ABK_PAI Volume 89 - Canonical Problem Registry', body)

@app.get('/abk-pai/ingestion-staging', response_class=HTMLResponse)
def v85_ingestion_staging() -> HTMLResponse:
    data=_v85_json(V85_INGEST_PATH, {'queue': [], 'workflow': []})
    rows=[]
    for x in reversed(data.get('queue', [])):
        rows.append(f"""<section class='panel'><h3>{h(x.get('title','Untitled candidate'))}</h3><p><strong>Source:</strong> {h(x.get('source_name',''))} | <strong>Location:</strong> {h(x.get('source_location',''))} | <strong>Status:</strong> {h(x.get('status','staged'))}</p><pre style='white-space:pre-wrap'>{h(x.get('problem_text',''))}</pre><p><strong>AI proposals:</strong> domain={h(x.get('proposed_domain','pending'))}; family={h(x.get('proposed_family','pending'))}; mode={h(x.get('proposed_mode','pending'))}; RCs={h(', '.join(x.get('proposed_rc',[])))}</p><p>Teacher actions: Approve / Edit / Merge / Reject in Lab Development before canonical promotion.</p></section>""")
    flow=' -> '.join(data.get('workflow', []))
    body=f"""<section class='hero'><h1>Controlled Problem Ingestion Staging</h1><p>Register textbook or PDF-derived problem candidates. Staging never promotes a problem automatically.</p><p><strong>Workflow:</strong> {h(flow)}</p></section>
    <section class='panel'><h2>Stage a candidate</h2><form method='post' action='/abk-pai/ingestion-staging'><label>Source filename or book title<input name='source_name' required></label><label>Page, chapter, or problem number<input name='source_location'></label><label>Candidate title<input name='title'></label><label>Problem text<textarea name='problem_text' required rows='6'></textarea></label><label>Proposed domain<input name='proposed_domain'></label><label>Proposed family<input name='proposed_family'></label><label>Proposed learning mode<input name='proposed_mode'></label><label>Proposed RC codes, comma-separated<input name='proposed_rc'></label><button type='submit'>Stage for AI and Teacher Review</button></form></section>{''.join(rows) or '<section class="panel"><p>No staged candidates yet.</p></section>'}"""
    return page('ABK_PAI Volume 89 - Ingestion Staging', body)

@app.post('/abk-pai/ingestion-staging', response_class=HTMLResponse)
def v85_stage_problem(source_name: str = Form(...), source_location: str = Form(''), title: str = Form(''), problem_text: str = Form(...), proposed_domain: str = Form(''), proposed_family: str = Form(''), proposed_mode: str = Form(''), proposed_rc: str = Form('')) -> HTMLResponse:
    data=_v85_json(V85_INGEST_PATH, {'version':V85_VERSION,'workflow':[],'queue':[]})
    queue=data.setdefault('queue',[])
    queue.append({'id':f"staged_{len(queue)+1}",'source_name':source_name.strip(),'source_location':source_location.strip(),'title':title.strip() or 'New problem candidate','problem_text':problem_text.strip(),'proposed_domain':proposed_domain.strip() or 'AI review pending','proposed_family':proposed_family.strip() or 'AI review pending','proposed_mode':proposed_mode.strip() or 'AI review pending','proposed_rc':[x.strip() for x in proposed_rc.split(',') if x.strip()],'status':'staged_teacher_review','created_at':utc_now(),'promotion_allowed':False})
    _v85_save(V85_INGEST_PATH,data)
    return HTMLResponse("<meta http-equiv='refresh' content='0; url=/abk-pai/ingestion-staging'>")

@app.get('/api/v85/canonical-integrity', response_class=JSONResponse)
def v85_canonical_integrity() -> JSONResponse:
    data=_v85_json(V85_CANONICAL_PATH, {'records':[]})
    records=data.get('records',[])
    required={'id','source_book','chapter','problem_number','prompt','domain','mode','problem_family','expected_rc','canonical_hash'}
    incomplete=[x.get('id') for x in records if not required.issubset(x.keys()) or not x.get('prompt')]
    duplicate_ids=[]
    seen=set()
    for x in records:
        i=x.get('id')
        if i in seen: duplicate_ids.append(i)
        seen.add(i)
    return JSONResponse({'version':'ABK_PAI_V89','source_registry_version':'ABK_PAI_V85','strategy':data.get('strategy'),'record_count':len(records),'complete_record_count':len(records)-len(incomplete),'incomplete_records':incomplete,'duplicate_ids':duplicate_ids,'textbook_aligned':True,'controlled_ingestion':True,'automatic_promotion':False,'overall':'PASS' if not incomplete and not duplicate_ids else 'REVIEW'})


