V89_VERSION = "ABK_PAI_V89"

V89_HIDDEN_PREFIXES = ()  # V90 restores Student View alongside Developer View


@app.middleware('http')
async def v89_developer_surface_guard(request: Request, call_next):
    path=request.url.path
    if any(path==x or path.startswith(x) for x in V89_HIDDEN_PREFIXES):
        return RedirectResponse(url='/', status_code=303)
    return await call_next(request)

@app.get('/abk-pai/native-problem-bank-v89-phase1-legacy', response_class=HTMLResponse)
def v89_native_problem_bank(q: str = Query(''), class_id: str = Query('All'), major: str = Query('All'), status: str = Query('All')) -> HTMLResponse:
    data=_v87_load(V87_BANK_PATH,{'problems':[]}); rows=data.get('problems',[])
    classes=sorted({x.get('problem_class_id','') for x in rows}); majors=sorted({x.get('major_context','') for x in rows})
    filtered=[]
    for x in rows:
        blob=' '.join(str(x.get(k,'')) for k in ('problem_id','problem_class','problem_statement','major_context','final_answer')).lower()
        if q and q.lower() not in blob: continue
        if class_id!='All' and x.get('problem_class_id')!=class_id: continue
        if major!='All' and x.get('major_context')!=major: continue
        if status!='All' and x.get('validation_status')!=status: continue
        filtered.append(x)
    cards=[]
    for x in filtered[:200]:
        cards.append(f"""<section class='panel'><h3>{h(x.get('problem_id',''))}: {h(x.get('problem_class',''))}</h3><p><strong>Class:</strong> {h(x.get('problem_class_id',''))} | <strong>Major:</strong> {h(x.get('major_context',''))} | <strong>Status:</strong> {h(x.get('validation_status',''))}</p><p>{h(x.get('problem_statement',''))}</p><details><summary>Developer record</summary><pre style='white-space:pre-wrap'>Model: {h(x.get('physics_model',''))}\nEquations: {h('; '.join(x.get('equation_family',[])))}\nSymbolic: {h(x.get('symbolic_solution',''))}\nNumerical: {h(x.get('numerical_solution',''))}\nFinal answer: {h(x.get('final_answer',''))}\nMisconceptions: {h('; '.join(x.get('common_misconceptions',[])))}</pre></details></section>""")
    co=''.join(f"<option value='{h(v)}'{' selected' if class_id==v else ''}>{h(v)}</option>" for v in ['All']+classes)
    mo=''.join(f"<option value='{h(v)}'{' selected' if major==v else ''}>{h(v)}</option>" for v in ['All']+majors)
    body=f"""<section class='hero'><h2>V89 Native Problem Bank</h2><p>Developer-facing 100-record source layer. Generated records remain pending approval.</p><p><strong>{len(rows)}</strong> total; <strong>{len(filtered)}</strong> shown.</p></section><section class='panel'><form method='get'><label>Search<input name='q' value='{h(q)}'></label><label>Class<select name='class_id'>{co}</select></label><label>Major<select name='major'>{mo}</select></label><button type='submit'>Apply Filters</button></form></section>{''.join(cards)}"""
    return page('ABK_PAI V89 Native Problem Bank',body)

