    for x in rows:
        blob=' '.join(str(x.get(k,'')) for k in ('problem_id','problem_class','problem_statement','major_context')).lower()
        if q and q.lower() not in blob: continue
        if phase!='All' and str(x.get('phase'))!=phase: continue
        if class_id!='All' and x.get('problem_class_id')!=class_id: continue
        if major!='All' and x.get('major_context')!=major: continue
        filtered.append(x)
    cards=''.join(f"<section class='panel'><h3>{h(x.get('problem_id',''))}: {h(x.get('problem_class',''))}</h3><p><strong>Phase:</strong> {h(x.get('phase',''))} | <strong>Major:</strong> {h(x.get('major_context',''))}</p><p>{h(x.get('problem_statement',''))}</p><details><summary>Validated record</summary><pre>{h(x.get('symbolic_solution',''))}\n{h(x.get('numerical_solution',''))}\nAnswer: {h(x.get('final_answer',''))}</pre></details></section>" for x in filtered[:300])
    po=''.join(f"<option{' selected' if phase==v else ''}>{v}</option>" for v in ['All','1','2','3','4','5','6','7']); co=''.join(f"<option{' selected' if class_id==v else ''}>{h(v)}</option>" for v in ['All']+classes); mo=''.join(f"<option{' selected' if major==v else ''}>{h(v)}</option>" for v in ['All']+majors)
    body=f"<section class='hero'><h2>V89 Integrated Native Problem Bank - Phases 1-7</h2><p><strong>{len(rows)}</strong> validated generated problems; <strong>{len(filtered)}</strong> shown.</p></section><section class='panel'><form><label>Search<input name='q' value='{h(q)}'></label><label>Phase<select name='phase'>{po}</select></label><label>Class<select name='class_id'>{co}</select></label><label>Major<select name='major'>{mo}</select></label><button>Apply</button></form></section>{cards}"
    return page('ABK_PAI V89 Phases 1-7',body)

