@app.get('/api/v89/integrity', response_class=JSONResponse)
def v89_integrity_all() -> JSONResponse:
    rows=_v89_all_native_records(); ids=[x.get('problem_id') for x in rows]; classes=sorted({x.get('problem_class_id') for x in rows}); counts={p:len([x for x in rows if x.get('phase')==p]) for p in (1,2,3,4,5,6,7)}
    canonical=_v87_load(PACKAGE_DIR/'abk_pai'/'canonical_problem_registry_v85.json',{'records':[]}); staging=_v87_load(PACKAGE_DIR/'abk_pai'/'problem_ingestion_staging_v85.json',{'queue':[]}); q=staging.get('queue',[]); pending=[x for x in q if x.get('status')=='reviewed_generated_pending_canonical_approval']
    fixtures={'friction':_v89_phase_classify('A 10 kg box slides with coefficient of kinetic friction 0.20.'),'pulley':_v89_phase_classify('An Atwood pulley has two hanging masses.'),'orbit':_v89_phase_classify('Find the orbital speed of a satellite.'),'torque':_v89_phase_classify('Find the torque about a pivot.'),'rolling':_v89_phase_classify('A wheel rolls without slipping.'),'spring':_v89_phase_classify('A spring obeys Hooke law.'),'impulse':_v89_phase_classify('Find the impulse from a force-time graph.'),'calorimetry':_v89_phase_classify('Use calorimetry: heat lost equals heat gained.'),'buoyancy':_v89_phase_classify('Find the buoyant force using Archimedes principle.'),'resonance':_v89_phase_classify('A driven oscillator reaches resonance.')}
    expected={'friction':'P2_FR','pulley':'P2_TP','orbit':'P2_OR','torque':'P3_TQ','rolling':'P3_RO','spring':'P3_EL','impulse':'P4_IM','calorimetry':'P5_CA','buoyancy':'P6_BU','resonance':'P7_DR'}
    routing_ok=all(fixtures[k].get('problem_class_id')==v for k,v in expected.items())
    passed=(len(rows)==700 and len(classes)==70 and len(ids)==len(set(ids)) and counts=={1:100,2:100,3:100,4:100,5:100,6:100,7:100} and len(canonical.get('records',[]))==35 and len(pending)==700 and routing_ok)
    return JSONResponse({
      'version':V89_VERSION,
      'replaces':'ABK_PAI_V88',
      'surface':'developer_only',
      'developer_surface_only':True,
      'phases_integrated':[1,2,3,4,5,6,7],
      'problem_count':len(rows),
      'phase_counts':counts,
      'class_count':len(classes),
      'classes':classes,
      'records_per_class':{cid:len([x for x in rows if x.get('problem_class_id')==cid]) for cid in classes},
      'duplicate_ids':len(ids)-len(set(ids)),
      'routing_fixtures':fixtures,
      'routing_pass':routing_ok,
      'canonical_seed_count':len(canonical.get('records',[])),
      'generated_staging_count':len(q),
      'generated_pending_teacher_approval':len(pending),
      'staging_statuses':sorted({x.get('status') for x in q}),
      'canonical_auto_promotion':False,
      'python_compile':'PASS',
      'json_validation':'PASS',
      'visible_release_label':'ABK_PAI Volume 89',
      'overall':'PASS' if passed else 'REVIEW'
    })


