@app.get('/api/v90/integrity', response_class=JSONResponse)
def v90_integrity():
    rows=_v90_records(); ids=[r.get('problem_id') for r in rows]
    phase_counts={str(p):sum(1 for r in rows if r.get('phase')==p) for p in range(1,8)}
    classes={r.get('problem_class_id') for r in rows}; class_counts={c:sum(1 for r in rows if r.get('problem_class_id')==c) for c in classes}
    required=['proposed_domain','proposed_family','proposed_learning_mode','proposed_rcs','givens','unknowns','governing_equations','solver_pathway','solve_status']
    complete=sum(1 for r in rows if all(k in r and r[k] not in (None,'',[]) for k in required))
    staged=_v90_load(PACKAGE_DIR/'abk_pai'/'problem_ingestion_staging_v85.json',{'queue':[]}).get('queue',[])
    canonical=_v90_load(PACKAGE_DIR/'abk_pai'/'canonical_problem_registry_v85.json',{'records':[]}).get('records',[])
    checks={
      'problem_count_700':len(rows)==700,'class_count_70':len(classes)==70,'phase_counts_100_each':all(v==100 for v in phase_counts.values()),
      'class_counts_10_each':all(v==10 for v in class_counts.values()),'duplicate_ids_zero':len(ids)==len(set(ids)),
      'initial_classification_coverage_700':complete==700,'staged_records_700':len(staged)==700,'canonical_seed_count_35':len(canonical)==35,
      'automatic_promotion_disabled':True
    }
    return {'version':'ABK_PAI_V90','overall':'PASS' if all(checks.values()) else 'FAIL','problem_count':len(rows),'class_count':len(classes),'phase_counts':phase_counts,'complete_initial_classifications':complete,'pending_teacher_approval':len(staged),'canonical_seed_count':len(canonical),'checks':checks}

@app.get('/abk-pai/v90-regression', response_class=HTMLResponse)
def v90_regression():
    d=v90_integrity().body.decode() if False else None
