V92_CLASSIFICATION_PATH = PACKAGE_DIR / "abk_pai" / "initial_classifications_v92.json"
V92_RC_PATH = PACKAGE_DIR / "physics_language_dictionary" / "rc_canonical_registry_v92.json"
V92_MODE_RC_PATH = PACKAGE_DIR / "physics_language_dictionary" / "mode_rc_registry_v92.json"

def _v92_load(path: Path, default):
    try: return json.loads(path.read_text(encoding="utf-8"))
    except Exception: return default

def _v92_records(): return _v92_load(V92_CLASSIFICATION_PATH,{"records":[]}).get("records",[])
def _v92_rc_items(): return _v92_load(V92_RC_PATH,{"items":{}}).get("items",{})
def _v92_modes(): return _v92_load(V92_MODE_RC_PATH,{"modes":{}}).get("modes",{})

def _v92_auto_rcs(problem_statement: str, mode: str):
    modes=_v92_modes(); pool=list(modes.get(mode,{}).get('rc_pool',[])); text=(problem_statement or '').lower(); chosen=[]
    for code in pool[:4]:
        if code not in chosen: chosen.append(code)
    tests={'mass_is_given':[' kg','mass'],'time_is_given':[' s',' min','hour','time'],'distance_is_given':[' km',' m','distance','length'],'height_is_given':['height','vertical'],'angle_is_given':['degree','°','angle'],'force_is_given':[' n','force'],'velocity_is_given':['m/s','speed','velocity'],'acceleration_is_given':['m/s^2','acceleration'],'find_torque':['find the torque','torque about'],'find_pressure':['find the pressure','pressure difference'],'find_flow_rate':['flow rate'],'find_work':['find the work','mechanical work'],'find_power':['find the power','power output'],'friction':['friction','coefficient'],'tension':['tension','rope','cable'],'weight_gravity':['gravity','weight','g ='],'find_acceleration':['find the acceleration'],'find_velocity':['find the speed','find the velocity','how fast'],'find_time':['find the time','how long'],'find_distance':['find the distance','how far']}
    for code,keys in tests.items():
        if code in pool and any(k in text for k in keys) and code not in chosen: chosen.append(code)
    for code in ['solve_symbolically_first','solve_numerically','check_units']:
        if code in pool and code not in chosen: chosen.append(code)
    return chosen[:12]

