@app.get('/abk-pai/staged-classification-v92', response_class=HTMLResponse)
def v92_staging(problem_id: str='', phase: str='', class_id: str=''):
    rows=_v92_records()
    if problem_id: rows=[r for r in rows if r.get('problem_id')==problem_id]
    if phase: rows=[r for r in rows if str(r.get('phase'))==phase]
    if class_id: rows=[r for r in rows if r.get('problem_class_id')==class_id]
    rcitems=_v92_rc_items(); modes=_v92_modes(); domains=sorted({r.get('proposed_domain') for r in _v92_records()}); families=sorted({r.get('proposed_family') for r in _v92_records()})
    def select(name,values,current): return f"<select name='{name}'>"+''.join(f"<option value='{h(v)}' {'selected' if v==current else ''}>{h(v)}</option>" for v in values)+"<option value='__new__'>Other / propose new</option></select>"
    forms=[]
    for r in rows[:50]:
        selected=list(r.get('proposed_rcs',[])); pool=modes.get(r.get('proposed_learning_mode'),{}).get('rc_pool',[])
        chips=''.join(f"<label class='chip removable'><input type='checkbox' name='rcs' value='{h(c)}' checked> {h(rcitems.get(c,{}).get('display_label',c))} ×</label>" for c in selected)
        recommended_groups={}
        for c in pool:
            meta=rcitems.get(c,{}); recommended_groups.setdefault(meta.get('category','other'),[]).append((c,meta.get('display_label',c)))
        recommended=''.join(f"<details class='rc-group' open><summary>Recommended — {h(cat.replace('_',' ').title())} ({len(vals)})</summary>"+''.join(f"<label><input type='checkbox' name='rcs' value='{h(c)}' {'checked' if c in selected else ''}> {h(lbl)}</label>" for c,lbl in vals)+"</details>" for cat,vals in recommended_groups.items())
        all_groups={}
        for c,meta in rcitems.items():
            all_groups.setdefault(meta.get('category','other'),[]).append((c,meta.get('display_label',c)))
        full=''.join(f"<details class='rc-group'><summary>{h(cat.replace('_',' ').title())} ({len(vals)})</summary>"+''.join(f"<label><input type='checkbox' name='rcs' value='{h(c)}' {'checked' if c in selected else ''}> {h(lbl)}</label>" for c,lbl in sorted(vals,key=lambda x:x[1].lower()))+"</details>" for cat,vals in sorted(all_groups.items()))
        menus=recommended+f"<details class='rc-full-registry'><summary>Full RC Registry ({len(rcitems)})</summary>{full}</details>"
        modeopts=''.join(f"<option value='{h(m)}' {'selected' if m==r['proposed_learning_mode'] else ''}>{h(meta.get('label',m))}</option>" for m,meta in modes.items())
        forms.append(f"""<article class='panel'><h3>{h(r['problem_id'])} — {h(r['problem_class'])}</h3><p>{h(r['problem_statement'])}</p><form method='post' action='/api/v92/classification/{h(r['problem_id'])}'><label>Domain{select('domain',domains,r['proposed_domain'])}<input name='new_domain' placeholder='New domain if Other'></label><label>Family{select('family',families,r['proposed_family'])}<input name='new_family' placeholder='New family if Other'></label><label>Learning Mode<select name='mode' id='mode-{h(r['problem_id'])}'>{modeopts}<option value='__new__'>Other / propose new</option></select><input name='new_mode' placeholder='New mode if Other'></label><p><strong>Selected RCs ({len(selected)}):</strong></p><div class='selected-rcs'>{chips or '<em>None selected</em>'}</div><details><summary>Add, remove, or replace RCs — recommendations plus full registry</summary><input class='rc-search' placeholder='Search RCs' oninput="this.parentElement.querySelectorAll('label').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(this.value.toLowerCase())?'block':'none')">{menus}<label>Other / Propose new RC<input name='new_rc' placeholder='New RC code or label'></label></details><button type='submit' name='action' value='save'>Save and Refresh</button><button type='submit' name='action' value='auto'>Auto-select RCs from Context</button></form><p><strong>Confidence:</strong> {r.get('confidence')} &nbsp; <strong>Status:</strong> {h(r.get('solve_status'))}</p></article>""")
    classes=sorted({r['problem_class_id'] for r in _v92_records()})
    filt=f"<section class='panel'><form method='get'><label>Problem ID<input name='problem_id' value='{h(problem_id)}'></label><label>Phase<input name='phase' value='{h(phase)}'></label><label>Class<select name='class_id'><option value=''>All</option>{''.join(f'<option value="{h(c)}" {"selected" if c==class_id else ""}>{h(c)}</option>' for c in classes)}</select></label><button>Filter</button></form></section>"
    return page('ABK_PAI Volume 91 Classification Workspace',f"<section class='hero'><h2>ABK_PAI Volume 91 Generated / Staged Classification</h2><p>Assigned RCs are visible immediately. Remove incorrect RCs, use mode recommendations, or search the complete RC registry to add missing RCs.</p></section>{filt}{''.join(forms)}")

