def _v93_rc_menu(selected=None) -> str:
    selected = set(selected or [])
    items = _v93_rc_items()
    groups = {}
    for code, meta in items.items():
        category = meta.get('category', 'other')
        groups.setdefault(category, []).append((code, meta.get('display_label', code)))
    blocks = []
    for category, vals in sorted(groups.items()):
        options = ''.join(
            f"<label class='rc-option v93-rc-option'><input type='checkbox' name='rc' value='{h(code)}'{' checked' if code in selected else ''}> {h(label)}</label>"
            for code, label in sorted(vals, key=lambda x: x[1].lower())
        )
        blocks.append(f"<details class='rc-group'><summary>{h(category.replace('_',' ').title())} ({len(vals)})</summary><div class='rc-grid'>{options}</div></details>")
    return ''.join(blocks)


