@app.post('/student-view-v93/submit', response_class=HTMLResponse)
def v93_submit_story(
    story_title: str = Form(...),
    physics_topic: str = Form(...),
    physics_topic_other: str = Form(''),
    story_text: str = Form(...),
    learning_mode: str = Form(...),
    mode_other: str = Form(''),
    rc: List[str] = Form([]),
    rc_other: str = Form('')
) -> HTMLResponse:
    _v93_ensure_story_metadata_table()
    title = story_title.strip()
    story = story_text.strip()
    topic = physics_topic_other.strip() if physics_topic == '__other__' else physics_topic.strip()
    if not topic:
        topic = "I don't know"
    final_mode = mode_other.strip() if learning_mode == '__other__' else learning_mode
    if not final_mode:
        final_mode = "I don't know"
    chosen_rcs = list(dict.fromkeys([x for x in rc if x]))
    if rc_other.strip():
        chosen_rcs.append('proposed:' + rc_other.strip())
    question = f"What physics explains this story, and what problem can be solved? Topic selected by student: {topic}"
    corrected = _v84_correct_case(story, question, '', '', final_mode, chosen_rcs)
    now = utc_now()
    with connect() as conn:
        cur = conn.execute(
            "INSERT INTO v84_student_cases(student_name,major,story_text,physics_question,givens,learning_mode,selected_rc_json,student_attempt,corrected_solution,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            ('', topic, story, question, '', final_mode, json.dumps(chosen_rcs), '', corrected['solution'], now, now)
        )
        case_id = int(cur.lastrowid)
        conn.execute(
            "INSERT INTO v93_student_story_metadata(case_id,story_title,physics_topic,physics_topic_other,mode_other,rc_other,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)",
            (case_id, title, topic, physics_topic_other.strip(), mode_other.strip(), rc_other.strip(), now, now)
        )
        conn.commit()
    return RedirectResponse(f'/student-learning-chat?case_id={case_id}', status_code=303)


