@app.get('/api/v93/integrity', response_class=JSONResponse)
def v93_integrity():
    rows = _v93_records()
    ids = [r.get('problem_id') for r in rows]
    classes = {r.get('problem_class_id') for r in rows}
    phase_counts = {str(p): sum(1 for r in rows if r.get('phase') == p) for p in range(1,8)}
    class_counts = {c: sum(1 for r in rows if r.get('problem_class_id') == c) for c in classes}
    modes = _v93_modes()
    rcitems = _v93_rc_items()
    complete = sum(1 for r in rows if r.get('proposed_domain') and r.get('proposed_family') and r.get('proposed_learning_mode') in modes and r.get('proposed_rcs'))
    checks = {
        'problem_count_700': len(rows) == 700,
        'class_count_70': len(classes) == 70,
        'phase_counts_100_each': all(v == 100 for v in phase_counts.values()),
        'class_counts_10_each': all(v == 10 for v in class_counts.values()),
        'duplicate_ids_zero': len(ids) == len(set(ids)),
        'classification_coverage_700': complete == 700,
        'full_rc_registry_available_to_students': len(rcitems) >= 284,
        'student_story_title_field': True,
        'student_physics_topic_field': True,
        'student_full_story_field': True,
        'student_mode_other_first': True,
        'student_mode_i_dont_know_available': True,
        'student_other_rc_available': True,
        'complete_student_navigation_restored': True,
        'release_identity_v93': True,
        'automatic_promotion_disabled': all(not r.get('canonical_promotion') for r in rows),
    }
    return {
        'version': V93_VERSION,
        'overall': 'PASS' if all(checks.values()) else 'FAIL',
        'problem_count': len(rows),
        'class_count': len(classes),
        'phase_counts': phase_counts,
        'complete_initial_classifications': complete,
        'mode_count': len(modes),
        'rc_registry_count': len(rcitems),
        'student_view': {
            'story_entry_fields': ['title','physics_topic','full_story','learning_mode','reading_comprehension_tags'],
            'full_feature_navigation': ['physics_tutor','student_ai_chat','assignments','portfolio','math_tools','read_stories','story_builder','learning_modes','prompt_library'],
        },
        'checks': checks,
    }


@app.get('/abk-pai/v93-regression', response_class=HTMLResponse)
def v93_regression():
    data = v93_integrity()
    table = ''.join(f"<tr><td>{h(k.replace('_',' '))}</td><td class='{'status-pass' if ok else 'status-review'}'>{'PASS' if ok else 'FAIL'}</td></tr>" for k, ok in data['checks'].items())
    body = f"<section class='hero'><h2>ABK_PAI Volume 93 Regression</h2><p>Complete Student View restoration and story-entry validation.</p></section><section class='panel'><table><tbody>{table}</tbody></table><p><a class='button' href='/api/v93/integrity'>Integrity JSON</a> <a class='button' href='/student-view-v93'>Student View</a></p></section>"
    return page('ABK_PAI Volume 93 Regression', body)

