def _v94_ensure_tables() -> None:
    with connect() as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS v94_assignment_submissions(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          assignment_key TEXT NOT NULL,
          problem_id TEXT DEFAULT '',
          source_type TEXT DEFAULT '',
          selected_mode TEXT DEFAULT '',
          selected_rc_json TEXT DEFAULT '[]',
          student_reasoning TEXT DEFAULT '',
          student_solution TEXT DEFAULT '',
          comparison_json TEXT DEFAULT '{}',
          status TEXT DEFAULT 'submitted',
          created_at TEXT DEFAULT '',
          updated_at TEXT DEFAULT ''
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS v94_student_story_metadata(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          case_id INTEGER NOT NULL,
          physics_topics_json TEXT DEFAULT '[]',
          learning_mode TEXT DEFAULT '',
          selected_rc_json TEXT DEFAULT '[]',
          teacher_comment TEXT DEFAULT '',
          created_at TEXT DEFAULT '',
          updated_at TEXT DEFAULT ''
        )""")
        conn.commit()


@app.on_event('startup')
def _v94_startup() -> None:
    _v94_ensure_tables()


def _v94_mode_options(selected: str='') -> str:
    opts = ["<option value=''>Choose the learning mode</option>", "<option value='auto_mode'>I am not sure — ask for guidance</option>"]
    for code, meta in sorted(_v93_modes().items(), key=lambda x: x[1].get('label', x[0]).lower()):
        opts.append(f"<option value='{h(code)}'{' selected' if code == selected else ''}>{h(meta.get('label', code))}</option>")
    return ''.join(opts)


def _v94_rc_menu(name: str='selected_rc', selected=None, prefix: str='v94') -> str:
    selected = set(selected or [])
    groups = {}
    for code, meta in _v93_rc_items().items():
        groups.setdefault(meta.get('category', 'other'), []).append((code, meta.get('display_label', code)))
    blocks=[]
    for cat, vals in sorted(groups.items()):
        options=''.join(f"<label class='rc-option {prefix}-rc-option'><input type='checkbox' name='{h(name)}' value='{h(code)}'{' checked' if code in selected else ''}> {h(label)}</label>" for code,label in sorted(vals,key=lambda x:x[1].lower()))
        blocks.append(f"<details class='rc-group'><summary>{h(cat.replace('_',' ').title())} ({len(vals)})</summary><div class='rc-grid'>{options}</div></details>")
    return ''.join(blocks)


def _v94_default_assignments() -> List[Dict[str, Any]]:
    rows = _v93_records()
    # Balanced deterministic sample: two records from each phase, preserving approved metadata.
    chosen=[]
    for phase in range(1,8):
        chosen.extend([r for r in rows if r.get('phase') == phase][:2])
    return chosen


def _v94_teacher_assignments() -> List[Dict[str, Any]]:
    try:
        return json.loads(V94_TEACHER_ASSIGNMENTS_PATH.read_text(encoding='utf-8')).get('assignments', [])
    except Exception:
        return []


def _v94_save_teacher_assignments(rows: List[Dict[str, Any]]) -> None:
    V94_TEACHER_ASSIGNMENTS_PATH.write_text(json.dumps({'version':'ABK_PAI_V94','assignments':rows}, indent=2), encoding='utf-8')


