@app.get('/student-assignments-v94', response_class=HTMLResponse)
def v94_student_assignments(problem_id: str = Query(default='')) -> HTMLResponse:
    _v94_ensure_tables()
    records = _v94_default_assignments()
    teacher_ids = [x.get('problem_id') for x in _v94_teacher_assignments()]
    by_id = {r.get('problem_id'):r for r in _v93_records()}
    records += [by_id[x] for x in teacher_ids if x in by_id and x not in {r.get('problem_id') for r in records}]
    if problem_id:
        records = [r for r in records if r.get('problem_id') == problem_id]
    cards=[]
    for r in records:
        expected_rc = list(r.get('proposed_rcs') or [])
        cards.append(f"""
        <section class='panel' id='{h(r.get('problem_id'))}'>
          <h3>{h(r.get('problem_id'))} — {h(r.get('problem_class'))}</h3>
          <p><strong>Source:</strong> {'Teacher selected' if r.get('problem_id') in teacher_ids else 'AI default from the approved 700-problem bank'} | <strong>Major/context:</strong> {h(r.get('major_context','General Physics'))}</p>
          <p>{h(r.get('problem_statement',''))}</p>
          <form method='post' action='/student-assignments-v94/{h(r.get('problem_id'))}/submit'>
            <label><strong>1. Decide the Learning Mode</strong><select name='selected_mode' required>{_v94_mode_options()}</select></label>
            <fieldset><legend><strong>2. Decide which RCs are needed</strong></legend>
              <input type='search' placeholder='Search RCs' oninput="const q=this.value.toLowerCase();this.parentElement.querySelectorAll('.v94a-rc-option').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'block':'none')">
              {_v94_rc_menu(prefix='v94a')}
            </fieldset>
            <label><strong>3. Explain your classification</strong><textarea name='student_reasoning' rows='4' required placeholder='Why does this mode apply? Why are these RCs needed?'></textarea></label>
            <label><strong>4. Solve the assignment</strong><textarea name='student_solution' rows='7' required placeholder='Show the model, governing equation, substitution, units, answer, and interpretation.'></textarea></label>
            <button type='submit'>Submit Classification and Solution</button>
            <a class='button secondary' href='/prompt-library-v94?context=assignment'>Open Assignment Prompts</a>
          </form>
          <details><summary>Teacher/AI reference metadata (revealed after the student has made a decision)</summary><p><strong>Expected mode:</strong> {h(r.get('proposed_learning_mode',''))}</p><p><strong>Expected RC count:</strong> {len(expected_rc)}</p></details>
        </section>""")
    body = _v94_student_nav() + "<section class='hero'><h2>Assignments</h2><p>Every assignment requires two kinds of work: classify the physics by choosing a Learning Mode and RCs, then solve and explain the problem.</p></section>" + ''.join(cards)
    return page('ABK_PAI V94 Assignments', body)


@app.post('/student-assignments-v94/{problem_id}/submit', response_class=HTMLResponse)
def v94_submit_assignment(problem_id: str, selected_mode: str = Form(...), selected_rc: List[str] = Form([]), student_reasoning: str = Form(...), student_solution: str = Form(...)) -> HTMLResponse:
    _v94_ensure_tables()
    r = next((x for x in _v93_records() if x.get('problem_id') == problem_id), None)
    if not r:
        raise HTTPException(404, 'Approved problem not found')
    expected_mode = r.get('proposed_learning_mode','')
    expected_rc = list(r.get('proposed_rcs') or [])
    chosen = list(dict.fromkeys(selected_rc))
    comparison = {
      'expected_mode': expected_mode,
      'student_mode': selected_mode,
      'mode_match': selected_mode == expected_mode,
      'expected_rcs': expected_rc,
      'student_rcs': chosen,
      'matched_rcs': [x for x in chosen if x in expected_rc],
      'missing_expected_rcs': [x for x in expected_rc if x not in chosen],
      'additional_student_rcs': [x for x in chosen if x not in expected_rc]
    }
    now=utc_now()
    with connect() as conn:
        conn.execute("INSERT INTO v94_assignment_submissions(assignment_key,problem_id,source_type,selected_mode,selected_rc_json,student_reasoning,student_solution,comparison_json,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)", (problem_id, problem_id, 'approved_700', selected_mode, json.dumps(chosen), student_reasoning.strip(), student_solution.strip(), json.dumps(comparison), 'submitted_for_teacher_review', now, now))
        conn.commit()
    feedback = f"""{_v94_student_nav()}<section class='panel'><h2>Assignment Submitted</h2><p>Your classification and solution were saved for teacher review.</p><p><strong>Learning Mode comparison:</strong> {'Match' if comparison['mode_match'] else 'Review needed'}</p><p><strong>RCs matched:</strong> {len(comparison['matched_rcs'])} | <strong>Expected RCs not selected:</strong> {len(comparison['missing_expected_rcs'])} | <strong>Additional RCs selected:</strong> {len(comparison['additional_student_rcs'])}</p><p>The teacher can comment on both your physics solution and your classification decisions.</p><a class='button' href='/student-assignments-v94'>Return to Assignments</a></section>"""
    return page('Assignment Submitted', feedback)


@app.get('/teacher/assign-problems-v94', response_class=HTMLResponse)
def v94_teacher_assign_problem(q: str = Query(default='')) -> HTMLResponse:
    rows = _v93_records()
    if q:
        rows=[r for r in rows if q.lower() in (str(r.get('problem_id',''))+' '+str(r.get('problem_statement',''))+' '+str(r.get('problem_class',''))).lower()]
    cards=''.join(f"<article class='card'><h3>{h(r.get('problem_id'))}</h3><p>{h(r.get('problem_statement'))}</p><p><strong>Mode:</strong> {h(r.get('proposed_learning_mode'))} | <strong>RCs:</strong> {len(r.get('proposed_rcs') or [])}</p><form method='post' action='/teacher/assign-problems-v94'><input type='hidden' name='problem_id' value='{h(r.get('problem_id'))}'><button>Assign to Student View</button></form></article>" for r in rows[:100])
    body=f"<section class='hero'><h2>Teacher Problem Assignment</h2><p>Select canonical or approved problems from the 700-problem bank. Students must decide the Learning Mode and RCs before solving.</p></section><section class='panel'><form method='get'><label>Search approved bank<input name='q' value='{h(q)}'></label><button>Search</button></form></section><section class='dev-grid'>{cards}</section>"
    return page('V94 Teacher Assignment Selection', body)


@app.post('/teacher/assign-problems-v94', response_class=HTMLResponse)
def v94_teacher_assign_problem_post(problem_id: str = Form(...)) -> HTMLResponse:
    r=next((x for x in _v93_records() if x.get('problem_id') == problem_id), None)
    if not r: raise HTTPException(404,'Problem not found')
    rows=_v94_teacher_assignments()
    if problem_id not in [x.get('problem_id') for x in rows]:
        rows.append({'problem_id':problem_id,'assigned_at':utc_now(),'status':'active'})
        _v94_save_teacher_assignments(rows)
    return RedirectResponse('/teacher/assign-problems-v94', status_code=303)


