@app.get('/story-builder-v94', response_class=HTMLResponse)
def v94_story_builder(story_prompt: str = Query(default=''), title: str = Query(default=''), topic: str = Query(default='')) -> HTMLResponse:
    topic_boxes=''.join(f"<label class='rc-option'><input type='checkbox' name='physics_topics' value='{h(x)}'{' checked' if x==topic else ''}> {h(x)}</label>" for x in V94_TOPICS)
    body=_v94_student_nav()+f"""
    <section class='panel'><h2>Write and Submit a Student Physics Story</h2><p>Write your own situation. You must decide one or more physics topics, a Learning Mode, and the RCs. The AI may suggest or explain choices, while the teacher reviews and comments.</p>
    <form method='post' action='/story-builder-v94/submit' class='story-form'>
      <label>Story title<input name='story_title' required value='{h(title)}'></label>
      <label>Student name<input name='student_name'></label>
      <label>Full story<textarea name='story_text' rows='9' required>{h(story_prompt)}</textarea></label>
      <fieldset><legend><strong>Select one or more physics topics</strong></legend><div class='rc-grid'>{topic_boxes}</div><label>Other topic<input name='topic_other'></label></fieldset>
      <label><strong>Select the Learning Mode</strong><select name='learning_mode' required>{_v94_mode_options()}</select></label>
      <fieldset><legend><strong>Select the RCs</strong></legend><input type='search' placeholder='Search RCs' oninput="const q=this.value.toLowerCase();this.parentElement.querySelectorAll('.v94s-rc-option').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'block':'none')">{_v94_rc_menu(prefix='v94s')}</fieldset>
      <label>Student explanation or first solution idea<textarea name='student_attempt' rows='6' placeholder='Explain the physics, propose a question, sketch a model, or begin a solution.'></textarea></label>
      <div class='actions'><button name='action' value='submit'>Save and Submit to Teacher</button><button class='secondary' name='action' value='draft'>Save as Draft</button><a class='button secondary' href='/prompt-library-v94?context=story'>Open Story Prompts</a></div>
    </form></section>"""
    return page('ABK_PAI V94 Story Builder', body)


@app.post('/story-builder-v94/submit', response_class=HTMLResponse)
def v94_story_builder_submit(story_title: str=Form(...), student_name: str=Form(''), story_text: str=Form(...), physics_topics: List[str]=Form([]), topic_other: str=Form(''), learning_mode: str=Form(...), selected_rc: List[str]=Form([]), student_attempt: str=Form(''), action: str=Form('submit')) -> HTMLResponse:
    _v94_ensure_tables()
    topics=list(dict.fromkeys(physics_topics + ([topic_other.strip()] if topic_other.strip() else [])))
    if not topics: topics=['I do not know yet']
    rcs=list(dict.fromkeys(selected_rc))
    now=utc_now(); status='draft' if action=='draft' else 'submitted_for_teacher_review'
    question='What physics explains this story, and what question can be modeled or solved? Student-selected topics: '+', '.join(topics)
    corrected=_v84_correct_case(story_text, question, '', student_attempt, learning_mode, rcs)
    with connect() as conn:
        cur=conn.execute("INSERT INTO v84_student_cases(student_name,major,story_text,physics_question,givens,learning_mode,selected_rc_json,student_attempt,corrected_solution,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)", (student_name.strip(), ', '.join(topics), story_text.strip(), question, '', learning_mode, json.dumps(rcs), student_attempt.strip(), corrected.get('solution',''), now, now))
        case_id=int(cur.lastrowid)
        conn.execute("INSERT INTO v94_student_story_metadata(case_id,physics_topics_json,learning_mode,selected_rc_json,teacher_comment,created_at,updated_at) VALUES(?,?,?,?,?,?,?)", (case_id,json.dumps(topics),learning_mode,json.dumps(rcs),'',now,now))
        conn.commit()
    target=f'/student-learning-chat?case_id={case_id}' if status!='draft' else '/student-portfolio'
    return RedirectResponse(target,status_code=303)


