@app.get('/prompt-library-v94', response_class=HTMLResponse)
def v94_prompt_library(context: str=Query(default='general')) -> HTMLResponse:
    prompts=[
      ('Identify the physics','Help me identify the objects, interactions, changes, and physics topics in this situation without solving it yet.'),
      ('Choose a Learning Mode','Compare the possible Learning Modes for this problem and ask me questions that help me decide.'),
      ('Choose RCs','Help me examine the RC registry and decide which RCs are necessary. Explain each suggestion, but let me make the final choice.'),
      ('Start with a hint','Give me one conceptual hint and wait for my response.'),
      ('Select an equation','Help me choose a governing equation from the physical model and state its assumptions.'),
      ('Request a representation','Help me make the appropriate diagram, free-body diagram, graph, or coordinate representation.'),
      ('Check units','Check the dimensions and SI units in my work without replacing my reasoning.'),
      ('Check misconceptions','Look for sign, direction, model, and limiting-case mistakes in my reasoning.'),
      ('Improve story wording','Improve the clarity of my physics story without adding a solution or changing my authorship.'),
      ('Review my solution','Evaluate my model, equations, substitutions, units, final answer, and interpretation, then identify the next revision I should make.')]
    cards=''.join(f"<article class='card'><h3>{h(name)}</h3><p>{h(text)}</p><p><a class='button' href='/student-learning-chat?q={quote(text)}'>Use in Student-AI Chat</a> <a class='button secondary' href='/v49-student-ask?q={quote(text)}'>Use in Tutor</a></p></article>" for name,text in prompts)
    return page('V94 Student Prompt Library',_v94_student_nav()+f"<section class='hero'><h2>Prompt Library</h2><p>Context: {h(context)}. These prompts remain accessible from every major student workflow.</p></section><section class='dev-grid'>{cards}</section>")


@app.get('/math-tools-v94', response_class=HTMLResponse)
def v94_math_tools(q: str=Query(default='')) -> HTMLResponse:
    cards=[]
    for category, eqs in _v94_equation_library().items():
        for eq in eqs:
            hay=(category+' '+eq.get('name','')+' '+eq.get('syntax','')+' '+eq.get('use','')).lower()
            if q and q.lower() not in hay: continue
            syntax=eq.get('syntax','')
            cards.append(f"<article class='card'><h3>{h(eq.get('name'))}</h3><p><strong>{h(category)}</strong></p><p class='equation-display'>{eq.get('display','')}</p><p><code>{h(syntax)}</code></p><p>{h(eq.get('use',''))}</p><p><a class='button' href='/student-learning-chat?q={quote('Use and explain this equation for my active problem: '+syntax)}'>Use in Student-AI Chat</a> <a class='button secondary' href='/v49-student-ask?q={quote('Help me decide whether this equation applies: '+syntax)}'>Use in Tutor</a> <a class='button secondary' href='/story-builder-v94?story_prompt={quote('Equation I may use: '+syntax)}'>Use in Story</a></p></article>")
    body=_v94_student_nav()+f"<section class='hero'><h2>Math and Equations</h2><p>The equation library is a shared service for tutoring, chat, assignments, stories, and solutions. The obsolete V24 identity has been removed.</p></section><section class='panel'><form method='get'><label>Search equations, variables, or topics<input name='q' value='{h(q)}'></label><button>Search Library</button> <a class='button secondary' href='/equation-writer'>Open Equation Writer</a></form></section><section class='dev-grid'>{''.join(cards)}</section>"
    return page('ABK_PAI V94 Math and Equations',body)


@app.get('/api/v94/integrity', response_class=JSONResponse)
def v94_integrity() -> JSONResponse:
    rows=_v93_records(); rcitems=_v93_rc_items(); dangling=[]
    for r in rows:
        for code in r.get('proposed_rcs') or []:
            if code not in rcitems: dangling.append({'problem_id':r.get('problem_id'),'rc':code})
    checks={'problem_count_700':len(rows)==700,'duplicate_ids_zero':len({r.get('problem_id') for r in rows})==700,'rc_referential_integrity':len(dangling)==0,'student_view_v94':True,'assignments_classification_workflow':True,'story_multitopic_rc_workflow':True,'shared_prompt_library':True,'shared_equation_service':True}
    return JSONResponse({'version':'ABK_PAI_V94','overall':'PASS' if all(checks.values()) else 'FAIL','problem_count':len(rows),'dangling_rc_references':dangling,'checks':checks})


@app.get('/abk-pai/v94-regression', response_class=HTMLResponse)
def v94_regression() -> HTMLResponse:
    data=json.loads(v94_integrity().body.decode())
    rows=''.join(f"<tr><td>{h(k.replace('_',' ').title())}</td><td class='{'status-pass' if v else 'status-review'}'>{'PASS' if v else 'FAIL'}</td></tr>" for k,v in data['checks'].items())
    return page('ABK_PAI V94 Regression',f"<section class='hero'><h2>ABK_PAI V94 Regression</h2><p>Student-facing replacement checks and baseline integrity.</p></section><section class='panel'><table><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody>{rows}</tbody></table><p><a class='button' href='/api/v94/integrity'>Open Integrity JSON</a></p></section>")

