def _v94_equation_library() -> Dict[str, List[Dict[str, str]]]:
    merged={k:list(v) for k,v in EQUATION_LIBRARY.items()}
    for category, equations in V94_EXTENDED_EQUATIONS.items():
        merged.setdefault(category,[]).extend(equations)
    return merged


