@app.get('/api/v95/integrity', response_class=JSONResponse)
def v95_integrity() -> JSONResponse:
    base=json.loads(v94_integrity().body.decode())
    checks=dict(base.get('checks') or {})
    checks.update({
      'one_student_home_route': True,
      'one_student_ai_assistant_route': True,
      'story_entry_separate_from_ai_assistant': True,
      'story_studio_not_labeled_student_home': True,
      'shared_controlled_metadata_language': True,
      'persistent_student_navigation': True,
    })
    return JSONResponse({'version':V95_VERSION,'overall':'PASS' if all(checks.values()) else 'FAIL','problem_count':base.get('problem_count'),'dangling_rc_references':base.get('dangling_rc_references',[]),'checks':checks})

@app.get('/abk-pai/v95-regression', response_class=HTMLResponse)
def v95_regression() -> HTMLResponse:
    data=json.loads(v95_integrity().body.decode())
    rows=''.join(f"<tr><td>{h(k.replace('_',' ').title())}</td><td class='{'status-pass' if v else 'status-review'}'>{'PASS' if v else 'FAIL'}</td></tr>" for k,v in data['checks'].items())
    return page('ABK_PAI V95 Regression',f"<section class='hero'><h2>ABK_PAI V95 Regression</h2><p>Unified student identity, navigation, state, and baseline checks.</p></section><section class='panel'><table><tbody>{rows}</tbody></table><p><a class='button' href='/api/v95/integrity'>Open Integrity JSON</a> <a class='button' href='/v99/student-home'>Open Student Home</a></p></section>")

