V96_VERSION = "ABK_PAI_V96"
V96_ASSIGNMENTS_PATH = PACKAGE_DIR / 'abk_pai' / 'v96_teacher_assignments.json'


def _v96_student_nav(active: str='') -> str:
    items=[
      ('home','/student-home-v96','Student Home'),
      ('tutor','/physics-tutor-v96','Physics Tutor'),
      ('assignments','/student-assignments-v96','Assignments'),
      ('portfolio','/student-portfolio-v96','My Portfolio'),
      ('math','/math-equations-v96','Math and Equations'),
      ('stories','/physics-stories-v96','Physics Stories'),
      ('write','/story-builder-v94','Write a Physics Story'),
      ('prompts','/prompt-library-v96','Prompt Library'),
    ]
    return "<nav class='quick-chat v96-nav' aria-label='Student navigation'>"+''.join(
      f"<a class='button small{' secondary' if key!=active else ''}' href='{url}'>{label}</a>" for key,url,label in items
    )+"</nav>"


def _v96_teacher_nav(active: str='') -> str:
    items=[('home','/teacher-home-v96','Teacher Home'),('builder','/teacher-assignment-builder-v96','Assignment Builder'),('assigned','/teacher-assigned-work-v96','Assigned Work'),('submissions','/teacher-submissions-v96','Student Submissions'),('bank','/abk-pai/native-problem-bank-v93','Problem Bank'),('student','/student-home-v96','Student Home')]
    return "<nav class='quick-chat' aria-label='Teacher navigation'>"+''.join(f"<a class='button small{' secondary' if key!=active else ''}' href='{url}'>{label}</a>" for key,url,label in items)+"</nav>"


def _v96_load_assignments() -> List[Dict[str,Any]]:
    try:
        data=json.loads(V96_ASSIGNMENTS_PATH.read_text(encoding='utf-8'))
        return list(data.get('assignments',[]))
    except Exception:
        return []


def _v96_save_assignments(rows: List[Dict[str,Any]]) -> None:
    V96_ASSIGNMENTS_PATH.write_text(json.dumps({'version':V96_VERSION,'assignments':rows},indent=2),encoding='utf-8')


def _v96_record_map() -> Dict[str,Dict[str,Any]]:
    return {str(r.get('problem_id')):r for r in _v93_records()}


def _v96_assigned_records(active_only: bool=True) -> List[Dict[str,Any]]:
    byid=_v96_record_map(); out=[]
    for a in _v96_load_assignments():
        if active_only and str(a.get('status','active')).lower()!='active': continue
        pid=str(a.get('problem_id',''))
        if pid in byid:
            r=dict(byid[pid]); r['_assignment']=a; out.append(r)
    return out


def _v96_ensure_tables() -> None:
    _v94_ensure_tables()
    with connect() as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS v96_assignment_submissions(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          problem_id TEXT NOT NULL,
          student_name TEXT DEFAULT '',
          selected_mode TEXT DEFAULT '',
          selected_rc_json TEXT DEFAULT '[]',
          known_information TEXT DEFAULT '',
          equations_used TEXT DEFAULT '',
          representation TEXT DEFAULT '',
          symbolic_work TEXT DEFAULT '',
          numerical_work TEXT DEFAULT '',
          interpretation TEXT DEFAULT '',
          final_answer TEXT DEFAULT '',
          status TEXT DEFAULT 'submitted',
          teacher_feedback TEXT DEFAULT '',
          created_at TEXT DEFAULT '')""")
        conn.commit()


@app.on_event('startup')
def _v96_startup() -> None:
    _v96_ensure_tables()
    if not V96_ASSIGNMENTS_PATH.exists():
        legacy=_v94_teacher_assignments()
        _v96_save_assignments([dict(x, status=x.get('status','active')) for x in legacy])


