@app.get('/teacher-assignment-builder-v96', response_class=HTMLResponse)
def v96_teacher_assignment_builder(q: str=Query(''), phase: str=Query('')) -> HTMLResponse:
    rows=_v93_records(); low=q.lower().strip()
    if low: rows=[r for r in rows if low in (str(r.get('problem_id'))+' '+str(r.get('problem_statement'))+' '+str(r.get('problem_class'))+' '+str(r.get('major_context'))).lower()]
    if phase.isdigit(): rows=[r for r in rows if int(r.get('phase',0))==int(phase)]
    assigned={a.get('problem_id') for a in _v96_load_assignments() if a.get('status')=='active'}
    cards=[]
    for r in rows[:100]:
        pid=str(r.get('problem_id')); action='Already Assigned' if pid in assigned else 'Assign to Students'
        disabled=' disabled' if pid in assigned else ''
        cards.append(f"<article class='card'><h3>{h(pid)} — {h(r.get('problem_class'))}</h3><p>{h(r.get('problem_statement'))}</p><p><strong>Phase:</strong> {h(r.get('phase'))} | <strong>Context:</strong> {h(r.get('major_context'))}</p><form method='post' action='/teacher-assignment-builder-v96/assign'><input type='hidden' name='problem_id' value='{h(pid)}'><label>Teacher directions<input name='directions' placeholder='Optional directions or required representation'></label><button{disabled}>{action}</button></form><details><summary>Authoritative teacher/system reference</summary><p><strong>Mode:</strong> {h(r.get('proposed_learning_mode'))}</p><p><strong>RCs:</strong> {h(', '.join(r.get('proposed_rcs') or []))}</p><p><strong>Equations:</strong> {h('; '.join(r.get('governing_equations') or []))}</p><p><strong>Solution:</strong> {h(r.get('preliminary_solution'))}</p><p><strong>Final answer:</strong> {h(r.get('final_answer'))}</p></details></article>")
    body=_v96_teacher_nav('builder')+f"<section class='hero'><h2>Teacher Assignment Builder</h2><p>Assignments are populated only by the teacher from the approved 700-problem bank.</p><form method='get'><input name='q' value='{h(q)}' placeholder='Search problem, class, context, or wording'><select name='phase'><option value=''>All phases</option>{''.join(f'<option value={i}'+(' selected' if phase==str(i) else '')+f'>Phase {i}</option>' for i in range(1,8))}</select><button>Filter</button></form></section><section class='dev-grid'>{''.join(cards)}</section>"
    return page('Teacher Assignment Builder',body)


@app.post('/teacher-assignment-builder-v96/assign', response_class=HTMLResponse)
def v96_teacher_assign(problem_id: str=Form(...), directions: str=Form('')) -> RedirectResponse:
    rows=_v96_load_assignments()
    if problem_id not in {x.get('problem_id') for x in rows}:
        rows.append({'problem_id':problem_id,'directions':directions,'assigned_at':datetime.now(timezone.utc).isoformat(),'status':'active'})
    else:
        for x in rows:
            if x.get('problem_id')==problem_id: x.update({'directions':directions,'status':'active'})
    _v96_save_assignments(rows)
    return RedirectResponse('/teacher-assigned-work-v96',status_code=303)


