def v96_teacher_assigned_work() -> HTMLResponse:
    byid=_v96_record_map(); cards=[]
    for a in _v96_load_assignments():
        r=byid.get(a.get('problem_id'),{})
        cards.append(f"<article class='card'><h3>{h(a.get('problem_id'))} — {h(r.get('problem_class','Unknown'))}</h3><p>{h(r.get('problem_statement',''))}</p><p><strong>Status:</strong> {h(a.get('status'))}</p><p><strong>Directions:</strong> {h(a.get('directions') or 'None')}</p><form method='post' action='/teacher-assigned-work-v96/status'><input type='hidden' name='problem_id' value='{h(a.get('problem_id'))}'><select name='status'><option value='active'>Active</option><option value='closed'>Closed</option></select><button>Update</button></form></article>")
    return page('Assigned Work',_v96_teacher_nav('assigned')+f"<section class='hero'><h2>Assigned Work</h2><p>{len(cards)} teacher-selected assignment records.</p></section><section class='dev-grid'>{''.join(cards) or '<p>No assignments selected.</p>'}</section>")


