V97_VERSION = "ABK_PAI_V97"
V97_ASSIGNMENTS_PATH = PACKAGE_DIR / 'abk_pai' / 'v97_teacher_assignments.json'


def _v97_student_nav(active: str='') -> str:
    items=[('home','/student-home-v97','Student Home'),('tutor','/physics-tutor-v97','Physics Tutor'),('assignments','/student-assignments-v97','Assignments'),('portfolio','/student-portfolio-v97','My Portfolio'),('math','/math-equations-v97','Math and Equations'),('stories','/physics-stories-v97','Physics Stories'),('write','/story-builder-v94','Write a Physics Story'),('prompts','/prompt-library-v97','Prompt Library')]
    return "<nav class='quick-chat v97-nav' aria-label='Student navigation'>"+''.join(f"<a class='button small{' secondary' if key!=active else ''}' href='{url}'>{label}</a>" for key,url,label in items)+"</nav>"


def _v97_teacher_nav(active: str='') -> str:
    items=[('home','/teacher-home-v97','Teacher Home'),('builder','/teacher-assignment-builder-v97','Assignment Builder'),('assigned','/teacher-assigned-work-v97','Assigned Work'),('submissions','/teacher-submissions-v97','Student Submissions'),('preview','/teacher-student-preview-v97','Student Preview'),('developer','/developer-home-v97','Developer Home'),('student','/student-home-v97','Student Home')]
    return "<nav class='quick-chat' aria-label='Teacher navigation'>"+''.join(f"<a class='button small{' secondary' if key!=active else ''}' href='{url}'>{label}</a>" for key,url,label in items)+"</nav>"


def _v97_load_assignments() -> List[Dict[str,Any]]:
    try:
        return list(json.loads(V97_ASSIGNMENTS_PATH.read_text(encoding='utf-8')).get('assignments',[]))
    except Exception:
        return _v96_load_assignments()


def _v97_save_assignments(rows: List[Dict[str,Any]]) -> None:
    V97_ASSIGNMENTS_PATH.write_text(json.dumps({'version':V97_VERSION,'assignments':rows},indent=2),encoding='utf-8')


def _v97_assigned_records(active_only: bool=True) -> List[Dict[str,Any]]:
    byid=_v96_record_map(); out=[]
    for a in _v97_load_assignments():
        if active_only and str(a.get('status','active')).lower()!='active': continue
        pid=str(a.get('problem_id',''))
        if pid in byid:
            r=dict(byid[pid]); r['_assignment']=a; out.append(r)
    return out


def _v97_active_problem(problem_id: str='') -> tuple[str,str,Dict[str,Any]]:
    byid=_v96_record_map()
    if problem_id and problem_id in byid:
        r=byid[problem_id]
        return str(r.get('problem_statement') or ''), f"Assignment {problem_id}", r
    active=_v57_load_active_problem()
    return str(active.get('problem_text') or ''), 'Current active problem', active


def _v97_prompt_cards_inline(problem_id: str='') -> str:
    cards=''.join(f"<button type='button' class='secondary v97-prompt' data-prompt={json.dumps(p)}>{h(t)}</button>" for t,p in V96_PROMPTS)
    return f"<details class='v97-inline'><summary><strong>Add Prompt</strong></summary><p>Select a prompt for the active problem. It will be inserted into the Tutor message box.</p><div class='actions'>{cards}</div></details>"


def _v97_equation_candidates(problem: str, record: Dict[str,Any]) -> List[Dict[str,str]]:
    preferred=[str(x) for x in (record.get('governing_equations') or []) if str(x).strip()]
    out=[]; seen=set()
    for eq in preferred:
        if eq not in seen:
            out.append({'name':'Recommended for this problem','syntax':eq,'use':'From the approved problem record.'}); seen.add(eq)
    words=set(re.findall(r'[a-zA-Z]{4,}', (problem+' '+str(record.get('problem_class',''))).lower()))
    for cat,eqs in _v94_equation_library().items():
        for e in eqs:
            syntax=str(e.get('syntax',''))
            hay=(cat+' '+str(e.get('name',''))+' '+str(e.get('use',''))).lower()
            score=sum(1 for w in words if w in hay)
            if score and syntax not in seen:
                out.append({'name':str(e.get('name','Equation')),'syntax':syntax,'use':str(e.get('use',''))}); seen.add(syntax)
            if len(out)>=12: return out
    if not out:
        for cat,eqs in _v94_equation_library().items():
            for e in eqs[:2]:
                syntax=str(e.get('syntax',''))
                if syntax not in seen: out.append({'name':str(e.get('name','Equation')),'syntax':syntax,'use':str(e.get('use',''))}); seen.add(syntax)
            if len(out)>=8: break
    return out


def _v97_equation_cards_inline(problem: str, record: Dict[str,Any]) -> str:
    rows=''.join(f"<article class='card compact'><h4>{h(e['name'])}</h4><code>{h(e['syntax'])}</code><p>{h(e['use'])}</p><button type='button' class='secondary v97-equation' data-equation={json.dumps(e['syntax'])}>Insert Equation</button><button type='button' class='secondary' onclick='navigator.clipboard.writeText({json.dumps(e['syntax'])})'>Copy</button></article>" for e in _v97_equation_candidates(problem,record))
    return f"<details class='v97-inline'><summary><strong>Add Equation</strong></summary><p>Equations are filtered for the active problem. Select one to insert it into the Tutor message box.</p><div class='dev-grid'>{rows}</div></details>"


def _v97_contextual_reply(problem: str, request: str, mode: str, rcs: List[str], record: Dict[str,Any]) -> str:
    q=request.lower()
    topic=str(record.get('problem_class') or record.get('course_topic') or mode or 'the active problem')
    if 'compare the possible learning modes' in q or 'choose a learning mode' in q:
        expected=str(record.get('proposed_learning_mode') or mode or 'not yet selected')
        return (f"For this active problem, first identify what changes and what is being calculated. The situation is classified in the approved record as **{topic}**. "
                f"Ask yourself: (1) Is the central quantity motion, force, energy transfer, momentum, rotation, fluid behavior, waves, circuits, optics, or thermal change? "
                f"(2) Which givens directly connect to the requested quantity? (3) Which representation would make that connection visible? "
                f"The system's reference mode is **{expected}**, but you should confirm it from the problem evidence before selecting it.")
    if 'canonical rc registry' in q or 'choose rcs' in q or 'which rcs' in q:
        expected=record.get('proposed_rcs') or []
        sample=', '.join(expected[:8]) if expected else 'the givens, target quantity, method, representation, unit check, and interpretation'
        return (f"For this problem, inspect the wording for the situation, known quantities, requested quantity, physical method, representation, and final-product requirements. "
                f"Candidate RCs from the approved record include: **{sample}**. Select only those you can justify from the text; the Tutor should explain each candidate, not choose for you.")
    if 'governing equation' in q or 'select an equation' in q:
        eqs=record.get('governing_equations') or []
        if eqs:
            return f"For this active problem, the approved equation family includes: **{'; '.join(map(str,eqs))}**. Before using one, state the physical model and assumptions, then map each symbol to a known or requested quantity in this problem."
    if 'one conceptual hint' in q or 'start with a hint' in q:
        return f"Hint for this active problem: classify the physical process represented by the givens before substituting numbers. Identify the system boundary and the quantity that changes."
    if 'diagram' in q or 'representation' in q:
        return f"For this active problem, choose a representation that exposes the governing relationship: a labeled situation diagram, free-body diagram, energy-flow diagram, graph, circuit diagram, ray diagram, or coordinate sketch as appropriate to **{topic}**."
    if 'check the dimensions' in q or 'check units' in q:
        return "List the units of every factor in your selected equation, reduce them symbolically, and verify that the result has the units of the requested quantity. Paste your equation and substitution for a specific check."
    if 'review my solution' in q or 'check my solution' in q:
        return "Paste your solution steps. I will compare the model, knowns, equation, algebra, units, and interpretation, identify the first substantive error, and stop so you can correct it."
    return _v49_tutor_reply(_v49_augment_problem_with_tags(problem+'\n\nStudent request: '+request,_v49_normalize_tags(rcs)),'guided',_v47_last_assistant_message())


