def _v98_canonical_records() -> List[Dict[str, Any]]:
    path = PACKAGE_DIR / "abk_pai" / "canonical_problem_registry_v85.json"
    try:
        return list(json.loads(path.read_text(encoding="utf-8")).get("records", []))
    except Exception:
        return []


def _v98_canonical_map() -> Dict[str, Dict[str, Any]]:
    return {str(r.get("id")): r for r in _v98_canonical_records()}


def _v98_load_assignments() -> List[Dict[str, Any]]:
    try:
        rows = list(json.loads(V98_ASSIGNMENTS_PATH.read_text(encoding="utf-8")).get("assignments", []))
    except Exception:
        rows = []
    normalized = []
    changed = False
    for index, row in enumerate(rows, start=1):
        item = dict(row)
        if not item.get("assignment_id"):
            item["assignment_id"] = f"V98-{index:04d}"
            changed = True
        if not item.get("title"):
            item["title"] = f"Homework {index}"
            changed = True
        if "directions" not in item:
            item["directions"] = "Complete all classification and solution fields on this page."
            changed = True
        normalized.append(item)
    if changed and V98_ASSIGNMENTS_PATH.exists():
        _v98_save_assignments(normalized)
    return normalized


def _v98_save_assignments(rows: List[Dict[str, Any]]) -> None:
    V98_ASSIGNMENTS_PATH.write_text(
        json.dumps({"version": V98_VERSION, "assignments": rows}, indent=2), encoding="utf-8"
    )


def _v98_ensure_tables() -> None:
    with connect() as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS v98_tutor_submissions(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_name TEXT NOT NULL,
            problem_id TEXT NOT NULL,
            selected_domain TEXT,
            selected_family TEXT,
            selected_mode TEXT,
            selected_rc_json TEXT,
            equations_used TEXT,
            representation TEXT,
            symbolic_work TEXT,
            numerical_work TEXT,
            interpretation TEXT,
            final_answer TEXT,
            tutor_feedback TEXT,
            completed INTEGER DEFAULT 0,
            created_at TEXT,
            updated_at TEXT
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS v98_assignment_submissions(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_name TEXT NOT NULL,
            assignment_id TEXT NOT NULL,
            problem_id TEXT NOT NULL,
            selected_domain TEXT,
            selected_family TEXT,
            selected_mode TEXT,
            selected_rc_json TEXT,
            known_information TEXT,
            equations_used TEXT,
            representation TEXT,
            symbolic_work TEXT,
            numerical_work TEXT,
            interpretation TEXT,
            final_answer TEXT,
            submitted_at TEXT
        )""")


def _v98_options(values: List[str], selected: str = "", blank: str = "Select") -> str:
    unique = sorted({str(v) for v in values if str(v).strip()})
    out = [f"<option value=''>{h(blank)}</option>"]
    for value in unique:
        sel = " selected" if value == selected else ""
        out.append(f"<option value='{h(value)}'{sel}>{h(value.replace('_', ' ').title())}</option>")
    return "".join(out)


def _v98_rc_checkboxes(record: Dict[str, Any], selected: List[str], prefix: str) -> str:
    # Students select from the same canonical RC language used by the system.
    registry = _v63_rc_registry().get("items", {})
    expected = [str(x) for x in record.get("expected_rc", [])]
    # Show the full grouped registry, but put RCs related to this canonical record first.
    ordered = []
    seen = set()
    for code in expected + sorted(registry.keys()):
        if code in registry and code not in seen:
            ordered.append(code); seen.add(code)
    rows = []
    for code in ordered:
        meta = registry.get(code, {})
        label = str(meta.get("display_label") or meta.get("label") or code.replace("_", " ").title())
        checked = " checked" if code in selected else ""
        rows.append(
            f"<label class='rc-option'><input type='checkbox' name='selected_rc' "
            f"value='{h(code)}'{checked}> <strong>{h(label)}</strong> "
            f"<small>({h(code)})</small></label>"
        )
    return f"<div id='{h(prefix)}' class='rc-menu'>{''.join(rows)}</div>"


def _v98_equation_panel(record: Dict[str, Any], target_id: str) -> str:
    problem = str(record.get("prompt") or record.get("problem_statement") or "")
    normalized = {
        "problem_class": record.get("problem_family") or record.get("problem_class"),
        "governing_equations": record.get("equations") or record.get("governing_equations") or [],
    }
    candidates = _v97_equation_candidates(problem, normalized)
    cards = "".join(
        f"<article class='card compact'><h4>{h(e['name'])}</h4><code>{h(e['syntax'])}</code>"
        f"<p>{h(e['use'])}</p><button type='button' class='secondary v98-insert-equation' "
        f"data-target='{h(target_id)}' data-equation={json.dumps(e['syntax'])}>Insert into Work</button> "
        f"<button type='button' class='secondary' onclick='navigator.clipboard.writeText({json.dumps(e['syntax'])})'>Copy Equation</button></article>"
        for e in candidates
    )
    return f"<details><summary><strong>Select or Copy Equations</strong></summary><div class='dev-grid'>{cards}</div></details>"


def _v98_prompt_panel(target_id: str) -> str:
    cards = "".join(
        f"<button type='button' class='secondary v98-insert-prompt' data-target='{h(target_id)}' "
        f"data-prompt={json.dumps(prompt)}>{h(title)}</button>"
        for title, prompt in V96_PROMPTS
    )
    return f"<details><summary><strong>Select a Prompt</strong></summary><p>The selected prompt is inserted into your Tutor request for this problem.</p><div class='actions'>{cards}</div></details>"


def _v98_feedback(record: Dict[str, Any], domain: str, family: str, mode: str,
                  selected_rc: List[str], equations: str, symbolic: str,
                  numerical: str, final_answer: str) -> str:
    expected_domain = str(record.get("domain") or "")
    expected_family = str(record.get("problem_family") or "")
    expected_mode = str(record.get("mode") or "")
    expected_rc = [str(x) for x in record.get("expected_rc", [])]
    matched = [x for x in selected_rc if x in expected_rc]
    missing = [x for x in expected_rc if x not in selected_rc]
    extra = [x for x in selected_rc if x not in expected_rc]
    parts = ["<h3>Physics Tutor Response</h3>"]
    parts.append(f"<p><strong>Domain:</strong> {'Good match.' if domain == expected_domain else 'Review your choice.'} "
                 f"The problem evidence points to <code>{h(expected_domain)}</code>.</p>")
    parts.append(f"<p><strong>Problem Family:</strong> {'Good match.' if family == expected_family else 'Review your choice.'} "
                 f"Look for the physical process represented by the givens and target.</p>")
    parts.append(f"<p><strong>Learning Mode:</strong> {'Good match.' if mode == expected_mode else 'Review your choice.'} "
                 f"The canonical mode is <code>{h(expected_mode)}</code>; justify it from the problem statement.</p>")
    parts.append(f"<p><strong>RC review:</strong> {len(matched)} matched. "
                 f"Missing candidates: {h(', '.join(missing) or 'none')}. "
                 f"Additional selections to justify: {h(', '.join(extra) or 'none')}.</p>")
    if not equations.strip():
        parts.append("<p><strong>Next step:</strong> Select or copy an equation and explain why it applies before substituting values.</p>")
    elif not symbolic.strip():
        parts.append("<p><strong>Next step:</strong> Write the symbolic relationship and solve for the requested quantity before numerical substitution.</p>")
    elif not numerical.strip() or not final_answer.strip():
        parts.append("<p><strong>Next step:</strong> Complete the numerical work with units, then state and interpret the final answer.</p>")
    else:
        canonical_answer = str(record.get("final_answer") or "")
        parts.append("<p><strong>Solution review:</strong> Your classification and solution are sufficiently complete for comparison. "
                     "Check dimensional consistency, significant figures, and whether every requested part is answered.</p>")
        if canonical_answer:
            parts.append(f"<details><summary>Show canonical answer after completing your attempt</summary><p>{h(canonical_answer)}</p></details>")
    parts.append("<p>Revise any weak choice or solution step below and submit again. Select <strong>Finish Problem</strong> only when the work is complete.</p>")
    return "".join(parts)


@app.on_event("startup")
def _v98_startup() -> None:
    _v98_ensure_tables()
    if not V98_ASSIGNMENTS_PATH.exists():
        # Preserve actual teacher assignments already made in V97.
        _v98_save_assignments(_v97_load_assignments())


