@app.get("/teacher-assignment-builder-v98", response_class=HTMLResponse)
def v98_teacher_assignment_builder(q: str = Query(""), phase: str = Query("")) -> HTMLResponse:
    rows = _v93_records(); low = q.strip().lower()
    if phase: rows = [r for r in rows if str(r.get("phase")) == phase]
    if low: rows = [r for r in rows if low in (str(r.get("problem_id"))+" "+str(r.get("problem_statement"))+" "+str(r.get("problem_class"))).lower()]
    assigned = {str(a.get("problem_id")) for a in _v98_load_assignments() if str(a.get("status", "active")) == "active"}
    cards = []
    for r in rows[:100]:
        pid = str(r.get("problem_id")); is_assigned = pid in assigned
        cards.append(f"<article class='card'><h3>{h(pid)} — {h(str(r.get('problem_class')))}</h3><p>{h(str(r.get('problem_statement')))}</p>"
                     f"<form method='post' action='/teacher-assignment-builder-v98/assign'><input type='hidden' name='problem_id' value='{h(pid)}'>"
                     f"<label>Homework title<input name='title' value='{h(str(r.get('problem_class') or pid))}' required></label>"
                     f"<label>Teacher directions<textarea name='directions' rows='3'></textarea></label>"
                     f"<button{' disabled' if is_assigned else ''}>{'Already Assigned' if is_assigned else 'Assign Homework'}</button></form>"
                     f"<details><summary>Teacher/system solution and tags</summary><p><strong>Domain:</strong> {h(str(r.get('domain')))}</p>"
                     f"<p><strong>Problem Family:</strong> {h(str(r.get('problem_class')))}</p><p><strong>Mode:</strong> {h(str(r.get('proposed_learning_mode')))}</p>"
                     f"<p><strong>RCs:</strong> {h(', '.join(r.get('proposed_rcs') or []))}</p><p><strong>Equations:</strong> {h('; '.join(r.get('governing_equations') or []))}</p>"
                     f"<p><strong>Solution:</strong> {h(str(r.get('preliminary_solution')))}</p><p><strong>Final answer:</strong> {h(str(r.get('final_answer')))}</p></details></article>")
    body = _v98_teacher_nav("builder") + f"<section class='hero'><h2>Assignment Builder</h2><form><input name='q' value='{h(q)}' placeholder='Search approved 700 problems'><input name='phase' value='{h(phase)}' placeholder='Phase'><button>Search</button></form></section><section class='dev-grid'>{''.join(cards)}</section>"
    return page("Assignment Builder", body)


