@app.get("/student-assignments-v98", response_class=HTMLResponse)
def v98_student_assignments(assignment_id: str = Query("")) -> HTMLResponse:
    assignments = [a for a in _v98_load_assignments() if str(a.get("status", "active")) == "active"]
    byid = _v96_record_map()
    if not assignment_id:
        cards = []
        for a in assignments:
            r = byid.get(str(a.get("problem_id")), {})
            cards.append(f"<article class='card'><h3>{h(str(a.get('title') or a.get('assignment_id')))}</h3><p>{h(str(r.get('problem_statement')))}</p>"
                         f"<p><strong>Teacher directions:</strong> {h(str(a.get('directions')))}</p>"
                         f"<a class='button' href='/student-assignments-v98?assignment_id={quote(str(a.get('assignment_id')))}'>Open Homework</a></article>")
        return page("Assignments", _v98_student_nav("assignments") + f"<section class='hero'><h2>Assignments</h2><p>Select one homework assigned by your teacher.</p></section><section class='dev-grid'>{''.join(cards) or '<article class=card><p>No active homework has been assigned.</p></article>'}</section>")
    assignment = next((a for a in assignments if str(a.get("assignment_id")) == assignment_id), None)
    if not assignment:
        raise HTTPException(status_code=404, detail="Assigned homework not found")
    record = byid.get(str(assignment.get("problem_id")))
    if not record:
        raise HTTPException(status_code=404, detail="Approved problem not found")
    domains = [str(r.get("domain")) for r in _v93_records()]
    families = [str(r.get("problem_class")) for r in _v93_records()]
    modes = [str(r.get("proposed_learning_mode")) for r in _v93_records()]
    eq_record = dict(record); eq_record["prompt"] = record.get("problem_statement")
    body = _v98_student_nav("assignments") + f"""
    <section class='hero'><h2>{h(str(assignment.get('title')))}</h2><p>Complete and submit this homework independently on this page. No Tutor hints are provided.</p></section>
    <section class='panel'><h3>Problem</h3><p>{h(str(record.get('problem_statement')))}</p><p><strong>Teacher directions:</strong> {h(str(assignment.get('directions')))}</p></section>
    <section class='panel'><form method='post' action='/student-assignments-v98/submit' class='story-form'>
      <input type='hidden' name='assignment_id' value='{h(assignment_id)}'><input type='hidden' name='problem_id' value='{h(str(assignment.get('problem_id')))}'>
      <label>Student name<input name='student_name' required></label>
      <label>Domain<select name='selected_domain' required>{_v98_options(domains)}</select></label>
      <label>Problem Family<select name='selected_family' required>{_v98_options(families)}</select></label>
      <label>Learning Mode<select name='selected_mode' required>{_v98_options(modes)}</select></label>
      <details><summary><strong>Select RCs</strong></summary>{_v98_rc_checkboxes({'expected_rc': record.get('proposed_rcs') or []}, [], 'v98-assignment-rc')}</details>
      <label>Known or observable information<textarea name='known_information' rows='5'></textarea></label>
      {_v98_equation_panel(eq_record, 'v98-assignment-equations')}
      <label>Equations used<textarea id='v98-assignment-equations' name='equations_used' rows='4'></textarea></label>
      <label>Representation or diagram description<textarea name='representation' rows='4'></textarea></label>
      <label>Symbolic solution<textarea name='symbolic_work' rows='5'></textarea></label>
      <label>Numerical solution and units<textarea name='numerical_work' rows='5'></textarea></label>
      <label>Interpretation<textarea name='interpretation' rows='4'></textarea></label>
      <label>Final answer<textarea name='final_answer' rows='4'></textarea></label>
      <button type='submit'>Submit Assignment</button>
    </form></section>{_v98_insert_script()}"""
    return page("Assignment", body)


@app.post("/student-assignments-v98/submit", response_class=HTMLResponse)
def v98_assignment_submit(
    assignment_id: str = Form(...), problem_id: str = Form(...), student_name: str = Form(...),
    selected_domain: str = Form(...), selected_family: str = Form(...), selected_mode: str = Form(...),
    selected_rc: List[str] = Form([]), known_information: str = Form(""), equations_used: str = Form(""),
    representation: str = Form(""), symbolic_work: str = Form(""), numerical_work: str = Form(""),
    interpretation: str = Form(""), final_answer: str = Form("")
) -> HTMLResponse:
    assignments = _v98_load_assignments()
    if not any(str(a.get("assignment_id")) == assignment_id and str(a.get("problem_id")) == problem_id for a in assignments):
        raise HTTPException(status_code=400, detail="Assignment does not match a teacher-released problem")
    with connect() as conn:
        conn.execute("""INSERT INTO v98_assignment_submissions(
            student_name,assignment_id,problem_id,selected_domain,selected_family,selected_mode,selected_rc_json,
            known_information,equations_used,representation,symbolic_work,numerical_work,interpretation,final_answer,submitted_at)
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (student_name, assignment_id, problem_id, selected_domain, selected_family, selected_mode,
             json.dumps(selected_rc), known_information, equations_used, representation, symbolic_work,
             numerical_work, interpretation, final_answer, utc_now()))
    body = _v98_student_nav("assignments") + f"""
    <section class='hero'><h2>Assignment Submitted</h2><p>Your completed homework was submitted to the teacher. No solution or hint is displayed on the student side.</p></section>
    <section class='panel'><p><strong>Assignment:</strong> {h(assignment_id)}</p><p><strong>Student:</strong> {h(student_name)}</p><a class='button' href='/assignments'>Return to Assignments</a></section>"""
    return page("Assignment Submitted", body)


