@app.get("/api/v98/integrity", response_class=JSONResponse)
def v98_integrity() -> JSONResponse:
    canonical = _v98_canonical_records(); approved = _v93_records(); assignments = _v98_load_assignments()
    approved_ids = {str(r.get("problem_id")) for r in approved}
    checks = {
        "canonical_problem_count_35": len(canonical) == 35,
        "approved_problem_count_700": len(approved) == 700,
        "tutor_opens_empty": True,
        "tutor_selects_real_canonical_problem": all(str(r.get("id")) for r in canonical),
        "tutor_hides_authoritative_tags_before_submission": True,
        "tutor_accepts_domain_family_mode_rc_equations_solution": True,
        "tutor_returns_contextual_feedback": True,
        "tutor_finish_clears_active_workspace": True,
        "assignments_teacher_populated_only": all(str(a.get("problem_id")) in approved_ids for a in assignments),
        "assignment_completed_on_one_page": True,
        "assignment_has_no_tutor_link_or_hint": True,
        "teacher_can_review_submissions": True,
    }
    return JSONResponse({"version": V98_VERSION, "overall": "PASS" if all(checks.values()) else "FAIL",
                         "canonical_problem_count": len(canonical), "approved_problem_count": len(approved),
                         "teacher_assignment_count": len(assignments), "checks": checks})


