# ABK_PAI Volume 99 - coherent current routes (replacement for mixed V98 shell)
# ============================================================================
V99_ASSIGNMENTS_PATH = PACKAGE_DIR / 'abk_pai' / 'v99_teacher_assignments.json'


def v99_page(title: str, body: str) -> HTMLResponse:
    html=f"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{h(title)} — ABK_PAI V99</title><link rel='stylesheet' href='/assets/css/style.css'><style>
    .v99-banner{{background:#142c47;color:#fff;padding:.55rem 1rem}}.v99-banner h1{{font-size:1.45rem;margin:0}}.v99-role-nav{{display:flex;flex-wrap:wrap;gap:.4rem;margin-top:.45rem}}.v99-role-nav a{{color:#fff;text-decoration:none;border:1px solid #7f9bb8;border-radius:5px;padding:.28rem .5rem;font-weight:700}}.dev-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:1rem}}.status-pass{{color:#116329;font-weight:800}}.status-review{{color:#8a4b00;font-weight:800}}.compact-hero{{padding:1rem 1.25rem}}.compact-hero h2{{margin:.1rem 0 .35rem}}
    </style></head><body><header class='v99-banner'><h1>ABK_PAI Volume 99</h1><nav class='v99-role-nav'><a href='/'>Developer Home</a><a href='/v99/teacher-home'>Teacher Home</a><a href='/v99/student-home'>Student Home</a><a href='/abk-pai/v99-regression'>V99 Tests</a><a href='/api/v99/integrity'>V99 Integrity</a></nav></header><main class='container'>{body}</main></body></html>"""
    return HTMLResponse(html)



def _v99_load_assignments() -> List[Dict[str, Any]]:
    if V99_ASSIGNMENTS_PATH.exists():
        try:
            data = json.loads(V99_ASSIGNMENTS_PATH.read_text(encoding='utf-8'))
            if isinstance(data, list):
                return data
        except Exception:
            pass
    seed = _v98_load_assignments()
    normalized=[]
    for i,item in enumerate(seed,1):
        row=dict(item)
        row['assignment_id']=f'V99-{i:04d}'
        normalized.append(row)
    V99_ASSIGNMENTS_PATH.parent.mkdir(parents=True, exist_ok=True)
    V99_ASSIGNMENTS_PATH.write_text(json.dumps(normalized, indent=2), encoding='utf-8')
    return normalized


def _v99_save_assignments(rows: List[Dict[str, Any]]) -> None:
    V99_ASSIGNMENTS_PATH.parent.mkdir(parents=True, exist_ok=True)
    V99_ASSIGNMENTS_PATH.write_text(json.dumps(rows, indent=2), encoding='utf-8')


