def _v99_ensure_tables() -> None:
    with connect() as conn:
        conn.execute('''CREATE TABLE IF NOT EXISTS v99_tutor_submissions(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            problem_id TEXT NOT NULL,
            student_name TEXT,
            selected_domain TEXT,
            selected_family TEXT,
            selected_mode TEXT,
            selected_rcs TEXT,
            tutor_request TEXT,
            equations_used TEXT,
            representation TEXT,
            symbolic_work TEXT,
            numerical_work TEXT,
            interpretation TEXT,
            final_answer TEXT,
            feedback TEXT,
            completed INTEGER DEFAULT 0,
            created_at TEXT,
            updated_at TEXT
        )''')
        conn.execute('''CREATE TABLE IF NOT EXISTS v99_assignment_submissions(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assignment_id TEXT NOT NULL,
            problem_id TEXT NOT NULL,
            student_name TEXT,
            selected_domain TEXT,
            selected_family TEXT,
            selected_mode TEXT,
            selected_rcs TEXT,
            known_information TEXT,
            equations_used TEXT,
            representation TEXT,
            symbolic_work TEXT,
            numerical_work TEXT,
            interpretation TEXT,
            final_answer TEXT,
            submitted_at TEXT
        )''')


_v99_ensure_tables()


def _v99_canonical_map() -> Dict[str, Dict[str, Any]]:
    return {str(r.get('id')): r for r in _v98_canonical_records()}


def _v99_approved_map() -> Dict[str, Dict[str, Any]]:
    return {str(r.get('problem_id')): r for r in _v93_records()}


def _v99_unique(values: List[Any]) -> List[str]:
    return sorted({str(v) for v in values if str(v).strip()})


def _v99_options(values: List[str], selected: str = '', blank: str = 'Select') -> str:
    vals = _v99_unique(values)
    return f"<option value=''>{h(blank)}</option>" + ''.join(
        f"<option value='{h(v)}'{' selected' if v==selected else ''}>{h(v.replace('_',' ').title())}</option>" for v in vals
    )


def _v99_rc_menu(selected: List[str], prefix: str) -> str:
    reg = _v63_rc_registry(); selected_set = set(selected or [])
    blocks = []
    for cat in reg.get('categories', []):
        codes = cat.get('items', [])
        checks = []
        for code in codes:
            meta = (reg.get('items') or {}).get(code, {})
            label = meta.get('display_label') or code.replace('_',' ')
            checks.append(f"<label class='rc-choice'><input type='checkbox' name='selected_rc' value='{h(code)}'{' checked' if code in selected_set else ''}> {h(label)}</label>")
        blocks.append(f"<details class='compact-details'><summary>{h(cat.get('display_label') or cat.get('category_code'))}</summary><div class='rc-grid'>{''.join(checks)}</div></details>")
    return ''.join(blocks)


V99_PROMPTS = [
    ('Identify the physics','Help me identify the objects, interactions, changes, and physics ideas in this problem without solving it yet.'),
    ('Choose a Learning Mode','Compare the plausible Learning Modes for this problem and ask me questions that help me decide.'),
    ('Choose RCs','Help me examine the RC registry for this problem. Explain each suggestion, but let me make the final choice.'),
    ('Start with a hint','Give me one conceptual hint about this problem and wait for my response.'),
    ('Select an equation','Help me choose a governing equation for this problem and explain the assumptions without solving it.'),
    ('Request a representation','Help me choose and construct the appropriate diagram, graph, free-body diagram, or coordinate representation for this problem.'),
    ('Check units','Check the dimensions and units in my current work for this problem and identify the first inconsistency.'),
    ('Check my solution','Check my current classification, equations, reasoning, calculations, units, interpretation, and final answer. Identify the first issue and let me revise it.'),
]


def _v99_prompt_panel(target_id: str) -> str:
    buttons = ''.join(f"<button type='button' class='secondary v99-prompt' data-target='{h(target_id)}' data-text='{h(text)}'>{h(label)}</button>" for label,text in V99_PROMPTS)
    return f"<details class='compact-details'><summary><strong>Add a Prompt</strong></summary><p class='muted'>Choose one. Its exact text is inserted into the Tutor request for the active problem.</p><div class='actions wrap'>{buttons}</div></details>"


def _v99_equations(record: Dict[str, Any]) -> List[Dict[str, str]]:
    eqs = []
    for e in record.get('equations') or []:
        if isinstance(e, dict):
            eqs.append({'name':str(e.get('name') or 'Equation'),'equation':str(e.get('equation') or e.get('latex') or ''),'use':str(e.get('use') or '')})
        else:
            eqs.append({'name':'Recommended equation','equation':str(e),'use':'From the approved problem record.'})
    if not eqs:
        problem = str(record.get('prompt') or record.get('problem_statement') or '')
        normalized = dict(record)
        normalized['problem_statement'] = problem
        try:
            raw = _v97_equation_candidates(problem, normalized)
            eqs = [{'name':str(e.get('name') or 'Equation'),'equation':str(e.get('equation') or e.get('syntax') or ''),'use':str(e.get('use') or '')} for e in raw]
        except Exception:
            eqs = []
    seen=set(); out=[]
    for e in eqs:
        eq = str(e.get('equation') or e.get('syntax') or '').strip()
        if eq and eq not in seen:
            seen.add(eq); out.append({'name':str(e.get('name') or 'Equation'),'equation':eq,'use':str(e.get('use') or '')})
    return out[:12]


def _v99_equation_panel(record: Dict[str, Any], target_id: str) -> str:
    cards = []
    for e in _v99_equations(record):
        cards.append(f"<article class='eq-card'><h4>{h(e['name'])}</h4><code>{h(e['equation'])}</code><p>{h(e['use'])}</p><div class='actions'><button type='button' class='secondary v99-equation' data-target='{h(target_id)}' data-equation='{h(e['equation'])}'>Insert into Work</button><button type='button' class='secondary v99-copy' data-equation='{h(e['equation'])}'>Copy Equation</button></div></article>")
    return f"<details class='compact-details'><summary><strong>Select or Copy Equations</strong></summary><div class='eq-grid'>{''.join(cards) or '<p>No equation candidates are available for this record.</p>'}</div></details>"


def _v99_script() -> str:
    return r"""
<script>
(function(){
  function appendTo(id,text){const el=document.getElementById(id);if(!el)return;const t=String(text||'').trim();if(!t)return;el.value=(el.value.trim()?el.value.trim()+'\n':'')+t;el.dispatchEvent(new Event('input',{bubbles:true}));el.focus();}
  document.addEventListener('click',async function(e){
    const p=e.target.closest('.v99-prompt'); if(p){appendTo(p.dataset.target,p.dataset.text);return;}
    const q=e.target.closest('.v99-equation'); if(q){appendTo(q.dataset.target,q.dataset.equation);return;}
    const c=e.target.closest('.v99-copy'); if(c){try{await navigator.clipboard.writeText(c.dataset.equation||'');c.textContent='Copied';setTimeout(()=>c.textContent='Copy Equation',900);}catch(err){alert('Copy failed. Select the equation text manually.');}return;}
  });
})();
</script>
<style>
.v99-workspace{display:grid;grid-template-columns:minmax(0,1fr);gap:.7rem}.compact-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.6rem}.compact-grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.compact-details{border:1px solid #c7d3df;border-radius:8px;padding:.45rem .65rem;background:#fff}.compact-details>summary{cursor:pointer;font-weight:700}.rc-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.25rem .65rem;max-height:240px;overflow:auto;padding:.5rem}.rc-choice{font-weight:400}.eq-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.6rem;padding-top:.6rem}.eq-card{border:1px solid #d4dee8;border-radius:8px;padding:.65rem;background:#f8fafc}.eq-card h4{margin:.1rem 0 .45rem}.actions.wrap{flex-wrap:wrap}.sticky-submit{position:sticky;bottom:0;background:#fff;border-top:1px solid #cbd5e1;padding:.65rem 0;z-index:10}.compact-textarea{min-height:72px}.problem-box{padding:.7rem;border-left:4px solid #506b89;background:#f7f9fc;border-radius:7px}.feedback-box{padding:.7rem;border-left:4px solid #2468b4;background:#eef5ff;border-radius:7px}.current-nav{margin-bottom:.6rem}@media(max-width:900px){.compact-grid,.compact-grid.two,.eq-grid,.rc-grid{grid-template-columns:1fr}}
</style>
"""


def _v99_tutor_feedback(record: Dict[str, Any], domain: str, family: str, mode: str, rcs: List[str], request: str, equations: str, symbolic: str, numerical: str, final_answer: str) -> str:
    expected_domain = str(record.get('domain') or '')
    expected_family = str(record.get('problem_family') or '')
    expected_mode = str(record.get('mode') or '')
    expected_rc = set(record.get('expected_rc') or [])
    chosen_rc = set(rcs or [])
    parts=[]
    parts.append(f"Domain: {'good match' if domain==expected_domain else 'review your choice'}.")
    parts.append(f"Problem Family: {'good match' if family==expected_family else 'review your choice'}.")
    parts.append(f"Learning Mode: {'good match' if mode==expected_mode else 'review your choice'}.")
    if chosen_rc:
        parts.append(f"RC review: {len(chosen_rc & expected_rc)} expected RC(s) selected; {len(expected_rc-chosen_rc)} expected RC(s) still worth reconsidering.")
    else:
        parts.append('RC review: no RCs were selected yet.')
    lower = request.lower()
    prompt_reply=''
    problem = str(record.get('prompt') or '')
    if 'learning mode' in lower:
        prompt_reply = f"For this problem, focus on what physical process changes and what quantities connect that change. Compare the process in the statement with your selected mode, then justify why that mode is more suitable than the nearest alternative."
    elif 'rc' in lower:
        prompt_reply = "Review the statement phrase by phrase: identify the situation, givens, requested result, governing physical process, equation tool, and required checks. Use those observations to revise your RC choices."
    elif 'equation' in lower:
        prompt_reply = "Choose equations only after naming the physical process. Check that every symbol in the equation corresponds to a stated or inferable quantity in this problem and state the assumptions that make the equation valid."
    elif 'unit' in lower:
        prompt_reply = "Track the units through each substitution and verify that the final unit matches the requested physical quantity. Correct the first mismatch before continuing."
    elif 'representation' in lower:
        prompt_reply = "Choose a representation that exposes the governing relationships in this specific situation. Label known quantities, unknowns, directions, and system boundaries."
    elif 'hint' in lower:
        prompt_reply = "First hint: identify the system and the physical quantity that changes over the stated interval. Do not calculate yet."
    elif 'check my solution' in lower:
        prompt_reply = "Check your work in this order: model, equation, symbolic isolation, substitution, units, numerical value, and interpretation. Revise the earliest step that does not follow from the problem statement."
    else:
        prompt_reply = f"Continue with the active problem: {problem[:220]}{'…' if len(problem)>220 else ''}"
    parts.append(prompt_reply)
    if not equations.strip(): parts.append('Next step: select or enter at least one governing equation and explain why it applies.')
    elif not symbolic.strip(): parts.append('Next step: rearrange the equation symbolically before substituting numbers.')
    elif not numerical.strip(): parts.append('Next step: substitute values with units and calculate.')
    elif not final_answer.strip(): parts.append('Next step: state the final answer with units and a physical interpretation.')
    else: parts.append('You have a complete draft. Recheck consistency among the model, equations, units, and final interpretation before finishing the problem.')
    return ' '.join(parts)


