@app.get('/physics-tutor-v99', response_class=HTMLResponse)
def v99_physics_tutor(problem_id: str = Query('')) -> HTMLResponse:
    records = _v98_canonical_records(); cmap = _v99_canonical_map()
    if not problem_id:
        opts=''.join(f"<option value='{h(str(r.get('id')))}'>{h(str(r.get('title') or r.get('source_location') or r.get('id')))}</option>" for r in records)
