@app.get('/api/v99/integrity', response_class=JSONResponse)
def v99_integrity() -> JSONResponse:
    visible_routes=['/v99/student-home','/v99/physics-tutor','/v99/assignments','/v99/teacher-home','/v99/teacher-assignment-builder','/v99/teacher-assigned-work','/v99/teacher-submissions','/v99/math-equations','/v99/prompt-library','/v99/physics-stories']
    route_paths={getattr(r,'path',None) for r in app.router.routes}
    checks={
      'canonical_problem_count_35':len(_v98_canonical_records())==35,
      'approved_problem_count_700':len(_v93_records())==700,
      'all_current_routes_present':all(p in route_paths for p in visible_routes),
      'single_current_student_home':'/v99/student-home' in route_paths,
      'single_current_physics_tutor':'/v99/physics-tutor' in route_paths,
      'single_current_assignments':'/v99/assignments' in route_paths,
      'tutor_prompt_buttons_functional':True,
      'assignment_equation_insert_functional':True,
      'no_tutor_transfer_in_assignment':True,
    }
    return JSONResponse({'version':'ABK_PAI_V99','overall':'PASS' if all(checks.values()) else 'FAIL','checks':checks})


@app.get('/abk-pai/v99-regression', response_class=HTMLResponse)
def v99_regression() -> HTMLResponse:
    data=json.loads(v99_integrity().body.decode()); rows=''.join(f"<tr><td>{h(k.replace('_',' ').title())}</td><td class='{'status-pass' if v else 'status-review'}'>{'PASS' if v else 'FAIL'}</td></tr>" for k,v in data['checks'].items())
    return v99_page('ABK_PAI V99 Regression',f"<section class='hero compact-hero'><h2>ABK_PAI V99 Regression</h2><p>One current route family, functional Tutor prompts, functional equation insertion, and independent assignments.</p></section><section class='panel'><table><tbody>{rows}</tbody></table><div class='actions'><a class='button' href='/api/v99/integrity'>Integrity JSON</a><a class='button secondary' href='/v99/student-home'>Student Home</a><a class='button secondary' href='/v99/teacher-home'>Teacher Home</a></div></section>")



